import {addEntityClass,ATTRIB, IEDAttrib} from "../../engine/IEDProxy"
import { VeryEngine,DataType} from "../../engine";
import { IEDGUI } from "./IEDGUI";
import { Tools } from "../../utility/Tools";


@addEntityClass
export class Button extends IEDGUI{
    public get subtype(): string {
        return "button"
    }

    private image:HTMLElement;
    private textDiv:HTMLElement;

    protected realLoad(is2D:boolean): void {
        if(is2D){
            this.sceneObj = document.createElement("div");
            this.sceneObj.style.pointerEvents = "auto";
            let divStyle = this.sceneObj.style;
            divStyle.borderStyle = "solid";
            divStyle.position = "absolute";
            divStyle.overflow = "hidden";
            divStyle.cursor = "pointer";
            this.image = document.createElement("img");
            this.image.style.position = "absolute";
            this.image.style.width = "100%";
            this.image.style.height = "100%";
            this.textDiv = document.createElement("div");
            this.textDiv.style.position = "absolute";
            this.textDiv.style.display = "flex";
            this.textDiv.style.width = "100%";
            this.textDiv.style.height = "100%";
            this.textDiv.style.justifyContent = "center";
            this.textDiv.style.alignItems = "center";
            this.sceneObj.append(this.image);
            this.sceneObj.append(this.textDiv);
        }else{
            this.sceneObj = BABYLON.GUI.Button.CreateImageWithCenterTextButton(this.name,"","");
            this.sceneObj.isPointerBlocker = true;
        }
    }

    private title="按钮"

    @ATTRIB("gui.background")
    public background:IEDAttrib<DataType.Color4>={
        name:"背景色",
        type:DataType.Color4,
        onchange(this:Button,val){
            if(this.is2D){
                (this.sceneObj as HTMLElement).style.background = Tools.rgba2hsvString(val);
            }else{
                (this.sceneObj as BABYLON.GUI.Container).background = Tools.rgba2hsvString(val);
            }
        },
        title:this.title
    }

    @ATTRIB("gui.borderColor")
    public borderColor:IEDAttrib<DataType.Color4>={
        name:"边框色",
        type:DataType.Color4,
        onchange(this:Button,val){
            if(this.is2D){
                (this.sceneObj as HTMLElement).style.borderColor = Tools.rgba2hsvString(val);
            }else{
                (this.sceneObj as BABYLON.GUI.Container).color = Tools.rgba2hsvString(val);
            }
        },
        title:this.title
    }

    @ATTRIB("gui.textColor")
    public textColor:IEDAttrib<DataType.Color4>={
        name:"字体颜色",
        type:DataType.Color4,
        onchange(this:Button,val){
            if(this.is2D){
                (this.sceneObj as HTMLElement).style.color = Tools.rgba2hsvString(val);
            }else{
                (this.sceneObj as BABYLON.GUI.Button).textBlock.color = Tools.rgba2hsvString(val);
            }
        },
        default:[0,0,0,1],
        title:this.title
    }
    @ATTRIB("gui.text")
    public text:IEDAttrib<DataType.Textarea>={
        name:"文字",
        type:DataType.Textarea,
        onchange(this:Button,val,isFirst) {
            val=val+""
            if(this.is2D)
                this.textDiv.innerHTML = val.replace(/ /g, "&nbsp;").replace(/\n/g, "<br>");
            else
                (this.sceneObj as BABYLON.GUI.Button).textBlock!.text=val;
            if(isFirst){
                let split = val.split(".");
                if (split[split.length - 1].startsWith("*")){
                    this.addVeryVal({ attr: "gui.text", valName: val });
                }
            }
        },
        title:this.title
    }

    @ATTRIB("gui.fontSize")
    public fontSize:IEDAttrib<DataType.Number>={
        name:"字体大小",
        type:DataType.Number,
        onchange(this:Button,val){
            if(this.is2D){
                (this.sceneObj as HTMLElement).style.fontSize = val+"px"
            }else{
                (this.sceneObj as BABYLON.GUI.Button).textBlock.fontSize = val
            }
        },
        default:18,
        title:this.title
    }

    @ATTRIB("gui.lineSpacing")
    public lineSpacing:IEDAttrib<DataType.Number>={
        name:"行间距",
        type:DataType.Number,
        onchange(this:Button,val){
            if(this.is2D){
                (this.sceneObj as HTMLElement).style.lineHeight = (this.get("gui.fontSize")+val)+"px"
            }else{
                (this.sceneObj as BABYLON.GUI.Button).textBlock.lineSpacing = val
            }
        },
        title:this.title
    }

    @ATTRIB("gui.source")
    public source:IEDAttrib<DataType.TextureBox>={
        name:"图片",
        type:DataType.TextureBox,
        async onchange(val) {
            let picAsset = VeryEngine.shareBox.id2Asset[val];
            if (picAsset) {
                await picAsset.onceOnlyLoad();
                if(this.is2D){
                    this.image.src = picAsset.assetObj;
                }else{
                    if(!(this.sceneObj as BABYLON.GUI.Button).image.domImage)
                        (this.sceneObj as BABYLON.GUI.Button).image.domImage=document.createElement("img");
                    (this.sceneObj as BABYLON.GUI.Button).image.domImage.src=picAsset.assetObj
                }
            }else{
                if(this.is2D){
                    this.image.src=""
                }else{
                    (this.sceneObj as BABYLON.GUI.Button).image.domImage=document.createElement("img");
                    (this.sceneObj as BABYLON.GUI.Button).image._markAsDirty()
                }
            }
        },
        title:this.title
    }

    @ATTRIB("gui.stretch")
    public stretch:IEDAttrib<DataType.DropDown>={
        name:"填充模式",
        type:DataType.DropDown,
        onchange(this:Button,val){
            if(this.is2D){
                if (val == 1) {
                    this.image.style.objectFit = "contain";
                } else {
                    this.image.style.objectFit = "initial";
                }
            }else{
                (this.sceneObj as BABYLON.GUI.Button).image!.stretch  = val
            }
        },
        extra:["自由拉伸","原始比例"],
        title:this.title
    }

    @ATTRIB("gui.thickness")
    public thickness:IEDAttrib<DataType.Number>={
        name:"边框厚度",
        type:DataType.Number,
        onchange(this:Button,val){
            if(this.is2D){
                (this.sceneObj as HTMLElement).style.borderWidth = val + "px";
            }else{
                (this.sceneObj as BABYLON.GUI.Rectangle).thickness= val
            }
        },
        default:1,
        title:this.title
    }

    @ATTRIB("gui.cornerRadius")
    public cornerRadius:IEDAttrib<DataType.Number>={
        name:"圆角半径",
        type:DataType.Number,
        onchange(this:Button,val){
            if(this.is2D){
                (this.sceneObj as HTMLElement).style.borderRadius = val + "px";
            }else{
                (this.sceneObj as BABYLON.GUI.Rectangle).cornerRadius= val
            }
        },
        default:10,
        title:this.title
    }
}