import {addEntityClass,ATTRIB, IEDAttrib} from "../../engine/IEDProxy"
import { VeryEngine,DataType} from "../../engine";
import { IEDGUI } from "./IEDGUI";
import { IEDEntity } from "../IEDEntity";
import { Tools } from "../../utility/Tools";


@addEntityClass
export class Panel extends IEDGUI{
    public get subtype(): string {
        return "panel"
    }

    protected realLoad(is2D:boolean): void {
        if(is2D){
            this.sceneObj = document.createElement("div");
            let divStyle = this.sceneObj.style;
            divStyle.borderStyle = "solid";
            divStyle.position = "absolute";
        }else{
            this.sceneObj = new BABYLON.GUI.Rectangle(this.name);
            this.sceneObj.isPointerBlocker = true;
        }
    }

    public filterParentType(parent: IEDEntity): boolean {
        if (["canvas", "panel", "scrollviewer","3d-canvas"].includes(parent.subtype)){
            return true;
        }else{
            return false;
        }
    }

    private title="容器"

    @ATTRIB("gui.through")
    public through:IEDAttrib<DataType.Bool>={
        name:"是否点击穿透",
        type:DataType.Bool,
        onchange(this:Panel,val){
            if(this.is2D){
                if (!VeryEngine.EditMode) {
                    if (val) {
                        (this.sceneObj as HTMLElement).style.pointerEvents = "none";
                    } else {
                        (this.sceneObj as HTMLElement).style.pointerEvents = "auto";
                    }
                } else {
                    (this.sceneObj as HTMLElement).style.pointerEvents = "auto";
                }
            }
        },
        title:this.title
    }

    @ATTRIB("gui.clipping")
    public clipping:IEDAttrib<DataType.Bool>={
        name:"边界裁剪",
        type:DataType.Bool,
        onchange(this:Panel,val){
            if(this.is2D){
                if (val) {
                    (this.sceneObj as HTMLElement).style.overflow = "hidden";
                } else {
                    (this.sceneObj as HTMLElement).style.overflow = "visible";
                }
            }else{
                (this.sceneObj as BABYLON.GUI.Container).clipChildren=val;
                (this.sceneObj as BABYLON.GUI.Container).clipContent =val;
            }
        },
        title:this.title
    }

    @ATTRIB("gui.background")
    public background:IEDAttrib<DataType.Color4>={
        name:"背景色",
        type:DataType.Color4,
        onchange(this:Panel,val){
            if(this.is2D){
                (this.sceneObj as HTMLElement).style.background = Tools.rgba2hsvString(val);
            }else{
                (this.sceneObj as BABYLON.GUI.Container).background = Tools.rgba2hsvString(val);
            }
        },
        default:[1,1,1,0.4],
        title:this.title
    }

    @ATTRIB("gui.borderColor")
    public borderColor:IEDAttrib<DataType.Color4>={
        name:"边框色",
        type:DataType.Color4,
        onchange(this:Panel,val){
            if(this.is2D){
                (this.sceneObj as HTMLElement).style.borderColor = Tools.rgba2hsvString(val);
            }else{
                (this.sceneObj as BABYLON.GUI.Container).color = Tools.rgba2hsvString(val);
            }
        },
        title:this.title
    }

    @ATTRIB("gui.thickness")
    public thickness:IEDAttrib<DataType.Number>={
        name:"边框厚度",
        type:DataType.Number,
        onchange(this:Panel,val){
            if(this.is2D){
                (this.sceneObj as HTMLElement).style.borderWidth = val + "px";
            }else{
                (this.sceneObj as BABYLON.GUI.Rectangle).thickness= val
            }
        },
        default:1,
        title:this.title
    }

    @ATTRIB("gui.cornerRadius")
    public cornerRadius:IEDAttrib<DataType.Number>={
        name:"圆角半径",
        type:DataType.Number,
        onchange(this:Panel,val){
            if(this.is2D){
                (this.sceneObj as HTMLElement).style.borderRadius = val + "px";
            }else{
                (this.sceneObj as BABYLON.GUI.Rectangle).cornerRadius= val
            }
        },
        default:10,
        title:this.title
    }
}