    public static sceneBackgroundLayer: Nullable<BABYLON.Layer> = null;

    public static onBeforeUnloadFunc = function (e: any) {
        return true;
    };

    private static _onBeforeUnloadNames: string[] = [];
    public static onBeforeUnload(name: string, raise: boolean): void {
        if (raise) {
            if (Config._onBeforeUnloadNames.indexOf(name) === -1) {
                Config._onBeforeUnloadNames.push(name);
            }
            window.onbeforeunload = Config.onBeforeUnloadFunc;
        } else {
            if (Config._onBeforeUnloadNames.length === 0) {
                window.onbeforeunload = null;
            } else {
                let ind = Config._onBeforeUnloadNames.indexOf(name);
                if (ind === -1) {
                    return;
                } else {
                    Config._onBeforeUnloadNames.splice(ind, 1);
                }
                if (Config._onBeforeUnloadNames.length === 0) {
                    window.onbeforeunload = null;
                }
            }
        }
    }


