    public createGridDiv(
        columns: number,
        rows: number,
        columnGap: number,
        rowGap: number
    ) {
        const lineDiv = document.createElement("div");
        const lineDivStyle = lineDiv.style;
        lineDivStyle.display = "grid";
        lineDivStyle.gridTemplateColumns = "repeat(" + columns + ", 1fr)";
        lineDivStyle.gridTemplateRows = "repeat(" + rows + ", 1fr)";
        lineDivStyle.columnGap = columnGap + "px";
        lineDivStyle.rowGap = rowGap + "px";
        return lineDiv;
    }
    public createFlexDiv(config) {
        if (!config) config = {};
        let div = document.createElement("div") as any;
        div.style =
            " display: flex;flex-wrap: wrap;width: 100%;justify-content: flex-start;align-items: center;row-gap: 4px;";
        if (config.parent) {
            config.parent.append(div);
        } else {
            this.content.append(div);
        }
        return div;
    }

    public Button(
        name: string,
        config?: any,
        parent: HTMLElement = this.content,
        extra?: { label: string }
    ) {
        const label = extra?.label;

        function createButtonDiv() {
            const div = document.createElement("div");
            if (config) {
                Object.assign(div.style, config);
            }
            div.classList.add("button");
            div.innerText = name;
            return div;
        }

        if (label) {
            const item = this.dealPre(label, parent);
            const div = createButtonDiv();

            // 使用 Object.defineProperty 拦截 onclick 的设置
            Object.defineProperty(item, "onclick", {
                get: () => div.onclick,
                set: (newValue) => {
                    div.onclick = newValue;
                },
            });

            item.append(div);
            return item;
        } else {
            const div = createButtonDiv();
            parent.append(div);
            return div;
        }
    }
    
    public NumberField(label: string, value: number | string, parent?: HTMLElement,extra?:{digits:number}) {
        if (value == undefined) value = 0;
        parent = parent || this.content;
        let item = this.dealPre(label, parent);
        let input = document.createElement("input");
        input.value = value + "";
        input.classList.add("item-input");
        input.type = "number";
        item.append(input);
        let result = this.createResult(
            value,
            (val:number) => {
                val=Number(val);
                let digits=2;
                if(extra&&extra.digits){
                    digits=extra.digits;
                }
                if(digits>=0){
                    val=parseFloat(val.toFixed(digits));
                }
                input.value=val+"";
            },
            item
        );
        input.onchange = function () {
            result.value = +input.value;
        };
        return result;
    }


    public string(label: string, value: string, parent?: HTMLElement, extra?: { placeholder: string}) {
        if (value == undefined) value = "";
        let item = this.dealPre(label, parent);
        let input = document.createElement("input");
        input.placeholder = extra?.placeholder || "请输入";
        input.value = value;
        input.classList.add("item-input");
        item.append(input);
        let result = this.createResult(
            value,
            (val) => {
                input.value = val;
            },
            item
        );
        input.onchange = function () {
            result.value = input.value;
        };
        return result;
    }
