    public vector3mini(
        label: string,
        value: number[],
        parent?: HTMLElement,
        extra?: {
            vectorName: string[];
        }
    ) {
        if (value == undefined) {
            value = [0, 0, 0];
        }
        let item = this.dealPre(label, parent);
        let vec3 = document.createElement("div");
        vec3.classList.add("item-vec3-mini");
        let xyz = ["x", "y", "z"];
        if (extra?.vectorName) {
            xyz = extra.vectorName;
        }
        let inputs = [];

        for (let i = 0; i < xyz.length; i++) {
            let div = document.createElement("div");
            let input = document.createElement("input");
            div.append(input);
            div.setAttribute("tag", xyz[i]);
            input.type = "number";
            input.value = value[i] + "";
            input.onchange = () => {
                result.value[i] = +input.value;
                if (result.onchange) result.onchange(result.value);
            };
            inputs.push(input);
            vec3.append(div);
        }
        let result = this.createResult(
            value,
            (val) => {
                for (let i = 0; i < val.length; i++) {
                    inputs[i].value = val[i];
                }
            },
            item
        );
        item.append(vec3);
        return result;
    }
    public vector3(
        label: string,
        value: number[],
        parent?: HTMLElement,
        extra?: { vectorName: string[] }
    ) {
        if (value == undefined) {
            value = [0, 0, 0];
        }else{
            value=[...value];
        }
        let item = this.dealPre(label, parent);
        (item.querySelector(".item-title") as HTMLElement).style.alignSelf =
            "flex-start";
        let vec3 = document.createElement("div");
        vec3.classList.add("item-vec");
        let vectorName: string[];
        if (extra?.vectorName && extra?.vectorName.length > 0) {
            vectorName = extra.vectorName;
        } else {
            vectorName = ["x", "y", "z"];
        }
        let inputs = [];

        for (let i = 0; i < vectorName.length; i++) {
            let div = document.createElement("div");
            div.className = "item-vec-input-box";
            let name = document.createElement("div");
            name.innerText = vectorName[i];
            name.className = "item-vec-name";
            div.append(name);
            let input = document.createElement("input");
            div.append(input);
            div.setAttribute("tag", vectorName[i]);
            input.type = "number";
            input.value = value[i] + "";
            input.onchange = () => {
                let tmp=[...result.value];
                tmp[i]=+input.value;
                result.value=tmp
            };
            inputs.push(input);
            vec3.append(div);
        }
        let result = this.createResult(
            value,
            (val) => {
                for (let i = 0; i < val.length; i++) {
                    inputs[i].value = val[i].toFixed(3);
                }
            },
            item
        );
        item.append(vec3);
        return result;
    }
