    public Toggle(
        label: string,
        value: boolean,
        parent?: HTMLElement,
        extra?: { openText?: string; closeText?: string }
    ) {
        parent = parent || this.content;
        if (value == undefined) value = false;
        let item = this.dealPre(label, parent);
        let toggle = document.createElement("div");
        toggle.classList.add("item-toggle");
        item.append(toggle);
        let check = document.createElement("input");
        check.hidden = true;
        check.type = "checkbox";
        toggle.append(check);
        check.checked = value;
        let hideDiv = document.createElement("div");
        hideDiv.innerText = extra?.closeText || "关";
        hideDiv.classList.add("item-toggle-hide");
        let showDiv = document.createElement("div");
        showDiv.innerText = extra?.openText || "开";
        showDiv.classList.add("item-toggle-show");
        toggle.append(hideDiv);
        toggle.append(showDiv);

        if (value) {
            showDiv.classList.add("item-toggle-checked");
            hideDiv.classList.remove("item-toggle-checked");
        } else {
            hideDiv.classList.add("item-toggle-checked");
            showDiv.classList.remove("item-toggle-checked");
        }
        toggle.onclick = () => check.click();
        let result = this.createResult(
            value,
            (val) => {
                if (val) {
                    showDiv.classList.add("item-toggle-checked");
                    hideDiv.classList.remove("item-toggle-checked");
                } else {
                    hideDiv.classList.add("item-toggle-checked");
                    showDiv.classList.remove("item-toggle-checked");
                }
            },
            item
        );
        check.onchange = function () {
            if (check.checked) {
                showDiv.classList.add("item-toggle-checked");
                hideDiv.classList.remove("item-toggle-checked");
            } else {
                hideDiv.classList.add("item-toggle-checked");
                showDiv.classList.remove("item-toggle-checked");
            }
            result.value = check.checked;
        };
        return result;
    }
    public Tag(label: string, value: string[], parent?: HTMLElement) {
        if (value == undefined) {
            value = [];
        }
        let orginValue = cloneDeep(value);
        let item = this.dealPre(label, parent);
        (item.querySelector(".item-title") as HTMLElement).style.alignSelf =
            "flex-start";
        // 操作box
        const tagBox = document.createElement("div");
        tagBox.className = "item-tag-box";
        item.appendChild(tagBox);
        // 输入框背景
        const tagInputBox = document.createElement("div");
        tagInputBox.className = "tag-input-box";
        tagBox.append(tagInputBox);
        // 输入框
        const tagInput = document.createElement("input");
        tagInput.className = "tag-input";
        tagInputBox.append(tagInput);
        // 加好box
        const plusBox = document.createElement("div");
        plusBox.className = "plus-box";
        tagInputBox.append(plusBox);
        // 加号
        let plusSvg = document.createElementNS(
            "http://www.w3.org/2000/svg",
            "svg"
        );
        plusSvg.ariaHidden = "true";
        plusSvg.classList.add("icon", "icon-jiahao1");
        plusSvg.innerHTML = `<use xlink:href="#icon-jiahao1"></use>`;
        plusBox.append(plusSvg);
        plusBox.onclick = () => {
            if (tagInput.value) {
                if (orginValue.includes(tagInput.value)) {
                    tagInput.value = "";
                    return;
                }
                addTag(tagInput.value);
                orginValue.push(tagInput.value);
                result.value = cloneDeep(orginValue);
                tagInput.value = "";
            }
        };
        //
        const tagListBox = document.createElement("div");
        tagListBox.className = "tag-list-box";
        tagListBox.style.display = "none";
        tagBox.append(tagListBox);

        function addTag(text: string) {
            const tagItemBox = document.createElement("div");
            tagItemBox.className = "tag-item-box";
            const tagItemText = document.createElement("div");
            tagItemText.className = "tag-item-text";
            tagItemText.innerHTML = text;
            const tagItemDelete = document.createElement("div");
            tagItemDelete.className = "tag-item-delete";
            let deleteSvg = document.createElementNS(
                "http://www.w3.org/2000/svg",
                "svg"
            );
            deleteSvg.ariaHidden = "true";
            deleteSvg.classList.add("icon", "icon-cuowu1");
            deleteSvg.innerHTML = `<use xlink:href="#icon-cuowu1"></use>`;
            deleteSvg.onclick = () => {
                tagItemBox.remove();
                const index = orginValue.indexOf(text);
                orginValue.splice(index, 1);
                result.value = cloneDeep(orginValue);
                if (orginValue.length === 0) {
                    tagListBox.style.display = "none";
                }
            };
            tagItemDelete.append(deleteSvg);
            tagItemBox.append(tagItemText);
            tagItemBox.append(tagItemDelete);
            tagListBox.style.display = "flex";
            tagListBox.append(tagItemBox);
        }
        if (orginValue.length > 0) {
            orginValue.forEach((it) => {
                addTag(it);
            });
        }
        let result = this.createResult(value, (val) => {}, item);
        return result;
    }
