    /**
     *
     * @param value 选项参数
     * @param parent 父元素
     * @param isSelect 是否是选择题
     */
    public textInputList(
        value: { text: string; isChecked?: boolean }[],
        parent: HTMLElement,
        isSelect = true,
        limited = 0,
        placeholder = "请在此输入文字"
    ) {
        let orginValue = cloneDeep(value);
        const answerBox = document.createElement("div");
        answerBox.className = "item-question-answer-box";
        const result = this.createResult(value, (value) => {}, answerBox);
        parent.append(answerBox);

        function addTextAnswer(
            answerValue: { text?: string; isChecked?: boolean },
            index: number,
            isSelect: boolean
        ) {
            orginValue.push({ text: "", isChecked: false });
            const answerItem = document.createElement("div");
            answerItem.className = "item-question-answer-item";
            const input = document.createElement("input");
            input.className = "item-question-answer-item-input";
            input.placeholder = placeholder;
            input.value = answerValue.text;
            input.onchange = (e) => {
                orginValue[index]["text"] = (
                    e.target as HTMLInputElement
                ).value;
                result.value = orginValue;
            };
            const svg = document.createElementNS(
                "http://www.w3.org/2000/svg",
                "svg"
            );
            svg.ariaHidden = "true";
            svg.classList.add("icon", "icon-shanchu-xuanzhong");
            svg.innerHTML = `<use xlink:href="#icon-shanchu-xuanzhong"></use>`;
            svg.onclick = () => {
                orginValue.splice(index, 1);
                result.value = orginValue;

                answerItem.remove();
                addAnswer.style.display = "block";
            };

            answerItem.append(input);
            if (isSelect) {
                const checkbox = document.createElement("input");
                checkbox.type = "checkbox";
                checkbox.className = "item-question-answer-item-checkbox";
                checkbox.checked = answerValue.isChecked;
                checkbox.onchange = (e) => {
                    orginValue[index]["isChecked"] = (
                        e.target as HTMLInputElement
                    ).checked;
                    result.value = orginValue;
                };
                checkbox.id = Tools.uuid();
                const label = document.createElement("label");
                label.className = "item-question-answer-item-checkbox-label";
                label.setAttribute("for", checkbox.id);
                answerItem.append(checkbox);
                answerItem.append(label);
            }
            answerItem.append(svg);
            return answerItem;
        }

        if (value.length !== 0) {
            value.forEach((it, index) => {
                const answer = addTextAnswer(it, index, isSelect);
                answerBox.append(answer);
            });
        }

        const addAnswer = document.createElement("div");
        addAnswer.className = "item-question-answer-add";
        addAnswer.innerText = "添加答案选项";
        addAnswer.onclick = () => {
            const num = answerBox.querySelectorAll(
                ".item-question-answer-item"
            ).length;
            if (limited !== 0 && num === limited) {
                addAnswer.style.display = "none";
                return;
            }

            const answer = addTextAnswer(
                { text: "", isChecked: false },
                num,
                isSelect
            );
            answerBox.insertBefore(answer, addAnswer);

            answerBox.querySelectorAll(".item-question-answer-item").length ===
            limited
                ? (addAnswer.style.display = "none")
                : "";
        };
        answerBox.append(addAnswer);
        value.length === limited ? (addAnswer.style.display = "none") : "";

        return result;
    }
