    public hotSpotText(
        label: string,
        value: { title: string; content: string; show?: boolean },
        parent?: HTMLElement,
        extra?: {
            titlePlaceholder: string;
            valuePlaceholder: string;
        }
    ) {
        if (!extra) {
            extra = {
                titlePlaceholder: "",
                valuePlaceholder: "",
            };
        }
        if (!value) {
            value = { title: "", content: "", show: false };
        }
        let orginValue = cloneDeep(value);
        orginValue["show"] = false;
        const hotSpotTextBox = document.createElement("div");
        hotSpotTextBox.className = "item-hotspot";
        // 热点单项的大标题
        const hotSpotTextLabel = document.createElement("div");
        hotSpotTextLabel.className = "item-hotspot-lable";
        hotSpotTextLabel.innerHTML = label;
        hotSpotTextBox.append(hotSpotTextLabel);
        // 创建功能区盒子
        const hotSpotTextContent = document.createElement("div");
        hotSpotTextContent.className = "item-hotspot-content";
        hotSpotTextBox.append(hotSpotTextContent);

        // 热点单项的提示文字
        const hotSpotTextTitle = document.createElement("div");
        hotSpotTextTitle.className = "item-hotspot-title";
        hotSpotTextTitle.innerHTML = "添加" + label;
        const hotSpotTextEditButton = document.createElement("div");
        hotSpotTextEditButton.className = "item-hotspot-btn";
        hotSpotTextEditButton.innerHTML = "编辑";
        const editBox = document.createElement("div");
        editBox.className = "item-hotspot-edit-box";
        editBox.append(hotSpotTextTitle);
        editBox.append(hotSpotTextEditButton);
        hotSpotTextContent.append(editBox);
        hotSpotTextEditButton.onclick = () => {
            editBox.style.display = "none";
            inputContainer.style.display = "flex";
        };
        // 热点单项的提示文字
        const hotSpotTextTitleTitle = document.createElement("div");
        hotSpotTextTitleTitle.className = "item-hotspot-title";
        hotSpotTextTitleTitle.innerHTML = "标题";
        const inputBox = document.createElement("div");
        inputBox.className = "item-hotspot-title-input-box";
        const hotSpotTextTitleTitleInput = document.createElement("input");
        hotSpotTextTitleTitleInput.className = "item-hotspot-title-input";
        hotSpotTextTitleTitleInput.placeholder =
            extra.titlePlaceholder || "输入标题";
        inputBox.append(hotSpotTextTitleTitleInput);

        hotSpotTextTitleTitleInput.onchange = (e) => {
            let target = e.target as HTMLInputElement;
            orginValue.title = target.value;
            result.value = cloneDeep(orginValue);
        };
        const inputContainer = document.createElement("div");
        inputContainer.className = "item-hotspot-input-container";
        inputContainer.append(hotSpotTextTitleTitle);
        inputContainer.append(inputBox);
        inputContainer.style.display = "none";
        hotSpotTextContent.append(inputContainer);

        // 热点单项的提示文字
        const hotSpotTextTextTitle = document.createElement("div");
        hotSpotTextTextTitle.className = "item-hotspot-title";
        hotSpotTextTextTitle.innerHTML = "编辑" + label;
        const textareaBox = document.createElement("div");
        textareaBox.className = "item-hotspot-title-textarea-box";
        const hotSpotTextArea = document.createElement("textarea");
        hotSpotTextArea.className = "item-hotspot-title-textarea";
        hotSpotTextArea.placeholder = extra.valuePlaceholder || "输入文字";
        textareaBox.append(hotSpotTextArea);
        hotSpotTextArea.onchange = (e) => {
            let target = e.target as HTMLInputElement;
            orginValue.content = target.value;
            result.value = cloneDeep(orginValue);
            
        };
        inputContainer.append(hotSpotTextTextTitle);
        inputContainer.append(textareaBox);
        const hotSpotTextCancelButton = document.createElement("div");
        hotSpotTextCancelButton.className = "item-hotspot-btn";
        hotSpotTextCancelButton.innerHTML = "放弃内容";
        inputContainer.append(hotSpotTextCancelButton);
        if (orginValue.title && orginValue.content) {
            inputContainer.style.display = "flex";
            editBox.style.display = "none";
            hotSpotTextArea.value = orginValue.title;
            hotSpotTextTitleTitleInput.value = orginValue.content;
            orginValue.show = true;
        }
        hotSpotTextCancelButton.onclick = () => {
            hotSpotTextArea.value = "";
            hotSpotTextTitleTitleInput.value = "";
            result.value = {
                title: "",
                content: "",
            };
            editBox.style.display = "flex";
            inputContainer.style.display = "none";
            orginValue.show = false;

        };
        if (parent) {
            parent.append(hotSpotTextBox);
        }
        const result = this.createResult(
            value,
            (path, value) => {},
            hotSpotTextBox
        );
        result.onchange = (path, value) => {
            if (path.includes("title") && value) {
                inputContainer.style.display = "flex";
                editBox.style.display = "none";
                hotSpotTextTitleTitleInput.value = value;
            }else if(path.includes("title") && !value){
                hotSpotTextTitleTitleInput.value = value;
            }
            if (path.includes("content") && value) {
                inputContainer.style.display = "flex";
                editBox.style.display = "none";
                hotSpotTextArea.value = value;
            }else if(path.includes("content") && !value){
                hotSpotTextArea.value = value;
            }
            const data = cloneDeep(result.value);
            if (!data.title && !data.content && orginValue.show) {
                inputContainer.style.display = "flex";
                editBox.style.display = "none";
                hotSpotTextArea.value = "";
                hotSpotTextTitleTitleInput.value = "";
            }
        };
        return result;
    }
