import { VeryCamera } from "../middleware/VeryCamera";
import { VeryEngine,DataType} from "../engine";
import { Tools } from "../utility/Tools";
import { IEDTransform } from "./IEDTransform";
import { ATTRIB, IEDAttrib,addEntityClass } from "../engine/IEDProxy";

@addEntityClass
export class IEDCamera extends IEDTransform{
 
    public cameraGizmo:BABYLON.CameraGizmo;

    protected dispose(): void {
        this.sceneObj.dispose();
        if(this.cameraGizmo)
            this.cameraGizmo.dispose();
    }

    public sceneObj:VeryCamera; 

    public get type(): string {
        return "camera"
    }

    async Load(){
        if(this.subtype==='sceneCamera'){
            this.sceneObj = this.createSceneCameraWraper(this.name,VeryEngine.scene, VeryEngine.canvas);
        }else{
            this.sceneObj=this.createCameraWraper(this.name,VeryEngine.scene, VeryEngine.canvas);
        }
        if(!VeryEngine.EditMode){
            if(!VR.GameGlobal.cameras){
                VR.GameGlobal.cameras=[];
            }
            VR.GameGlobal.cameraDic[this.id]=this.sceneObj
            VR.GameGlobal.cameras.push(this.sceneObj);
            VR.GameGlobal.cameraClearcolors[this.sceneObj.camera.name] = this.sceneObj.clearColor;
        }
        this.sceneObj.id = this.id;
        // 先不要渲染出来
        if(VeryEngine.EditMode){
            this.sceneObj.renderCamera(false);
            this.cameraGizmo = new BABYLON.CameraGizmo();
            this.cameraGizmo.scaleRatio = 1;
            this.cameraGizmo.camera = this.sceneObj.camera;
            this.cameraGizmo.displayFrustum=false;
            this.cameraGizmo._rootMesh.getScene().onPointerObservable.add((e) => {
                let result=e.pickInfo;
                if (result && result.hit){
                    if(result.pickedMesh.isDescendantOf(this.cameraGizmo._rootMesh))
                    VeryEngine.pickEntity(this.id,e.event.ctrlKey)
                }
                e.stopPropagation();
            },BABYLON.PointerEventTypes.POINTERUP);
        }
    }
    private cameraTitle="摄像机属性";

    public isEnabled:IEDAttrib<DataType.Bool>={
        name:"激活",
        type:DataType.Bool,
        onchange(this:IEDCamera,val){
            this.sceneObj.setEnabled(val);
            if(VeryEngine.EditMode){
                this.cameraGizmo._rootMesh.setEnabled(val);
            }
        },
        default:true
    }
    @ATTRIB()
    public inertia={
        onchange(this:IEDCamera,val:number){
            this.sceneObj.inertia=val;
        },
        default:0.9
    }
    
    @ATTRIB()
    public clearColor:IEDAttrib<DataType.Color4>={
        name:"相机背景色",
        type:DataType.Color4,
        onchange(this:IEDCamera,val){
            this.sceneObj.clearColor=BABYLON.Color4.FromArray(val)
        },
        default:[0.176,0.568,0.73,1],
        title:this.cameraTitle
    }

    @ATTRIB()
    public mode:IEDAttrib<DataType.DropDown>={
        name:"相机类型",
        type:DataType.DropDown,
        onchange(this:IEDCamera,val){
            this.sceneObj.mode = val;
            if(val==0){
                this.sceneObj.fov = Tools.eulerAngleFloatToRadian(this.get("fov"));
            }else{
                this.sceneObj.orthoSize = this.get("orthoSize")
            }
        },
        extra:["透视相机","正交相机"],
        title:this.cameraTitle
    }

    @ATTRIB()
    public fov:IEDAttrib<DataType.Slide>={
        name:"视野角度",
        type:DataType.Slide,
        onchange(this:IEDCamera,val){
            this.sceneObj.fov = Tools.eulerAngleFloatToRadian(val);
        },
        default:46,
        extra:{max:90},
        filter(){
            return !this.get("mode")
        },
        title:this.cameraTitle
    }

    @ATTRIB()
    public orthoSize:IEDAttrib<DataType.Number>={
        name:"视野宽度",
        type:DataType.Number,
        onchange(this:IEDCamera,val,isFirst){
            if(!isFirst)
            this.sceneObj.orthoSize = val;
        },
        default:0.5,
        filter(){
            return this.get("mode")==1
        },
        title:this.cameraTitle
    }

    @ATTRIB()
    public viewport:IEDAttrib<DataType.Vector4>={
        name:"视窗大小",
        type:DataType.Vector4,
        onchange(this:IEDCamera,arr:number[]){
            this.sceneObj.viewport = new BABYLON.Viewport(arr[0], arr[1], arr[2], arr[3]);
        },
        default:[0,0,1,1],
        title:this.cameraTitle
    }

    @ATTRIB()
    public minZ:IEDAttrib<DataType.Number>={
        name:"近平面",
        type:DataType.Number,
        onchange(this:IEDCamera,val){
            this.sceneObj.minZ = val;
        },
        default:0.1,
        title:this.cameraTitle
    }
    @ATTRIB()
    public maxZ:IEDAttrib<DataType.Number>={
        name:"远平面",
        type:DataType.Number,
        onchange(this:IEDCamera,val){
            this.sceneObj.maxZ = val;
        },
        default:2000000,
        title:this.cameraTitle
    }

    @ATTRIB()
    public applyGravity:IEDAttrib<DataType.Bool>={
        name:"启用重力",
        type:DataType.Bool,
        onchange(this:IEDCamera,val){
            this.sceneObj.applyGravity = val;
        },
        default:true,
        title:this.cameraTitle
    }

    private createSceneCameraWraper(name: string, scene: BABYLON.Scene, canvas: HTMLCanvasElement): VeryCamera {
        var tmpCamera = new BABYLON.UniversalCamera(name, new BABYLON.Vector3(0, 0, 0), scene);
        tmpCamera.attachControl(canvas, true);
        //按键
        tmpCamera.keysUp.push(87);
        tmpCamera.keysDown.push(83);
        tmpCamera.keysLeft.push(65);
        tmpCamera.keysRight.push(68);
        let cameraWraper = new VeryCamera(tmpCamera, scene, canvas,!VeryEngine.EditMode);
        return cameraWraper;
    }

    private createCameraWraper(name: string, scene: BABYLON.Scene, canvas: HTMLCanvasElement): VeryCamera {
        var camera = new BABYLON.UniversalCamera(name, new BABYLON.Vector3(0, 100, -200), scene);
        let cameraWraper = new VeryCamera(camera, scene, canvas);
        return cameraWraper;
    }
}

@addEntityClass
export class SceneCamera  extends IEDCamera{

    public get subtype(): string {
        return "sceneCamera"
    }

    private sceneTitle="漫游属性"

    public rotation:IEDAttrib<DataType.Vector3>={
        name:"角度",
        type:DataType.Vector3,
        onchange(this:SceneCamera,val){
            if(!VeryEngine.EditMode)
            this.sceneObj.camera.rotation = Tools.eulerAngleToRadian(BABYLON.Vector3.FromArray(val));
            else
            this.sceneObj.rotation=Tools.eulerAngleToRadian(BABYLON.Vector3.FromArray(val));

        }
    }

    @ATTRIB()
    public ellipsoid:IEDAttrib<DataType.Vector3>={
        name:"碰撞体大小",
        type:DataType.Vector3,
        onchange(this:SceneCamera,val){
            this.sceneObj.ellipsoid = BABYLON.Vector3.FromArray(val);
        },
        default:[0.5, 1, 0.5],
        title:this.sceneTitle
    }

    @ATTRIB()
    public speed:IEDAttrib<DataType.Number>={
        name:"移动速度",
        type:DataType.Number,
        onchange(this:SceneCamera,val){
            this.sceneObj.speed =val;
        },
        default:10,
        title:this.sceneTitle
    }

    @ATTRIB()
    public angularSensibility:IEDAttrib<DataType.Number>={
        name:"旋转速度",
        type:DataType.Number,
        onchange(this:SceneCamera,val){
            this.sceneObj.angularSensibility =val;
        },
        default:1,
        title:this.sceneTitle
    }

    @ATTRIB()
    public checkCollisions:IEDAttrib<DataType.Bool>={
        name:"碰撞检测",
        type:DataType.Bool,
        onchange(this:SceneCamera,val){
            this.sceneObj.checkCollisions =val;
        },
        default:true,
        title:this.sceneTitle
    }
}
