import {  IEDAsset} from ".";
import { VeryEngine,DataType} from "../engine";
import { ATTRIB, BUTTON, IEDAttrib, IEDButton, addAssetClass } from "../engine/IEDProxy";

@addAssetClass
export class IEDMirrorTexture extends IEDAsset{

    public get type(): string {
        return "texture_mirror"
    }

    public get suffix(): string[] {
        return ["mirror"];
    }

    public assetObj: BABYLON.MirrorTexture;
    private _baseTexture: Nullable<BABYLON.BaseTexture> = null;
    public get BaseTexture(): Nullable<BABYLON.BaseTexture> {
        return this._baseTexture;
    }
    public set BaseTexture(val: Nullable<BABYLON.BaseTexture>) {
        this._baseTexture = val;
    }

    protected async Load() {
        const mirror = new BABYLON.MirrorTexture(this.name, 1024, VeryEngine.scene, true);
        this.BaseTexture = mirror;
        this.assetObj=mirror;
    }

    
    public init(): void {
        this.onceOnlyLoad();
    }

    protected dispose(): void {
        this.assetObj = undefined;
        if (this._baseTexture) {
            this._baseTexture.dispose();
        }
    }

    private title="镜面反射贴图";
    @ATTRIB("size")
    public mirrorSize:IEDAttrib<DataType.DropDown>={
        name:"贴图大小",
        extra: ['256', '512', '1024', '2048', '4096'],
        onchange(this:IEDMirrorTexture,val) {
            const size = Math.pow(2, val) * 256;
            this.assetObj.resize(size);
        },
        type:DataType.DropDown,
        default:2,
        title:this.title
    }

    @ATTRIB()
    public level:IEDAttrib<DataType.Number>={
        name:"level",
        onchange(this:IEDMirrorTexture,val) {
            this.assetObj.level=val;
        },
        type:DataType.Number,
        default:1,
        title:this.title
    }

    @ATTRIB()
    public adaptiveBlurKernel:IEDAttrib<DataType.Number>={
        name:"模糊参数",
        onchange(this:IEDMirrorTexture,val) {
            this.assetObj.adaptiveBlurKernel=val;
        },
        type:DataType.Number,
        title:this.title
    }

    @ATTRIB()
    public refreshRate:IEDAttrib<DataType.Number>={
        name:"刷新率",
        onchange(this:IEDMirrorTexture,val) {
            this.assetObj.refreshRate=val;
        },
        type:DataType.Number,
        default:1,
        title:this.title
    }

    @ATTRIB()
    public tag:IEDAttrib<DataType.DropDown>={
        name:"反射物体标签",
        extra:this.getTags,
        type:DataType.DropDown,
        title:this.title,
        default:"empty",
        onchange(this: IEDMirrorTexture, val: string) {
            if (this.assetObj.renderList && this.assetObj.renderList.length > 0) {
                while (this.assetObj.renderList.length > 0) {
                    this.assetObj.renderList.splice(0, 1);
                }
            } else {
                this.assetObj.renderList = [];
            }
            VeryEngine.useTag(val,this.id,"tag",(isAdd, id)=>{
                if (VeryEngine.shareBox.id2Entity[id] ) {
                    if (VeryEngine.shareBox.id2Entity[id].sceneObj instanceof BABYLON.TransformNode) {
                        if (isAdd) {
                            this.linkWithTag(VeryEngine.shareBox.id2Entity[id].sceneObj, this.assetObj);
                        } else {
                            this.unlinkWithTag(VeryEngine.shareBox.id2Entity[id].sceneObj, this.assetObj);
                        }
                    }
                }
            }); 
        }
    }


    @ATTRIB("plane")
    public plane:IEDAttrib<DataType.Vector4>={
        name:"反射平面",
        extra: { pre: ['A', 'B', 'C', 'D'] },
        onchange(this:IEDMirrorTexture,val) {
            this.assetObj.mirrorPlane=BABYLON.Plane.FromArray(val);
        },
        type:DataType.Vector4,
        title:this.title
    }

    @BUTTON
    public pick:IEDButton={
        name:"激活选择反射平面",
        title:this.title,
        action() {
            VeryEngine.hideDiv();
            let func=VeryEngine.scene.onPointerObservable.add((eventData: BABYLON.PointerInfo, eventState: BABYLON.EventState) => {
                if (eventData.type === BABYLON.PointerEventTypes.POINTERUP && eventData.event.button === 0 ) {
                    const rect = VeryEngine.canvas.getBoundingClientRect();
                    let mouse_x = eventData.event.clientX - rect.left;
                    let mouse_y = eventData.event.clientY - rect.top;
    
                    let result = VeryEngine.scene.pick(mouse_x, mouse_y, undefined, undefined, VeryEngine.viewCamera.veryCamera.camera);
    
                    if (result && result.hit && result.pickedMesh) {
                        let normal = result.getNormal();
                        let matrix: BABYLON.Matrix = result.pickedMesh.computeWorldMatrix();
                        let worldNormal = BABYLON.Vector3.TransformCoordinates(normal!, matrix).subtract(result.pickedMesh.getAbsolutePosition());
                        worldNormal = worldNormal.scale(-1);
                        let plane = BABYLON.Plane.FromPositionAndNormal(result.pickedPoint!, worldNormal).normalize();
                        this.set('plane', plane.asArray());
                        VeryEngine.pickAsset(this.id);
                        VeryEngine.showDiv();
                        eventData.stopPropagation()
                        VeryEngine.scene.onPointerObservable.remove(func);
                    }
                }
                eventData.stopPropagation()
            })
        },
    }

    private getTags(val: string) {
        let tmp = { "empty": "默认:空" };
        for (let key in VeryEngine.systemTags) {
            tmp[key] = key;
        }
        if (val && !(val in tmp)) {
            tmp[val] = val;
        }
        return tmp;
    }

    private linkWithTag(node: BABYLON.TransformNode | BABYLON.AbstractMesh, cubemap: BABYLON.RenderTargetTexture) {
        if (node instanceof BABYLON.AbstractMesh) {
            let ind = cubemap.renderList!.indexOf(node);
            if (ind === -1) {
                cubemap.renderList!.push(node);
            }
        }
        if (node.getChildren()) {
            let children = node.getChildren();
            for (let i = 0; i < children.length; i++) {
                if (children[i] instanceof BABYLON.TransformNode) {
                    this.linkWithTag(<BABYLON.TransformNode>children[i], cubemap);
                } else if (children[i] instanceof BABYLON.AbstractMesh) {
                    this.linkWithTag(<BABYLON.AbstractMesh>children[i], cubemap);
                }
            }
        }
    }

    private unlinkWithTag(node: BABYLON.TransformNode, cubemap: BABYLON.RenderTargetTexture) {
        if (node instanceof BABYLON.AbstractMesh) {
            let ind = cubemap.renderList!.indexOf(node);
            if (ind !== -1) {
                cubemap.renderList!.splice(ind, 1);
            }
        }
        if (node.getChildren()) {
            let children = node.getChildren();
            for (let i = 0; i < children.length; i++) {
                if (children[i] instanceof BABYLON.TransformNode) {
                    this.unlinkWithTag(<BABYLON.TransformNode>children[i], cubemap);
                } else if (children[i] instanceof BABYLON.AbstractMesh) {
                    this.unlinkWithTag(<BABYLON.AbstractMesh>children[i], cubemap);
                }
            }
        }
    }
}