import { IEDMaterial } from "./IEDMaterial";
import { addAssetClass } from "../../engine/IEDProxy";
import { VeryEngine, DataType } from "../../engine";
import { IEDAttrib, ATTRIB } from "../../engine/IEDProxy";

@addAssetClass
export abstract class IEDMultiMaterial extends IEDMaterial {

    public get subtype(): string {
        return "Babylon.MultiMaterial"
    }

    public assetObj: BABYLON.MultiMaterial;
    private materialList: IEDMaterial[] = [];
    protected async Load() {
        let materials = this.data.get("materials").jsonParse();
        this.assetObj = new BABYLON.MultiMaterial(this.name, VeryEngine.scene);
        for (let k = 0; k < materials.length; k++) {
            let subMaterialAssetID = IEDMaterial.matID2AssetID[materials[k]];
            if (subMaterialAssetID && VeryEngine.shareBox.id2Asset[subMaterialAssetID]) {
                await VeryEngine.shareBox.id2Asset[subMaterialAssetID].onceOnlyLoad();
                this.materialList.push(VeryEngine.shareBox.id2Asset[subMaterialAssetID] as IEDMaterial);
                (this.assetObj as BABYLON.MultiMaterial).subMaterials.push(VeryEngine.shareBox.id2Asset[subMaterialAssetID].assetObj);
            }
        }
        //todo 复合材质球添加依赖子材质球关系，当子材质球发生变动时，需要重新生成复合材质球的贴图
    }

    public export(vrData: any, file: any[]): void {
        let json = this.data.jsonParse();
        let materials = json["materials"];
        vrData.multiMaterials.push(json);
        for (let k = 0; k < materials.length; k++) {
            let subMaterialAssetID = IEDMaterial.matID2AssetID[materials[k]]
            if (subMaterialAssetID) {
                if (VeryEngine.shareBox.id2Asset[subMaterialAssetID]) {
                    VeryEngine.shareBox.id2Asset[subMaterialAssetID].export(vrData, file);
                }
            }
        }
    }

    @ATTRIB("name")
    public attrNameStr: IEDAttrib<DataType.String> = {
        type: DataType.String,
        name: "名字",
    }

    @ATTRIB("data.backFaceCulling")
    public backFaceCulling: IEDAttrib<DataType.Bool> = {
        name: "背面隐藏",
        type: DataType.Bool,
        onchange(this: IEDMultiMaterial, val: boolean, a) {
            if (!a) {
                this.assetObj.backFaceCulling = val;
                for (let mat of this.materialList) {
                    mat.set("data.backFaceCulling", val);
                }
                this.preview();
            }
        },
        default: true
    }

    @ATTRIB("data.needDepthPrePass")
    public needDepthPrePass: IEDAttrib<DataType.Bool> = {
        name: "深度值预先计算",
        type: DataType.Bool,
        onchange(this: IEDMultiMaterial, val: boolean, a) {
            if (!a) {
                this.assetObj.needDepthPrePass = val;
                for (let mat of this.materialList) {
                    mat.set("data.needDepthPrePass", val);
                }
                this.preview();
            }
        },
        default: true
    }

    @ATTRIB("data.alpha")
    public alpha: IEDAttrib<DataType.Slide> = {
        name: "透明度",
        type: DataType.Slide,
        onchange(this: IEDMultiMaterial, val: number, a) {
            if (!a) {
                this.assetObj.alpha = val;
                for (let mat of this.materialList) {
                    mat.set("data.alpha", val);
                }
                this.preview();
            }
        },
        default: 1
    }

    @ATTRIB("data.transparencyMode")
    public transparencyMode: IEDAttrib<DataType.DropDown> = {
        name: "透明度模式",
        type: DataType.DropDown,
        onchange(this: IEDMultiMaterial, val: number) {
            this.assetObj.transparencyMode = val;
            for (let mat of this.materialList) {
                mat.set("data.transparencyMode", val);
            }
            this.preview();
        },
        default: -1,
        extra: ['NULL', 'OPAQUE', 'ALPHATEST', 'ALPHABLEND', 'ALPHATESTANDBLEND'],
    }

    @ATTRIB("data.alphaMode")
    public alphaMode: IEDAttrib<DataType.DropDown> = {
        name: "Alpha模式",
        type: DataType.DropDown,
        onchange(this: IEDMultiMaterial, val: number, a) {
            if (!a) {
                this.assetObj.alphaMode = val;
                for (let mat of this.materialList) {
                    mat.set("data.alphaMode", val);
                }
                this.preview();
            }
        },
        extra: ['DISABLE', 'ADD', 'COMBINE', 'SUBTRACT', 'MULTIPAY', 'MAXIMIZED', 'ONEONE', 'PREMULTIPAIED',
            'PREMULTIPAIED_PORTERDUFF', 'INTERPPOLATE', 'SCREENMODE'],
        default: 2
    }


    protected other = "其他"
    @ATTRIB("data.sideOrientation")
    public sideOrientation: IEDAttrib<DataType.DropDown> = {
        name: "面朝向",
        type: DataType.DropDown,
        onchange(this: IEDMultiMaterial, val, a) {
            if (!a) {
                this.assetObj.sideOrientation = val
                for (let mat of this.materialList) {
                    mat.set("data.sideOrientation", val);
                }
                this.preview();
            }
        },
        extra: ["顺时针", "逆时针"],
        title: this.other,
        default: 1
    }

    @ATTRIB("data.zOffset")
    public zOffset: IEDAttrib<DataType.Number> = {
        name: "zOffset",
        type: DataType.Number,
        onchange(this: IEDMultiMaterial, val, a) {
            if (!a) {
                this.assetObj.zOffset = val
                for (let mat of this.materialList) {
                    mat.set("data.zOffset", val);
                }
                this.preview();
            }
        },
        title: this.other,
        default: 0
    }

    @ATTRIB("data.zOffsetUnits")
    public zOffsetUnits: IEDAttrib<DataType.Number> = {
        name: "zOffsetUnits",
        type: DataType.Number,
        onchange(this: IEDMultiMaterial, val, a) {
            if (!a) {
                this.assetObj.zOffsetUnits = val
                for (let mat of this.materialList) {
                    mat.set("data.zOffsetUnits", val);
                }
                this.preview();
            }
        },
        title: this.other,
        default: 0
    }

    @ATTRIB("data.wireframe")
    public wireframe: IEDAttrib<DataType.Bool> = {
        name: "wireframe",
        type: DataType.Bool,
        onchange(this: IEDMultiMaterial, val, a) {
            if (!a) {
                this.assetObj.wireframe = val
                for (let mat of this.materialList) {
                    mat.set("data.wireframe", val);
                }
                this.preview();
            }
        },
        title: this.other,
    }

    @ATTRIB("data.separateCullingPass")
    public separateCullingPass: IEDAttrib<DataType.Bool> = {
        name: "separateCullingPass",
        type: DataType.Bool,
        onchange(this: IEDMultiMaterial, val, a) {
            if (!a) {
                this.assetObj.separateCullingPass = val
                for (let mat of this.materialList) {
                    mat.set("data.separateCullingPass", val);
                }
                this.preview();
            }
        },
        title: this.other,
    }

    @ATTRIB("data.disableColorWrite")
    public disableColorWrite: IEDAttrib<DataType.Bool> = {
        name: "disableColorWrite",
        type: DataType.Bool,
        onchange(this: IEDMultiMaterial, val, a) {
            if (!a) {
                this.assetObj.disableColorWrite = val
                for (let mat of this.materialList) {
                    mat.set("data.disableColorWrite", val);
                }
                this.preview();
            }
        },
        title: this.other,
    }

    @ATTRIB("data.disableDepthWrite")
    public disableDepthWrite: IEDAttrib<DataType.Bool> = {
        name: "disableDepthWrite",
        type: DataType.Bool,
        onchange(this: IEDMultiMaterial, val, a) {
            if (!a) {
                this.assetObj.disableDepthWrite = val
                for (let mat of this.materialList) {
                    mat.set("data.disableDepthWrite", val);
                }
                this.preview();
            }
        },
        title: this.other,
    }

    @ATTRIB("data.forceDepthWrite")
    public forceDepthWrite: IEDAttrib<DataType.Bool> = {
        name: "forceDepthWrite",
        type: DataType.Bool,
        onchange(this: IEDMultiMaterial, val, a) {
            if (!a) {
                this.assetObj.forceDepthWrite = val
                for (let mat of this.materialList) {
                    mat.set("data.forceDepthWrite", val);
                }
                this.preview();
            }
        },
        title: this.other,
    }
}

