import { VeryEngine } from "../engine/VeryEngine";

export class VeryLight extends BABYLON.TransformNode {


    public light: BABYLON.Light;

    public get type(): number {
        return this.light.getTypeID();
    }

    public get intensity(): number {
        return this.light.intensity;
    }
    public set intensity(value: number) {
        this.light.intensity = value;
    }

    public get diffuse(): BABYLON.Color3 {
        return this.light.diffuse;
    }
    public set diffuse(value: BABYLON.Color3) {
        this.light.diffuse = value;
    }

    public get specular(): BABYLON.Color3 {
        return this.light.specular;
    }
    public set specular(value: BABYLON.Color3) {
        this.light.specular = value;
    }

    public get angle(): number {
        if (this.light instanceof BABYLON.SpotLight) {
            return this.light.angle;
        } else {
            return 0;
        }
    }
    public set angle(value: number) {
        if (this.light instanceof BABYLON.SpotLight) {
            this.light.angle = value;
        }
    }

    public get exponent(): number {
        if (this.light instanceof BABYLON.SpotLight) {
            return this.light.exponent;
        } else {
            return 0;
        }
    }
    public set exponent(value: number) {
        if (this.light instanceof BABYLON.SpotLight) {
            this.light.exponent = value;
        }
    }


    public constructor(light: BABYLON.Light, scene: BABYLON.Scene) {
        super(light.name, scene);
        light.name += '-Light';
        // light
        this.light = light;
        this.position.copyFrom(light.getAbsolutePosition());
        // this.rotation = BABYLON.Vector3.Zero();
        if(VeryEngine.EditMode){
            if(this.type==BABYLON.Light.LIGHTTYPEID_POINTLIGHT){
                this.createPointLightMesh(BABYLON.UtilityLayerRenderer.DefaultUtilityLayer.utilityLayerScene).parent=this;
            }else if(this.type==BABYLON.Light.LIGHTTYPEID_DIRECTIONALLIGHT){
                this.createDirectionalLightMesh(BABYLON.UtilityLayerRenderer.DefaultUtilityLayer.utilityLayerScene).parent=this;
            }else if(this.type==BABYLON.Light.LIGHTTYPEID_HEMISPHERICLIGHT){
                this.createHemisphericLightMesh(BABYLON.UtilityLayerRenderer.DefaultUtilityLayer.utilityLayerScene).parent=this;
            }else{
                this.createSpotLightMesh(BABYLON.UtilityLayerRenderer.DefaultUtilityLayer.utilityLayerScene).parent=this;
            }
        }
        light.parent = this;
    }

    public dispose() {
        if(this.light) {
            this.light.dispose();
        }
        super.dispose();
    }

    private createHemisphericLightMesh(scene: BABYLON.Scene) {
        var root = new BABYLON.Mesh("hemisphereLight", scene);
        var hemisphere = BABYLON.HemisphereBuilder.CreateHemisphere(root.name, { segments: 10, diameter: 1 }, scene);
        hemisphere.position.z = -0.15;
        hemisphere.rotation.x = Math.PI / 2;
        hemisphere.parent = root;

        var lines = this.createLightLines(3, scene);
        lines.parent = root;
        lines.position.z - 0.15;

        root.scaling.scaleInPlace(0.07);
        root.rotation.x = Math.PI / 2;
        this.update(root,scene);
        return root;
    }

    private createPointLightMesh(scene: BABYLON.Scene) {
        var root = new BABYLON.Mesh("pointLight", scene);
        var sphere = BABYLON.SphereBuilder.CreateSphere(root.name, { segments: 10, diameter: 1 }, scene);
        sphere.rotation.x = Math.PI / 2;
        sphere.parent = root;

        var lines = this.createLightLines(5, scene);
        lines.parent = root;
        root.scaling.scaleInPlace(0.07);
        root.rotation.x = Math.PI / 2;
        this.update(root,scene);
        return root;
    }

    private createSpotLightMesh(scene: BABYLON.Scene) {
        var root = new BABYLON.Mesh("spotLight", scene);
        var sphere = BABYLON.SphereBuilder.CreateSphere(root.name, { segments: 10, diameter: 1 }, scene);
        sphere.parent = root;

        var hemisphere = BABYLON.HemisphereBuilder.CreateHemisphere(root.name, { segments: 10, diameter: 2 }, scene);
        hemisphere.parent = root;
        hemisphere.rotation.x = -Math.PI / 2;

        var lines = this.createLightLines(2, scene);
        lines.parent = root;
        root.scaling.scaleInPlace(0.07);
        root.rotation.x = Math.PI / 2;
        this.update(root,scene);
        return root;
    }

    private createDirectionalLightMesh(scene: BABYLON.Scene) {
        var root = new BABYLON.Mesh("directionalLight", scene);

        var mesh = new BABYLON.Mesh(root.name, scene);
        mesh.parent = root;
        var sphere = BABYLON.SphereBuilder.CreateSphere(root.name, { diameter: 1.2, segments: 10 }, scene);
        sphere.parent = mesh;

        var line = BABYLON.Mesh.CreateCylinder(root.name, 6, 0.3, 0.3, 6, 1, scene);
        line.parent = mesh;

        var left = line.clone(root.name)!;
        left.scaling.y = 0.5;
        left.position.x += 1.25;

        var right = line.clone(root.name)!;
        right.scaling.y = 0.5;
        right.position.x += -1.25;

        var arrowHead = BABYLON.Mesh.CreateCylinder(root.name, 1, 0, 0.6, 6, 1, scene);
        arrowHead.position.y += 3;
        arrowHead.parent = mesh;

        var left = arrowHead.clone(root.name);
        left.position.y = 1.5;
        left.position.x += 1.25;

        var right = arrowHead.clone(root.name);
        right.position.y = 1.5;
        right.position.x += -1.25;

        mesh.scaling.scaleInPlace(0.07);
        mesh.rotation.z = Math.PI / 2;
        mesh.rotation.y = Math.PI / 2;
        this.update(mesh,scene);
        return root;
    }

    private update(root:BABYLON.AbstractMesh,scene:BABYLON.Scene){
        scene.onBeforeRenderObservable.add(() => {
            let rate=VeryEngine.viewCamera.Camera.globalPosition.subtract(this.getAbsolutePosition()).length()*0.01;
            root.scaling.set(rate, rate, rate);
        });
        scene.onPointerObservable.add((e) => {
            let result=e.pickInfo;
            if (result && result.hit){
                if(result.pickedMesh.isDescendantOf(this)){
                    VeryEngine.pickEntity(this.id,e.event.ctrlKey);
                    e.stopPropagation();
                }
            }
        },BABYLON.PointerEventTypes.POINTERUP);
        let material=new BABYLON.StandardMaterial("light",scene);
        material.emissiveColor = new BABYLON.Color3(0.9, 0.9, 0.9);
        material.diffuseColor=new BABYLON.Color3(0,0,0);
        material.specularColor=new BABYLON.Color3(0,0,0);
        material.ambientColor=new BABYLON.Color3(0,0,0);
        root.getChildMeshes(false).forEach((m) => {
            m.material = material;
        });
    }

    private createLightLines = (levels: number, scene: BABYLON.Scene) => {
        var distFromSphere = 1.2;

        var root = new BABYLON.Mesh("root", scene);
        root.rotation.x = Math.PI / 2;

        // Create the top line, this will be cloned for all other lines
        var linePivot = new BABYLON.Mesh("linePivot", scene);
        linePivot.parent = root;
        var line = BABYLON.Mesh.CreateCylinder("line", 2, 0.2, 0.3, 6, 1, scene);
        line.position.y = line.scaling.y / 2 + distFromSphere;
        line.parent = linePivot;

        if (levels < 2) {
            return linePivot;
        }
        for (var i = 0; i < 4; i++) {
            var l = linePivot.clone("lineParentClone")!;
            l.rotation.z = Math.PI / 4;
            l.rotation.y = (Math.PI / 2) + (Math.PI / 2 * i);

            l.getChildMeshes()[0].scaling.y = 0.5;
            l.getChildMeshes()[0].scaling.x = l.getChildMeshes()[0].scaling.z = 0.8;
            l.getChildMeshes()[0].position.y = l.getChildMeshes()[0].scaling.y / 2 + distFromSphere;
        }

        if (levels < 3) {
            return root;
        }
        for (var i = 0; i < 4; i++) {
            var l = linePivot.clone("linePivotClone");
            l.rotation.z = Math.PI / 2;
            l.rotation.y = (Math.PI / 2 * i);
        }

        if (levels < 4) {
            return root;
        }
        for (var i = 0; i < 4; i++) {
            var l = linePivot.clone("linePivotClone");
            l.rotation.z = Math.PI + (Math.PI / 4);
            l.rotation.y = (Math.PI / 2) + (Math.PI / 2 * i);

            l.getChildMeshes()[0].scaling.y = 0.5;
            l.getChildMeshes()[0].scaling.x = l.getChildMeshes()[0].scaling.z = 0.8;
            l.getChildMeshes()[0].position.y = l.getChildMeshes()[0].scaling.y / 2 + distFromSphere;
        }

        if (levels < 5) {
            return root;
        }
        var l = linePivot.clone("linePivotClone");
        l.rotation.z = Math.PI;

        return root;
    }
}