import { AbstractType } from "./AbstractType";
import {ID, Item} from "../content/Item";
import {AbstractContent, ContentAny,ContentType} from "../content";
import { Doc } from "./Doc";
import { VeryEngine } from "../../engine/VeryEngine";
import { DArray } from "./DArray";

export class DMap extends AbstractType{
  private _prelimContent:Map<string,any>=null;

  constructor (entries?:any) {
      super()
      if (entries === undefined) {
          this._prelimContent = new Map()
      } else {
        this._prelimContent = new Map();
        for(let key in entries){
          if(typeof (entries[key]) == 'object'){
            if(Object.prototype.toString.call(entries[key]).toLowerCase() == "[object object]")
              this._prelimContent.set(key,new DMap(entries[key]))
            else if(Object.prototype.toString.call(entries[key]).toLowerCase() == "[object array]"){
              if(DArray.isArray(key)){
                this._prelimContent.set(key,new DArray(entries[key]));
              }else{
                this._prelimContent.set(key,entries[key])
              }
            }
          }else{
            this._prelimContent.set(key,entries[key]);
          }
        }
      }
  }

  public get refID(){
    return 1
  }

  [Symbol.iterator](){
    return this._map.keys();
  }

  //获取具体属性，非操作
  public get(key:string){
    if(this._prelimContent&&this._prelimContent.size!=0)
      return this._prelimContent.get(key);
    let item=this.mapGet(key);
    return item&&!item.deleted?item.content.value():null;
  }
  private timeStamp:{[key:string]:{start:number,last:number,timer?:NodeJS.Timer}}={};
  public set (key:string, value:any,ischild?:boolean,config?:{isNetwork?:boolean,undoStack?:boolean,group?:string}) {
    if(this.doc){
      let item=this.mapGet(key);
      if(VeryEngine.EditMode&&item&&!item.deleted){
        let old=item.content.value();
        if(value==old) return;
        if(value instanceof Array&&value.length<5&&value.length==old.length){
          let result=true;
          for(let i=0;i<value.length;i++){
            if(value[i]!=old[i]){
              result=false; break;
            }
          }
          if(result) return;
        }
      }
      let now=new Date().getTime();
      let isType=false;
      if(value instanceof AbstractType) isType=true;
      else if(Object.prototype.toString.call(value) == '[object Object]') isType=true;
      else if(Object.prototype.toString.call(value) == '[object Array]'&&DArray.isArray(key)) isType=true;
      if(isType||!this.timeStamp[key]||this.timeStamp[key].last<now-500){
        if(!ischild)
        this.doc.createTranscation("local");
        if(!isType){
          this.timeStamp[key]={start:now,last:now};
        }

        item=this.typeMapSet(key,value);
        if(config&&config.group)
          item.group=config.group;
        item.write();
        item.integrate();
        if(!ischild)
          this.doc.frameEndAndSend(config);
      }else{
        this.timeStamp[key].last=now;
        if(item.id.client===this.doc.clientID){
          item.reset(value);
        }
        if(!this.timeStamp[key].timer){
          this.timeStamp[key].timer=setTimeout(() => {
            if(item.id.client===this.doc.clientID)
              this.createAnyCopy(item);
            this.timeStamp[key].start=new Date().getTime()
            this.timeStamp[key].timer=null;
          }, 500);
        }
      }
    }else{
      this._prelimContent.set(key, value)
    }
  }

  private createAnyCopy(t:Item){
    if(!t.deleted){
      let id=t.id;
      let value=t.content.value();
      let copy= new ContentAny([value]);
      let item=new Item(id,null,null,null,null,this,null,copy);
      item.write();
      if(this.doc.socket){
        this.doc.socket.send();
      }
    }
  }

  public forceTrigger(){
    this.doc.createTranscation("force");
    this.doc.addFrameItem(this._item);
    this.doc.frameEnd();
  }

  public forceDeleteTrigger(){
    let deleted=this._item.deleted;
    this._item.info|=4;
    this.doc.createTranscation("force");
    this.doc.addFrameItem(this._item);
    this.doc.frameEnd();
    if(!deleted)
      this._item.info ^=4;
  }


  //监听对象任意属性改变
  public watchObject(type:"update"|"delete",act:(key:string,value?:any,config?:any)=>void){
    if(type==="update")
      this.mapGlobalAct.update.push(act);
    else
      this.mapGlobalAct.delete.push(act);
  }


  public _integrate (y:Doc, item:Item) {
    super._integrate(y, item);
    if(this._prelimContent){
      this._prelimContent.forEach((value, key) => {
        this.set(key, value,true)
      })
    }
    this._prelimContent = null
  }
  private convertContent(key:string, value:any){
    let content:AbstractContent
    if (value == null) {
      content = new ContentAny([null])
    } else {
      if(value instanceof AbstractType){
        content = new ContentType(value)
      }else if(Object.prototype.toString.call(value) == '[object Object]'){
        content=new ContentType(new DMap(value));
      }else if(Object.prototype.toString.call(value) == '[object Array]'){
        if(DArray.isArray(key)){
          content=new ContentType(new DArray(value))
        }else{
          content = new ContentAny([value])
        }
      }
      else{
        content = new ContentAny([value])
      }
    }
    return content;
  }
  public  typeMapSet(key:string, value:any){
      let left = this.mapGet(key) || null
      let ownClientId = this.doc.clientID
      let content=this.convertContent(key,value);
      return new Item({client:ownClientId,clock:this.doc.getState(ownClientId)}, left, left && left.lastId, null, null, this, key, content);
  }

    //监听指定属性改变
    public watch(key:string,act:(value?:any,old?:any)=>void,group?:string){
      if(!group)
        group="";
      if(!this.mapSetAct[group]){
        this.mapSetAct[group]={};
      }
      if(!this.mapSetAct[group][key])
        this.mapSetAct[group][key]=[act];
      else
      this.mapSetAct[group][key].push(act);
    }
  
    
    public unwatch(group:string){
      if(this.mapSetAct)
        delete this.mapSetAct[group];
    }
    
  public delete (key:string,undo:boolean) {
    if (this.doc !== null) {
      this.doc.createTranscation("local");
      let item=this.mapGet(key);
      if(item&&!item.deleted){
        item.delete();
        item.write();
        this.doc.frameEndAndSend({isNetwork:true,undoStack:undo});
      }
    } else {
      this._prelimContent.delete(key)
    }
  }
}