    @ATTRIB("data.useAlphaFromAlbedoTexture")
    public useAlphaFromAlbedoTexture={
        name:"使用Albedo贴图通道",
        type:DataType.Bool,
        onchange(this:IEDPBRMaterial,val:boolean,isFirst) {
            if(!isFirst){
            this.assetObj.useAlphaFromAlbedoTexture=val;
            this.preview();
            }
        },
    }
