import { addEntityClass, ATTRIB, IEDAttrib, IEDProxyFactory } from "../../engine/IEDProxy";
import { VeryEngine, DataType, IED } from "../../engine";
import { IEDEntity } from "../IEDEntity";
import { IEDKrpano } from "./IEDKrpano";
import { Tools } from "../../utility/Tools";
import { IEDFolder } from "src/assets";
import { KrpanoCategory } from "./IEDKrpanoCategory";
import { KrpanoSceneImage } from "./IEDKrpanoSceneImage";
import { KrpanoSceneVideo } from "./IEDKrpanoSceneVideo";
import { VREvent } from "src/engine/VREvent";
import { cloneDeep } from "lodash";
@addEntityClass
export abstract class KrpanoCanvas extends IEDKrpano {
    public get subtype(): string {
        return "canvas";
    }
    //上一次操作的canvas，创建的ui默认创建在这个canvas下
    // public static lastKrpanoCanvas: KrpanoCanvas;
    // public static lastKrpanoCategory:;
    public static lastKrpanoCanvas: KrpanoCanvas;
    public krpanoInstance;
    public lastTourXml;
    protected currentCatageory:KrpanoCategory
    protected currentScene:KrpanoSceneImage|KrpanoSceneVideo
    public sceneObj: HTMLElement;

    protected realLoad() {}

    public loadEvent = null;
    public filterParentType(parent: IEDKrpano): boolean {
        if (!["krpano"].includes(this.subtype)) {
            if (["krpano"].includes(parent.subtype)) {
                return true;
            } else {
                return false;
            }
        } else {
            if (parent.type == "root") {
                return true;
            } else {
                return false;
            }
        }
    }

    protected async Load(): Promise<void> {
        KrpanoCanvas.lastKrpanoCanvas = this;
        let krpanoGuiBox = document.createElement("div");
        krpanoGuiBox.classList.add("krpano-gui"); // 添加 class
        // 获取layout-toolbar元素，准备把canvas的元素放到它前面
        const parent = document.getElementById("layout-viewport");
        const guibox = parent.querySelector(".layout-gui");
        if (guibox) {
            // 添加 div 元素到父元素前面
            guibox.parentNode.insertBefore(krpanoGuiBox, guibox);
        } else {
            parent.append(krpanoGuiBox);
        }

        this.sceneObj = document.createElement("div");
        this.sceneObj.id = this._data.get("resource_id");
        this.sceneObj.style.pointerEvents = "auto";
        let gui = this.get("gui");
        let divStyle = this.sceneObj.style;
        divStyle.borderStyle = "solid";
        divStyle.position = "absolute";
        krpanoGuiBox.append(this.sceneObj);
        const sceneList = document.createElement("div");
        sceneList.className = "scene-list";

        const sceneItem = document.createElement("div");
        sceneItem.className = "scene-item";

        const sceneContainerBox = document.createElement("div");
        sceneContainerBox.className = "scene-container-box";

        const sceneContainer = document.createElement("div");
        sceneContainer.className = "scene-container";

        sceneContainerBox.appendChild(sceneContainer);
        sceneItem.appendChild(sceneContainerBox);
        sceneList.appendChild(sceneItem);

        const sceneTitle = document.createElement("div");
        sceneTitle.className = "scene-title";

        const sceneTitleContainerBox = document.createElement("div");
        sceneTitleContainerBox.className = "scene-title-container-box";

        const sceneTitleContainer = document.createElement("div");
        sceneTitleContainer.className = "scene-title-container";
        function createSceneItemBox(url, name) {
            const sceneItemBox = document.createElement("div");
            sceneItemBox.className = "scene-item-box";

            const sceneItemTitleBox = document.createElement("div");
            sceneItemTitleBox.className = "scene-item-title-box";

            const sceneItemTitle = document.createElement("div");
            sceneItemTitle.className = "scene-item-title";

            const sceneItemTitleSpan = document.createElement("span");
            sceneItemTitleSpan.textContent = name;

            sceneItemTitle.appendChild(sceneItemTitleSpan);
            sceneItemTitleBox.appendChild(sceneItemTitle);
            sceneItemBox.appendChild(sceneItemTitleBox);
            return sceneItemBox;
        }

        sceneTitleContainerBox.appendChild(sceneTitleContainer);
        sceneTitle.appendChild(sceneTitleContainerBox);
        sceneList.appendChild(sceneTitle);
        setTimeout(() => {
            this.children.forEach((item, index) => {
                const sceneTitleBox = document.createElement("div");
                sceneTitleBox.className = "scene-title-box";
                const sceneTitleTextBox = document.createElement("div");
                sceneTitleTextBox.className = "scene-title-text-box";
                if (index === 0) {
                    sceneTitleTextBox.classList.add("scene-title-selected");
                    item.children.forEach((it, i) => {
                        const sceneItemBox = createSceneItemBox("", it.name);
                        i===0?sceneItemBox.classList.add("scene-item-selected"):""
                        sceneItemBox.onclick = () => {
                            const sceneItemBoxArray = Array.from(sceneContainer.children);
                       
                            sceneItemBoxArray.map((it) => {
                                it.classList.remove("scene-item-selected");
                            });
                            sceneItemBox.classList.add("scene-item-selected");
                            VeryEngine.pickEntity(it.id)
                        };
                        sceneContainer.appendChild(sceneItemBox);
                    });
                }
                const sceneTitleText = document.createElement("div");
                sceneTitleText.className = "scene-title-text";
                sceneTitleText.textContent = item.name;
                sceneTitleTextBox.appendChild(sceneTitleText);
                sceneTitleBox.appendChild(sceneTitleTextBox);
                sceneTitleContainer.appendChild(sceneTitleBox);
                sceneTitleBox.onclick = () => {
                    if(this.currentCatageory===item){
                        return
                    }
                    this.currentCatageory = item as KrpanoCategory
                    const sceneTitleBoxArray = Array.from(sceneTitleContainer.querySelectorAll(".scene-title-text-box"));
                    sceneTitleBoxArray.map((it) => {
                        it.classList.remove("scene-title-selected");
                    });
                    sceneTitleTextBox.classList.add("scene-title-selected");
                    sceneContainer.innerHTML=""
                    item.children.forEach((it, i) => {
                        const sceneItemBox = createSceneItemBox("", it.name);
                        sceneItemBox.onclick = () => {
                            this.currentScene = it as (KrpanoSceneImage|KrpanoSceneVideo)
                            const sceneItemBoxArray = Array.from(sceneContainer.children);
                            sceneItemBoxArray.map((it) => {
                                it.classList.remove("scene-item-selected"); 
                            });
                            sceneItemBox.classList.add("scene-item-selected");
                            VeryEngine.pickEntity(it.id)
                        };
                        sceneContainer.appendChild(sceneItemBox);
                    });
                };
            });
        }, 100);

        this.sceneObj.append(sceneList);
        if (gui) {
            if (gui.get("background")) {
                divStyle.background = Tools.rgba2hsvString(gui.get("background"));
            } else {
                divStyle.background = Tools.rgba2hsvString([1, 1, 1, 0.4]);
            }
        }
        // this.initDraggable();
        OSS.clientOrigin.get(`project/${VeryEngine.projectId}/ALL/vtour/tour.xml`).then((result) => {
            const uint8array = new Uint8Array(result.content);
            const decoder = new TextDecoder("utf-8");
            this.lastTourXml = decoder.decode(uint8array);
        });

        await new Promise<void>((resolve) => {
            setTimeout(async () => {
                // @ts-ignore
                embedpano({
                    // swf: `./vtour/tour.swf`,
                    // xml: `./vtour/tour.xml`,
                    swf: `https://project.veryengine.cn/project/${VeryEngine.projectId}/ALL/vtour/tour.swf`,
                    xml: `https://project.veryengine.cn/project/${VeryEngine.projectId}/ALL/vtour/tour.xml`,
                    target: this._data.get("resource_id"),
                    html5: "only+webgl",
                    id: this._data.get("resource_id") + "krpano",
                    mobilescale: 1.0,
                    passQueryParameters: true,
                    consolelog: true,
                    onready: (a) => {
                        this.krpano_onready_callback(a);
                        console.warn("画好了");
                        resolve();
                    },
                });
            }, 0);
        });
    }
    @ATTRIB("enabled")
    public isEnabled: IEDAttrib<DataType.Bool> = {
        name: "激活",
        type: DataType.Bool,
        onchange(this: KrpanoCanvas, val) {
            (this.sceneObj as HTMLElement).style.display = val ? "flex" : "none";
        },
        default: true,
    };
    @ATTRIB("gui.xType")
    public xType: IEDAttrib<DataType.DropDown> = {
        name: "位置x类型",
        type: DataType.DropDown,
        onchange(this: KrpanoCanvas) {
            this.set2DXY("x");
        },
        extra: ["像素", "百分比", "视窗宽度百分比", "视窗高度百分比"],
    };

    @ATTRIB("gui.x")
    public x: IEDAttrib<DataType.Number> = {
        name: "位置x",
        type: DataType.Number,
        onchange(this: KrpanoCanvas, _, isFirst) {
            if (!isFirst) {
                this.set2DXY("x");
            }
        },
    };

    @ATTRIB("gui.yType")
    public yType: IEDAttrib<DataType.DropDown> = {
        name: "位置y类型",
        type: DataType.DropDown,
        onchange(this: KrpanoCanvas) {
            this.set2DXY("y");
        },
        extra: ["像素", "百分比", "视窗宽度百分比", "视窗高度百分比"],
    };

    @ATTRIB("gui.y")
    public y: IEDAttrib<DataType.Number> = {
        name: "位置y",
        type: DataType.Number,
        onchange(this: KrpanoCanvas, _, isFirst) {
            if (!isFirst) {
                this.set2DXY("y");
            }
        },
    };

    @ATTRIB("gui.widthType")
    public widthType: IEDAttrib<DataType.DropDown> = {
        name: "宽度类型",
        type: DataType.DropDown,
        onchange(this: KrpanoCanvas) {
            this.set2DSize("width");
        },
        extra: ["像素", "百分比", "视窗宽度百分比", "视窗高度百分比"],
    };

    @ATTRIB("gui.width")
    public with: IEDAttrib<DataType.Number> = {
        name: "宽度",
        type: DataType.Number,
        onchange(this: KrpanoCanvas, _, isFirst) {
            if (!isFirst) {
                this.set2DSize("width");
            }
        },
        default: 100,
    };

    @ATTRIB("gui.heightType")
    public heightType: IEDAttrib<DataType.DropDown> = {
        name: "高度类型",
        type: DataType.DropDown,
        onchange(this: KrpanoCanvas) {
            this.set2DSize("height");
        },
        extra: ["像素", "百分比", "视窗宽度百分比", "视窗高度百分比"],
    };

    @ATTRIB("gui.height")
    public height: IEDAttrib<DataType.Number> = {
        name: "高度",
        type: DataType.Number,
        onchange(this: KrpanoCanvas, _, isFirst) {
            if (!isFirst) {
                this.set2DSize("height");
            }
        },
        default: 100,
    };

    @ATTRIB("gui.horizontal_alignment")
    public horizontal: IEDAttrib<DataType.DropDown> = {
        name: "水平对齐方式",
        type: DataType.DropDown,
        onchange(this: KrpanoCanvas, _, isFirst) {
            if (!isFirst) {
                this.set2DXY("x");
            }
        },
        extra: ["居左", "居右", "居中"],
        default: 2,
    };

    @ATTRIB("gui.vertical_alignment")
    public vertical: IEDAttrib<DataType.DropDown> = {
        name: "垂直对齐方式",
        type: DataType.DropDown,
        onchange(this: KrpanoCanvas, _, isFirst) {
            if (!isFirst) {
                this.set2DXY("y");
            }
        },
        extra: ["居上", "居下", "居中"],
        default: 2,
    };

    @ATTRIB("gui.rotation")
    public rotation: IEDAttrib<DataType.Slide> = {
        name: "旋转角度",
        type: DataType.Slide,
        onchange(this: KrpanoCanvas, val) {
            this.addTransformProperty((this.sceneObj as HTMLElement).style, "rotate", `${val}deg`);
        },
        extra: { max: 360 },
    };

    protected type2DList = ["px", "%", "vw", "vh"];
    protected set2DSize(type: "width" | "height") {
        const divStyle = (this.sceneObj as HTMLElement).style;
        let orginWidth = this.get("gui." + type);
        // 宽度类型 0 1 2 3 分别对应像素，百分比，vw,vh
        let widthType = this.get("gui." + type + "Type");
        divStyle[type] = orginWidth + this.type2DList[widthType];
    }

    protected addTransformProperty(divStyle: CSSStyleDeclaration, type: string, value: string) {
        let split: string[] = [];
        if (divStyle.transform) split = divStyle.transform.split(" ");
        let str = "";
        let have = false;
        for (let tmp of split) {
            if (tmp) {
                if (tmp.startsWith(type)) {
                    str += type + "(" + value + ") ";
                    have = true;
                } else {
                    str += tmp + " ";
                }
            }
        }
        if (!have) {
            str += type + "(" + value + ") ";
        }
        divStyle.transform = str;
    }
    private set2DXY(type: "x" | "y") {
        const divStyle = (this.sceneObj as HTMLElement).style;
        let orginX = this.get("gui." + type);
        // x坐标类型 0 1 2 3 分别对应像素，百分比，vw,vh
        let xType = this.get("gui." + type + "Type");
        let alignment = { x: "horizontal_alignment", y: "vertical_alignment" };
        let horizontal_alignment = this.get("gui." + alignment[type]);
        orginX = orginX < 0 ? " - " + -orginX + this.type2DList[xType] : " + " + orginX + this.type2DList[xType];
        let pos = { x: "left", y: "top" };
        switch (horizontal_alignment) {
            case 0:
                this.addTransformProperty(divStyle, "translate" + type.toUpperCase(), "0");
                divStyle[pos[type]] = `calc(0%${orginX})`;
                break;
            case 1:
                this.addTransformProperty(divStyle, "translate" + type.toUpperCase(), "-100%");
                divStyle[pos[type]] = `calc(100%${orginX})`;
                break;
            case 2:
                this.addTransformProperty(divStyle, "translate" + type.toUpperCase(), "-50%");
                divStyle[pos[type]] = `calc(50%${orginX})`;
        }
    }

    protected dispose(): void {
        (this.sceneObj as HTMLElement).remove();
    }

    private specialType = ["input"];
    public initDraggable() {
        if (!VeryEngine.EditMode) {
            (this.sceneObj as HTMLElement).style.userSelect = "none";
            if (VeryEngine.EditMode) return;
            (this.sceneObj as HTMLElement).addEventListener("mouseup", (e: MouseEvent) => {
                if (!e.isStop) {
                    //点击ui后，键盘w按下等操作任何可以运行、鼠标滚轮还能控制相机视角
                    if (!this.specialType.includes(this.subtype)) {
                        VeryEngine.canvas.focus();
                    }
                    e.customPropagation();
                }
            });

            return;
        }
        let id = this.id;

        (this.sceneObj as HTMLElement).addEventListener("mouseup", (e: MouseEvent) => {
            if (!e.isStop) {
                e.customPropagation();
                setTimeout(() => {
                    VeryEngine.pickEntity(id);
                }, 0);
            }
        });

        this.dragHander();
    }

    public dragHander(stop?: boolean) {
        if (!stop) {
            (this.sceneObj as HTMLElement).addEventListener("mousedown", this.onMouseDown);
            document.addEventListener("selectstart", this.onSelectStart);
        } else {
            (this.sceneObj as HTMLElement).removeEventListener("mousedown", this.onMouseDown);
            document.removeEventListener("mousemove", this.onMouseMove);
            window.removeEventListener("mouseup", this.onMouseUp);
            document.removeEventListener("selectstart", this.onSelectStart);
        }
    }

    public krpano_onready_callback(krpano_interface) {
        this.krpanoInstance = krpano_interface;
        //@ts-ignore
        window.krpanoImagePositionChange = (ath, atv, id) => {
            VeryEngine.pickEntities([id]);
            let ied = VeryEngine.shareBox.id2Entity[id];
            ied.set("gui.atv", atv);
            ied.set("gui.ath", ath);
        };
    }

    private isDragging = false;
    private offset = { x: 0, y: 0 };

    private onMouseDown = (event: MouseEvent) => {
        if (!event.isStop) {
            if (event.button != 0) return;
            event.customPropagation();
            if (this.subtype === "button") {
                (this.sceneObj as HTMLElement).style.transform += "scale(0.95)";
            }
            this.isDragging = true;
            this.offset.x = event.pageX - (this.sceneObj as HTMLElement).offsetLeft;
            this.offset.y = event.pageY - (this.sceneObj as HTMLElement).offsetTop;

            document.addEventListener("mousemove", this.onMouseMove);
            window.addEventListener("mouseup", this.onMouseUp);
        }
    };

    private onMouseMove = (event) => {
        if (this.isDragging && event.button == 0) {
            let currentX = event.pageX - this.offset.x;
            let currentY = event.pageY - this.offset.y;
            let realXDis: number;
            let GUIX: string;
            switch (this.get("gui.horizontal_alignment")) {
                case 0:
                    realXDis = currentX;
                    break;
                case 1:
                    realXDis = currentX - this.parent.sceneObj.getBoundingClientRect().width;
                    break;
                case 2:
                    realXDis = currentX - 0.5 * this.parent.sceneObj.getBoundingClientRect().width;
            }

            switch (this.get("gui.xType")) {
                case 0:
                    GUIX = realXDis + "";
                    break;
                case 1:
                    GUIX = ((realXDis / this.parent.sceneObj.getBoundingClientRect().width) * 100).toFixed(1);
                    break;
                case 2:
                    GUIX = ((realXDis / window.innerWidth) * 100).toFixed(1);
                    break;
                case 3:
                    GUIX = ((realXDis / window.innerHeight) * 100).toFixed(1);
            }

            let realYDis;
            let GUIY;
            switch (this.get("gui.vertical_alignment")) {
                case 0:
                    realYDis = currentY;
                    break;
                case 1:
                    realYDis = currentY - this.parent.sceneObj.getBoundingClientRect().height;
                    break;
                case 2:
                    realYDis = currentY - 0.5 * this.parent.sceneObj.getBoundingClientRect().height;
            }

            switch (this.get("gui.yType")) {
                case 0:
                    GUIY = realYDis;
                    break;
                case 1:
                    GUIY = ((realYDis / this.parent.sceneObj.getBoundingClientRect().height) * 100).toFixed(1);
                    break;
                case 2:
                    GUIY = ((realYDis / window.innerWidth) * 100).toFixed(1);
                    break;
                case 3:
                    GUIY = ((realYDis / window.innerHeight) * 100).toFixed(1);
            }

            this.set("gui.x", GUIX);
            this.set("gui.y", GUIY);
        }
    };

    private onMouseUp = (event) => {
        if (event.button == 0) {
            this.isDragging = false;
            if (this.subtype === "button") {
                let str = (this.sceneObj as HTMLElement).style.transform;

                let charToRemove = "scale(0.95)";
                let newStr = str.replace(charToRemove, "");

                (this.sceneObj as HTMLElement).style.transform = newStr;
            }
            document.removeEventListener("mousemove", this.onMouseMove);
            window.removeEventListener("mouseup", this.onMouseUp);
            document.removeEventListener("selectstart", this.onSelectStart);
        }
    };

    private onSelectStart = (event) => {
        event.preventDefault();
    };
}
