import { VeryEngine } from "../engine/VeryEngine";

export class Progress{
    public static entityTotal=0
    public static entityCount=0;
    private static progress:HTMLProgressElement;
    private static timeterval:NodeJS.Timer;
    private static timeterval2:NodeJS.Timer;
    private static max=0;
    public static init(){
        this.timeterval=setInterval(()=>{
            if(!this.progress){
                this.progress=document.getElementById("progress") as HTMLProgressElement;
            }
            if(this.progress){
                this.progress.value=this.progress.value+1;
            }
        },500)
    }
    public static setTotal(num:number){
        this.entityTotal=num;
        if(!this.progress){
            this.progress=document.getElementById("progress") as HTMLProgressElement;
        }else{
            if(this.timeterval){
                clearInterval(this.timeterval);
                this.timeterval=undefined;
            }
            this.progress.value=20;
        }
        this.timeterval2=setInterval(()=>{
            this.max+=10;
            if(this.progress&&this.max<=this.entityCount/this.entityTotal*100){
                this.progress.value=this.max*0.8+20;
                if(this.progress.value==100){
                    this.progress.parentElement.style.display="none";
                    clearInterval(this.timeterval2);
                }
            }
        },100)
    }
    public static entityLoad(){
        this.entityCount++;
        if(!this.progress){
            this.progress=document.getElementById("progress") as HTMLProgressElement;
            return;
        }
        if(this.timeterval){
            clearInterval(this.timeterval);
            this.timeterval=undefined;
        }
        let value=this.entityCount/this.entityTotal;
        if(value==1){
            VeryEngine.LoadComplete();
        }
        if(value*100<=this.max){
            this.progress.value=value*80+20;
            if(this.progress.value==100){
                this.progress.parentElement.style.display="none";
                if(this.timeterval2){
                    clearInterval(this.timeterval2);
                }
            }
        }
    }
}