export class DataBuffer
{
    //自动大小数据缓存器
    private _minBuffLen!:number;
    private _buff!:Uint8Array;
    private _curBuffPosition:number=0;
    private _buffLength = 0;
    private _dataLength:number=0;

    /// <summary>
    /// 构造函数
    /// </summary>
    /// <param name="_minBuffLen">最小缓冲区大小</param>
    constructor(_minBuffLen:number = 1024)
    {
        if (_minBuffLen <= 0)
        {
            this._minBuffLen = 1024;
        }
        else
        {
            this._minBuffLen = _minBuffLen;
        }
        this._buff = new Uint8Array(this._minBuffLen);
    }

    public GetClientID(){
        if(this._buff.length>=2){
            let id=this.ToShort(this._buff,0);
            this._curBuffPosition-=2;
            this._buff=this._buff.slice(2);
            return id;
        }
        return null;
    }
    /// <summary>
    /// 添加缓存数据
    /// </summary>
    /// <param name="_data"></param>
    /// <param name="_dataLen"></param>
    public AddBuffer(_data:Uint8Array)
    {
        let dataLen = _data.length
        if (dataLen > this._buff.length - this._curBuffPosition)//超过当前缓存
        {
            let _tmpBuff = new Uint8Array(this._curBuffPosition + dataLen);
            _tmpBuff.set(this._buff);

            _tmpBuff.set(_data,this._curBuffPosition);
            this._buff = _tmpBuff;
        }
        else
        {
            this._buff.set(_data,this._curBuffPosition);
        }

        this._curBuffPosition += dataLen;//修改当前数据标记
    }

    /// <summary>
    /// 更新数据长度
    /// </summary>
    public UpdateDataLength()
    {
        if (this._dataLength == 0 && this._curBuffPosition >= 4)
        {
            this._buffLength = this.ToInt32(this._buff, 0);
            this._dataLength = this._buffLength -4;
        }
    }

    /// <summary>
    /// 获取一条可用数据，返回值标记是否有数据
    /// </summary>
    /// <param name="_tmpSocketData"></param>
    /// <returns></returns>
    public GetData()
    {
        if (this._buffLength <= 0)
        {
            this.UpdateDataLength();
        }

        if (this._buffLength > 0 && this._curBuffPosition >=this._buffLength)
        {
            let socketData=this._buff.slice(4,this._buffLength);
            this._curBuffPosition -= this._buffLength;
            let tmpBuff = this._buff.slice(this._buffLength);
            this._buff = new Uint8Array(this._curBuffPosition < this._minBuffLen ? this._minBuffLen : this._curBuffPosition);
            this._buff.set(tmpBuff);
            this._buffLength = 0;
            this._dataLength = 0;
            return socketData;
        }
        return null
    }

    public ToInt32(value:Uint8Array,index:number):number
    {
        let re=(value[index]<<24);
        re+=(value[index+1]<<16);
        re+=(value[index+2]<<8);
        re+=(value[index+3]);
        return re;
    }

    public ToShort(value:Uint8Array,index:number):number
    {
        let re=(value[index]<<8);
        re+=(value[index+1]);
        return re;
    }

}