import {  IEDAsset} from ".";
import { VeryEngine,DataType,IED} from "../engine";
import { Tools } from "../utility/Tools";
import { ATTRIB, IEDAttrib, addAssetClass } from "../engine/IEDProxy";

@addAssetClass
export class IEDTexture extends IEDAsset{

    public get type(): string {
        return "texture"
    }

    public assetObj:string;
    private gifURLs:string[];
    private _gifIndex=0;
    //todo 将gif分解为多张png时间太慢了，需要将png存在缓存中
    public set gifIndex(val:number){
        this._gifIndex=val;
        for(let i=0;i<this.gifTarget.length;i++){
            let tmp=this.gifTarget[i];
            if(tmp.mode=="html"){
                if((tmp.ied&&tmp.ied.isDestroy)||!this.doImage.includes(tmp.target[tmp.property])){
                    this.gifTarget.splice(i,1);
                    break;
                }
                tmp.target[tmp.property]=this.doImage[this._gifIndex];
            }else if(tmp.mode=="BABYLON"){
                if((tmp.ied&&tmp.ied.isDestroy)||!this.texture.includes(tmp.target[tmp.property])){
                    this.gifTarget.splice(i,1);
                    break;
                }
                tmp.target[tmp.property]=(this.texture[this._gifIndex])
            }
        }
    }
    private doImage;

    private texture;
    public get isGif(){
        return this.gifURLs!=undefined;
    }    
    public gifTimeOut;

    private gifTarget:{ied:IED,target:object,property:string,mode:string}[]=[];

    //如何卸载
    //todo 多张gui引用一个texture情况上存在问题
    public bindTexture(ied:IED,target:object,property:string,mode?:"BABYLON"|"html"|"string"){
        if(!mode)
            mode="html";
        if(!this.isGif){
            if(mode=="html"){
                target[property]=document.createElement("img");
                target[property].src=this.assetObj;
            }
            else if(mode=="BABYLON"){
                if(!this.texture){
                    this.texture=new BABYLON.Texture(this.assetObj,VeryEngine.scene);
                    this.texture.hasAlpha=true;
                }
                target[property]=this.texture;
            }
        }else{
            if(mode=="html"){
                if(!this.doImage){
                    this.doImage=[];
                    for(let url of this.gifURLs){
                        let image=document.createElement("img");
                        image.src=url;
                        this.doImage.push(image);
                    }
                }
                target[property]=this.doImage[this._gifIndex];
            }
            else if(mode=="BABYLON"){
                if(!this.texture){
                    this.texture=[];
                    for(let url of this.gifURLs){
                        let tmp=new BABYLON.Texture(url,VeryEngine.scene);
                        tmp.hasAlpha=true;
                        this.texture.push(tmp);
                    }
                }
                target[property]=this.texture[this._gifIndex];
            }
            this.gifTarget.push({ied:ied,target:target,property:property,mode:mode});
        }
    }

    protected async Load(){
        try{
            this.assetObj=await OSS.getUrl(this.id,this.fileName,this.fileHash);
        }catch(e){
            this.assetObj="";
            console.error(e,this.assetObj);
        }
    }


    public get Priority(){
        return 1;
    }
    public get suffix(): string[] {
        return ["png","jpg","jpeg","gif","tif","bpm","tga","dds","hdr","exr","env","dds","ico","cur"]
    }
    protected dispose(): void {
        this.assetObj=undefined;
        this.gifURLs=undefined;
        if(this._baseTexture){
            this._baseTexture.dispose();
        }
        if(this.gifTimeOut){
            clearTimeout(this.gifTimeOut);
        }
    }

    @ATTRIB()
    public resolution:IEDAttrib<DataType.String>={
        name:"分辨率",
        type:DataType.String,
        readonly:true
    }

    private _baseTexture:BABYLON.BaseTexture;
    public get BaseTexture():BABYLON.BaseTexture {
        if(!this._baseTexture){
            if(!this.assetObj){
                console.warn(this.id+"-"+this.name+",该图片未加载，请调用onceOnlyLoad函数后再获取BaseTexture");
                return null;
            }
            if(this.fileName.toLowerCase().endsWith(".env")||this.fileName.toLowerCase().endsWith(".dds")){
                this._baseTexture=new BABYLON.CubeTexture(this.assetObj,VeryEngine.scene);
            }else if(this.fileName.toLowerCase().endsWith(".hdr")){
                this._baseTexture=new BABYLON.HDRCubeTexture(this.assetObj,VeryEngine.scene,1024)
            }else{
                this._baseTexture=new BABYLON.Texture(this.assetObj,VeryEngine.scene);
            }
        }
        return this._baseTexture
    }
    
    protected async upload(file:File,folderId?:string):Promise<any>{
        var hash = await  Tools.getmd5(file);
        var assetID = Tools.assetID();
        let path=[];
        if(folderId!=null){
            if(!folderId) path=[];
            else path=[folderId];
        }else if(VeryEngine.commonJson.get("pickAssetFolder")){
            path=[VeryEngine.commonJson.get("pickAssetFolder")]
        }else{
            path=[]
        }
        let resolution;
        try{
            let base64=await new Promise<string>((resolve,reject) => {
                const reader = new FileReader();
                reader.onload = () => {
                    resolve(reader.result as string);
                };
                reader.onerror=()=>{
                    reject();
                }
                reader.readAsDataURL(file);
            });
            await new Promise<void>((resolve) =>{
                const image = new Image();
                image.onload = () => {
                    const width = image.width;
                    const height = image.height;
                    resolution=width+"X"+height;
                    resolve();
                }
                image.onerror=()=>{
                    resolve();
                }
                image.src = base64;
            });
        }catch{

        }
        await OSS.uploadFile(file, assetID, file.name, hash);
        var createdAt = Tools.createdTime();
        return {
            id: assetID,
            type: this.type,
            createdAt: createdAt,
            name: file.name,
            file: {
                filename: file.name,
                size: file.size,
                hash: hash,
            },
            resolution:resolution,
            path: path
        };
    }
}