import { DMap, Doc,Transaction } from "../type";
import {AbstractContent, ContentCopy, ContentType, Item} from "../content"
import { VeryEngine } from "../../engine/VeryEngine";

export class UndoManager{
    private undoing = false;
    private redoing = false;
    private undoStack:Array<StackItem> = [];
    private redoStack:Array<StackItem>=[]
    private lastChange = 0;
    private doc:Doc;
    private captureTimeout=500;
    constructor(doc:Doc){
        this.doc=doc;
        doc.addFrameEndAct(this.frameEnd.bind(this));
    }

    private frameEnd(item:Item,undoStack:boolean,transaction:Transaction){
      if(undoStack==undefined) undoStack=true;
      if(VeryEngine.isLoadComplete&&undoStack&&transaction.origin=="local"||transaction.origin=="undo"){
        const undoing = this.undoing
        const redoing = this.redoing
        const stack = undoing ? this.redoStack : this.undoStack
        if (undoing) {
          // this.lastChange=0;
        } else if (!redoing) {
          if(this.redoStack.length!=0)
          for(let act of this.stackAction.redo){
            act(0);
          }
          this.redoStack = [];
        }
        const insertions = new DeleteSet();
        if(!item.deleted)
        insertions.clients.set(item.id.client,[new DeleteItem(item.id.clock,item.length,null)]);
        const now = Date.now();
        if (now - this.lastChange < this.captureTimeout && stack.length > 0) {
          const lastOp = stack[stack.length - 1]
          lastOp.deletions.mergeDeleteSets(transaction.deleteSet)
          lastOp.insertions.mergeDeleteSets(insertions);
          lastOp.deletions.duplicateRemoval(lastOp.insertions);
          lastOp.defatult.push(...transaction.defaultDel);
        } else {
          let tmp=new DeleteSet();
          tmp.mergeDeleteSets(transaction.deleteSet);
          tmp.duplicateRemoval(insertions);
          stack.push(new StackItem(tmp, insertions,transaction.defaultDel))
          if(stack.length>50){
            stack.shift()
          }
          if(this.undoing){
            for(let act of this.stackAction.redo){
              act(stack.length);
            }
          }else{
            for(let act of this.stackAction.undo){
              act(stack.length);
            }
          }
        }
        // if (!undoing && !redoing) {
          this.lastChange = now;
        // }
      }
    }
    private stackAction={undo:[],redo:[]};
    public addStackAction(type:"undo"|"redo",act:(num:number)=>void){
      if(type=="redo"){
        this.stackAction.redo.push(act);
      }else{
        this.stackAction.undo.push(act);
      }
    }

    public  undo () {
        this.undoing = true
        try {
            this.popStackItem(this.undoStack);
            for(let act of this.stackAction.undo){
              act(this.undoStack.length);
            }
        } finally {
            this.undoing = false
        }
    }

    public redo(){
      this.redoing=true;
      try{
        this.popStackItem(this.redoStack);
        for(let act of this.stackAction.redo){
          act(this.redoStack.length);
        }
      }finally{
        this.redoing=false;
      }
    }

    private popStackItem(stack:StackItem[]){
      if(stack.length>0){
        this.lastChange=0;
        let statckItem=stack.pop();
        this.doc.createTranscation("undo");
        statckItem.deletions.clients.forEach((inserts,client) => {
          for(let insert of inserts){
            let content=new ContentCopy(insert.items);
            let value=this.doc.getItem({client:client,clock:insert.clock})
            if(value.parentSub){
              let left =value.parent.mapGet(value.parentSub) || null
              let ownClientId = this.doc.clientID;
              let item=new Item({client:ownClientId,clock:this.doc.getState(ownClientId)}, left, left && left.lastId, null, null, value.parent, value.parentSub, content);
              item.write();
              item.integrate();
            }else{
              let item=new Item(value.id,null,null,null,null,value.parent,null,content);
              item.write();
              content.integrate(item);
              if(value.length>item.length){
                this.doc.splitItem(value,item.length);
              }
              value.content=item.content;
              value.info ^=4;
              this.doc.addFrameItem(value);
            }
          }
        });
        statckItem.insertions.clients.forEach((dels,client) => {
          for(let del of dels){
            this.doc.iterateDelStructs(client,del.clock,del.len).forEach(value=>{
                value.delete();
                value.write();
            });
          }
        });
        for(let def of statckItem.defatult){
          let item=def.map.mapGet(def.key);
          if(item&&!item.deleted){
            item.delete();
            item.write();
          }
        }
        this.doc.frameEndAndSend({})
      }
    }

    private findIndexDS(dis:DeleteItem[], clock:number){
      let left = 0
      let right = dis.length - 1
      while (left <= right) {
        const midindex = Math.floor((left + right) / 2)
        const mid = dis[midindex]
        const midclock = mid.clock
        if (midclock <= clock) {
          if (clock < midclock + mid.len) {
            return midindex
          }
          left = midindex + 1
        } else {
          right = midindex - 1
        }
      }
      return null
    }
}

class StackItem {
    public insertions:DeleteSet;
    public deletions:DeleteSet;
    public defatult:{map:DMap,key:string}[];
    constructor (deletions:DeleteSet, insertions:DeleteSet,defatult:{map:DMap,key:string}[]) {
        this.insertions = insertions
        this.deletions = deletions
        this.defatult=[...defatult];
    }
}

export class DeleteSet {
    public clients:Map<number,Array<DeleteItem>>;
    constructor () {
      this.clients = new Map()
    }

    //this-self为del，other-item为add
    //两组线段去重 算法
    public duplicateRemoval(other:DeleteSet){
        other.clients.forEach((items,client)=>{
            let self=this.clients.get(client);
            if(self){
              let i=0,j=0;
              while(i<self.length&&j<items.length){
                if(items[j].clock>=self[i].clock+self[i].len){
                  i++;continue;
                }
                if(self[i].clock>=items[j].clock+items[j].len){
                  j++;continue;
                }
                if(items[j].clock>=self[i].clock){
                  if(items[j].clock+items[j].len<=self[i].clock+self[i].len){
                    let unit:AbstractContent;
                    unit=self[i].content.splice(items[j].clock-self[i].clock).splice(items[j].len);
                    self.splice(i+1,0,new DeleteItem(items[j].clock+items[j].len,self[i].clock+self[i].len-items[j].clock-items[j].len,client,unit))
                    self[i].len=items[j].clock-self[i].clock;
                    items.splice(j,1);
                    i++;
                  }
                  else{
                    let clock=items[j].clock;
                    items[j].len=items[j].clock+items[j].len-self[i].clock-self[i].len;
                    items[j].clock=self[i].clock+self[i].len;
                    self[i].content.splice(clock-self[i].clock);
                    self[i].len=clock-self[i].clock;
                    i++
                  }
                }
                else{
                  if(items[j].clock+items[j].len>=self[i].clock+self[i].len){
                      items.splice(j+1,0,new DeleteItem(self[i].clock+self[i].len,items[j].clock+items[j].len-self[i].clock-self[i].len,null));
                      items[j].len=self[i].clock-items[j].clock;
                      self.splice(i,1);
                      j++;
                  }
                  else{
                    let clock=self[i].clock;
                    self[i]=new DeleteItem(items[j].clock+items[j].len,self[i].clock+self[i].len-items[j].clock-items[j].len,
                      client,self[i].content.splice(items[j].clock+items[j].len-self[i].clock));
                    items[j].len=clock-items[j].clock;
                    j++
                  }
                }
              }
              for(let i=0;i<self.length;){
                if(self[i].len==0){
                  self.splice(i,1);
                }else{
                  i++;
                }
              }
              for(let i=0;i<items.length;){
                if(items[i].len==0){
                  items.splice(i,1);
                }else{
                  i++;
                }
              }
            }
        })
    }

    public mergeDeleteSets(other:DeleteSet){
      other.clients.forEach((items,client)=>{
        let self=this.clients.get(client);
        if(self){
          for(let unit1 of items){
            let exit=false;
            for(let unit2 of self){
              if(unit1.clock==unit2.clock){
                exit=true;
              }
            }
            if(!exit)self.push(unit1);
          }
          self.sort((a,b)=>a.clock-b.clock)
        }else{
          this.clients.set(client,items);
        }
      })
    }
}

export class DeleteItem {
    public clock:number;
    public len:number;
    //ps items存在多个分两种清空，一个是记录的item是list或者map，把其子物体都记录上去了，这种时候len必定为1，去重的时候只需要考虑整个删除
    //另外是ContentAny，len可能不会1，去重时需要考虑拆分,items长度仍然为1
    public content:AbstractContent;
    public items:{client:number,clock:number,content:AbstractContent}[]=[];

    constructor (clock:number, len:number,client?:number,content?:AbstractContent) {
      this.clock = clock
      this.len = len
      if(content&&client){
        this.content=content.copy();
        this.obj2Buff(client,clock,this.content)
      }
    }

    private obj2Buff(client:number,clock:number,content:AbstractContent){
      let refId=content.refID;
      this.items.push({client:client,clock:clock,content:content});
      if(refId==3){
        let tmp=(content as ContentType).value();
        for(let key of tmp._map.keys()){
          let item=tmp._map.get(key);
          this.obj2Buff(item.id.client,item.id.clock,item.content.copy());
        }
        let start=tmp._start;
        while(start){
          if(!start.deleted){
            this.obj2Buff(start.id.client,start.id.clock,start.content.copy());
          }
          start=start.left;
        }
      }
    }
  }