import { VeryEngine } from "../../engine/VeryEngine";
import { contentRefs, ID, Item } from "../content";
import { AbstractType, Doc } from "../type";
import { ByteBuffer } from "./ByteBuffer";
import {DataBuffer} from "./DataBuffer"

export class SocketManager{
    private _buff:ByteBuffer;
    private doc:Doc;
    private _isConnected=false;
    private _databuffer:DataBuffer=new DataBuffer();

    private clientSocket: WebSocket | null = null;
    constructor(doc:Doc){
        this.doc=doc;
        this.onConnet();
    }

    public get buff(){
        if(!this._buff)
            this._buff=ByteBuffer.Allocate(1024);
        return this._buff
    }

    public send(){
        if(this._isConnected&&this._buff){
            let array=this._buff.ToArray();
            let tmp=new Uint8Array(array.byteLength+4);
            this._buff=null;
            tmp.set(this.GetBytesInt32(array.byteLength+4))
            tmp.set(new Uint8Array(array),4);
            this.clientSocket.send(tmp);
        }
    }

    private GetBytesInt32(value:number):Uint8Array
    {
        let bytes=new  Uint8Array(4);
        bytes[0]=value>>24;
        bytes[1]=(value>>16)-(bytes[0]<<8);
        bytes[2]=(value>>8)-(bytes[1]<<8)-(bytes[0]<<16);
        bytes[3]=value-(bytes[2]<<8)-(bytes[1]<<16)-(bytes[0]<<24);
        return bytes;
    }
    
    private onConnet() {
        try {
        //   this.clientSocket = window.location.protocol.startsWith("https")?
        //   new WebSocket("wss://ipc.veryengine.cn/ws")
        //   :new WebSocket("ws://ipc.veryengine.cn/ws")
          this.clientSocket=new WebSocket("ws://121.43.136.90:3001/ws/"+this.doc.project);
          this.clientSocket.onopen = this.connectSucess.bind(this);
          this.clientSocket.onclose = this.close;
          this.clientSocket.onmessage = this.getClientId.bind(this);
          this.clientSocket.onerror = this.error;
          this.clientSocket.binaryType = "arraybuffer";
        } catch (e) {
          console.error(e);
          this.close();
        }
    }

    private connectSucess() {
        this._isConnected = true;
        console.log("连接成功");
    }

    private close() {
        if (!this._isConnected) return;
    
        this._isConnected = false;
    
        if (this.clientSocket != null && this.clientSocket.readyState == 1) {
          this.clientSocket.close();
          this.clientSocket = null;
        }
    }
    private getClientId(e: MessageEvent){
        this._databuffer.AddBuffer(new Uint8Array(e.data));
        let id=this._databuffer.GetClientID();
        if(id!=null){
            this.doc.clientID=id;
            this.receiveItem();
            this.clientSocket.onmessage = this.receiveSocket.bind(this);
        }   
    }

    private receiveSocket(e: MessageEvent) {
        try {
          this._databuffer.AddBuffer(new Uint8Array(e.data)); //将收到的数据添加到缓存器中
          this.receiveItem();
        } catch (e) {
          console.error(e);
          if (this.clientSocket != null) {
            this.clientSocket.close();
            this.clientSocket = null;
          }
        }
    }

    private receiveItem(){
        let data:Uint8Array=null;
        while (data=this._databuffer.GetData()) {
            //取出一条完整数据
            VeryEngine.doc.createTranscation("net");
            let buff = ByteBuffer.Allocate(data.buffer);
            while(buff.ReadableBytes()>0){
                let id={client:buff.ReadUshort(),clock:buff.ReadUint()};
                let info=buff.ReadByte();
                let content=contentRefs[info&7](buff);
                let origin:ID=null;
                let rightOrigin:ID=null;
                let parentSub:string=null;
                let parent:AbstractType|ID=null;
                if(info&64){
                    origin={client:buff.ReadUshort(),clock:buff.ReadUint()};
                }
                if(info&32){
                    rightOrigin={client:buff.ReadUshort(),clock:buff.ReadUint()};
                }
                if(info&16){
                    parentSub=buff.ReadString();
                }
                if(info&8){
                    parent={client:buff.ReadUshort(),clock:buff.ReadUint()};
                }else{
                    let rootName=buff.ReadString();
                    let rootType=buff.ReadByte();
                    if(rootType===1){
                        parent=this.doc.getMap(rootName);
                    }
                }
                if((info&7)===2){
                    let remainder=content.getLength();
                    if(id.clock+remainder<=this.doc.getState(id.client)){
                        while(remainder>0){
                            let item=this.doc.getItem(id);
                            let len=item.id.clock+item.length-id.clock;
                            item.delete(id.clock,Math.min(len,remainder));
                            remainder=remainder-len;
                            id.clock+=len;
                        }
                        continue;
                    }
                }
                if(id.clock+content.getLength()<=this.doc.getState(id.client)){
                    //若是拷贝则正常否则是无效指令
                    if((info&7)===1){
                        let item=this.doc.getItem(id);
                        if(!item.deleted){
                            item.reset(content.value());
                        }
                    }
                }else{
                    let item=new Item(id,null,origin,null,rightOrigin,parent,parentSub,content);
                    if(item.updateMiss(this.doc)){
                        item.integrate();
                    }
                }
            }
            this.doc.frameEnd();
        }
    }

    private error(e: Event) {
        console.error("[ERROR] " + e.type);
        this.close();

    }
}