export class PoseMatrixTool{
    
    //物体姿态变换事件
    private static beforePoseMatrixUpdate:({[key:string]:((entity:BABYLON.TransformNode)=>void)[]})={};
    private static afterPoseMatrixUpdate:({[key:string]:((entity:BABYLON.TransformNode)=>void)[]})={};
    public static addBeforePoseMatrix(id:string,act:(entity:BABYLON.TransformNode)=>void){
        if(!this.beforePoseMatrixUpdate[id])this.beforePoseMatrixUpdate[id]=[];
        this.beforePoseMatrixUpdate[id].push(act);
    }
    public static removeBeforePoseMatrix(id:string){
        delete this.beforePoseMatrixUpdate[id];
    }
    public static beforePoseMatrix(entity:BABYLON.TransformNode){
        for(let key in this.beforePoseMatrixUpdate){
            for(let tmp of this.beforePoseMatrixUpdate[key])
            tmp(entity);
        }
    }
    public static addAfterPoseMatrix(id:string,act:(entity:BABYLON.TransformNode)=>void){
        if(!this.afterPoseMatrixUpdate[id])this.afterPoseMatrixUpdate[id]=[];
        this.afterPoseMatrixUpdate[id].push(act);
    }
    public static removeAfterPoseMatrix(id:string){
        delete this.afterPoseMatrixUpdate[id];
    }
    public static afterPoseMatrix(entity:BABYLON.TransformNode){
        for(let key in this.afterPoseMatrixUpdate){
            for(let tmp of this.afterPoseMatrixUpdate[key])
            tmp(entity);
        }
    }
 
    private static posInfoHeap:{node:BABYLON.TransformNode,info:{dir:BABYLON.Vector3,time:number}[]}[]=[];

    public static update(diffTime:number){
        for(let posInf of PoseMatrixTool.posInfoHeap){
            while(diffTime>0&&posInf.info.length>0){
                let pos=posInf.info[0];
                let moveTime=Math.min(diffTime,pos.time);
                PoseMatrixTool.poseMatrix(posInf.node);
                posInf.node.position=pos.dir.multiplyByFloats(moveTime,moveTime,moveTime);
                diffTime=diffTime-pos.time;
                if(diffTime>=0){
                    posInf.info.shift();
                }
            }  
        }
    }

    private static isMove=false;
    private static latelyMove:number=0;
    public static poseMatrix(node:BABYLON.TransformNode){
        if(!this.isMove){
            this.beforePoseMatrix(node);
            let tmp=setInterval(()=>{
                if(new Date().getTime()-this.latelyMove>300){
                    this.isMove=false;
                    this.afterPoseMatrix(node);
                    clearInterval(tmp);
                }
            },100)
        }
        this.latelyMove=new Date().getTime();
    }
    
}