import { IEDEntity} from "./IEDEntity";
import { Tools } from "../utility/Tools";
import { IEDAttrib,ATTRIB } from "../engine/IEDProxy";
import { IEDSprite } from "./index";
import {DataType, VeryEngine} from "../engine"
import {PoseMatrixTool} from "./PoseMatrixTool"

export abstract class IEDTransform extends IEDEntity{
    public sceneObj:BABYLON.TransformNode;
    private calRot(parent:BABYLON.Node,quat:BABYLON.Quaternion):BABYLON.Quaternion{
        if(parent&&'rotation' in parent){
            return BABYLON.Quaternion.Inverse((parent as any).rotation.toQuaternion()).multiply(this.calRot(parent.parent,quat))
        }else{
            return quat;
        }
    }

    protected setChild( child: IEDEntity,config:{origin:string}) {          
        if(child instanceof IEDTransform&&child._parent!=this){
            //撤销操作和协同操作会发送两个信号一个修改父子关系，一个设置位置
            //因此这些操作不能改变姿态
            if(config.origin!="local"||child.parent===undefined){
                child.sceneObj.parent=this.sceneObj;
            }else{
                let rotation=this.calRot(this.sceneObj,child.sceneObj.absoluteRotationQuaternion).toEulerAngles();
                let position=BABYLON.Vector3.TransformCoordinates(child.sceneObj.getAbsolutePosition(),
                BABYLON.Matrix.Invert(this.sceneObj.computeWorldMatrix()))
                let scal=child.sceneObj.absoluteScaling.divide(this.sceneObj.absoluteScaling);
                child.sceneObj.parent=this.sceneObj;
                child.set("position",position.asArray());
                child.set("rotation",Tools.radianToEulerAngle(rotation).asArray());
                child.set("scale",scal.asArray());
            }
        }else if(child instanceof IEDSprite){
            child.realPos(this.sceneObj)
        }
    }

    public filterParentType(parent: IEDEntity){
        if(parent instanceof IEDTransform||parent.type=="root"){
            if(parent.type=="gui"){
                return false
            }else
                return true
        }else
            return false
    }
    @ATTRIB("tags")
    public tagList:IEDAttrib<DataType.Tag>={
        name:"标签",
        type:DataType.Tag,
        onchange(this:IEDTransform,index:number,value:string,config:{deleted:boolean}){
            if(value&&config)
            if(!config.deleted){
                VeryEngine.addTag(this.id,value);
            }else{
                VeryEngine.removeTag(this.id,this.tagNames);
            }
        }
        
    }

    public isEnabled:IEDAttrib<DataType.Bool>={
        name:"激活",
        type:DataType.Bool,
        onchange(this:IEDTransform,val){
            this.sceneObj.setEnabled(val);
        },
        default:true
    }

    @ATTRIB()
    public position:IEDAttrib<DataType.Vector3>={
        name:"位置",
        type:DataType.Vector3,
        onchange(this:IEDTransform,val){
            PoseMatrixTool.poseMatrix(this.sceneObj);
            this.sceneObj.position=BABYLON.Vector3.FromArray(val);
        }
    }

    @ATTRIB()
    public rotation:IEDAttrib<DataType.Vector3>={
        name:"角度",
        type:DataType.Vector3,
        onchange(this:IEDTransform,val){
            PoseMatrixTool.poseMatrix(this.sceneObj);
            this.sceneObj.rotation=Tools.eulerAngleToRadian(BABYLON.Vector3.FromArray(val));
        }
    }

    @ATTRIB()
    public scale:IEDAttrib<DataType.Vector3>={
        name:"尺寸",
        type:DataType.Vector3,
        onchange(this:IEDTransform,val){
            PoseMatrixTool.poseMatrix(this.sceneObj);
            this.sceneObj.scaling=BABYLON.Vector3.FromArray(val);;
        },
        default:[1,1,1]
    }

}