import {addEntityClass,ATTRIB, IEDAttrib} from "../../engine/IEDProxy"
import { VeryEngine,DataType} from "../../engine";
import { IEDGUI } from "./IEDGUI";
import { Canvas3D } from "./Canvas";
import { Tools } from "../../utility/Tools";


@addEntityClass
export class Text extends IEDGUI{
    public get subtype(): string {
        return "text";
    }

    private textDiv:HTMLElement;
    protected realLoad(is2D:boolean){
        if(is2D){
            this.sceneObj = document.createElement("div");
            let divStyle = this.sceneObj.style;
            divStyle.position = "absolute";
            divStyle.overflow = "hidden";
            divStyle.cursor = "pointer";
            divStyle.position = "absolute";
            divStyle.display = "flex";
            divStyle.width = "100%";
            divStyle.height = "100%";
            this.textDiv = document.createElement("span");
            this.sceneObj.append(this.textDiv);
            if(VeryEngine.EditMode){
                divStyle.border = "1px solid #aaa";
            }
        }else{
            this.sceneObj = new BABYLON.GUI.TextBlock(this.name, "");
            this.sceneObj.isPointerBlocker = true;
        }
    }
    private title="文字"

    @ATTRIB("gui.through")
    public through:IEDAttrib<DataType.Bool>={
        name:"是否点击穿透",
        type:DataType.Bool,
        onchange(this:Text,val){
            if(this.is2D){
                if (!VeryEngine.EditMode) {
                    if (val) {
                        (this.sceneObj as HTMLImageElement).style.pointerEvents = "none";
                    } else {
                        (this.sceneObj as HTMLImageElement).style.pointerEvents = "auto";
                    }
                } else {
                    (this.sceneObj as HTMLImageElement).style.pointerEvents = "auto";
                }
            }
        },
        title:this.title
    }

    @ATTRIB("gui.textColor")
    public textColor:IEDAttrib<DataType.Color4>={
        name:"字体颜色",
        type:DataType.Color4,
        onchange(this:Text,val){
            if(this.is2D){
                (this.sceneObj as HTMLElement).style.color = Tools.rgba2hsvString(val);
            }else{
                (this.sceneObj as BABYLON.GUI.TextBlock).color = Tools.rgba2hsvString(val);
            }
        },
        default:[0,0,0,1],
        title:this.title
    }

    @ATTRIB("gui.text")
    public text:IEDAttrib<DataType.Textarea>={
        name:"文字",
        type:DataType.Textarea,
        onchange(this:Text,val,isFirst) {
            val=val+""
            if(this.is2D){
                this.textDiv.innerHTML = val.replace(/ /g, "&nbsp;").replace(/\n/g, "<br>");
            }else
                (this.sceneObj as BABYLON.GUI.TextBlock).text=val;
            if(isFirst){
                let split = val.split(".");
                if (split[split.length - 1].startsWith("*"))
                   this.addVeryVal({ attr: "gui.text", valName: val });
            }
        },
        title:this.title
    }

    @ATTRIB("gui.fontSize")
    public fontSize:IEDAttrib<DataType.Number>={
        name:"字体大小",
        type:DataType.Number,
        onchange(this:Text,val){
            if(this.is2D){
                (this.sceneObj as HTMLElement).style.fontSize = val+"px"
            }else{
                (this.sceneObj as BABYLON.GUI.TextBlock).fontSize = val
            }
        },
        default:18,
        title:this.title
    }

    @ATTRIB("gui.lineSpacing")
    public lineSpacing:IEDAttrib<DataType.Number>={
        name:"行间距",
        type:DataType.Number,
        onchange(this:Text,val){
            if(this.is2D){
                (this.sceneObj as HTMLElement).style.lineHeight = (this.get("gui.fontSize")+val)+"px"
            }else{
                (this.sceneObj as BABYLON.GUI.TextBlock).lineSpacing = val
            }
        },
        title:this.title
    }

    @ATTRIB("gui.textWrapping")
    public textWrapping:IEDAttrib<DataType.DropDown>={
        name:"文字环绕方式",
        type:DataType.DropDown,
        onchange(this:Text,val){
            if(this.is2D){
                switch (val) {
                    case 0:
                        this.textDiv.style.overflowWrap = "normal";
                        this.textDiv.style.whiteSpace = "normal";
                        this.textDiv.style.overflow = "hidden";
                        this.textDiv.style.textOverflow = "initial";
                        break;
                    case 1:
                        this.textDiv.style.overflowWrap = "break-word";
                        this.textDiv.style.whiteSpace = "normal";
                        this.textDiv.style.overflow = "visible";
                        this.textDiv.style.textOverflow = "initial";
                        break;
                    case 2:
                        this.textDiv.style.overflowWrap = "normal";
                        this.textDiv.style.whiteSpace = "nowrap";
                        this.textDiv.style.overflow = "hidden";
                        this.textDiv.style.textOverflow = "ellipsis";
                }
            }else{
                (this.sceneObj as BABYLON.GUI.TextBlock).textWrapping = val;
                this.set3DSize("width");
            }
        },
        extra: ["裁剪显示", "自动换行", "省略显示"],
        default:1,
        title:this.title
    }

    @ATTRIB("gui.textHorizontalAlignment")
    public textHorizontalAlignment:IEDAttrib<DataType.DropDown>={
        name:"文字水平对齐",
        type:DataType.DropDown,
        onchange(this:Text,val){
            if(this.is2D){
                let typelist=["flex-start","flex-end","center"];
                (this.sceneObj as HTMLElement).style.justifyContent=typelist[val];
            }else{
                (this.sceneObj as BABYLON.GUI.TextBlock).textHorizontalAlignment = val
            }
        },
        extra: ["居左", "居右", "居中"],
        title:this.title
    }

    @ATTRIB("gui.textVerticalAlignment")
    public textVerticalAlignment:IEDAttrib<DataType.DropDown>={
        name:"文字垂直对齐",
        type:DataType.DropDown,
        onchange(this:Text,val){
            if(this.is2D){
                let typelist=["flex-start","flex-end","center"];
                (this.sceneObj as HTMLElement).style.alignItems=typelist[val];
            }else{
                (this.sceneObj as BABYLON.GUI.TextBlock).textVerticalAlignment = val
            }
        },
        extra: ["居上", "居下", "居中"],
        default:2,
        title:this.title
    }

    @ATTRIB("gui.resizeToFit")
    public resizeToFit:IEDAttrib<DataType.Bool>={
        name:"适应父容器大小",
        type:DataType.Bool,
        onchange(this:Text,val){
            if(this.is2D){
                this.set2DSize("height");
            }else{
                (this.sceneObj as BABYLON.GUI.TextBlock).resizeToFit = val;
            }
        },
        title:this.title
    }

    protected set2DSize(type:"width"|"height"){
        super.set2DSize(type);
        if(type=="height"){
            const divStyle = (this.sceneObj as HTMLElement).style;
            if(this.get("gui.resizeToFit")){
                divStyle.height = "initial";
            }else{
                let orginWidth = this.get("gui."+type);
                // 宽度类型 0 1 2 3 分别对应像素，百分比，vw,vh
                let widthType = this.get("gui."+type+"Type");
                divStyle[type]=orginWidth+this.type2DList[widthType];
            }
        }
    }

}