import { Tools } from "../utility/Tools";
import { IED,VeryEngine,DataType } from "../engine";
import { DMap } from "../djs/type";
import { IEDEntity } from "../main";
import { IEDAttrib,ATTRIB, IEDProxyFactory } from "../engine/IEDProxy";

export abstract class IEDAsset extends IED{
    private _id:string;
    public get id():string{
        return this._id;
    }
    public get path():string[]{
        return this._data.get("path");
    }

    public fileName:string;
    constructor(data){
        super(data);
        if(data){
            this._id=data.get("id");
            let file=data.get("file");
            if(file){
                this.fileName=file.get("filename");
            }
        }
    }
    //父子关系：若先加载子，父还未加载，需要先记录一下
    private static id2Children:{[key:string]:string[]}={};

    //处理同时上传多个文件时进行排序
    public get Priority(){
        return 10
    }

    private _rename:string;
    public get autoRename(){
        if(!this._rename){
            return this.name;
        }else{
            return this._rename;
        }
    }

    public doubleClick?():void;
    

    public dealWithParent(){
        if(IEDAsset.id2Children[this.id]){
            this._children=IEDAsset.id2Children[this.id];
            delete IEDAsset.id2Children[this.id];
        }
        if(this.id!="root"){
            let pre=this.path&&this.path.length>0?this.path[this.path.length-1]:'root';
            this._parent=pre;
            if(VeryEngine.shareBox.id2Asset[pre]){
                VeryEngine.shareBox.id2Asset[pre]._children.push(this.id);
            }else{
                if(!IEDAsset.id2Children[pre])
                    IEDAsset.id2Children[pre]=[];
                IEDAsset.id2Children[pre].push(this.id);
            }
        }
        this.watch("path",(val:string[])=>{
            if(val&&val.length!=0){
                let old=VeryEngine.shareBox.id2Asset[this._parent];
                if(old){
                    old._children.splice(old._children.indexOf(this.id),1);
                }
                this._parent=val[0];
                if(VeryEngine.shareBox.id2Asset[val[0]]){
                    VeryEngine.shareBox.id2Asset[val[0]]._children.push(this.id);
                }
            }
        })
        VeryEngine.shareBox.id2Asset[this.id]=this;
        if(VeryEngine.entityReady.have(this.id)){
            this.onceOnlyLoad();
        }
    }

    public getAssetByPath(path:string){
        let split=path.split('/');
        let asset=VeryEngine.shareBox.id2Asset[this.parent];
        if(asset){
            for(let s of split){
                if(asset){
                    if(s==".."){
                        asset=VeryEngine.shareBox.id2Asset[asset.parent];
                    }else if(s!="."){
                        for(let childStr of asset.children){
                            let tmp=VeryEngine.shareBox.id2Asset[childStr];
                            if(tmp.name==s){
                                asset=tmp;
                                break;
                            }
                        }
                    }
                }
            }
        }
        return asset;
    }

    private _children:string[]=[];
    private _parent:string="";

    public get children():string[]{
        return this._children;
    }
    public get parent():string{
        return this._parent;
    }

    public get data():DMap{
        return this._data.get("data");
    }

    public get fileHash():string{
        return this.get("file.hash");
    }

    public abstract assetObj:any;
    //上传时根据后缀，创建不同asset
    public abstract get suffix():string[];
    protected async upload(file:File,folderId?:string):Promise<any>{
        var hash = await  Tools.getmd5(file);
        var assetID = Tools.assetID();
        await OSS.uploadFile(file, assetID, file.name, hash);
        var createdAt = Tools.createdTime();
        let path=[];
        //记录原先path为[] 代表是最顶层的子物体，现在变成[root]
        if(folderId!=null){
            if(!folderId) path=[];
            else path=[folderId];
        }else if(VeryEngine.commonJson.get("pickAssetFolder")){
            path=[VeryEngine.commonJson.get("pickAssetFolder")]
        }else{
            path=[]
        }
        return {
            id: assetID,
            type: this.type,
            createdAt: createdAt,
            name: file.name,
            file: {
                filename: file.name,
                size: file.size,
                hash: hash,
            },
            path: path
        };
    }

    public async createUploadData(file:any,folderId?:string){
        let data=await this.upload(file,folderId);
        //只需在数据结构中增加数据，会自动监听并创建资源
        VeryEngine.shareBox.assetMap.set(data.id,new DMap(data));
    }

    public get size(){
        let size:number=this.get("file.size");
        if(size){
            let index=0;
            let b=["B","KB","MB","GB"]
            while(size>1024&&index<b.length){
                size=size/1024;
                index++;
            }
            return size.toFixed(2)+b[index];
        }else{
            return "0KB"
        }
    }

    protected abstract Load():Promise<void>;
    public loadComplete=false;
    private loading:any[]=[];
    public onceOnlyLoad():Promise<void>{
        let self=this;
        return new Promise<void>(async(resolve)=>{
            if(this.loadComplete)
                resolve();
            else{
                if(self.loading.length>0){
                    self.loading.push(resolve);
                }else{
                    self.loading.push(resolve);
                    await self.Load();
                    await IEDProxyFactory.loadComplete(self);
                    VeryEngine.entityReady.triggerEvent(self.id);
                    for(let r of self.loading){
                        r();
                    }
                    this.loadComplete=true;
                    self.loading=[];
                }
            }
        })
    }

    public async destroy() {
        if (this.fileName) {
            await OSS.deleteJsonAsset(
                this.id,
                this.fileName
            );
        }
        super.destroy();
        this.assetObj=undefined;
    }
    public export(vrData:any,file:IED[]){
        if(!file.includes(this)){
            for(let one of file){
                if(one.name==this.name){
                    console.log(this.name);
                    this._rename=this.id.substring(this.id.length-6)+this.name;
                    break;
                }
            }
            file.push(this);
        }
    }

    protected async convertSceneData?(children:string[]):Promise<any[]>;

    public loadToScene(parent?:IEDEntity|string,autoPick?:boolean){
        return new Promise<IEDEntity[]>(async(resolve)=>{
            if(this.convertSceneData){
                let children:string[]=[];
                let iedEntity:IEDEntity[]=[]
                await this.onceOnlyLoad();
                let sceneData=await this.convertSceneData(children);
                let pickEntity:IEDEntity;
                if(parent){
                    if(typeof parent =="string"){
                        parent=VeryEngine.shareBox.id2Entity[parent];
                    }
                    pickEntity=parent;
                }else{
                    //TODO 判断加载的父物体能否是当前选中对象的子物体，若不是将其放在根目录
                    // let pickEntityIds=VeryEngine.commonJson.get("pickEntity");
                    let pickEntityId=IEDEntity.rootId;
                    // if(pickEntityIds&&pickEntityIds.length!=0){
                    //     pickEntityId=pickEntityIds[0];
                    // }
                    pickEntity=VeryEngine.shareBox.id2Entity[pickEntityId];
                }
                let isFirst=true;
                let length=children.length;

                let tmpFunc=(entity:IEDEntity)=>{
                    iedEntity.push(entity);
                    if(iedEntity.length==length){
                        resolve(iedEntity);
                    }
                }
                if(pickEntity)
                    pickEntity.children.push(...children);
                for (let data of sceneData) {
                    data.originAsset=this.id;
                    VeryEngine.addEntityOnlyData(data).then((val)=>{
                        if(children.includes(val.id)){
                            if(isFirst&&autoPick!=false){
                                isFirst=false;
                                VeryEngine.pickEntity(val.id);
                            }
                            tmpFunc(val);
                        }
                    })
                }
            }else{
                resolve(null);
            }
        })
    }

    public downLoad(){
        OSS.getUrl(this.id,this.fileName,this.fileHash).then(url=>{
            var a = document.createElement('a');
            a.innerHTML =this.fileName;
            // 指定生成的文件名
            a.download =this.fileName
            a.href = url;
            document.body.appendChild(a);
            var evt = document.createEvent("MouseEvents");
            evt.initEvent("click", false, false);
            a.dispatchEvent(evt);
            document.body.removeChild(a);
        })
    }

    @ATTRIB("id")
    public attrID:IEDAttrib<DataType.String>={
        type:DataType.String,
        name:"ID",
        readonly:true
    }

    @ATTRIB("name")
    public attrName:IEDAttrib<DataType.Name>={
        type:DataType.Name,
        name:"名字"
    }
}