import { VeryEngine } from "./engine/VeryEngine";
import { IEDEntity } from "./entities";
import { IEDTable } from "./main";
import {PluginPackage } from "./plugin/IEDPlugin";
import { IContextmenu } from "./plugin/Iplugin";
import { Viewport } from "./viewport";

export class Hierarchy {
    private hierarchyParent: HTMLElement;
    private entityID2Html: { [key: string]: HTMLElement } = {};
    private lastHtmls: HTMLElement[] = [];
    private contextMenu: HTMLElement;
    private menuPathHtml:{[key:string]:HTMLElement}={};
    private firstChild:HTMLElement;
    private drag:HTMLElement;
    private dragSort:IEDEntity[]=[];
    private dragTarget:IEDEntity;
    private dragStart=false;
    public viewport:Viewport;
    private move: NodeJS.Timer;
    private hierarchy:HTMLElement;
    constructor() {
        this.hierarchyParent = document.getElementById("hierarchy-list-ui-container");
        this.hierarchyParent.onmousemove=(e)=>{
            if(this.dragStart){
                this.drag.style.top = e.clientY + 8 + "px";
                this.drag.style.left = e.clientX + 10 + "px";
                let rect=this.hierarchyParent.getBoundingClientRect();
                if(e.clientY-rect.top<10){
                    if(!this.move){
                        this.move=setInterval(()=>{
                            this.hierarchyParent.scrollTo(0,this.hierarchyParent.scrollTop-10);
                        }, 20);
                    }
                }else if(rect.top+rect.height-e.clientY<10){
                    if(!this.move){
                        this.move=setInterval(()=>{
                            this.hierarchyParent.scrollTo(0,this.hierarchyParent.scrollTop+10);
                        }, 20);
                    }
                }else{
                    if(this.move){
                        clearInterval(this.move);
                        this.move=undefined;
                    }
                }
            }
        };

        this.hierarchyParent.onclick = () => {
            if (this.filterType == null) VeryEngine.pickEntity("");
        };
        this.hierarchy = document.getElementById("layout-hierarchy");
        this.overLay=document.getElementById("asset-overlay");
        this.hierarchy.style.display = "block";
        this.hierarchy.onmousedown = (e) => {
            if (this.filterType==null&&e.button === 2) {
                this.contextMenuShow(e, null);
            }
            event.stopPropagation();
        };
        VeryEngine.shareBox.filterEntityType=this.filterEntityType.bind(this);
        this.contextMenu=document.getElementById("context-menu");
        this.drag=document.getElementById("drag");
        VeryEngine.commonJson.watch("pickEntity",(newVal:string[])=>{
            for(let html of this.lastHtmls){
                html.firstElementChild.classList.remove("active");
            }
            this.lastHtmls = [];
            for (let id of newVal) {
                if (this.entityID2Html[id]) this.lastHtmls.push(this.entityID2Html[id]);
            }
            if (this.lastHtmls.length != 0) {
                for (let html of this.lastHtmls) {
                    html.firstElementChild.classList.add("active");
                    let isOpen = this.dealWithParent(html);
                    if (!isOpen) {
                        this.sumOffset(html, 0);
                    } else {
                        setTimeout(() => {
                            this.sumOffset(html, 0);
                        }, 10);
                    }
                }
            }
        });
        VeryEngine.shareBox.sceneMap.watchObject("delete",(key,config:{origin:string})=>{
            if (VeryEngine.isLoadComplete) VeryEngine.change |= 2;
            this.removeEntity(key,config);
            VeryEngine.shareBox.id2Entity[key].destroy();
            delete VeryEngine.shareBox.id2Entity[key];
            let pickEntities:string[]=[...VeryEngine.commonJson.get("pickEntity")];
            let index=pickEntities.indexOf(key);
            if(index>=0){
                pickEntities.splice(index,1);
                VeryEngine.pickEntities(pickEntities);
            }
        });
        let searchInput: HTMLInputElement = document.querySelector("#hierarchy-search-text-input");
        let clearInput = () => {
            searchInput.value = "";
            this.hierarchyParent.classList.remove("input");
            if (timeOut) {
                clearTimeout(timeOut);
                timeOut = undefined;
            }
            this.hierarchyParent.innerHTML = "";
            this.hierarchyParent.append(this.firstChild);
        };
        let timeOut;
        searchInput.addEventListener("input", (e) => {
            if (searchInput.value != "") {
                if (!this.hierarchyParent.classList.contains("input")) {
                    this.hierarchyParent.innerHTML = "";
                    this.hierarchyParent.classList.add("input");
                    this.viewport.addPrePointerDown(clearInput);
                }
                if (!timeOut) {
                    timeOut = setTimeout(() => {
                        this.hierarchyParent.innerHTML = "";
                        let lastTime = 0;
                        let last;
                        let func = (entity: IEDEntity) => {
                            let now = new Date().getTime();
                            if (now - lastTime < 500 && last == entity) {
                                clearInput();
                                setTimeout(() => {
                                    if (this.filterType == null) VeryEngine.pickEntity(entity.id);
                                    else{
                                        this.revert();
                                        this.selectAct.resolve(entity);
                                        this.selectAct=undefined;
                                    }
                                }, 50);
                            }
                            lastTime = now;
                            last = entity;
                        };
                        for (let key in VeryEngine.shareBox.id2Entity) {
                            let entity = VeryEngine.shareBox.id2Entity[key];
                            if (entity.name.includes(searchInput.value)) {
                                if(this.filterType==null||this.filterType.includes(entity.type)||this.filterType.includes("*")){
                                    let div = document.createElement("div");
                                    div.classList.add("ui-input-li");
                                    div.innerText = entity.name;
                                    this.hierarchyParent.append(div);
                                    div.onclick = () => {
                                        func(entity);
                                    };
                                }
                            }
                        }
                        clearTimeout(timeOut);
                        timeOut = undefined;
                    }, 500);
                }
            } else {
                if (this.hierarchyParent.classList.contains("input")) {
                    this.viewport.romvePrePointerDown(clearInput);
                    clearInput();
                }
            }
        });
    }

    private dealWithParent(el: HTMLElement, open = false) {
        let parent = el.parentElement;
        if (parent?.classList.contains("ui-tree-item")) {
            if (parent.classList.contains("item-pre-close")) {
                parent.classList.remove("item-pre-close");
                parent.classList.add("item-pre");
                parent.firstElementChild.firstElementChild.innerHTML = `<svg class='icon icon-zhankai1' aria-hidden="true">
            <use xlink:href="#icon-zhankai1"></use></svg>`;
                open = true;
            }
            return this.dealWithParent(parent, open);
        } else {
            return open;
        }
    }

    private sumOffset(el: HTMLElement, offset: number) {
        offset = offset + el.offsetTop;
        let parent = el.parentElement;
        if (parent?.classList.contains("ui-tree-item")) {
            return this.sumOffset(parent, offset);
        } else {
            if (offset - this.hierarchyParent.scrollTop < this.hierarchyParent.clientHeight && offset + 24 > this.hierarchyParent.scrollTop) {
                return offset;
            }
            this.hierarchyParent.scrollTo(0, offset - this.hierarchyParent.clientHeight / 2);
            return offset;
        }
    }

    private pickWithChild(current:string,dirct:boolean,entity:string,list:string[]){
        if(dirct){
            list.push(current);
            if(current==entity){
                return true;
            }
        }
        let children:string[]=VeryEngine.shareBox.id2Entity[current].childIds;
        if(children&&this.entityID2Html[current].classList.contains("item-pre")){
            if(!dirct) children=[...children].reverse();
            for(let child of children){
                if(this.pickWithChild(child,dirct,entity,list)){
                    return true;
                }
            }
        }
        if(!dirct){
            list.push(current);
            if(current==entity){
                return true;
            }
        }
        return false;
    }
    private pickedEntities = [];
    public addEntity(entity: IEDEntity) {
        let div = document.createElement("div");
        div.classList.add("ui-tree-item");
        let spanContainer = document.createElement("div");
        let span = document.createElement("span");
        spanContainer.classList.add("ui-tree-li");
        span.classList.add("li-text");
        span.innerText = entity.name.replace("\n"," ");
        
        entity.watch("name",(val:string)=>{
            span.innerText=val;
        });
        spanContainer.onclick=(e)=>{
            e.stopPropagation();
            this.contextMenu.style.top="-1000px";
            if(this.filterType==null){
                if(e.shiftKey){
                    let start=VeryEngine.pickedEntity;
                    if(start&&start!=entity){
                        let dirct=this.entityID2Html[start.id].getBoundingClientRect().top<this.entityID2Html[entity.id].getBoundingClientRect().top;
                        let list:string[]=[];
                        if (dirct && this.pickWithChild(start.id, dirct, entity.id, list)) return;
                        while(true){
                            if(!start.parent){
                                break;
                            } else {
                                let parent = start.parent;
                                if(dirct){
                                    let children=parent.children;
                                    let index=children.indexOf(start);
                                    for(let i=index+1;i<children.length;i++){
                                        if(this.pickWithChild(children[i].id,dirct,entity.id,list)){
                                            VeryEngine.pickEntities(list,true);
                                            return;
                                        }
                                    }
                                }else{
                                    list.push(start.id);
                                    if(start==entity){
                                        VeryEngine.pickEntities(list,true);
                                        return;
                                    }
                                    let children = parent.children;
                                    for(let i=children.indexOf(start)-1;i>=0;i--){
                                        if(this.pickWithChild(parent.children[i].id,dirct,entity.id,list)){
                                            VeryEngine.pickEntities(list,true);
                                            return;
                                        }
                                    }
                                }
                                start=parent;
                            }
                        }
                    }
                }else{
                    VeryEngine.pickEntity(entity.id,e.ctrlKey);
                }
            }else{
                if(this.filterType.includes(entity.type)||this.filterType.includes("*")){
                    this.revert();
                    this.selectAct.resolve(entity);
                    this.selectAct=undefined;
                }
            }
        };
        spanContainer.onmousedown=(e)=>{
            event.stopPropagation();
            if(this.filterType==null){
                if(e.button===2){
                    this.contextMenu.style.top="-1000px";
                    this.contextMenuShow(e,entity);
                }else if(e.button==0&&!this.dragTarget){
                    this.dragTarget=entity;
                }
                window.onmouseup=()=>{
                    if (this.dragTarget) this.entityID2Html[this.dragTarget.id].firstElementChild.classList.remove("active2");
                    this.dragTarget=null;
                    this.drag.style.display="none";
                    this.dragStart=false;
                    if(this.move){
                        clearInterval(this.move);
                        this.dragSort=[];
                        this.move=undefined;
                    }
                };
            }
        };
        spanContainer.append(span);
        div.append(spanContainer);
        let children = entity.children;
        if (children && children.length != 0) {
            if (entity.type != "root") {
                div.classList.add("item-pre-close");
                let iconDiv = document.createElement("div");
                iconDiv.classList.add("li-icon");
                iconDiv.innerHTML = `<svg class='icon icon-helong' aria-hidden="true">
                <use xlink:href="#icon-helong"></use></svg>`;
                iconDiv.onclick = this.preClick.bind(this);
                spanContainer.prepend(iconDiv);
            }
            for (let i = 0; i < children.length; i++) {
                if (this.entityID2Html[children[i].id]) {
                    let last = true;
                    for (let j = i + 1; j < children.length; j++) {
                        if (this.entityID2Html[children[j].id] &&this.entityID2Html[children[j].id].parentElement==div) {
                            div.insertBefore(this.entityID2Html[children[i].id],this.entityID2Html[children[j].id]);
                            last = false;
                            break;
                        }
                    }
                    if (last) {
                        div.append(this.entityID2Html[children[i].id]);
                    }
                }
            }
        }
        if (entity.type != "root") {
            if(entity.parent){
                if (this.entityID2Html[entity.parent.id]) {
                    let parentEntity = entity.parent;
                    let parentDiv=this.entityID2Html[parentEntity.id];
                    if (parentEntity.type != "root" &&!parentDiv.classList.contains("item-pre")) {
                        parentDiv.classList.add("item-pre-close");
                        const liIconDiv = (parentDiv.firstChild as HTMLDivElement).querySelector(".li-icon") as HTMLDivElement;
                        if (liIconDiv) {
                            liIconDiv.remove();
                        }
                        const liDiv = parentDiv.firstChild as HTMLElement;
                        let iconDiv = document.createElement("div");
                        iconDiv.classList.add("li-icon");
                        iconDiv.innerHTML = `<svg class='icon' aria-hidden="true"><use xlink:href="#icon-helong"></use></svg>`;
                        iconDiv.onclick = this.preClick.bind(this);
                        liDiv.prepend(iconDiv);
                    }
                    let sibbing = parentEntity.children;
                    if (!sibbing) sibbing = [];
                    let index = sibbing.indexOf(entity);
                    let last = true;
                    for (let i = index + 1; i < sibbing.length; i++) {
                        if (this.entityID2Html[sibbing[i].id]) {
                            this.entityID2Html[entity.parent.id].insertBefore(div,this.entityID2Html[sibbing[i].id]);
                            last = false;
                            break;
                        }
                    }
                    if (last) this.entityID2Html[entity.parent.id].append(div);
                }
            }
        } else {
            this.firstChild = div;
            this.hierarchyParent.append(div);
        }
        entity.watch("children",(_,value:string,config:{deleted:boolean})=>{
            if(!config.deleted&&this.entityID2Html[value]==null) return;
            let children=entity.children;
            //和前面假设一样，删除操作，会直接导致div被remove，改变父子关系div会被添加到另外一个div下，故无需考虑删除的情况
            for(let i=0;i<children.length;i++){
                if(this.entityID2Html[children[i].id]){
                    if(!config.deleted){
                        div.append(this.entityID2Html[children[i].id]);
                    }
                }
            }
            
            if(entity.type!="root"){
                if(children.length==0&&config.deleted){
                    const liIconDiv = div.querySelector(".li-icon");
                    if (liIconDiv) {
                        liIconDiv.remove();
                    }
                    div.classList.remove("item-pre-close", "item-pre");
                } else if (!div.classList.contains("item-pre-close") &&!div.classList.contains("item-pre")) {
                    if(!config.deleted){
                        div.classList.add("item-pre");
                        const liIconDiv = (div.firstChild as HTMLDivElement).querySelector(".li-icon") as HTMLDivElement;
                        if (!liIconDiv) {
                            const liDiv = div.firstChild as HTMLElement;
                            let iconDiv = document.createElement("div");
                            iconDiv.classList.add("li-icon");
                            iconDiv.innerHTML = `<svg class='icon' aria-hidden="true"><use xlink:href="#icon-zhankai1"></use></svg>`;
                            iconDiv.onclick = this.preClick.bind(this);
                            liDiv.prepend(iconDiv);
                        }
                    }
                }
            }
        });
        entity.watch("enabled",(val)=>{
            if(this.filterType==null){
                if(val){
                    div.style.color = "inherit";
                }else{
                    div.style.color="rgba(255,255,255,0.4)";
                }
            }
        });
        if(entity.enabled===false){
            div.style.color="rgba(255,255,255,0.4)";
        }
        this.entityID2Html[entity.id] = div;
        spanContainer.onmouseleave=()=>{
            if(!this.dragStart){
                if(this.dragTarget){
                    let children=this.dragTarget.parent.children;
                    let arr=[];
                    this.dragSort=[];
                    this.dragSort.push(this.dragTarget);
                    arr.push(children.indexOf(this.dragTarget));
                    let showText = this.dragTarget.name;
                    let count=0;
                    if(VeryEngine.pickedEntities.includes(this.dragTarget)){
                        this.pickedEntities=VeryEngine.pickedEntities;
                    }else{
                        this.pickedEntities=[this.dragTarget];
                    }
                    for(let pick of this.pickedEntities){
                        if(pick==this.dragTarget) continue;
                        count++;
                        if(this.dragTarget.parent!=pick.parent){
                            showText=undefined;
                            this.dragSort=[];
                            break;
                        }else if(count<3){
                            showText += "," + pick.name;
                        }
                        this.dragSort.push(pick);
                        arr.push(children.indexOf(pick.id));
                    }
                    if(showText){
                        if(count>2) showText=showText+"...";
                        this.dragStart=true;
                        
                        this.drag.innerText=showText;
                        this.drag.style.display="block";
                        spanContainer.classList.add("active2");
                        for (let i = 0; i < arr.length-1; i++){
                            for(let j = 0; j < arr.length-1-i; j++){
                                if(arr[j]>arr[j+1]){
                                    let temp = arr[j + 1];
                                    arr[j + 1] = arr[j];
                                    arr[j] = temp;
                                    let tmp2=this.dragSort[j+1];
                                    this.dragSort[j+1]=this.dragSort[j];
                                    this.dragSort[j]=tmp2;
                                }
                            } 
                        }
                    }
                }
            } else {
                spanContainer.classList.remove("check", "check-top", "not-allow");
        }
        };
        spanContainer.onmousemove=(e)=>{
            if(this.dragStart&&!this.pickedEntities.includes(entity)){
                if(!this.isParent(entity)){
                    let rect=spanContainer.getBoundingClientRect();
                    if(e.clientY-rect.top<7){
                        if(entity.parent){
                            let parentEntity=entity.parent;
                            if(entity.parent==this.dragTarget.parent){
                                let children=parentEntity.children;
                                let index=children.indexOf(this.dragSort[this.dragSort.length-1]);
                                let index2=children.indexOf(entity);
                                if(index2-index==1){
                                    return;
                                }
                            }
                            if(this.filterParentType(parentEntity)){
                                spanContainer.classList.remove("check","not-allow");
                                spanContainer.classList.add("check-top");
                            } else {
                                spanContainer.classList.remove("check-top", "check");
                                spanContainer.classList.add("not-allow");
                            }
                        } else {
                            spanContainer.classList.remove("check", "check-top", "not-allow");
                        }
                    } else {
                        let result = this.dragTarget.parent != entity;
                        if (!result) {
                            let children = entity.children;
                            result =children.indexOf(this.dragTarget) !=children.length -1;
                        }
                        if(result){
                            if(this.filterParentType(VeryEngine.shareBox.id2Entity[entity.id])){
                                spanContainer.classList.add("check");
                                spanContainer.classList.remove("check-top", "not-allow");
                            } else {
                                spanContainer.classList.remove("check-top", "check");
                                spanContainer.classList.add("not-allow");
                            }
                        } else {
                            spanContainer.classList.remove("check", "check-top", "not-allow");
                    }
                }
            }
        }
        };
        spanContainer.onmouseup=()=>{
            if(this.dragStart){
                if(spanContainer.classList.contains("check")){
                    let parentEntity=this.dragTarget.parent;
                    if(parentEntity){
                        let sibbing=parentEntity.children;
                        for(let tmp of this.dragSort){
                            let index=sibbing.indexOf(tmp);
                            sibbing.splice(index,1);
                        }
                    }
                    for(let tmp of this.dragSort){
                        entity.children.push(tmp.id);
                    }
                    spanContainer.classList.remove("check");
                }else if(spanContainer.classList.contains("check-top")){
                    let parentEntity=this.dragTarget.parent;
                    if(parentEntity){
                        let sibbing = parentEntity.children;
                        for(let tmp of this.dragSort){
                            let index=sibbing.indexOf(tmp);
                            sibbing.splice(index,1);
                        }
                    }
                    parentEntity=entity.parent;
                    if(parentEntity){
                        let sibbing=parentEntity.children;
                        let ids = [];
                        for(let tmp of this.dragSort){
                            ids.push(tmp);
                        }
                        parentEntity.children.splice(sibbing.indexOf(entity), 0, ...ids);
                    }
                    spanContainer.classList.remove("check-top");
                } else {
                    spanContainer.classList.remove("not-allow");
                }
            }
        };
    }

    public filterParentType(parentEntity:IEDEntity){
        for(let tmp of this.pickedEntities){
            if(!tmp.filterParentType(parentEntity)){
                return false;
            }
        }
        return true;
    }
    private isParent(child:IEDEntity){
        if(this.dragTarget==child||this.pickedEntities.includes(child)){
            return true;
        } else {
            let childParent = child.parent;
            if (!childParent || childParent.type == "root") {
                return false;
            }else{
                return this.isParent(childParent);
            }
        }
    }

    public removeEntity(id:string,config:{origin:string}){
        let entity=VeryEngine.shareBox.id2Entity[id];
        let parent=entity.parent;
        if(parent){
            if(config.origin!="force"){
                if(!parent.isDestroy){
                    let index=parent.children.indexOf(entity);
                    if(index>=0){
                        parent.children.splice(index,1);
                    }
                }
            }else{
                parent.removeChildButRecord(entity);
                //强制删除=背后数据还在只需要删除场景中的内容
                IEDEntity.loadedParentChild[id]=parent;
            }
        }
        if (this.entityID2Html[id]) {
            this.entityID2Html[id].remove();
            delete this.entityID2Html[id];
        }
    }

    private preClick(e: PointerEvent) {
        let div = e.currentTarget as HTMLElement;
        let iconDiv = div.children[0];
        let parentUlDiv = div.parentElement.parentElement;

        if (parentUlDiv.classList.contains("item-pre-close")) {
            iconDiv.innerHTML = `<svg class='icon icon-zhankai1' aria-hidden="true">
            <use xlink:href="#icon-zhankai1"></use></svg>`;
            parentUlDiv.classList.remove("item-pre-close");
            parentUlDiv.classList.add("item-pre");
        } else if (parentUlDiv.classList.contains("item-pre")) {
            iconDiv.innerHTML = `<svg class='icon icon-helong' aria-hidden="true">
            <use xlink:href="#icon-helong"></use></svg>`;
            parentUlDiv.classList.remove("item-pre");
            parentUlDiv.classList.add("item-pre-close");
        }
        this.contextMenu.style.top = "-1000px";
        e.stopPropagation();
    }

    //插件 右键菜单功能
    private itemList: { [key: string]: IContextmenu[] } = {};
    public addMenuItem(id: string, any: IContextmenu) {
        if (!this.itemList[id]) this.itemList[id] = [];
        this.itemList[id].push(any);
    }
    public removeMenuItem(id: string) {
        delete this.itemList[id];
    }
    private contextMenuShow(e: MouseEvent, target: IEDEntity) {
        this.contextMenu.innerHTML = "";
        this.menuPathHtml={};
        let entities:IEDEntity[]=[...VeryEngine.pickedEntities];
        //若target不存在，则为右键空白处情况
        if (!target) {
            entities.unshift(null);
        } else {
            let index = entities.indexOf(target);
            if (index >= 0) {
                entities.splice(index, 1);
                entities.unshift(target);
            }else{
                entities=[target];
            }
        }
        for (let key in this.itemList) {
            for (let item of this.itemList[key]) {
                let filter = false;
                if (item.include) {
                    if (entities[0] == null) {
                        for (let tmp of item.include) {
                            if (tmp == "*" || tmp == "root") {
                                filter = true;
                                break;
                            }
                        }
                    } else {
                        for (let tmp of item.include) {
                            if (tmp == "*") {
                                filter = true;
                                break;
                            }
                            if (tmp == "transform") {
                                if ("calRot" in entities[0]) {
                                    filter = true;
                                    break;
                                }
                            } else {
                                let split = tmp.split(".");
                                if (split.length == 1 &&tmp == entities[0].type) {
                                    filter = true;
                                    break;
                                } else if (split.length == 2 &&tmp ==entities[0].type +"." +entities[0].subtype) {
                                    filter = true;
                                    break;
                                }
                            }
                        }
                    }
                } else if (item.includeMulti) {
                    filter = true;
                    for (let entity of entities) {
                        if (entity != null) {
                            let tmpPass = false;
                            for (let tmp of item.includeMulti) {
                                if (tmp == "*") {
                                    tmpPass = true;
                                    break;
                                }
                                if (tmp == "transform") {
                                    if ("calRot" in entity) {
                                        tmpPass = true;
                                        break;
                                    }
                                } else {
                                    let split = tmp.split(".");
                                    if (split.length == 1 && tmp == entity.type) {
                                        tmpPass = true;
                                        break;
                                    } else if (split.length == 2 && tmp == entity.type + "." + entity.subtype) {
                                        tmpPass = true;
                                        break;
                                    }
                                }
                            }
                            if (!tmpPass) {
                                filter = false;
                                break;
                            }
                        }
                    }
                } else {
                    filter = true;
                }
                if (filter) {
                    if (item.exclude) {
                        if (entities[0] == null) {
                            for (let tmp of item.exclude) {
                                if (tmp == "root") {
                                    filter = false;
                                    break;
                                }
                            }
                        } else {
                            for (let tmp of item.exclude) {
                                if (tmp == "transform") {
                                    if ("calRot" in entities[0]) {
                                        filter = false;
                                        break;
                                    }
                                } else {
                                    let split = tmp.split(".");
                                    if (split.length == 1 &&tmp == entities[0].type) {
                                        filter = false;
                                        break;
                                    } else if (split.length == 2 &&tmp ==entities[0].type +"." +entities[0].subtype) {
                                        filter = false;
                                        break;
                                    }
                                }
                            }
                        }
                    } else if (item.excludeMulti) {
                        if (item.excludeMulti.includes("blank") && entities.length == 1 && entities[0] == null) {
                            filter = false;
                        } else {
                            for (let entity of entities) {
                                if (entity != null) {
                                    let tmpPass = true;
                                    for (let tmp of item.excludeMulti) {
                                        if (tmp == "transform") {
                                            if ("calRot" in entity) {
                                                tmpPass = false;
                                                break;
                                            }
                                        } else {
                                            let split = tmp.split(".");
                                            if (split.length == 1 && tmp == entity.type) {
                                                tmpPass = false;
                                                break;
                                            } else if (split.length == 2 && tmp == entity.type + "." + entity.subtype) {
                                                tmpPass = false;
                                                break;
                                            }
                                        }
                                    }
                                    if (!tmpPass) {
                                        filter = false;
                                        break;
                                    }
                                }
                            }
                        }
                    } else {
                        filter = true;
                    }
                }

                if (filter) {
                    let current = this.contextMenu;
                    if (item.path) {
                        for (let path of item.path) {
                            let last = current;
                            current = this.menuPathHtml[path];
                            if (!current) {
                                let tmp = document.createElement("div");
                                tmp.classList.add("context_menu", "child");
                                let pathDiv = document.createElement("div");
                                pathDiv.innerText = path;
                                pathDiv.classList.add("item");
                                tmp.append(pathDiv);
                                current = document.createElement("div");
                                current.classList.add("content");
                                tmp.append(current);
                                last.append(tmp);
                                this.menuPathHtml[path] = current;
                                let transfer=current;
                                tmp.addEventListener("mouseenter",()=>{
                                    let bottom=transfer.childElementCount*33+transfer.getBoundingClientRect().top-document.body.clientHeight;
                                    if(bottom>0){
                                        let count=Math.ceil(bottom/33);
                                        transfer.style.top = -count * 33 + "px";
                                    }
                                });
                            }
                        }
                    }

                    let btn = document.createElement("div");
                    btn.classList.add("context_menu");
                    let btnTxt = document.createElement("div");
                    btnTxt.classList.add("item");
                    btnTxt.innerText = item.text;
                    btn.append(btnTxt);
                    if (item.excludeMulti || item.includeMulti) {
                        btn.onclick = () => {
                            item.onclick(entities);
                        };
                    } else {
                        btn.onclick = () => {
                            item.onclick(entities[0]);
                        };
                    }
                    current.append(btn);
                }
            }
        }
        if (this.contextMenu.innerHTML) {
            this.contextMenu.style.left = e.clientX + "px";
            this.contextMenu.style.top = Math.min(document.body.clientHeight-this.contextMenu.childElementCount*33,e.clientY) + "px";
        }
    }

    private overLay:HTMLElement;
    private filterType:string[];
    private selectAct: { resolve: (value: IEDEntity | PromiseLike<IEDEntity>) => void; reject: any };
    private filterEntityType(type: string|string[]) {
        return new Promise<IEDEntity>((resolve,reject)=>{
            let root=VeryEngine.shareBox.id2Entity[IEDEntity.rootId];
            if(root){
                this.overLay.onclick = () => {
                    this.revert();
                    this.selectAct.reject(null);
                    this.selectAct=undefined;
                };
                this.hierarchy.style.zIndex="4";
                this.overLay.style.display = "block";
                if (typeof type == "string") this.filterType = [type];
                else this.filterType = type;
                this.selectAct={resolve:resolve,reject:reject};
                this.judgeChildType(root);
            }else{
                resolve(null);
            }
        });
    }
    private activeHtml=[];
    private judgeChildType(parent:IEDEntity){
        let result=false;
        for(let childEntity of parent.children){
            if(childEntity){
                if(this.entityID2Html[childEntity.id]&&this.entityID2Html[childEntity.id].firstElementChild.classList.contains("active")){
                    this.activeHtml.push(childEntity.id);
                    this.entityID2Html[childEntity.id].firstElementChild.classList.remove("active");
                }
                if(this.filterType.includes(childEntity.type)||this.filterType.includes("*")){
                    this.entityID2Html[childEntity.id].style.color="rgb(250,255,255)";
                    // if(!this.judgeChildType(childEntity)){
                    //     this.dealWithParent(this.entityID2Html[childEntity.id])
                    // }
                    this.judgeChildType(childEntity);
                    result=true;
                }else{
                    if(this.judgeChildType(childEntity)){
                        this.entityID2Html[childEntity.id].style.color="rgba(250,255,255,0.4)";
                        result=true;
                    }else{
                        this.entityID2Html[childEntity.id].style.display="none";
                    }
                }
            }
        }
        return result;
    }

    private revert(){
        this.hierarchy.style.zIndex="2";
        this.overLay.style.display = "none";
        this.filterType =null;
        for(let key in VeryEngine.shareBox.id2Entity){
            let entity=VeryEngine.shareBox.id2Entity[key];
            if(entity&&this.entityID2Html[entity.id]){
                this.entityID2Html[entity.id].style.display = "";
                if(entity.enabled===false){
                    this.entityID2Html[entity.id].style.color="rgba(255,255,255,0.4)";
                }else{
                    this.entityID2Html[entity.id].style.color = "inherit";
                }
            }
        }
        for(let div of this.activeHtml){
            this.entityID2Html[div].firstElementChild.classList.add("active");
        }
        this.activeHtml=[];
    }
}
