import { IEDMaterial } from "../assets";
import { VeryEngine } from "./VeryEngine";

export class PreviewMaterial{
    private previewSphere:BABYLON.Mesh;
    private camera:BABYLON.UniversalCamera;
    private queueMaterialAssets:IEDMaterial[]=[];

    constructor(){
        this.previewSphere = BABYLON.MeshBuilder.CreateSphere('__previewSphere', { diameter: 100 }, VeryEngine.scene);
        this.previewSphere.isPickable = false;
        this.previewSphere.checkCollisions = false;
        this.previewSphere.layerMask = 0x90000000;
        this.previewSphere.position = new BABYLON.Vector3(0, 0, 0);

        this.camera = new BABYLON.UniversalCamera('__previewCamera', new BABYLON.Vector3(this.previewSphere.position.x, this.previewSphere.position.y + 62, this.previewSphere.position.z + 120), VeryEngine.scene);
        this.camera.rotation = BABYLON.Vector3.Zero();
        this.camera.inputs.clear();
        this.camera.rotation.x =27.2 * Math.PI / 180;
        this.camera.layerMask = 0x90000000;
        this.camera.setTarget(this.previewSphere.position);

        let light = new BABYLON.HemisphericLight('__previewlight', new BABYLON.Vector3(0, 1, 0), VeryEngine.scene);
        light.intensity = 1;
        light.includeOnlyWithLayerMask =0x90000000;
    }

    public createMatPreview(mat:IEDMaterial,vip?:boolean){
        if(this.queueMaterialAssets.length==0){
            this.queueMaterialAssets.push(mat);
            this.dealWithMaterial();
        }else{
            if(this.queueMaterialAssets.indexOf(mat)<0){
                if(!vip)
                    this.queueMaterialAssets.push(mat);
                else
                    this.queueMaterialAssets.splice(1,0,mat);
            }
        }
    }

    public async dealWithMaterial(){
        for(let i=0;i< this.queueMaterialAssets.length;){
            let mat=this.queueMaterialAssets[i];
            await mat.onceOnlyLoad();
            this.previewSphere.material = mat.assetObj;
            await new Promise<void>(async(resolve)=>{
                this.previewSphere.onMeshReadyObservable.add(async()=>{
                    await this.shotPreview(mat);
                    resolve()
                })
            }) 
            this.queueMaterialAssets.splice(i, 1);

        }
    }

    private async shotPreview(mat:IEDMaterial){
        let base64= await new Promise<string>((resolve)=>{
            BABYLON.Tools.CreateScreenshotUsingRenderTarget(VeryEngine.engine, this.camera, 64, (data: string) => {
               resolve(data);
             });            
        })
        //草泥马这一句用了2.5小时
        this.previewSphere.material=undefined;
        mat.setPreview(base64);          
    }
}