import { DMap } from "../djs/type";
import { IEDAsset, IEDTexture } from ".";
import { VeryEngine } from "../engine";
import { Tools } from "../utility/Tools";
import { addAssetClass } from "../engine/IEDProxy";
import { IEDNodeMaterial } from "./Material/IEDNodeMaterial";

@addAssetClass
export class IEDJson extends IEDAsset{

    public get type(): string {
        return "json"
    }

    public assetObj: any;
    
    protected async Load() {
        try {
            this.assetObj = JSON.parse(await OSS.getJsonAsset(this.id, this.fileName, this.fileHash));
        } catch (e) {
            console.error(e);
            this.assetObj = null;
        }
    }

    public get suffix(): string[] {
        return ["json"];
    }

    protected async upload(file:File,folderId?:string):Promise<any>{
        var hash = await  Tools.getmd5(file);
        var assetID = Tools.assetID();
        var createdAt = Tools.createdTime();
        let path=[];
        if(folderId!=null){
            if(!folderId) path=[];
            else path=[folderId];
        }else if(VeryEngine.commonJson.get("pickAssetFolder")){
            path=[VeryEngine.commonJson.get("pickAssetFolder")]
        }else{
            path=[]
        }
        let data={
            id: assetID,
            type: this.type,
            createdAt: createdAt,
            name: file.name,
            file: {
                filename: file.name,
                size: file.size,
                hash: hash,
            },
            path: path
        };
        let jsonFile:any = await new Promise<string>((resolve, reject) => {
            var reader = new FileReader();
            reader.readAsText(file, 'utf-8');
            reader.onload = function (e) {
                resolve(reader.result!.toString());
            };
            reader.onerror = function (err) {
                reject(err);
            }
        });
        try{
            jsonFile = JSON.parse(jsonFile);
            //无需生成json asset
            if (jsonFile['customType'] && jsonFile['customType'] === 'BABYLON.NodeMaterial'){
                //上传json，并生成一个nodematerial id指向这个json
                await OSS.uploadFile(file, assetID, file.name, hash);
                await IEDNodeMaterial.prototype.createUploadData(
                    {file:data.file,customType:'BABYLON.NodeMaterial',name:file.name,materialId:jsonFile.id,assetId:assetID}
                ,folderId);
                return null;
            }else if(jsonFile['particleEmitterType']){
                data["subtype"] = "ParticleSystem";
                if (jsonFile.texture && jsonFile.texture.url) {
                    // 贴图名
                    var tmpfilename = file.name;
                    var tmpArray = tmpfilename.split(".");
                    tmpfilename =
                        tmpfilename.substring(0, tmpArray[0].length) + ".png";
    
                    // base64转blob
                    const base64ToBlob = function (base64Data: any) {
                        let arr = base64Data.split(","),
                            fileType = arr[0].match(/:(.*?);/)[1],
                            bstr = atob(arr[1]),
                            l = bstr.length,
                            u8Arr = new Uint8Array(l);
                        while (l--) {
                            u8Arr[l] = bstr.charCodeAt(l);
                        }
                        return new Blob([u8Arr], {
                            type: fileType,
                        });
                    };
                    // blob转file
                    const blobToFile = function (newBlob: Blob, fileName: any) {
                        var file = new File([newBlob], fileName, {
                            type: "application/octet-stream",
                        });
                        return file;
                    };
                    const blob = base64ToBlob(jsonFile.texture.url);
                    const textureFile = blobToFile(blob, tmpfilename);
                    await IEDTexture.prototype.createUploadData(textureFile,folderId);
                    let parentId=folderId;
                    if(!parentId) parentId='root';
                    for(let child of VeryEngine.shareBox.id2Asset[parentId].children){
                        let childAsset=VeryEngine.shareBox.id2Asset[child];
                        if(childAsset)
                        if(childAsset&&childAsset.name==tmpfilename){
                            delete jsonFile.texture;
                            jsonFile.particleTexture=childAsset.id;
                            break;
                        }
                    }
                    let particleEmitterType=jsonFile.particleEmitterType;
                    if(particleEmitterType){
                        delete jsonFile.particleEmitterType;
                        if(!particleEmitterType.type||particleEmitterType.type=="BoxParticleEmitter"){
                            jsonFile.emitterType=0;
                        }else if(particleEmitterType.type=="ConeParticleEmitter"){
                            jsonFile.emitterType=1;
                        }else if(particleEmitterType.type=="CylinderParticleEmitter"){
                            jsonFile.emitterType=2;
                        }else if(particleEmitterType.type=="HemisphericParticleEmitter"){
                            jsonFile.emitterType=3;
                        }else if(particleEmitterType.type=="PointParticleEmitter"){
                            jsonFile.emitterType=4;
                        }else{
                            jsonFile.emitterType=5;
                        }
                        jsonFile.direction1=particleEmitterType.direction1;
                        jsonFile.direction2=particleEmitterType.direction2;
                        jsonFile.minEmitBox=particleEmitterType.minEmitBox;
                        jsonFile.maxEmitBox=jsonFile.maxEmitBox;
                    }
                    await OSS.uploadFile(new File([JSON.stringify(jsonFile)],tmpfilename), assetID, file.name, hash);
                    return data;
                }else{
                    return data;
                }
            }else{
                await OSS.uploadFile(file, assetID, file.name, hash);
                return data;
            }
        }catch{
            console.error("上传文件:"+file.name+",非json文件请检查");
        }
    }


    public async createUploadData(file: any,folderId?:string){
        let data=await this.upload(file,folderId);
        if(data){
            VeryEngine.shareBox.assetMap.set(data.id, new DMap(data));
        }
    }

    protected async convertSceneData(children:string[]){
        if(this.subtype!="ParticleSystem"){
            return []
        }else{
            let obj=this.assetObj;
            obj.resource_id=Tools.uuid();
            obj.type="particle";
            obj.subtype="ParticleSystem";
            children.push(obj.resource_id)
            return [obj]
        }
    }
}