import { AbstractType, DMap,DArray} from "../type"
import { AbstractContent,addContent} from "./AbstractContent";
import {Item} from "./Item";
import { ByteBuffer } from "../util/ByteBuffer";

@addContent
export class ContentType extends AbstractContent {
    private type:AbstractType;
    constructor (type:AbstractType) {
      super();
      this.type = type
    }
  
    getLength () {
      return 1
    }
  
    public get refID(): number {
      return 3;
    }
    
    getContent () {
      return [this.type]
    }
  
    isCountable () {
      return true
    }
  
    mergeWith (right) {
      return false
    }
    //offset必定是0
    splice(offset: number) {
        if(offset==0){
          return this;
        }else{
          return null;
        }
    }
    
    copy () {
      return new ContentType(this.type)
    }

    integrate (item:Item) {
      this.type._integrate(item.parent.doc,item)
    }

    delete () {
      this.type.deepClear();
    }

    public reset(value: AbstractType): void {
      this.type=value;
    }
    write(buff:ByteBuffer,offset?: number): void {
      buff.WriteByte(this.type.refID);
    }
    value(){
      return this.type;
    }

    read(buf: ByteBuffer): AbstractContent {
      let refID=buf.ReadByte();
      if(refID===1){
        return new ContentType(new DMap());
      }else if(refID===2){
        return new ContentType(new DArray());
      }
      return null;
    }
  }