import {  IEDAsset} from ".";
import { VeryEngine,DataType} from "../engine";
import { ATTRIB, IEDAttrib, addAssetClass } from "../engine/IEDProxy";

@addAssetClass
export class IEDProbeTexture extends IEDAsset{

    public get type(): string {
        return "texture_probe"
    }

    public get suffix(): string[] {
        return ["probe"];
    }

    public assetObj: BABYLON.ReflectionProbe;
    private _baseTexture: Nullable<BABYLON.BaseTexture> = null;
    public get BaseTexture(): Nullable<BABYLON.BaseTexture> {
        return this._baseTexture;
    }
    public set BaseTexture(val: Nullable<BABYLON.BaseTexture>) {
        this._baseTexture = val;
    }

    protected async Load() {
        const mirror = new BABYLON.ReflectionProbe(this.id + '.probe', 512, VeryEngine.scene, true);
        this.BaseTexture = mirror.cubeTexture;
        this.assetObj=mirror;
    }

    
    public init(): void {
        this.onceOnlyLoad();
    }

    protected dispose(): void {
        this.assetObj.dispose();
        if (this._baseTexture) {
            this._baseTexture.dispose();
        }
    }

    private title="环境反射贴图";
    @ATTRIB("size")
    public mirrorSize:IEDAttrib<DataType.DropDown>={
        name:"贴图大小",
        extra: ['256', '512', '1024', '2048', '4096'],
        onchange(this:IEDProbeTexture,val) {
            const size = Math.pow(2, val) * 256;
            this.assetObj.cubeTexture.resize(size);
        },
        type:DataType.DropDown,
        default:1,
        title:this.title
    }

    @ATTRIB()
    public level:IEDAttrib<DataType.Number>={
        name:"level",
        onchange(this:IEDProbeTexture,val) {
            this.assetObj.cubeTexture.level=val;
        },
        type:DataType.Number,
        default:1,
        title:this.title
    }


    @ATTRIB()
    public refreshRate:IEDAttrib<DataType.Number>={
        name:"刷新率",
        onchange(this:IEDProbeTexture,val) {
            this.assetObj.cubeTexture.refreshRate=val;
        },
        type:DataType.Number,
        default:1,
        title:this.title
    }

    @ATTRIB()
    public tag:IEDAttrib<DataType.DropDown>={
        name:"反射物体标签",
        extra:this.getTags,
        type:DataType.DropDown,
        title:this.title,
        default:"empty",
        onchange(this: IEDProbeTexture, val: string) {
            if (this.assetObj.cubeTexture.renderList && this.assetObj.cubeTexture.renderList.length > 0) {
                while (this.assetObj.cubeTexture.renderList.length > 0) {
                    this.assetObj.cubeTexture.renderList.splice(0, 1);
                }
            } else {
                this.assetObj.cubeTexture.renderList = [];
            }
            VeryEngine.useTag(val,this.id,"tag",(isAdd, id)=>{
                if (VeryEngine.shareBox.id2Entity[id] ) {
                    if (VeryEngine.shareBox.id2Entity[id].sceneObj instanceof BABYLON.TransformNode) {
                        if (isAdd) {
                            this.linkWithTag(VeryEngine.shareBox.id2Entity[id].sceneObj, this.assetObj.cubeTexture);
                        } else {
                            this.unlinkWithTag(VeryEngine.shareBox.id2Entity[id].sceneObj, this.assetObj.cubeTexture);
                        }
                    }
                }
            }); 
        }
    }

    @ATTRIB()
    public attach:IEDAttrib<DataType.DropDown>={
        name:"反射位置定位物体",
        extra:this.getTags,
        type:DataType.DropDown,
        title:this.title,
        default:"empty",
        onchange(this: IEDProbeTexture, val: string) {
            if (val === 'empty') {
                this.assetObj.attachToMesh(null);
            }else{
                VeryEngine.useTag(val, this.id, 'attach', (isAdd, id) => {
                    if (VeryEngine.shareBox.id2Entity[id]) {
                        if (VeryEngine.shareBox.id2Entity[id].sceneObj instanceof BABYLON.AbstractMesh) {
                            this.assetObj.attachToMesh(VeryEngine.shareBox.id2Entity[id].sceneObj);
                        }
                    }

                })
            }
        }
    }

    private getTags(val: string) {
        let tmp = { "empty": "默认:空" };
        for (let key in VeryEngine.systemTags) {
            tmp[key] = key;
        }
        if (val && !(val in tmp)) {
            tmp[val] = val;
        }
        return tmp;
    }

    private linkWithTag(node: BABYLON.TransformNode | BABYLON.AbstractMesh, cubemap: BABYLON.RenderTargetTexture) {
        if (node instanceof BABYLON.AbstractMesh) {
            let ind = cubemap.renderList!.indexOf(node);
            if (ind === -1) {
                cubemap.renderList!.push(node);
            }
        }
        if (node.getChildren()) {
            let children = node.getChildren();
            for (let i = 0; i < children.length; i++) {
                if (children[i] instanceof BABYLON.TransformNode) {
                    this.linkWithTag(<BABYLON.TransformNode>children[i], cubemap);
                } else if (children[i] instanceof BABYLON.AbstractMesh) {
                    this.linkWithTag(<BABYLON.AbstractMesh>children[i], cubemap);
                }
            }
        }
    }

    private unlinkWithTag(node: BABYLON.TransformNode, cubemap: BABYLON.RenderTargetTexture) {
        if (node instanceof BABYLON.AbstractMesh) {
            let ind = cubemap.renderList!.indexOf(node);
            if (ind !== -1) {
                cubemap.renderList!.splice(ind, 1);
            }
        }
        if (node.getChildren()) {
            let children = node.getChildren();
            for (let i = 0; i < children.length; i++) {
                if (children[i] instanceof BABYLON.TransformNode) {
                    this.unlinkWithTag(<BABYLON.TransformNode>children[i], cubemap);
                } else if (children[i] instanceof BABYLON.AbstractMesh) {
                    this.unlinkWithTag(<BABYLON.AbstractMesh>children[i], cubemap);
                }
            }
        }
    }
}