import $ from "jquery";
export class Message {
    public static showAlert(data: AlertData) {
        let { type, text, closeable } = data;
        let icon = "";
        switch (type) {
            case "warn":
                icon = "jinggao";
                break;
            case "success":
                icon = "dui";
                break;
            case "error":
                icon = "cuo";
                break;

            default:
                break;
        }
        const div: JQuery<HTMLElement> = $(`
        <div class="message">
            <svg class="icon icon-${icon}" aria-hidden="true">
                <use xlink:href="#icon-${icon}"></use>
            </svg>
            <span>${text}</span>
        </div>
        `);
        $(".message-container").append(div);

        setTimeout(() => {
            div.css("opacity", 1);
        }, 0);
        if (closeable!=false) {
            setTimeout(() => {
                div.css("margin-top", "-40px");
                div.css("opacity", 0);
                setTimeout(() => {
                    div.remove();
                }, 1000);
            }, 2000);
        }
    }
    public static removeAlert() {
        $(".message-container").empty();
    }
}
interface AlertData {
    type: "warn" | "success" | "error";
    text: string;
    closeable?: boolean;
}
