import { IEDAsset } from ".";
import { DataType } from "../engine";
import { addAssetClass } from "../engine/IEDProxy";

@addAssetClass
export class IEDVideo extends IEDAsset {
    public get type(): string {
        return "video";
    }

    public assetObj: string;

    protected async Load() {
        try {
            this.assetObj = await OSS.getUrl(
                this.id,
                this.fileName,
                this.fileHash
            );
        } catch (e) {
            console.error(e);
            this.assetObj = null;
        }
    }

    public get suffix(): string[] {
        return ["mp4", "ogv", "ogg", "m4a", "mkv", "webm"];
    }
}
