import { VeryEngine } from "../engine/VeryEngine";
import { Config } from "../utility/Config";

export class VeryCamera extends BABYLON.TransformNode {

    private _canvas: HTMLCanvasElement;
    private _width: number;
    private _height: number;

    public get mode(): number {
        return this.camera.mode;
    }
    public set mode(val: number) {
        this.camera.mode = val;
        if (val === BABYLON.Camera.ORTHOGRAPHIC_CAMERA) {
            this.orthoSize = this._orthoSize;
        }
    }

    public get fov(): number {
        return this.camera.fov;
    }
    public set fov(val: number) {
        // this.camera.fov = Tools.eulerAngleFloatToRadian(val);
        this.camera.fov = val;
    }

    public get inertia(): number {
        return this.camera.inertia;
    }
    public set inertia(val: number) {
        this.camera.inertia = val;
    }

    private _orthoSize: number = 0;
    public get orthoSize(): number {
        // if (this.camera.mode === BABYLON.Camera.ORTHOGRAPHIC_CAMERA) {
        this._orthoSize = this.camera!.orthoRight! / this._scene.getEngine().getRenderWidth() / this._realViewport.width;
        return this._orthoSize;
        // } else {
        //     return 0;
        // }
    }
    public set orthoSize(val: number) {
        this._orthoSize = val;
        // if (this.camera.mode === BABYLON.Camera.ORTHOGRAPHIC_CAMERA) {
        this.camera.orthoRight = val * this._scene.getEngine().getRenderWidth() * this._realViewport.width;
        this.camera.orthoLeft = -val * this._scene.getEngine().getRenderWidth() * this._realViewport.width;
        this.camera.orthoTop = val * this._scene.getEngine().getRenderHeight() * this._realViewport.height;
        this.camera.orthoBottom = -val * this._scene.getEngine().getRenderHeight() * this._realViewport.height;
        // }
    }

    private _clearColor: Nullable<BABYLON.Color4> = null;
    public get clearColor(): Nullable<BABYLON.Color4> {
        return this._clearColor;
    }
    public set clearColor(val: Nullable<BABYLON.Color4>) {
        this._clearColor = val;
        if (this._scene.activeCameras![0] === this.camera && val) {
            this._scene.clearColor.copyFrom(val);
        }
    }

    public get minZ(): number {
        return this.camera.minZ;
    }
    public set minZ(val: number) {
        this.camera.minZ = val;
    }

    public get maxZ(): number {
        return this.camera.maxZ;
    }
    public set maxZ(val: number) {
        this.camera.maxZ = val;
    }

    public get checkCollisions(): boolean {
        return (<BABYLON.FreeCamera>this.camera).checkCollisions;
    }
    public set checkCollisions(val: boolean) {
        (<BABYLON.FreeCamera>this.camera).checkCollisions = val;
    }

    public get applyGravity(): boolean {
        return (<BABYLON.FreeCamera>this.camera).applyGravity;
    }
    public set applyGravity(val: boolean) {
        (<BABYLON.FreeCamera>this.camera).applyGravity = val;
    }

    //DO_20210930:漫游相机
    public get ellipsoid(): BABYLON.Vector3 {
        return (<BABYLON.FreeCamera>this.camera).ellipsoid;
    }
    public set ellipsoid(val: BABYLON.Vector3) {
        (<BABYLON.FreeCamera>this.camera).ellipsoid = val;
    }
    public get speed(): number {
        return this.camera.speed;
    }
    public set speed(val: number) {
        this.camera.speed = val;
    }
    public get angularSensibility(): number {
        return 2000 / (<BABYLON.FreeCamera>this.camera).angularSensibility;
    }
    public set angularSensibility(val: number) {
        (<BABYLON.FreeCamera>this.camera).angularSensibility = 2000 / val;
    }

    public camera: BABYLON.TargetCamera;

    // public get mode()
    //DO_20210930:漫游相机
    public constructor(camera: BABYLON.TargetCamera, scene: BABYLON.Scene, canvas: HTMLCanvasElement, enableInput: boolean = false) {
        super(camera.name, scene);
        this.camera = camera;
        camera.name += '-Camera';
        this._canvas = canvas;
        if (!enableInput) {
            this.position.copyFrom(camera.position);
            this.rotation.copyFrom(camera.rotation);
            camera.parent = this;
            camera.position = BABYLON.Vector3.Zero();
            camera.rotation = BABYLON.Vector3.Zero();
            camera.inputs.clear();
        }
        else {
            this.position.copyFrom(camera.position);
            camera.parent = this;
            camera.position = BABYLON.Vector3.Zero();
            scene.getEngine().runRenderLoop(() => {
                if (scene.activeCamera === camera) {
                    if (!camera.inputs.attachedToElement) {
                        camera.attachControl(canvas, true);
                    }
                }
                else {
                    if (camera.inputs.attachedToElement) {
                        camera.detachControl(canvas);
                    }
                }
            });
        }
        VeryEngine.scene.onBeforeCameraRenderObservable.add(this.cameraRender);
    }

    private cameraRender = (c: BABYLON.Camera) => {
        if (this.camera == c) {
            var engine = VeryEngine.engine;
            var w = engine.getRenderWidth();
            var h = engine.getRenderHeight();
            engine.enableScissor(this.camera.viewport.x * w, this.camera.viewport.y * h, this.camera.viewport.width * w, this.camera.viewport.height * h);
            engine.clear(this.clearColor, true, true, true);
            engine.disableScissor();
        }
    }
    private _realViewport:BABYLON.Viewport=new BABYLON.Viewport(0, 0, 1, 1);
    public get viewport(){
        return this._realViewport;
    }

    public set viewport(val:BABYLON.Viewport){
        this._realViewport=val;
        if(!VeryEngine.EditMode){
            this.camera.viewport=val;
        }else{
            let w = this._scene.getEngine().getRenderWidth();
            let h = this._scene.getEngine().getRenderHeight();
            this.camera.viewport=new BABYLON.Viewport(Config.x / w, (h - Config.y - Config.height) / h, Config.width / w, Config.height / h)
        }
        this.orthoSize=this._orthoSize;
    }
    private _render: boolean = true;
    public renderCamera(render: boolean): void {
        if (this._render === render) return;
        this._render = render;

        let i = this._scene.activeCameras!.indexOf(this.camera);

        if (render) {
            if (i === -1) {
                this._scene.activeCameras!.push(this.camera);
            }
            if(VeryEngine.EditMode){
                let w = this._scene.getEngine().getRenderWidth();
                let h = this._scene.getEngine().getRenderHeight();
                this.camera.viewport=new BABYLON.Viewport(Config.x / w, (h - Config.y - Config.height) / h, Config.width / w, Config.height / h)
            }
            window.addEventListener("resize",this.resize)
        } else {
            if (i > -1) {
                this._scene.activeCameras!.splice(i, 1);
            }
            // this._backupViewport = this.camera.viewport.clone();
            window.removeEventListener("resize",this.resize);
        }
    }


    // orthographic相机在窗口resize后需要刷新；
    public resize=()=>{
        if (this.camera && this._canvas) {
            if (this._canvas.width !== this._width || this._canvas.height !== this._height) {

                this._width = this._canvas.width;
                this._height = this._canvas.height;

                let w = this._scene.getEngine().getRenderWidth();
                let h = this._scene.getEngine().getRenderHeight();
                if(VeryEngine.EditMode){
                    let w = this._scene.getEngine().getRenderWidth();
                    let h = this._scene.getEngine().getRenderHeight();
                    this.camera.viewport=new BABYLON.Viewport(Config.x / w, (h - Config.y - Config.height) / h, Config.width / w, Config.height / h)
                }
                if (this.camera.mode === BABYLON.Camera.ORTHOGRAPHIC_CAMERA) {
                    this.camera.orthoRight = this._orthoSize * w * this._realViewport.width;
                    this.camera.orthoLeft = -this._orthoSize * w * this._realViewport.width;
                    this.camera.orthoTop = this._orthoSize * h * this._realViewport.height;
                    this.camera.orthoBottom = -this._orthoSize * h * this._realViewport.height;
                } else {

                }

            }

        }
    }

    public enable(enabled: boolean, scene: BABYLON.Scene): void {
        if (scene.activeCameras) {
            let i = scene.activeCameras!.indexOf(this.camera);
            if (i > -1 && !enabled) {
                scene.activeCameras!.splice(i, 1);
            }
            if (i === -1 && enabled) {
                scene.activeCameras!.push(this.camera);
            }
        }
    }

    public dispose(doNotRecurse?: boolean, disposeMaterialAndTextures?: boolean): void {
        VeryEngine.scene.onBeforeCameraRenderObservable.removeCallback(this.cameraRender);
        super.dispose(doNotRecurse, disposeMaterialAndTextures);
    }

}