let init = async () => {
    let projectId = "FquznamF";
    let host=window.location.host;
    let hostSplit=host.split('.');
    let local=false;
    if(hostSplit.length==4){
        if(Number(hostSplit[0])==10||Number(hostSplit[0])==127){
            local=true;
        }else if(Number(hostSplit[0])==172&&Number(hostSplit[1])>=16&&Number(hostSplit[1])<=31){
            local=true;
        }else if(Number(hostSplit[0])==192&&Number(hostSplit[1])==168){
            local=true;
        }
    }else if(host.startsWith("localhost")){
        local=true;
    }
    if ((!host.startsWith("develop.veryengine.cn")&&!window.location.host.startsWith("va.cool360.com")&&!local&&window.location.host!="meta.veryengine.cn")
    ||window.location.pathname.endsWith("publish.html")) {
        VeryEngine.EditMode = false;
    }
    for (let split of window.location.search.substring(1).split("&")) {
        if (split.startsWith("projectId=")) {
            projectId = split.substring(10);
        }
        else if(split.startsWith("babylonId=")){
            VeryEngine.showBabylon=split.substring(10);
            VeryEngine.EditMode=false;
        }
    }
    let isNetwork=false;
    VeryEngine.projectId = projectId;
    if (projectId) {
        try {
            VeryEngine.version =await OSS.login(projectId);
        } catch (e) {
            console.error(e);
            return;
        }
    } else {
        alert("请指定想要打开的软件id");
        return;
    }
    VeryEngine.title = document.title;
    let doc = new Doc(false, true, VeryEngine.projectId);
    VeryEngine.undoManager =new UndoManager(doc);
    VeryEngine.doc=doc;
    VeryEngine.shareBox.assetMap=doc.getMap("assets");
    VeryEngine.shareBox.sceneMap=doc.getMap("scenes");
    VeryEngine.commonJson = Doc.getLocalMap(false, {
        pickEntity: [],
        pickAsset: [],
    });
    VeryEngine.commonJson.watch("pickEntity", (ids: string[]) => {
        VeryEngine.pickedEntities = [];
        for (let id of ids) {
            if (VeryEngine.shareBox.id2Entity[id]) {
                VeryEngine.pickedEntities.push(
                    VeryEngine.shareBox.id2Entity[id]
                );
            }
        }
    });
    VeryEngine.commonJson.watch("pickAsset", (ids: string[]) => {
        VeryEngine.pickedAssets = [];
        for (let id of ids) {
            if (VeryEngine.shareBox.id2Asset[id]) {
                VeryEngine.pickedAssets.push(VeryEngine.shareBox.id2Asset[id]);
            }
        }
    });
    let canvas = document.createElement("canvas");
    canvas.style.width = "100%";
    canvas.style.height = "100%";
    let viewportHtml = document.getElementById("layout-viewport");
    if(!viewportHtml) return;
    viewportHtml.append(canvas);
    let engine = new BABYLON.Engine(canvas, true, {
        useHighPrecisionMatrix: true,preserveDrawingBuffer: true, stencil: true
    });
    VeryEngine.engine = engine;
    VeryEngine.canvas = canvas;
    let scene = new BABYLON.Scene(engine);

    //暂时和点线面选择的插件冲突
    // scene.createDefaultEnvironment({
    //     createSkybox: false,
    //     createGround: false,
    //     enableGroundMirror: false,
    //     enableGroundShadow: false,
    // });

    VeryEngine.scene = scene;
    (scene.defaultMaterial as BABYLON.StandardMaterial).ambientColor=new BABYLON.Color3(1,1,1)
    let assetPanel = new AssetsPanel();
    let hierarchy: Hierarchy;
    let attrPanel: AttributesPanel;
    let viewport: Nullable<Viewport> = null;
    if (VeryEngine.EditMode) {
        hierarchy = new Hierarchy();
        attrPanel = new AttributesPanel(assetPanel);
    } else {
        document.getElementById("layout-hierarchy").style.display = "none";
    }
    viewport = new Viewport(hierarchy);
    IEDPlugin.createInstance(viewport, assetPanel, attrPanel, hierarchy);
    //需要等所有插件都加载完成后，再进行行shareBox初始化
    await new Promise<void>(async resolve=>{
        let pluginInfo=await OSS.ListPlugin();
        if(pluginInfo){
            let count=Object.keys(pluginInfo).length;
            let index=0;
            for(let key in pluginInfo){ 
                PluginPackage.createPackage(key,pluginInfo[key].pluginList,undefined,pluginInfo[key].name).then(()=>{
                    index++;
                    if(index==count){
                        resolve();
                    }
                })
            }
            if(count==0){
                resolve();
            }
        }else{
            resolve();
        }
    });
    if(VeryEngine.EditMode){
        VeryEngine.shareBox.init(doc);
    }else{
        let script=document.createElement("script");
        script.src="./verycompiler_"+VeryEngine.version+".js"
        script.onload=()=>{
            VeryEngine.shareBox.init(doc);
        }
        document.body.append(script);
    }
};

//取消浏览器默认的鼠标右键功能
window.addEventListener("contextmenu",function (evt) {evt.preventDefault();},false);
//取消浏览器默认的ctrl+a全选功能
window.addEventListener("keydown",(ev)=>{
    if(ev.ctrlKey){
        if(ev.keyCode==65&&document.activeElement.nodeName!="INPUT"&&document.activeElement.nodeName!="TEXTAREA"){
            ev.preventDefault();
        }if(ev.keyCode==83&&(document.activeElement.nodeName=="INPUT"||document.activeElement.nodeName=="TEXTAREA"))
            ev.preventDefault();
    }
})
init();
Tools.customPrototype();
Tools.AssetStoreExtend();
export const shareBox = VeryEngine.shareBox;