import { IEDTable } from "../assets/IEDTable";
import { Tools } from "../utility/Tools";
import { VeryEngine } from "./VeryEngine";

class TriggerGroup{
    public table:TableCompiler;
    public triggerList:Trigger[]=[];

    public name:string;
    public index:number;
    public id:string;
    constructor(table?:TableCompiler,name?:string,id?:string){
        if(name){
            this.name=name;
            let index=0;
            for(let fsm of table.FSM){
                if(fsm.name==name){
                    if(index<fsm.index){
                        index=fsm.index;
                    }
                }
            }
            this.index=index+1
        }
        this.id=id;
        this.table=table;
    }

    public addTrigger(t:Trigger){
        this.triggerList.push(t);
    }

    public createTrigger(params?:string,name?:string,id?:string){
        if(name&&this.table){
            for(let tmp of this.table.FSM){
                for(let trigger of tmp.triggerList){
                    trigger=this.judgeTriggerExit(trigger,name,params,id);
                    if(trigger) {
                        this.triggerList.push(trigger);
                        return trigger;
                    }
                }
            }
            for(let group of this.table.triggerGroup){
                for(let trigger of group.triggerList){
                    trigger=this.judgeTriggerExit(trigger,name,params,id);
                    if(trigger) {
                        this.triggerList.push(trigger);
                        return trigger;
                    }
                }
            }
            for(let tmp of this.table.triggerList){
                let trigger=this.judgeTriggerExit(tmp,name,params,id);
                if(trigger) {
                    this.triggerList.push(trigger);
                    return trigger;
                }
            }
        }
        let trigger=new Trigger(name,params,id);
        this.triggerList.push(trigger);
        return trigger;
    }

    private judgeTriggerExit(trigger:Trigger,name:string,params:string,id:string){
        if(trigger.name==name){
            if(params){
                if(trigger.params){
                    // console.warn("状态:"+this.name+",触发名:"+trigger.name+",该触发已定义，当前输入参数"+params+",无效");
                }else
                    trigger.params=params;
            }
            trigger=trigger.clone(id);
            this.triggerList.push(trigger);
            return trigger;
        }
        return null;
    }
}

class AndTriggerGroup extends TriggerGroup{
    public uuid:string;
    private time:number;
    constructor(table:TableCompiler|string,time?:number){
        if(typeof table=="string"){
            super();
            this.uuid=table;
        }else{
            super(table);
            this.uuid=table.andLogicCutom.getName;
        }
        if(time){
            this.time=time;
        }else{
            this.time=0.5;
        }
        this.disableActionList=[];
        this.enableActionList=[];
    }

    public linkFsm(fsm:FSM){
        let trigger=fsm.createTrigger("自定义",this.uuid);
        return trigger;
    }

    public disableActionList:Action[][];
    public enableActionList:Action[][];
    public bindAction(type:"disable"|"enable",trigger:Trigger,action:Action){
        let index=this.triggerList.indexOf(trigger);
        if(index>=0){
            if(type==="disable"){
                if(!this.disableActionList[index]) this.disableActionList[index]=[];
                this.disableActionList[index].push(action);
            }else{
                if(!this.enableActionList[index]) this.enableActionList[index]=[];
                this.enableActionList[index].push(action);
            }
        }
    }

    public convert2Table(){
        let triggers=this.triggerList;
        let uuid=this.uuid;
        let state:string[][]=[];
        let customVal:string[]=[];
        let customState=this.uuid+"状态"
        for(let i=0;i<triggers.length;i++){
            //定义标记变量
            let tmp=this.uuid+"变量"+i;
            customVal.push(tmp);
            let line=[];
            line[4]=tmp+",bool,false";
            state.push(line);
            //触发
            let s=triggers[i].convert2Table();
            if(s.length==0) s.push([]);
            s[0][6]="*"+tmp+"=true";
            s[0][7]=customState+"=1";
            let index=1;
            let cTrigger=this.uuid+"触发"+i;
            if(this.time>0){
                if(s.length==1) s.push([]);
                s[1][6]="定时器,true,"+cTrigger+","+this.time+",false";
                index++;
            }
            if(this.disableActionList[i])
            for(let act of this.disableActionList[i]){
                let actionState=act.convert2Table();
                for(let k=0;k<actionState.length;k++,index++){
                    if(index==s.length) s.push([]);
                    s[index][5]=actionState[k][5];
                    s[index][6]=actionState[k][6];
                }
            }
            state.push(...s)
            line=[];state.push(line);
            if(this.time>0){
                line=[];line[1]=cTrigger;line[2]="自定义";line[3]="*"+tmp;line[6]="*"+tmp+"=false";
                state.push(line);
                if(this.enableActionList[i])
                for(let act of this.enableActionList[i]){
                    let actionState=act.convert2Table();
                    state.push(...actionState);
                }
            }
        }
        let judgeStr="*"+customVal[0];
        for(let i=1;i<customVal.length;i++){
            judgeStr+="&&*"+customVal[i];
        }
        state.push(["","","",judgeStr,customState+",1","","触发,"+uuid]);
        for(let val of customVal){
            state.push(["","","","","","","*"+val+"=false"])
        }
        state.push([]);
        return state;
    }
}

class OrTriggerGroup extends TriggerGroup{
    public uuid:string;
    constructor(table:TableCompiler|string,){
        if(typeof table=="string"){
            super();
            this.uuid=table;
        }else{
            super(table);
            this.uuid=table.andLogicCutom.getName;
        }
    }
    public convert2Table(){
        let state:string[][]=[];
        for(let trigger of this.triggerList){
            state.push(...trigger.convert2Table());
        }
        if(state.length!=0){
            state[0][6]="触发,"+this.uuid;
        }
        return state;
    }

    public linkFsm(fsm:FSM){
        let trigger=fsm.createTrigger("自定义",this.uuid);
        return trigger;
    }
}


class FSM extends TriggerGroup{
    public needRecord=false;
    protected actionList:Action[]=[];
    public createAction(params?:string,name?:string,active?:boolean,frame?:boolean,sequence?:boolean,id?:string){
        if(name){
            for(let tmp of this.table.FSM){
                for(let action of tmp.actionList){
                    if(action.name==name){
                        if(params){
                            if(action.params){
                                // console.warn("状态:"+this.name+",响应名:"+action.name+",该响应已定义，当前输入参数"+params+",无效");
                            }else
                                action.params=params;
                        }
                        action=action.clone(active,frame,sequence,id)
                        this.actionList.push(action);
                        return action;
                    }
                }
            }
            for(let action of this.table.actionList){
                if(action.name==name){
                    if(params){
                        if(action.params){
                            // console.warn("状态:"+this.name+",响应名:"+action.name+",该响应已定义，当前输入参数"+params+",无效");
                        }else
                            action.params=params;
                    }
                    action=action.clone(active,frame,sequence,id)
                    this.actionList.push(action);
                    return action;
                }
            }
        }
        let action=new Action(name,params,active,frame,sequence,id);
        if(this.needRecord)
            action.fsm=this;
        this.actionList.push(action);
        return action;
    }

    public addAction(action:Action){
        this.actionList.push(action);
    }

    public createTrigger(params?: string, name?: string,id?:string): Trigger {
        let trigger=super.createTrigger(params,name,id);
        if(this.needRecord)
            trigger.fsm=this;
        return trigger;
    }

    public getTriggerById(id:string){
        let list:Trigger[]=[];
        for(let trigger of this.triggerList){
            if(trigger.id==id){
                list.push(trigger);
            }
        }
        return list;
    }

    public getActionById(id:string){
        let list:Action[]=[];
        for(let action of this.actionList){
            if(action.id==id){
                list.push(action);
            }
        }
        return list;
    }

    public emptyName(){
        for(let act of this.actionList){
            if(!act.name&&act.params){
                let split=act.params.split(/,|，/);
                if(split.length==1&&split[0].includes("="))
                    continue;
                if(!act.params.startsWith("log")&&!act.params.startsWith("error")&&!act.params.startsWith("warn"))
                act.name=this.table.actionCount.getName;
            }
        }       
        for(let trigger of this.triggerList){
            if(!trigger.name&&trigger.params){
                trigger.name=this.table.triggerCount.getName;
            }
        }
    }

    private _emptyAction:Action;
    public get emptyAction(){
        if(!this._emptyAction)
            this._emptyAction=this.createAction();
        return this._emptyAction;
    }

    private _emptyTrigger:Trigger;
    public get emptyTrigger(){
        if(!this._emptyTrigger)
            this._emptyTrigger=this.createTrigger();
        return this._emptyTrigger;
    }

    public convert2Table(){
        let state=[];

        for(let i=0;i<this.triggerList.length;i++){
            state.push(...this.triggerList[i].convert2Table());
        }

        if(this.name){
            if(0==state.length) state.push([]);
            state[0][4]=this.name+","+this.index;
        }
        let length=0
        for(let i=0;i<this.actionList.length;i++){
            let lines=this.actionList[i].convert2Table();
            for(let j=0;j<lines.length;j++){
                if(length+j==state.length){
                    state.push(lines[j]);
                }else{
                    state[length+j][5]=lines[j][5];
                    state[length+j][6]=lines[j][6];
                    state[length+j][7]=lines[j][7];
                }
            }
            length+=lines.length;
        }
        return state;
    }

    public disable(){
        let act:Action[]=[];
        let str:string[]=[];
        for(let act of this.actionList){
            if(act.name)
                str.push(act.name);
        }
        if(str.length!=0)
            act.push(this.table.createAction("响应失效,"+str,this.name+"_"+this.index+"_响应失效"));
        str=[];
        for(let t of this.triggerList){
            if(t.name)
                str.push(t.name);
        }
        if(str.length!=0)
            act.push(this.table.createAction("触发失效,"+str,this.name+"_"+this.index+"_触发失效"));
        return act;
    }

    public cancelDisable(){
        let act:Action[]=[];
        let str:string[]=[];
        for(let act of this.actionList){
            if(act.name)
                str.push(act.name);
        }
        if(str.length!=0)
            act.push(this.table.createAction("响应失效,"+str,this.name+"_"+this.index+"_响应失效",false));
        str=[];
        for(let t of this.triggerList){
            if(t.name)
                str.push(t.name);
        }
        if(str.length!=0)
            act.push(this.table.createAction("触发失效,"+str,this.name+"_"+this.index+"_触发失效",false))
        return act;
    }

}

//编译转化成表格过程中，需要创建临时触发响应，故TableCompiler 需继承FSM,为了继承FSM创建触发响应的功能
class TableCompiler extends FSM{
    private _fsmList:FSM[]=[];
    private variableList:Variable[]=[];
    private tableIED:IEDTable;
    public andLogicCutom=new Counter("与逻辑自定义");
    public disableTrigger=new Counter("触发失效");
    public logicNode=new Counter("空节点");
    public actionCount=new Counter("空响应");
    public triggerCount=new Counter("空触发");

    constructor(table?:IEDTable){
        super();
        this.table=this;
        this.tableIED=table;
    }
    public createFsm(name?:string,id?:string){
        let fsm=new FSM(this,name,id);
        fsm.needRecord=true;
        this._fsmList.push(fsm);
        return fsm;
    }

    public createVariable(name:string,type:string,val:any){
        let v=new Variable(name,type,val)
        this.variableList.push(v);
        return v;
    }

    public getTriggerById(id: string): Trigger[] {
        let list:Trigger[]=[]
        for(let group of this.triggerGroup){
            for(let trigger of group.triggerList){
                if(trigger.id==id){
                    list.push(trigger);
                }
            }
        }
        for(let group of this.triggerGroup2){
            for(let trigger of group.triggerList){
                if(trigger.id==id){
                    list.push(trigger);
                }
            }
        }
        return list;
    }

    public getFsmById(id:string){
        let list:FSM[]=[];
        for(let fsm of this._fsmList){
            if(fsm.id==id){
                list.push(fsm);
            }
        }
        return list;
    }

    
    public write2Table(){
        this.triggerList=[];
        this.actionList=[];
        this.tableList=[];
        this.startActionList=[];
        for(let v of this.variableList){
            this.tableList.push(v.convert2Table())
        }
        for(let or of this.triggerGroup2){
            this.tableList.push(...or.convert2Table());
        }
        for(let and of this.triggerGroup){
            this.tableList.push(...and.convert2Table())
        }
        for(let fsm of this._fsmList){
            this.tableList.push(...fsm.convert2Table());
            this.tableList.push([]);
        }
        for(let logic of this.logicList){
            this.tableList.push(...logic.convert2Table());
            this.tableList.push([]);
        }
        if(this.startActionList.length>0){
            let state:string[][]=[];
            for(let act of this.startActionList){
                let actState=act.convert2Table();
                state.push(...actState);
            }
            state.push([]);
            state[0][1]="开始"; state[0][2]="开始";
            this.tableList.push(...state);
        }
        if(!this.tableIED){
            let id=Tools.assetID();
            let data = {
                id: id,
                type: "table",
                createdAt: Tools.createdTime(),
                name: "新建表格.table",
                file: {
                    filename:"新建表格.table",
                    size: 0
                },
            };
            this.tableIED=VeryEngine.addAssetData(data,"root") as IEDTable;
            this.tableIED.setTable(this.tableList);
            this.tableIED.updateTable();
        }
        return this.tableList;
    }

    public triggerGroup:AndTriggerGroup[]=[];
    public triggerGroup2:OrTriggerGroup[]=[];

    public createAndTriggerGroup(){
        let group=new AndTriggerGroup(this);
        this.triggerGroup.push(group);
        return group;
    }

    public createOrTriggerGroup(){
        let group=new OrTriggerGroup(this);
        this.triggerGroup2.push(group);
        return group;
    }

    public get FSM(){
        return this._fsmList;
    }

    private logicList:LogicNode[]=[];
    public createLogicNode(type?:"and"|"or",time?:number){
        let logic=new LogicNode(this,type,time);
        this.logicList.push(logic);
        return logic;
    }

    private tableList:string[][];
    private startActionList:Action[]=[];
    public addStartAction(action:Action){
        if(this.startActionList.includes(action)) return;
        if(action.name){
            for(let act of this.startActionList){
                if(act.name==action.name){
                    return
                }
            }
        }
        this.startActionList.push(action);
    }
}


class LogicNode{
    private actionList:Action[]=[];
    private actionCondition:string[]=[];
    private uuid:string;
    private table:TableCompiler;
    private logicType:"and"|"or"="and";
    private time:number=0.5;
    constructor(table:TableCompiler,logicType?:"and"|"or",time?:number){
        if(logicType) this.logicType=logicType;
        this.table=table;
        this.uuid=table.logicNode.getName;
        if(time!=null){
            this.time=time;
        }
    }

    public linkAction(action:Action,condition?:string){
        action.addLogicNode(this);
        this.actionList.push(action);
        this.actionCondition.push(condition);
    }


    private triggerList:Trigger[]=[];
    private triggerCondition:string[]=[];
    public linkTrigger(trigger:Trigger,condition?:string){
        trigger.addLogicNode(this);
        this.triggerCondition.push(condition);
        this.triggerList.push(trigger);
    }

    private fsmList:FSM[]=[];
    private fsmCondition:string[]=[];
    public linkFsm(fsm:FSM,condition?:string){
        this.emptyName();
        fsm.emptyName();
        this.fsmList.push(fsm);
        this.fsmCondition.push(condition);
    }

    public emptyName(){
        for(let action of this.actionList){
            action.emptyFSMName();
        }
        for(let trigger of this.logicTrigger){
            trigger.emptyFSMName();
        }
    }

    private logicTrigger:Trigger[]=[];

    public linkLogicNode(node:LogicNode,condition?:string){
        let params=this.uuid+"关联"+this.selfActIndex;
        node.createAction(params);
        let trigger=this.table.createTrigger("自定义",params);
        trigger.originNode=node;
        trigger.addCondition(condition);
        this.logicTrigger.push(trigger);
        this.selfActIndex++;
    }

    private selfActIndex=0;
    private logicAction:Action[]=[];
    private createAction(params:string){
        let action=this.table.createAction("触发,"+params);
        this.logicAction.push(action);
    }

    public trigger2Table(trigger:Trigger){
        if(this.actionList.length==0) return null;
        let index=this.triggerList.indexOf(trigger);
        if(index>=0){
            let line=[];
            line[1]=this.uuid+"触发"+index;
            line[2]="自定义"
            if(this.triggerCondition[index]){
                line[3]=this.triggerCondition[index];
            }
            return line;
        }else{
            return null;
        }
    }

    public action2Table(action:Action){
        let index=this.actionList.indexOf(action);
        if(index>=0){
            let line=[];
            line[6]="触发,"+this.uuid+"响应"+index;
            return line;
        }else{
            return null;
        }
    }

    public getOriginFsm(fsm:FSM[]){
        if(!fsm) fsm=[];
        for(let act of this.actionList){
            act.getOriginFsm(fsm);
        }
        for(let trigger of this.logicTrigger){
            trigger.getOriginFsm(fsm);
        }
        return fsm;
    }

    public convert2Table(){
        let state:string[][]=[];
        // if((this.triggerList.length+this.fsmList.length!=0&&this.actionList.length!=0)){
        if(this.logicType=="or"){
            for(let i=0;i<this.actionCondition.length;i++){
                let tmpTrigger=this.table.createTrigger("自定义",this.uuid+"响应"+i);
                tmpTrigger.addCondition(this.actionCondition[i]);
                let line=tmpTrigger.convert2Table()[0];
                state.push(line);
            }
            for(let i=0;i<this.logicTrigger.length;i++){
                let line=this.logicTrigger[i].convert2Table()[0];
                console.log(line);
                state.push(line);
            }
            for(let i=0;i<this.triggerCondition.length;i++){
                if(state.length==i) state.push([]);
                state[i][6]="触发,"+this.uuid+"触发"+i;
            }
            let index=this.triggerCondition.length;
            for(let i=0;i<this.fsmList.length;i++){
                let actList=this.fsmList[i].cancelDisable();
                for(let act of actList){
                    if(state.length==index){
                        state.push([]);
                    }
                    let actStr=act.convert2Table()[0];
                    state[index][5]=actStr[5];
                    state[index][6]=actStr[6];
                    index++;
                }
                actList=this.fsmList[i].disable();
                for(let act of actList){
                    this.table.addStartAction(act);
                }
            }
            state.push([]);
            index++;
            for(let i=0;i<this.logicAction.length;i++,index++){
                let act=this.logicAction[i].convert2Table()[0];
                if(state.length==index){
                    state.push([]);
                }
                state[index][5]=act[5];
                state[index][6]=act[6];
            }
            if(this.fsmList.length!=0){
                for(let i=0;i<this.actionCondition.length;i++){
                    let line=["",this.uuid+"响应"+i,"",this.actionCondition[i]?this.actionCondition[i]:""];
                    for(let fsm of this.actionList[i].getOriginFsm()){
                        let actList=fsm.disable();
                        for(let act of actList){
                            let actStr=act.convert2Table()[0]
                            if(line){
                                line[5]=actStr[5];
                                line[6]=actStr[6];
                                state.push(line);
                                line=null;
                            }else{
                                state.push(actStr);
                            }
                        }
                        state.push([]);
                    }
                }
                for(let i=0;i<this.logicTrigger.length;i++){
                    let line=this.logicTrigger[i].convert2Table()[0];
                    for(let fsm of this.logicTrigger[i].getOriginFsm()){
                        let actList=fsm.disable();
                        for(let act of actList){
                            let actStr=act.convert2Table()[0]
                            if(line){
                                line[5]=actStr[5];
                                line[6]=actStr[6];
                                state.push(line);
                                line=null;
                            }else{
                                state.push(actStr);
                            }
                        }
                        state.push([]);
                    }
                }
            }
        }else{
            let andGroup=new AndTriggerGroup(this.uuid+"与",this.time);
            for(let i=0;i<this.actionCondition.length;i++){
                let t:Trigger;
                t=andGroup.createTrigger("自定义",this.uuid+"响应"+i);
                if(this.actionCondition[i]){
                    t.addCondition(this.actionCondition[i]);
                }
                if(this.fsmList.length!=0)
                for(let fsm of this.actionList[i].getOriginFsm()){
                    let act= fsm.disable();
                    for(let a of act){
                        andGroup.bindAction("disable",t,a)
                    }
                    act=fsm.cancelDisable();
                    for(let a of act){
                        andGroup.bindAction("enable",t,a)
                    }
                }
            }
            for(let i=0;i<this.logicTrigger.length;i++){
                let t=this.logicTrigger[i];
                andGroup.addTrigger(this.logicTrigger[i]);
                if(this.fsmList.length!=0)
                for(let fsm of t.getOriginFsm()){
                    let act= fsm.disable();
                    for(let a of act){
                        andGroup.bindAction("disable",t,a)
                    }
                    act=fsm.cancelDisable();
                    for(let a of act){
                        andGroup.bindAction("enable",t,a)
                    }
                }
            }
            state.push(...andGroup.convert2Table())
            let tmpFsm=new FSM();
            andGroup.linkFsm(tmpFsm);
            for(let i=0;i<this.triggerCondition.length;i++){
                tmpFsm.createAction("触发,"+this.uuid+"触发"+i);
            }
            for(let act of this.logicAction){
                tmpFsm.addAction(act);
            }
            for(let i=0;i<this.fsmList.length;i++){
                let act= this.fsmList[i].disable();
                for(let a of act){
                    this.table.addStartAction(a);
                }
                act= this.fsmList[i].cancelDisable();
                for(let a of act){
                    tmpFsm.addAction(a);
                }
            }
            state.push(...tmpFsm.convert2Table());
        }
        // }
        return state;
    }
}

abstract class CloneTarget{
    private _name:string;
    private _params:string;
    private _isCreate:boolean;
    public  fsm:FSM;
    public originNode:LogicNode;
    public id:string;
    public get name(){
        if(this._cloneTarget){
            return this._cloneTarget.name;
        }else{
            return this._name;
        }
    }

    public set name(val:string){
        if(this._cloneTarget){
            this._cloneTarget.name=val;
        }else{
            this._name=val;
        }
    }

    public getOriginFsm(fsm?:FSM[]){
        if(!fsm) fsm=[];
        if(this.fsm){
            if(!fsm.includes(this.fsm))
            fsm.push(this.fsm);
        }else if(this.originNode){
            this.originNode.getOriginFsm(fsm);
        }
        return fsm;
    }

    public emptyFSMName(){
        if(this.fsm){
            this.fsm.emptyName();
        }else if(this.originNode){
            this.originNode.emptyName();
        }
    }

    public reset(){
        if(!this._cloneTarget){
            this._isCreate=false;
        }
    }

    public get params(){
        if(this._cloneTarget){
            return this._cloneTarget.params;
        }else{
            return this._params;
        }
    }

    public set params(val:string){
        if(this._cloneTarget){
           this._cloneTarget.params=val;
        }else{
            this._params=val;
        }
    }

    public get isCreate(){
        if(this._cloneTarget){
            return this._cloneTarget.isCreate;
        }else{
            return this._isCreate;
        }
    }

    public set isCreate(val:boolean){
        if(this._cloneTarget){
            this._cloneTarget.isCreate=val;
        }else{
            this._isCreate=val;
        }
    }
    protected _cloneTarget:CloneTarget;

    constructor(name?:string,params?:string,id?:string){
        this._name=name;
        this._params=params;
        this.id=id;
    }

    
    protected logicNodeList:LogicNode[]=[];

    public addLogicNode(logic:LogicNode){
        this.logicNodeList.push(logic);
    }
}

class Trigger extends CloneTarget{

    public addPrejudge(condition:string){
        this.triggerPreJudge=condition;
    }

    public addCondition(condition:string){
        this.triggerCondition=condition;
    }

    private triggerPreJudge:string;
    private triggerCondition:string;
    public convert2Table(){
        let state:string[][]=[];
        if(this.name||this.params){
            let line=[];
            state.push(line);
            if(this.name){
                line[1]=this.name;
                if(!this.isCreate){
                    line[2]=this.params;
                    this.isCreate=true;
                }
            }else{
                line[2]=this.params;
            }
            if(this.triggerPreJudge){
                line[0]=this.triggerPreJudge
             }
             if(this.triggerCondition){
                 line[3]=this.triggerCondition;
             }
        }
        for(let logic of this.logicNodeList){
            let line=logic.trigger2Table(this);
            if(line)
                state.push(line);
        }
        return state;
    }

    public clone(id?:string){
        let newTrigger=new Trigger();
        newTrigger.id=id;
        newTrigger._cloneTarget=this;
        return newTrigger;
    }
}

class Action extends CloneTarget{
    public active?:boolean;
    public everyFrame?:boolean;
    public sequence?:boolean;

    constructor(name?:string,params?:string,active?:boolean,everyFrame?:boolean,sequence?:boolean,id?:string){
        super(name,params,id);
        this.active=active;
        this.everyFrame=everyFrame;
        this.sequence=sequence;
    }

    public convert2Table(){
        let state:string[][]=[];
        if(this.name||this.params){
            let line=[];
            state.push(line);
            if(this.name){
                line[5]=this.name+","+(this.active==null?true:this.active);
                if(this.everyFrame!=null){
                    line[5]+=","+this.everyFrame;
                }
                if(this.sequence!=null){
                    line[5]+=","+this.sequence;
                }
                if(!this.isCreate){
                    this.isCreate=true;
                    line[6]=this.params;
                }
            }else{
                line[6]=this.params;
            }
        }
        for(let logic of this.logicNodeList){
            let line=logic.action2Table(this);
            if(line)
                state.push(line);
        }
        return state;
    }


    public clone(active?:boolean,everyFrame?:boolean,sequence?:boolean,id?:string){
        let newAction=new Action();
        newAction._cloneTarget=this;
        newAction.active=active;
        newAction.everyFrame=everyFrame;
        newAction.sequence=sequence;
        newAction.id=id;
        return newAction;
    }
}

