class LogicMap{

    public static parseLogic(json:any){
        let table=new TableCompiler();
        let stateCounter=new Counter("空状态");
        let id2Block:{[name:string]:LogicBlock}={};
        let inner2Block:{[key:string]:string}={};
        let id2LogicNode:{[id:string]:{in:string,out:string,node:LogicNode}}
        for(let i=0;i<json.nodes.length;i++){
           let node=json.nodes[i];
           if(node.type=="rect"){
               if(node.properties){
                  let block=new LogicBlock(node.name?node.name:stateCounter.getName,node.id);
                  id2Block[node.id]=block
                  if(node.properties.trigger){
                    for(let trigger of node.properties.trigger){
                        if(trigger.type=="receive"){
                            block.createTrigger(trigger.key,"","",trigger.condition);
                        }else{
                            block.createTrigger(trigger.key,trigger.name,trigger.parameter,trigger.condition);
                        }
                    }
                  }
                  if(node.properties.action){
                    for(let action of node.properties.action){
                        if(action.type=="setup"){
                            block.createAction(action.key,"",action.name,action.active,action.frame,action.sequence);
                        }else{
                            block.createAction(action.key,action.name,action.parameter,action.active,action.frame,action.sequence);
                        }
                    }
                  }
               }
           }else if(node.type=="CircleWithOr"){
             if(node.properties.parent){
                id2Block[node.properties.parent].createInner(node.properties.type=="or"?"or":"and",node.properties.trigger[0].key,node.properties.action[0].key);
                inner2Block[node.id]=node.properties.parent
             }else{
                let logic=table.createLogicNode(node.properties.type);
                id2LogicNode[node.id]={in:node.properties.trigger[0].key,out:node.properties.action[0].key,node:logic}
             }
           }
        }
        for(let i=0;i<json.edges.length;i++){
            let edge=json.edges[i];
            let sourceBlock=inner2Block[edge.sourceNodeId];
            if(!sourceBlock) sourceBlock=edge.sourceNodeId;
            let targetBlock=inner2Block[edge.targetNodeId];
            if(!targetBlock)targetBlock=edge.targetNodeId
            if(sourceBlock==targetBlock){
                id2Block[sourceBlock].linkLine(edge.sourceAnchorId,edge.targetAnchorId,edge.text?.value);
            }
        }
        for(let key in id2Block){
           id2Block[key].convert(table);
        }
        for(let i=0;i<json.edges.length;i++){
            let edge=json.edges[i];
            let sourceBlock=inner2Block[edge.sourceNodeId];
            if(!sourceBlock) sourceBlock=edge.sourceNodeId;
            let targetBlock=inner2Block[edge.targetNodeId];
            if(!targetBlock)targetBlock=edge.targetNodeId
            if(sourceBlock!=targetBlock){
                let condition=edge.text?.value;
                let source=id2LogicNode[edge.sourceNodeId];
                if(source){
                    let target=id2LogicNode[edge.targetNodeId]
                    if(target){
                        target.node.linkLogicNode(source.node,condition);
                    }else{
                        let fsms=table.getFsmById(edge.targetNodeId);
                        for(let fsm of fsms){
                            for(let t of fsm.getTriggerById(edge.sourceAnchorId)){
                                source.node.linkTrigger(t,condition)
                            }
                        }
                        for(let t of table.getTriggerById(edge.targetNodeId)){
                            source.node.linkTrigger(t,condition);
                        }
                    }
                }else{
                    let actionlist:Action[]=[];
                    let fsms=table.getFsmById(edge.sourceNodeId);
                    for(let fsm of fsms){
                        actionlist.push(...fsm.getActionById(edge.sourceAnchorId))
                    }
                    let target=id2LogicNode[edge.targetNodeId]
                    if(target){
                        for(let act of actionlist){
                            target.node.linkAction(act,condition);
                        }
                    }else{
                        let triggerList:Trigger[]=[];
                        let fsms=table.getFsmById(edge.targetNodeId);
                        for(let fsm of fsms){
                            for(let t of fsm.getTriggerById(edge.sourceAnchorId)){
                                if(t.params||t.name)
                                    triggerList.push(t);
                            }
                        }
                        for(let t of table.getTriggerById(edge.targetNodeId)){
                            triggerList.push(t);
                        }
                        let logic=table.createLogicNode("or");
                        for(let act of actionlist){
                            logic.linkAction(act);
                        }
                        if(fsms.length!=0){
                            if(triggerList.length==0){
                                logic.linkFsm(fsms[0],condition);
                            }else{
                                for(let t of triggerList){
                                    logic.linkTrigger(t,condition);
                                }
                            }
                        }
                    }
                }
            }
        }
        table.write2Table();
    }
}
