class LogicBlock{
    private name:string;
    private id:string;
    constructor(name:string,id:string){
        this.name=name;
        this.id=id;
    }
    private inner:{in:string,out:string,type:"and"|"or"}[]=[];
    public createInner(type:"and"|"or",inId:string,outId:string){
        this.inner.push({in:inId,out:outId,type:type})
    }

    private triggerList:{[id:string]:{params:string,name:string,id:string,condition:string}}={}
    public createTrigger(id:string,name:string,params:string,condition:string){
        this.triggerList[id]={name:name,params:params,id:id,condition:condition};
    }

    private actionList:{[id:string]:{id:string,params:string,name:string,active:boolean,frame:boolean,sequence:boolean}}={};

    public createAction(id:string,name:string,params:string,active:boolean,frame:boolean,sequence:boolean){
        this.actionList[id]={name:name,params:params,active:active,frame:frame,sequence:sequence,id:id};
    }

    private state:{[id:string]:{[condition:string]:string[]}}={};
    private triggerGroup:{[id:string]:{id:string,condition:string}[]}={};
    private triggerGroup2:{[id:string]:{id:string,condition:string}[]}={};
    public linkLine(startId:string,endId:string,condition:string){
        let start:{in:string,out:string,type:"and"|"or"}|{params:string,name:string,id:string};
        for(let i of this.inner){
            if(startId==i.out){
                start=i;
                break;
            }
        }
        if(!start){
            start=this.triggerList[startId];
        }
        if(!start) return;
        let end:{in:string,out:string,type:"and"|"or"}|{params:string,name:string,id:string};
        for(let i of this.inner){
            if(endId==i.in){
                end=i;
                break;
            }
        }
        if(!end) end=this.actionList[endId];
        if(!end) return;
        //如果end连接着与 或
        if("type" in end){
            if(end.type=="and"){
                if(!this.triggerGroup[end.out])
                    this.triggerGroup[end.out]=[];
                if("type" in start)
                    this.triggerGroup[end.out].push({id:start.out,condition:condition});
                else
                    this.triggerGroup[end.out].push({id:start.id,condition:condition})
            }else{
                if(!this.triggerGroup2[end.out])
                    this.triggerGroup2[end.out]=[];
                if("type" in start)
                    this.triggerGroup2[end.out].push({id:start.out,condition:condition});
                else
                    this.triggerGroup2[end.out].push({id:start.id,condition:condition})
            }
        }else{
            if("type" in start){
                if(!this.state[start.out]) this.state[start.out]={};
                if(!this.state[start.out][condition]) this.state[start.out][condition]=[];
                this.state[start.out][condition].push(end.id);
            }else{
                if(!this.state[start.id]) this.state[start.id]={};
                if(!this.state[start.id][condition]) this.state[start.id][condition]=[];
                this.state[start.id][condition].push(condition);
            }
        }
    }

    public convert(table:TableCompiler){
        let id2Group:{[key:string]:AndTriggerGroup|OrTriggerGroup}={};
        for(let key in this.triggerGroup){
            let tg=table.createAndTriggerGroup();
            let triggers=this.triggerGroup[key];
            for(let trigger of triggers){
                let t=this.triggerList[trigger.id];
                let tmp=tg.createTrigger(t.params,t.name,t.id);
                tmp.addPrejudge(t.condition);
                tmp.addCondition(trigger.condition);
            }
            id2Group[key]=tg;
        }
        for(let key in this.triggerGroup2){
            let tg=table.createOrTriggerGroup();
            let triggers=this.triggerGroup2[key];
            console.log(triggers);
            for(let trigger of triggers){
                console.log(trigger)
                console.log(this.triggerList);
                let t=this.triggerList[trigger.id];
                let tmp=tg.createTrigger(t.params,t.name,t.id);
                tmp.addPrejudge(t.condition);
                tmp.addCondition(trigger.condition);
            }
            id2Group[key]=tg;
        }
        for(let triggerId in this.state){
            for(let condition in this.state[triggerId]){
                let fsm=table.createFsm(this.name,this.id);
                let trigger:Trigger;
                if(triggerId in id2Group){
                    trigger=id2Group[triggerId].linkFsm(fsm);
                }else if(triggerId in this.triggerList){
                    let triggerParam=this.triggerList[triggerId];
                    trigger=fsm.createTrigger(triggerParam.params,triggerParam.name,triggerParam.id);
                }
                if(trigger){
                    trigger.addCondition(condition);
                }
                for(let actId of this.state[triggerId][condition]){
                    let actionParam=this.actionList[actId];
                    if(actionParam){
                        fsm.createAction(actionParam.params,actionParam.name,actionParam.active,actionParam.frame,actionParam.sequence,actionParam.id);
                    }
                }
            }
        }
    }
}
