import { IED, IEDAttribute } from "./engine/IED";
import { VeryEngine, DataType } from "./engine";
import { AssetsPanel } from "./assets-panel";
import { IEDMaterial, IEDTexture, IEDAudio, IEDVideo } from "./assets";
import { Tools } from "./utility/Tools";
import { AllDataType, ArrayType, IEDAsset } from "./main";
import { DArray } from "./djs/type/DArray";
import { IEDProxyFactory,IEDAttrib, IEDButton } from "./engine/IEDProxy";
import { UIModule } from "./utility/UI";
import { isEqual, cloneDeep, differenceWith } from "lodash";


export class AttributesPanel {
    constructor(assetsPanel: AssetsPanel) {
        assetsPanel.attrPanel = this;
        this.createUI();
    }
    public attrParent: HTMLElement;
    private lastEntity: IED[];
    public UIModule = new UIModule();
    private scrollTo=0;
    private createUI() {
        this.attrParent = document.querySelector(".layout-attributes-container");
        this.UIModule.content = this.attrParent;
        let layout = document.getElementById("layout-attributes");
        layout.style.display = "block";
        layout.onmousedown = () => {
            event.stopPropagation();
        };
        VeryEngine.commonJson.watch("pickEntity", () => {
            this.createAttrPanel(VeryEngine.pickedEntities);
        });
        VeryEngine.commonJson.watch("pickAsset", () => {
            this.createAttrPanel(VeryEngine.pickedAssets);
        });
        VeryEngine.resetPanel=this.reset.bind(this);
    }

    public reset(type: string[]) {
        if (this.lastEntity) {
            if(type){
                for (let tmp of this.lastEntity) {
                    if (type.indexOf(tmp.type) >= 0) {
                        this.scrollTo=this.attrParent.scrollTop;
                        this.createAttrPanel(this.lastEntity);
                        this.attrParent.scrollTop=this.scrollTo;
                        break;
                    }
                }
            }else{
                this.scrollTo=this.attrParent.scrollTop;
                this.createAttrPanel(this.lastEntity);
                this.attrParent.scrollTop=this.scrollTo;
            }
        }
    }

    private createUnit(unit: IEDAttribute, e: IED, div: HTMLElement, label: string) {
        if (unit.des) {
            this.UIModule.titleDes = unit.des;
        } else {
            this.UIModule.titleDes = null;
                }
        if (unit.type === DataType.Vector2) {
            let vector = this.UIModule.vector2(label, cloneDeep(unit.value), div);
            vector.onchange = (val) => {
                if (!isEqual(unit.value, val)) {
                    unit.value = cloneDeep(val);
            }
                };
            this.bindValue(vector, unit, e);
        } else if (unit.type === DataType.Vector4) {
            let vector = this.UIModule.vector4(label, cloneDeep(unit.value), div);
            this.bindValue(vector, unit, e);
        } else if (unit.type === DataType.Vector3) {
            let vector = this.UIModule.vector3(label, cloneDeep(unit.value), div);
            this.bindValue(vector, unit, e);
        } else if (unit.type === DataType.Slide) {
            let val: number = unit.value;
            if (val == null) val = 0;
            let max = 1;
            let min = 0;
            let slideUnit:number;
            if (unit.extra) {
                if (unit.extra.max) {
                    if(typeof unit.extra.max=="function")
                        unit.extra.max=unit.extra.max.bind(e);
                    max = unit.extra.max;
                }
                if (unit.extra.min) {
                    if(typeof unit.extra.min=="function")
                        unit.extra.min=unit.extra.min.bind(e);
                    min = unit.extra.min;
                }
                if (unit.extra.slideUnit) {
                    slideUnit = unit.extra.slideUnit;
                }
            }
            const slide = this.UIModule.Slide(label, val, div, { min, max,slideUnit });
            this.bindValue(slide, unit, e);
        } else if (unit.type === DataType.Bool) {
            let val = unit.value;
            if (val == null) val = false;
            const toggle = this.UIModule.Toggle(label, val, div);

            this.bindValue(toggle, unit, e);
        } else if (unit.type == DataType.String ||unit.type == DataType.Name ||unit.type == DataType.Number) {
            let inputResult;
            let str: string = unit.value;
            if (str == null) {
                if (unit.type != DataType.Number) str = "";
                else str = "0";
            }
            if (unit.readonly && unit.extra) {
                str = unit.extra[str];
            }
            if (unit.type != DataType.Number) {
                inputResult = this.UIModule.string(label, str, div);
            } else {
                inputResult = this.UIModule.NumberField(label, str, div,unit.extra);
            }
            let input = inputResult.element.querySelector("input");
            if (unit.readonly) {
                input.disabled = true;
            }
            if (!unit.readonly) {
                if (unit.type == DataType.Name) {
                    let strSplit = str.split(".");
                    str = str.substring(0, str.length - strSplit[strSplit.length - 1].length - 1);
                    inputResult.onchange = (value) => {
                        let nameSplit = unit.value.split(".");
                        unit.value = value + "." + nameSplit[nameSplit.length - 1];
                    };
                    e.watch(
                        unit.attr,
                        (val: string) => {
                            let nameSplit = val.split(".");
                            if (inputResult.value !== val.substring(0, val.length - nameSplit[nameSplit.length - 1].length - 1)) {
                                inputResult.value = val.substring(0, val.length - nameSplit[nameSplit.length - 1].length - 1);
                            }
                        },
                        "attr"
                    );
                } else {
                    inputResult.onchange = (value) => {
                        if (value !== unit.value) {
                            if (unit.type == DataType.Number) {
                                unit.value = Number(value);
                            } else {
                                unit.value = value;
                            }
                        }
                    };
                    e.watch(
                        unit.attr,
                        (val: string) => {
                            if (inputResult.value !== val) {
                                inputResult.value = val;
                            }
                        },
                        "attr"
                    );
                }
            }
            input.value = str;
        } else if (unit.type == DataType.Textarea) {
            //文字调整
            let placeholder:string
            if(unit?.extra?.placeholder){
                placeholder = unit.extra.placeholder
            }
            let textarea =    this.UIModule.Textarea(unit.name,unit.value,div,{placeholder})
            this.bindValue(textarea,unit,e)
            

            
        } else if (unit.type === DataType.DropDown) {
            let value = unit.value;
            let list=unit.extra;
            if(list==null) return;
           
            if(typeof list =="function"){
                list=list.bind(e);
            }
            const dropDown = this.UIModule.DropDown(label, value, div, {choice:list});
            this.bindValue(dropDown, unit, e);
        } else if (unit.type === DataType.Color4 ||unit.type == DataType.Color3) {
            let val;
            if (unit.value == null) {
                if (unit.type == DataType.Color4) val = [1, 1, 1, 1];
                else val = [1, 1, 1];
            } else {
                val = [...unit.value];
            }
            const color = this.UIModule.Color(label, val, div);
            this.bindValue(color, unit, e);
        } else if (unit.type === DataType.TextureBox || unit.type === DataType.MaterialBox || unit.type === DataType.Video || unit.type === DataType.Audio) {
            let type: string[];
            if (unit.extra && unit.extra.filterType) type = unit.extra.filterType;
            if (!type) {
                switch (unit.type) {
                    case DataType.TextureBox:
                        type = ["texture"];
                        break;
                    case DataType.MaterialBox:
                        type = ["material"];
                        break;
                    case DataType.Video:
                        type = ["video"];
                        break;
                    case DataType.Audio:
                        type = ["audio"];
                        break;

                    default:
                        break;
                }
            }
            const select = this.UIModule.MediaSelect(unit.name, { resourceId: unit.value, resourceType: "" }, type, div);
            select.onchange=(path,val)=>{
                if(path=="resourceId"){
                    unit.value=val;
                }
            };
            e.watch(unit.attr,(val: string) => {
                select.value.resourceId=val;
            },
            "attr");
            (select.element.querySelector(".item-title") as HTMLElement).style.alignSelf = "flex-start";
        } else if (unit.type == DataType.Button) {
            const button = this.UIModule.Button(label, "", div);
            button.onclick = () => {
                if (unit.action) {
                    unit.action.call(e);
                }
            };
        } else if (unit.type == DataType.Tag) {
            let orginValue = cloneDeep(unit.value);
            const tags = this.UIModule.Tag("标签", orginValue, div);
            tags.onchange = (val) => {
                if (!isEqual(unit.value, val)) {
                    const differentValues = unit.value.filter((value) => !val.includes(value)).concat(val.filter((value) => !unit.value.includes(value)));
                    if (unit.value.length < val.length) {
                        differentValues.forEach((it) => {
                            unit.value.push(it);
            });
                    } else if(unit.value.length > val.length) {
                        differentValues.forEach((it) => {
                            unit.value.remove(it);
                });
            }
            }
            };
        } else if (unit.type === DataType.Krpano) {
            let picAsset = VeryEngine.shareBox.id2Asset[unit.value];
            // nameSpan.classList.add("setting-item-texture-big-title");
            // nameSpan.innerText = unit.name;
            let picDiv = document.createElement("div");
            picDiv.classList.add("setting-item-texture");
            div.append(picDiv);
            let picName = document.createElement("div");
            picDiv.append(picName);
            picName.classList.add("setting-item-texture-name-box");
            let tmpSpan = document.createElement("span");
            tmpSpan.classList.add("setting-item-texture-name");
            picName.append(tmpSpan);
            tmpSpan.innerText = picAsset ? picAsset.name : "";
            let svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
            svg.ariaHidden = "true";
            svg.classList.add("icon", "icon-cuowu1");
            svg.innerHTML = `<use xlink:href="#icon-cuowu1"></use>`;
            picName.append(svg);

            let imgbox = document.createElement("div");
            imgbox.onclick = () => {
                let target = VeryEngine.shareBox.id2Asset[unit.value];
                if (target) {
                    VeryEngine.pickAsset(unit.value);
                }
            };
            tmpSpan.onclick = () => {
                let target = VeryEngine.shareBox.id2Asset[unit.value];
                if (target) {
                    VeryEngine.pickAsset(unit.value);
                }
            };
            imgbox.classList.add("setting-item-texture-img-box");

            let img = document.createElement("img");
            imgbox.append(img);

            img.classList.add("setting-item-texture-img");
            img.onclick = function () {
                addButton.click();
            };
            let imgandnamebox = document.createElement("div");
            imgandnamebox.classList.add("img-name-box");
            imgandnamebox.append(imgbox);
            imgandnamebox.append(picName);
            picName.style.justifyContent = picAsset ? "auto" : "center";

            picDiv.append(imgandnamebox);

            // 创建添加按钮
            let addButton = document.createElement("div");
            addButton.classList.add("setting-item-texture-button");
                addButton.innerHTML = "选择";
            picDiv.append(addButton);
            if (picAsset instanceof IEDTexture) {
                img.src = picAsset.assetObj;
            }else {
                img.src=VeryEngine.empty;
                svg.style.display = "none";
                addButton.style.display = "flex";
            }
            e.watch(
                unit.attr,
                (val) => {
                    let picAsset = VeryEngine.shareBox.id2Asset[val];
                    tmpSpan.innerText = picAsset ? picAsset.name : "";
                    if (picAsset instanceof IEDTexture) {
                        img.src = picAsset.assetObj;
                        svg.style.display = "block";
                    } else {
                        img.src = VeryEngine.empty;
                        svg.style.display = "none";
                    }
                },
                "attr"
            );
            svg.onclick = () => {
                unit.value = "";
                svg.style.display = "none";
                addButton.style.display = "flex";
            };
            addButton.onclick = async() => {
                let asset = await VeryEngine.shareBox.filterAssetType("texture");
                if (asset) {
                    unit.value=asset.id;
                    addButton.style.display = "none";
            }
            };
        } else if (unit.type === DataType.Map) {
            let stringDiv = document.createElement("div");
            stringDiv.classList.add("setting-item-map");
            div.append(stringDiv);
            let mapIconBox = document.createElement("div");
            mapIconBox.className = "setting-item-map-icon-box";
            let icon = document.createElement("img");
            icon.className = "setting-item-map-icon-image";
            if (unit.extra["iconUrl"]) {
                icon.src = unit.extra["iconUrl"];
            } else {
                icon.src = VeryEngine.empty;
            }
            if (unit.extra["handleIconClick"]) {
                icon.onclick = () => {
                    unit.extra["handleIconClick"](e);
                };
            } else {
                icon.onclick = () => {};
            }
            mapIconBox.append(icon);
            stringDiv.append(mapIconBox);
            let input = document.createElement("input");
            input.type = "text";
            input.className = "setting-item-map-input";
            input.onchange = (e) => {
                unit.value = input.value;
            };
            stringDiv.append(input);
            if (unit.readonly) {
                input.disabled = true;
            }
            if (unit.value) {
                input.value = unit.value;
                    }
            div.append(stringDiv);
            e.watch(
                unit.attr,
                (val) => {
                    unit.extra["handleValueChange"](e, val);
                    input.value = val;
                },
                "attr"
            );
        }
    }
    private titleDiv:{[title:string]:HTMLElement}={};
    private createTitle(title:string){
        let parent = document.createElement("div");
        parent.classList.add("layout-attributes-box");
        let tmpbox1 = document.createElement("div");
        tmpbox1.classList.add("layout-attributes-title");
        tmpbox1.innerText = title;
        parent.append(tmpbox1);
        let settingbox = document.createElement("div");
        settingbox.classList.add("layout-attributes-settingbox");
        parent.append(settingbox);
        this.attrParent.append(parent);
        this.titleDiv[title]=settingbox;
        return settingbox;
    }
    private createAttrPanel(iedList: IED[]) {
        if (this.lastEntity) {
            for (let tmp of this.lastEntity) {
                tmp.unwatch("attr");
            }
        }
        this.lastEntity = iedList;
        this.attrParent.innerHTML = "";
        this.UIModule.allDragTarget={};
        this.titleDiv={};
        let attrProto: Omit<{ [proto: string]: { proto: IEDAttrib<AllDataType>; target: IED; associtated?: string[]; result?: boolean }[] }, "__button"> & {
            __button: { proto: IEDButton; target: IED; associtated?: string[]; result?: boolean }[];
        } = IEDProxyFactory.getAttrPanel(iedList);
        for(let attr in attrProto){
            if(attr!="__button"){
                let oneIED=attrProto[attr];
                let unit=oneIED[0].proto;
                let ied=oneIED[0].target;
                if (!unit.title) unit.title = VeryEngine.MainAttrTitle;
                if(attr){
                    if(ArrayType.includes(unit.type)){
                        Object.defineProperty(unit, "value", {
                            configurable: true,
                            get: function () {
                                let arrD=ied.get(attr);
                                let array=[];
                                if(arrD instanceof DArray){
                                    array=arrD.jsonParse() as Array<any>;
                                }
                                array.push=(value)=>{
                                    for(let ied of iedList){
                                        let tmp=ied.get(attr);
                                        if(tmp==null){
                                            tmp = new DArray();
                                            ied.set(attr,tmp);
                                        }
                                        if(tmp instanceof DArray&&!tmp.jsonParse().includes(value)){
                                            tmp.push(value);
                                        }
                                    }
                                    return array.length;
                                };
                                (array as any).remove=(value)=>{
                                    for(let ied of iedList){
                                        let tmp=ied.get(attr);
                                        let index=tmp.jsonParse().indexOf(value);
                                        if(tmp instanceof DArray&&index>=0){
                                            tmp.remove(index);
                                        }
                                    }
                                };
                                return array;
                            },
                        });
                    }else{
                        Object.defineProperty(unit, "value", {
                            configurable: true,
                            get: function () {
                                return ied.get(attr);
                            },
                            set: function (newVal) {
                                for (let ied of iedList) {
                                    ied.set(attr,newVal,{origin:"attr"});
                                }
                            },
                        });
                    }
                }
                this.beforeCreateUnit(oneIED,attr);
            }
        }
        if(attrProto.__button){
            for(let tmp of attrProto.__button){
                if(!tmp.proto.title) tmp.proto.title=VeryEngine.MainAttrTitle;
                this.beforeCreateUnit([tmp as any]);
            }
        }
        for(let key in this.titleDiv){
            let childNodes=this.titleDiv[key].childNodes;
            let hidden=true;
            for(let i=0;i<childNodes.length;i++){
                if((childNodes[i] as HTMLElement).style.display!="none"){
                    hidden=false;
                    break;
                }
            }
            if(hidden){
                (this.titleDiv[key].previousSibling as HTMLElement).style.display="none";
            }
        }
    }

    private beforeCreateUnit(oneIED: { proto: IEDAttrib<AllDataType>; target: IED; associtated?: string[]; result?: boolean }[], attr?: string) {
        let unit=oneIED[0].proto;
        let ied=oneIED[0].target;
        let parent=this.titleDiv[unit.title];
        if(!parent){
            parent=this.createTitle(unit.title);
        }
        let div = document.createElement("div");
        div.classList.add("setting-item");
        parent.append(div);
        let label = unit.name;

        let show=true;    
        for(let oneProto of oneIED){
            if(oneProto.proto.filter){
                oneProto.associtated=[];
                let obj=new Proxy(oneProto.target,{
                    get(target, p) {
                        if(p=="get"){
                            return function(key: string){
                                if(!oneProto.associtated.includes(key)){
                                    oneProto.associtated.push(key);
                                }
                                return oneProto.target.get(key);
                            };
                        }else if(typeof p=="string"&&IEDProxyFactory.inProperties(target,p)){
                             oneProto.associtated.push(p);
                            return target[p];
                        }else{
                            return target[p];
                    }
                    },
                });
                if(!(oneProto.result=oneProto.proto.filter.call(obj))){
                    show=false;
                }
                let func = (oneProto: { target: IED; associtated?: string[]; result?: boolean }) => {
                    let tmpAsso=[];
                    let obj=new Proxy(oneProto.target,{
                        get(target, p, receiver) {
                            if(p=="get"){
                                return function(key: string){
                                    tmpAsso.push(key);
                                    return ied.get(key);
                                };
                            } else if(IEDProxyFactory.inProperties(target,p as string)){
                                tmpAsso.push(p);
                                return target[p];
                            }else{
                                return target[p];
                        }
                        },
                    });
                    let res = (oneProto.result = unit.filter.call(obj));
                    for(let tmp of tmpAsso){
                        if(!oneProto.associtated.includes(tmp)){
                            ied.watch(tmp,() => {
                                func(oneProto);
                            },"attr");
                            oneProto.associtated.push(tmp);
                        }
                    }
                    if(res)
                    for(let oneProto of oneIED){
                        if(oneProto.result==false){
                            res=false;
                            break;
                        }
                    }
                    if (res){
                        if(div.childNodes.length==0){
                            this.createUnit(Object.assign(unit, { attr: attr }), ied, div, label);
                        }
                        div.style.display = "";
                        if(parent.style.display=="none"){
                            parent.style.display="";
                        }
                    }else{
                        div.style.display = "none";
                        if(parent.style.display!="none"){
                            let childNodes=parent.childNodes;
                            let hidden=true;
                            for(let i=0;i<childNodes.length;i++){
                                if((childNodes[i] as HTMLElement).style.display!="none"){
                                    hidden=false;
                                    break;
                                }
                            }
                            if(hidden){
                                parent.style.display="none";
                            }
                        }
                    }
                };
                for (let attr of oneProto.associtated) {
                    ied.watch(attr,() => {
                        func(oneProto);
                    },"attr");
                }
            }
        }
        if(show){
            this.createUnit(Object.assign(unit, { attr: attr }), ied, div, label);
        }else{
            div.style.display="none";
        }
    }

    private bindValue(result, unit, e) {
        result.onchange = (val) => {
            if (!isEqual(unit.value, val)) {
                unit.value = cloneDeep(val);
        }
        };
        e.watch(
            unit.attr,
            (newVal: number[]) => {
                if (!isEqual(newVal, result.value)) {
                    result.value = cloneDeep(newVal);
        }
            },
            "attr"
        );
    }
}
