import { DMap } from "../djs/type";
import {  IEDAsset} from ".";
import { VeryEngine } from "../engine";
import { addAssetClass } from "../engine/IEDProxy";

@addAssetClass
export class IEDAssetRoot extends IEDAsset{

    public get type(): string {
        return "asset-root"
    }
    constructor(){
        let map=new DMap();
        map.set("name","项目资源");
        map.set("id","root")
        map.set("path",[]);
        map.set("type","asset-root");
        super(map)
    }
    public get name(){
        return "项目资源";
    }
    public get id(){
        return "root";
    }

    public assetObj: string;
    
    protected async Load(){
    }
    public getEmptyID(name:string){
        let children=this.children;
        for(let i=children.length-1;i>=0;i--){
            let childAsset=VeryEngine.shareBox.id2Asset[children[i]];
            if(name==childAsset.name){
                return childAsset.id;
            }
        }
        return "";
    }

    public customAttributes() {
        return [];
    }

    public get suffix(): string[] {
        return [];
    }
}