export class VREvent<T extends string>{
    private vr_event:{[key:string]:((...params:any[])=>void)[]}={}
    public addEventListener(type:string,listener:(...params:any[])=>void){
        if(!this.vr_event[type])
            this.vr_event[type]=[];
        this.vr_event[type].push(listener);
    }

    public triggerEvent(type:string,...params:any[]){
        if(this.vr_event[type]){
            for(let func of this.vr_event[type]){
                func(...params);
            }
        }
    }

    public have(type:string){
        return type in this.vr_event;
    }

    public deleteEvent(type:string){
        delete this.vr_event[type];
    }

    public readyEvent(type:string,...params:any[]){
        this.triggerEvent(type,...params);
        this.deleteEvent(type);
    }

    private eventGroup:{[key:string]:VREvent<any>};
    public getEventGroup(group:T){
        if(!this.eventGroup) this.eventGroup={};
        if(!this.eventGroup[group])
            this.eventGroup[group]=new VREvent();
        return this.eventGroup[group];
    }

    public deleteEventGroup(group:T){
        if(this.eventGroup)
        delete this.eventGroup[group];
    }

    public triggerEventGroup(type:T,exclude:string[],...params:any[]){
        for(let group in this.eventGroup){
            if(!exclude||!exclude.includes(group)){
                this.eventGroup[group].triggerEvent(type,...params)
            }
        }
    }

    public clearEvent(){
        this.vr_event={};
        this.eventGroup=undefined;
    }
}