import {addEntityClass,ATTRIB, IEDAttrib} from "../../engine/IEDProxy"
import { VeryEngine,DataType} from "../../engine";
import { IEDGUI } from "./IEDGUI";


@addEntityClass
export class Dropdown extends IEDGUI{
    public get subtype(): string {
        return "dropdown"
    }

    private span:HTMLElement;
    private rightDiv:HTMLElement;
    private ulDiv:HTMLElement;

    protected realLoad(is2D:boolean): void {
        if(is2D){
            this.sceneObj = document.createElement("div");
            let divStyle = this.sceneObj.style;
            this.sceneObj.style.pointerEvents = "auto";
            divStyle.position = "absolute";
            divStyle.cursor = "pointer";
            divStyle.background = "#fff";
            divStyle.border = "1px solid black";
            divStyle.borderRadius = "5px";
            divStyle.display="flex";
            divStyle.alignItems="center";

            this.span = document.createElement("span");
            this.span.style.marginLeft="4px";
            this.span.innerText="123"
            this.sceneObj.append(this.span);

            this.ulDiv = document.createElement("div");
            let ulStyle = this.ulDiv.style;
            this.ulDiv.className = "ul";
            ulStyle.position = "absolute";
            ulStyle.top = "calc(100% + 2px)"
            ulStyle.height="100%";
            ulStyle.width="100%";
            ulStyle.display = "none";
            this.sceneObj.clickWithHide(()=>{ulStyle.display="block"},()=>{ulStyle.display="none"})
            this.sceneObj.append(this.ulDiv);

            this.rightDiv = document.createElement("div");
            this.rightDiv.className = "rightDiv";
            this.rightDiv.innerHTML = "✓";
            let rightDivStyle = this.rightDiv.style;
            rightDivStyle.position = "absolute";
            rightDivStyle.left = "0";
            rightDivStyle.top = "0";
            rightDivStyle.height = "100%";
            rightDivStyle.width = "25px";
            rightDivStyle.fontSize = "18px";
            rightDivStyle.display="flex";
            rightDivStyle.alignItems="center"
        }else{
        }
    }

    private createLi(text: string, index:number) {
        let liDiv = document.createElement("div");
        let liDivStyle = liDiv.style;
        liDivStyle.position = "relative";
        liDivStyle.width = "100%";
        liDivStyle.height="100%";
        liDivStyle.backgroundColor="#fff";
        liDivStyle.display="flex";
        liDivStyle.alignItems="center";
        liDivStyle.paddingLeft = "25px";
        liDivStyle.boxSizing = "border-box";
        liDiv.innerText = text;
        liDiv.addEventListener("mouseover", function () {
            liDivStyle.backgroundColor = "#808080";
        });

        liDiv.addEventListener("mouseout", function () {
            liDivStyle.backgroundColor = "#fff";
        });
        liDiv.addEventListener("click",()=>{this.set("gui.selectedIndex",index)});
        this.ulDiv.append(liDiv);
    }

    private title="下拉菜单";

    private tmpArray:string[];
    @ATTRIB("gui.options")
    public options:IEDAttrib<DataType.String>={
        name:"选项(~分割)",
        type:DataType.String,
        onchange(this:Dropdown,val){
            if(this.is2D){
                this.ulDiv.innerHTML="";
                this.tmpArray = val.split("~");
                for (let i = 0; i < this.tmpArray.length; i++) {
                    this.createLi(this.tmpArray[i],i)
                }
                this.ulDiv.children[this.get("gui.selectedIndex")].append(this.rightDiv);
                this.span.innerText=this.tmpArray[this.get("gui.selectedIndex")];
            }
        },
        default:"A~B~C",
        title:this.title
    }

    @ATTRIB("gui.selectedIndex")
    public selectedIndex:IEDAttrib<DataType.Number>={
        name:"选中索引",
        type:DataType.Number,
        onchange(this:Dropdown,val,isFirst){
            if(!isFirst){
                if(this.is2D){
                    this.span.innerText=this.tmpArray[val];
                    this.ulDiv.children[val].append(this.rightDiv);
                }
            }
        },
        title:this.title
    }

    @ATTRIB("gui.fontSize")
    public fontSize:IEDAttrib<DataType.Number>={
        name:"字体大小",
        type:DataType.Number,
        onchange(this:Dropdown,val){
            if(this.is2D)
                (this.sceneObj as HTMLElement).style.fontSize=val+"px"
        },
        default:18,
        title:this.title
    }
}