import { IED, VeryEngine } from "../engine";
import { DArray, DMap } from "../djs/type";
import {Tools} from "../utility/Tools";
import { IEDAttrib,ATTRIB, IEDProxyFactory } from "../engine/IEDProxy";
import {DataType} from "../engine"
import { IEDFolder } from "src/assets";

export abstract class IEDEntity extends IED{
    public static rootId;
    protected static loadSceneObj:{[id:string]:any}={};
    private _id:string;
    public get id():string{
        return this._id
    }
    
    public get childIds():string[]{
        let children=this._data.get('children');
        //children 必须初始就存在，若在push第一个元素时新增一个array在push，假如两个人同时操作，后一个array会替代前一个array;
        //正常情况需要同一个array里面有两次操作的内容，服务器端需要做特殊处理，初始化的时候，若无children就添加 或者能保证原始数据必定有children
        if(!children) 
        {
            children=new DArray();
            this._data.set("children",children);
        }
        return children.jsonParse();
    }
    private _children:IEDEntity[]=[]
    private _childrenProxy:Omit<Array<IEDEntity>,"push"|"splice">
    &{push:(...val:(string|IEDEntity)[])=>void,splice:(index:number,deleteCount:number,...val:(string|IEDEntity)[])=>void};
    public get children(){
        return this._childrenProxy;
    }

    public abstract filterParentType(parent:IEDEntity):boolean;

    protected _parent:IEDEntity;
    public get parent():IEDEntity{
        return this._parent;
    }

    public set parent(val:IEDEntity|string){
        if(typeof val=="string")
            val=VeryEngine.shareBox.id2Entity[val];
        if(val&&this._parent!=val){
            if(this._parent){
                let index=this._parent.children.indexOf(val);
                if(index>=0){
                    this._parent.children.splice(index,1);
                }
            }
            if(!val.childIds.includes(this.id)){
                val.children.push(this.id);
            }
        }
    }

    public get enabled():boolean{
        let result=this._data.get("enabled");
        return result==null?true:result;
    }

    constructor(data){
        super(data);
        if(data){
            this._id=data.get('resource_id')
            let self=this;
            this._childrenProxy=new Proxy(this._children,{
                get(target,p){
                    if(p=="push"){
                        return function(...vals:(string|IEDEntity)[]){
                            for(let val of vals){
                                if(val instanceof IEDEntity){
                                    val=val.name;
                                }
                                self._data.get("children").push(val);
                            }
                        }
                    }else if(p=="splice"){
                        return function(index:number,deleteCount:number,...vals:(string|IEDEntity)[]){
                            let array=self._data.get("children") as DArray;
                            if(!array) return;
                            let childIds=array.value;
                            let j=index;
                            while(deleteCount>0){
                                if(self._children[j].id==childIds[index]){
                                    array.remove(index);
                                    deleteCount--
                                }else{
                                    index++
                                }
                            }
                            for(let i=0;i<vals.length;i++){
                                let tmp=vals[i];
                                if(tmp instanceof IEDEntity){
                                    vals[i]=tmp.id;
                                }
                            }
                            array.insert(index,...vals);
                        }
                    }else{
                        return target[p];
                    }
                }
            })
        }
    }

    public removeChildButRecord(entity:IEDEntity){
        let index=this._children.indexOf(entity);
        if(index>=0){
            this._children.splice(index,1);
        }
    }
    public set enabled(val:boolean){
        this._data.set("enabled",val);
    }

    public get originAsset():string{
        return this._data.get("originAsset");
    }

    public sceneObj:any;
    //数据加载
    protected abstract Load(parent?:IEDEntity):Promise<void>;

    //子物体先加载，需记录在这
    public static mountEntity:{[id:string]:IEDEntity}={};
    //父物体先加载，其子物体需要记录这
    public static loadedParentChild:{[id:string]:IEDEntity}={};

    public async mount(){
        if(this.type=="root"){
            await this.sceneObjLoad(null);
            VeryEngine.entityReady.readyEvent(this.id);
        }else if(this.id in IEDEntity.loadedParentChild) {
            await this.sceneObjLoad(IEDEntity.loadedParentChild[this.id]);
            IEDEntity.loadedParentChild[this.id].childHandler(this,{origin:"local"});
            VeryEngine.entityReady.readyEvent(this.id);
            delete IEDEntity.loadedParentChild[this.id];
        }else{
            IEDEntity.mountEntity[this.id]=this;
        }
    }
    public async sceneObjLoad(parent:IEDEntity){
        if(IEDEntity.loadSceneObj[this.id]){
            this.sceneObj=IEDEntity.loadSceneObj[this.id];
            delete IEDEntity.loadSceneObj[this.id];
        }else{
           await this.Load(parent);
        }
        //顺序不能变，init 和loadcomplete函数内部有可能会调用到id2Entity
        VeryEngine.shareBox.id2Entity[this.id]=this;
        if(this.sceneObj){
            IEDProxyFactory.init(this);
            await IEDProxyFactory.loadComplete(this);
        }
        this.dealwithChildren();
    }

    public export(vrData:any,file:IED[],parent?:string){
        let json=this._data.jsonParse();
        if(parent)
            json.parent=parent;
        vrData.vr.push(json);
        for(let child of this.children){
            if(child){
                child.export(vrData,file,this.id);
            }
        }
        return json;
    }

    public recordSceneObj(sceneObj:any){
        let id =Tools.uuid();
        sceneObj.id=id;
        let tmp:any={name:sceneObj.name,resource_id:id}
        let root=VeryEngine.shareBox.id2Entity[IEDEntity.rootId];
        root.children.push(id);
        IEDEntity.loadSceneObj[id]=sceneObj;
        return tmp;
    }

    protected abstract setChild(child:IEDEntity,config:{origin:string}):void;
    private dealwithChildren(){
        let childrenJson=this.childIds;
        this.watch("children",(index:number,child:string,config:{origin:string,deleted:boolean})=>{
            //假设父子关系del的都是往另外一个对象下加的，加的时候会处理，del无需特殊处理
            if(!config.deleted){
                this.preprocessChild(child,config);
            }else{
                for(let i=0;i<this._children.length;i++){
                    if(this._children[i].id==child){
                        this._children.splice(i,1);
                        break;
                    }
                }
            }
        },"0");
        for(let i=0;i<childrenJson.length;i++){
            this.preprocessChild(childrenJson[i],{origin:"local"});
        }
    }

    private preprocessChild(child:string,config:{origin:string}){
        if(VeryEngine.shareBox.id2Entity[child]){
            this.childHandler(VeryEngine.shareBox.id2Entity[child],config);
        }else{
            if(IEDEntity.mountEntity[child]){
                IEDEntity.mountEntity[child].sceneObjLoad(this).then(()=>{
                    this.childHandler(IEDEntity.mountEntity[child],config);
                    VeryEngine.entityReady.readyEvent(child);
                    delete IEDEntity.mountEntity[child];
                })
            }else{
                IEDEntity.loadedParentChild[child]=this;
            }
        }
    }


    public childHandler(child:IEDEntity,config:{origin:string}){
        let i=0;
        let j=0;
        let childrenIds=this.childIds;
        while(i<childrenIds.length){
            if(childrenIds[i]==child.id){
                if(j<this._children.length)
                    this._children.splice(j,0,child);
                else
                    this._children.push(child);
                break;
            }
            if(j<this._children.length&&childrenIds[i]==this._children[j].id){
                j++;
            }
            i++;

        }
        //顺序不能变，transform设置子物体的时候，假如child的parent是undfined，则说明是第一次，不用跳转position等参数，否则需要调整position
        this.setChild(child,config);
        child._parent=this;
    }


    public import?(folder:IEDFolder,json:any):void;

    @ATTRIB("enabled")
    public abstract isEnabled:IEDAttrib<DataType.Bool>

    @ATTRIB("name")
    public nameStr:IEDAttrib<DataType.String>={
        name:"名字",
        type:DataType.String
    }

    public async clone(withChild:boolean,params?:any){
        let newId=Tools.uuid();
        let data=this.copyData();
        data.resource_id=newId;
        if(params){
            this.dealParams(data,params);
        }
        if(withChild){
            let copyChildren=[];
            for(let i=0,j=0;i<data.children.length;i++){
                if(this.children[j].id==data.children[i]){
                    data.children[i]=this.children[j].cloneFromParent(copyChildren);
                    j++;
                }
            }
            let enity=await VeryEngine.addEntityData(data,this.parent);
            //序号0是最子的子物体，需要从父物体开始一个个加载创建
            for(let i=copyChildren.length-1;i>=0;i--){
                await VeryEngine.addEntityOnlyData(copyChildren[i]);
            }
            return enity;
        }else{
            data.children=[];
            let enity=await VeryEngine.addEntityData(data,this.parent);
            return enity;
        }
    }
    private dealParams(data:any,params:any){
        for(let key in params){
            if(Object.prototype.toString.call(params[key])=='[object Object]'){
                if(!data[key]) data[key]={};
                this.dealParams(data[key],params[key]);
            }else{
                data[key]=params[key];
            }
        }
    }
    
    private cloneFromParent(childrenData:any[]){
        let newId=Tools.uuid();
        let data=this.copyData();
        data.resource_id=newId;
        for(let i=0,j=0;i<data.children.length;i++){
            if(this.children[j].id==data.children[i]){
                data.children[i]=this.children[j].cloneFromParent(childrenData)
                j++;
            }
        }
        childrenData.push(data);
        return newId;
    }
    
    public veryVar:{attr:string,valName:string}[]=[]

    protected addVeryVal( val:{attr: string;valName: string}){
        if(!VeryEngine.EditMode){
            this.veryVar.push(val);
        }
    }

    public copyData() {
        let data=super.copyData();
        for(let val of this.veryVar){
            let attr=data;
            let split=val.attr.split(".");
            for(let i=0;i<split.length;i++){
                if(attr){
                    if(i==split.length-1)
                        attr[split[i]]=val.valName;
                    else
                        attr=attr[split[i]];
                }
            }
        }
        return data;
    }

    public get isEnableDeep(){
        let parent:IEDEntity=this;
        while(parent&&parent.type!="root"){
            if(!parent.enabled){
                return false;
            }
            parent=parent.parent;
        }
        return true;
    }
}