import { IEDEntity } from "./IEDEntity";
import { VeryEngine,DataType } from "../engine";
import { ATTRIB, IEDAttrib, addEntityClass } from "../engine/IEDProxy";
import { IEDFolder } from "../assets/IEDFolder";
import { IEDTransform } from "./IEDTransform";
import { PoseMatrixTool } from "./PoseMatrixTool";

@addEntityClass
export class IEDSprite extends IEDEntity {
    protected setChild(child: IEDEntity, config?:{origin:string}) {
       
    }

    protected dispose(): void {
        this.sceneObj.dispose();
        this.spriteManager.dispose();
        if(this.pointerEvent)
            VeryEngine.scene.onPointerObservable.remove(this.pointerEvent);
        PoseMatrixTool.removeAfterPoseMatrix(this.id);
    }

    public sceneObj:BABYLON.Sprite;
    public filterParentType(parent: IEDEntity){
        if(parent instanceof IEDTransform ||parent.type=="root")
            return true
        else
            return false
    }

    private spriteManager:BABYLON.SpriteManager;
    public get type(): string {
        return "sprite";
    }

    async Load(parent:IEDEntity) {
        this.spriteManager = new BABYLON.SpriteManager("playerManager","",2000,64,VeryEngine.scene);
        this.spriteManager.isPickable = true;
        this.sceneObj = new BABYLON.Sprite(this.name, this.spriteManager);
        if(!VeryEngine.EditMode){
            VR.GameGlobal.sceneSpriteDic[this.sceneObj.name]=this.sceneObj;
        }
        PoseMatrixTool.addAfterPoseMatrix(this.id,(transform)=>{
            if(parent.sceneObj)
            if(parent.sceneObj.isDescendantOf(transform)){
                this.realPos();
            }
        })
        this.dealMove();
    }

    public isEnabled:IEDAttrib<DataType.Bool>={
        name:"激活",
        type:DataType.Bool,
        onchange(this:IEDSprite,val){
            this.sceneObj.isVisible=val;
        },
        default:true
    }
    @ATTRIB()
    public position:IEDAttrib<DataType.Vector3>={
        name:"位置",
        type:DataType.Vector3,
        onchange(this:IEDSprite,val,isFirst){
            if(!isFirst){
                this.realPos();
            }
        }
    }
    public realPos(parent?:BABYLON.TransformNode){
        let val=this.get("position")
        let vec3=BABYLON.Vector3.FromArray(val);
        if(parent!==null){
            if(!parent){
                if(this.parent.sceneObj&&this.parent.sceneObj instanceof BABYLON.TransformNode){
                    vec3=this.parent.sceneObj.getAbsolutePosition().add(vec3);
                }
            }else{
                vec3=parent.getAbsolutePosition().add(vec3);
            }
        }
        this.sceneObj.position=vec3;
    }

    @ATTRIB()
    public angle:IEDAttrib<DataType.Number>={
        name:"角度",
        type:DataType.Number,
        onchange(this:IEDSprite,val){
            this.sceneObj.angle=val;
        },
    }

    @ATTRIB()
    public cellWidth:IEDAttrib<DataType.Number>={
        name:"单元宽度",
        type:DataType.Number,
        onchange(this:IEDSprite,val){
            this.sceneObj.manager.cellWidth=val;
        },
        default:1024
    }

    @ATTRIB()
    public cellHeight:IEDAttrib<DataType.Number>={
        name:"单元高度",
        type:DataType.Number,
        onchange(this:IEDSprite,val){
            this.sceneObj.manager.cellHeight=val;
        },
        default:1024
    }

    @ATTRIB()
    public width:IEDAttrib<DataType.Number>={
        name:"宽度比例",
        type:DataType.Number,
        onchange(this:IEDSprite,val){
            this.sceneObj.width=val;
        },
        default:200
    }

    @ATTRIB()
    public height:IEDAttrib<DataType.Number>={
        name:"高度比例",
        type:DataType.Number,
        onchange(this:IEDSprite,val){
            this.sceneObj.height=val;
        },
        default:200
    }

    @ATTRIB()
    public color:IEDAttrib<DataType.Color4>={
        name:"颜色",
        type:DataType.Color4,
        onchange(this:IEDSprite,val){
            this.sceneObj.color=BABYLON.Color4.FromArray(val);
        }
    }

    @ATTRIB()
    public invertU:IEDAttrib<DataType.Bool>={
        name:"横向翻转",
        type:DataType.Bool,
        onchange(this:IEDSprite,val){
            this.sceneObj.invertU=val;
        }
    }

    @ATTRIB()
    public invertV:IEDAttrib<DataType.Bool>={
        name:"纵向翻转",
        type:DataType.Bool,
        onchange(this:IEDSprite,val){
            this.sceneObj.invertV=val;
        }
    }

    @ATTRIB()
    public isPickable:IEDAttrib<DataType.Bool>={
        name:"可点击",
        type:DataType.Bool,
        onchange(this:IEDSprite,val){
            if(VeryEngine.EditMode){
                this.sceneObj.isPickable=true;
            }else{
                this.sceneObj.isPickable=val;
            }
        },
        default:true
    }

    @ATTRIB()
    public useAlphaForPicking:IEDAttrib<DataType.Bool>={
        name:"透明度识别点击",
        type:DataType.Bool,
        onchange(this:IEDSprite,val){
            this.sceneObj.useAlphaForPicking=val;
        }
    }

    @ATTRIB()
    public loopAnimation:IEDAttrib<DataType.Bool>={
        name:"动画循环",
        type:DataType.Bool,
        onchange(this:IEDSprite,val){
            this.sceneObj.loopAnimation=val;
        }
    }

    @ATTRIB()
    public fromIndex:IEDAttrib<DataType.Number>={
        name:"动画起始索引",
        type:DataType.Number,
        onchange(this:IEDSprite,val){
            this.sceneObj.fromIndex=val;
        },
        filter(){
            return this.get("loopAnimation")
        }
    }

    @ATTRIB()
    public toIndex:IEDAttrib<DataType.Number>={
        name:"动画终止索引",
        type:DataType.Number,
        onchange(this:IEDSprite,val){
            this.sceneObj.toIndex=val;
        },
        filter(){
            return this.get("loopAnimation")
        }
    }

    @ATTRIB()
    public delay:IEDAttrib<DataType.Number>={
        name:"动画间隔",
        type:DataType.Number,
        onchange(this:IEDSprite,val){
            this.sceneObj.delay=val;
        },
        default:100,
        filter(){
            return this.get("loopAnimation")
        }
    }

    @ATTRIB()
    public imageUrl:IEDAttrib<DataType.TextureBox>={
        name:"图片",
        type:DataType.TextureBox,
        async onchange(this:IEDSprite,val){
            let picAset=VeryEngine.shareBox.id2Asset[val];
            if(picAset){
                await picAset.onceOnlyLoad();
                this.sceneObj.manager.texture = new BABYLON.Texture(picAset.assetObj,VeryEngine.scene,true,false,BABYLON.Texture.TRILINEAR_SAMPLINGMODE);
            }
        }
    }

    public export(vrData:any,file:any[],parent?:string){
        let json=super.export(vrData,file,parent);
        if(json['imageUrl']){
            let linkAsset=VeryEngine.shareBox.id2Asset[json['imageUrl']];
            if(linkAsset){
                linkAsset.export(vrData,file);
                json['imageUrl']=linkAsset.autoRename;
            }
        }
    }

    public import(folder:IEDFolder,json:any): void {
        if(json.imageUrl){
            let split=json.imageUrl.split('.');
            //若不是assetID,有.后缀
            if(split.length!=1){
                json.imageUrl=folder.getEmptyID(json.imageUrl)
            }
        }
    }

    private z:number=0;
    private parentPos=BABYLON.Vector3.Zero();
    private pointerEvent;
    private dealMove(){
        if(VeryEngine.EditMode){
            this.pointerEvent=VeryEngine.scene.onPointerObservable.add((data)=>{
                let evt=data.event;
                let func=()=>{
                    let curPosition = BABYLON.Vector3.Unproject(new BABYLON.Vector3(VeryEngine.scene.pointerX, VeryEngine.scene.pointerY, this.z), VeryEngine.scene.getEngine().getRenderWidth(), VeryEngine.scene.getEngine().getRenderHeight(), BABYLON.Matrix.Identity(), VeryEngine.scene.cameraToUseForPointers.getViewMatrix(), VeryEngine.scene.cameraToUseForPointers.getProjectionMatrix());
                    curPosition=curPosition.subtract(this.parentPos)
                    this.set('position', [curPosition.x, curPosition.y, curPosition.z]);
                }
                if (evt.button === 0) {
                    var pickResult = VeryEngine.scene.pickSprite(VeryEngine.scene.pointerX, VeryEngine.scene.pointerY, (sprite: BABYLON.Sprite): boolean => {
                        return sprite==this.sceneObj;
                    }, true, VeryEngine.scene.cameraToUseForPointers);
                    if (pickResult && pickResult.pickedSprite && VeryEngine.scene.cameraToUseForPointers !== null) {
                        if(this.parent.sceneObj instanceof BABYLON.TransformNode){
                            this.parentPos=this.parent.sceneObj.getAbsolutePosition();
                        }else{
                            this.parentPos=BABYLON.Vector3.Zero();
                        }
                        let localPosition = this.sceneObj.position.clone();
                        let startpoint1 = BABYLON.Vector3.Project(localPosition, BABYLON.Matrix.Identity(), VeryEngine.scene.cameraToUseForPointers.getTransformationMatrix(), VeryEngine.scene.cameraToUseForPointers.viewport.toGlobal(VeryEngine.scene.getEngine().getRenderWidth(), VeryEngine.scene.getEngine().getRenderHeight()));
                        this.z=startpoint1.z;
                        VeryEngine.pickEntity(this.id);
                        let tmp1= VeryEngine.scene.onPointerObservable.add(()=>{
                            func();
                        },BABYLON.PointerEventTypes.POINTERMOVE);
                        let tmp2=VeryEngine.scene.onPointerObservable.add((data)=>{
                            data.stopPropagation();
                            VeryEngine.scene.onPointerObservable.remove(tmp1);
                            VeryEngine.scene.onPointerObservable.remove(tmp2);
                        },BABYLON.PointerEventTypes.POINTERUP)
                    }
                }
            },BABYLON.PointerEventTypes.POINTERDOWN);
        }
        
    }
}