import { VeryEngine } from "../engine/VeryEngine";
import { IButton } from "../plugin/Iplugin";
import { PluginPackage } from "../plugin/IEDPlugin";
import { UIModule } from "./UI";
export abstract class Window extends UIModule {
    public popUp: HTMLElement;
    private mask: HTMLElement;
    private buton: IButton;
    private mode:"destroy" | "none" | "hide" | "confirm";
    public config;
    public UIModule = new UIModule();
    constructor(
        title: string,
        config?: {
            drag?: boolean;
            position?: { left: number; top: number } | MouseEvent | "bottom-right" | "bottom-left" | "top-left" | "top-right";
            closeMode?: "destroy" | "none" | "hide" | "confirm" ;
            maxHeight?: string;
            contentHeight?: string;
            contentWidth?: string;
            size?: number;
            mask?: boolean;
            button?:IButton
        },
        selfContent?: HTMLElement
    ) {
        super();
        if (!config) config = {};
        if (!config.closeMode) config.closeMode = "destroy";
        //处理遮罩背景
        if (config.mask) {
            this.mask = document.createElement("div");
            this.mask.classList.add("window-mask");
            document.body.append(this.mask);
        }
        //处理弹窗主体
        let popUp = document.createElement("div");
        popUp.classList.add("window-box");
        this.popUp = popUp;
        //处理标题
        if (title) {
            let titleDiv = document.createElement("div");
            titleDiv.classList.add("title");
            titleDiv.innerText = title;
            if (config.drag && typeof config.position != "string") {
                titleDiv.onmousedown = function (e) {
                    var x1 = e.offsetX;
                    var y1 = e.offsetY;
                    document.onmousemove = function (ev) {
                        var x2 = ev.clientX - 21;
                        var y2 = ev.clientY - 21;
                        var l = x2 - x1;
                        var t = y2 - y1;
                        if (l < -popUp.offsetWidth + 35) {
                            l = -popUp.offsetWidth + 35;
                        }
                        if (t < 0) {
                            t = 0;
                        }
                        if (t > document.documentElement.clientHeight - 35) {
                            t = document.documentElement.clientHeight - 35;
                        }
                        if (l > document.documentElement.clientWidth - 35) {
                            l = document.documentElement.clientWidth - 35;
                        }
                        popUp.style.left = l + "px";
                        popUp.style.top = t + "px";
                    };
                    window.onmouseup = function () {
                        document.onmousemove = null;
                    };
                };
            }else{
                titleDiv.style.cursor="auto"
            }
            popUp.append(titleDiv);
        }
        //创建主体content
        if (!selfContent) {
            let contentContainer = document.createElement("div");
            contentContainer.classList.add("content-container");

            let content = document.createElement("div");
            content.classList.add("content");
            popUp.append(contentContainer);
            if (config.maxHeight) {
                // content.style.maxHeight = config.maxHeight;
                contentContainer.style.maxHeight = config.maxHeight;
            }
            if (config.contentHeight) {
                content.style.height = config.contentHeight;
                contentContainer.style.height = config.contentHeight;
                contentContainer.style.overflowY = "auto";
            }
            if (config.contentWidth) {
                contentContainer.style.width = config.contentWidth+"px";
                content.style.width = config.contentWidth+"px";
            }
            contentContainer.append(content);
            this.content = content;
        } else {
            this.content = selfContent;
            this.UIModule.content = selfContent;
        }
        if (this.GUI) this.GUI();
        this.mode=config.closeMode;
        //处理底部按钮
        if (config.closeMode == "confirm") {
            let flex = document.createElement("div");
            flex.className = "window-control";
            popUp.append(flex);
            let confirm = document.createElement("div");
            confirm.innerText = "确认";
            confirm.classList.add("confirm");
            flex.append(confirm);
            let cancel = document.createElement("div");
            cancel.innerText = "取消";
            cancel.classList.add("cancel");
            flex.append(cancel);
            confirm.onclick = () => {
                for (let act of this.confirmActList) {
                    act();
                }
                this.destroy();
            };
            cancel.onclick = () => {
                for (let act of this.closeActList) {
                    act();
                }
                this.destroy();
            };
        } else if (config.closeMode != "none") {
            let flex = document.createElement("div");
            flex.style.cssText = "display:flex;justify-content:flex-end;margin-top:16px";
            popUp.append(flex);
            let cancel = document.createElement("div");
            cancel.innerText = "关闭";
            cancel.classList.add("cancel", "button");
            flex.append(cancel);
            let mode = config.closeMode;

            cancel.onclick = () => {
                if (mode == "destroy") this.destroy();
                else if (mode == "hide") this.hide();
                for (let act of this.closeActList) {
                    act();
                }
            };
        }
        if (selfContent) {
        } else {
            document.body.append(popUp);
        }
        this.config = config;
        if(config.button){
            this.bindButton(config.button);
        }
        setTimeout(() => {
            this.dealPos();
        }, 0);
    }
    public pluginTitle(title: string, parent: HTMLElement) {
        const pluginTitle = document.createElement("div");
        pluginTitle.className = "plugin-title";
        pluginTitle.innerText = title;
        parent.insertBefore(pluginTitle, parent.firstChild);
    }
    public dealPos(pos?: { left: number; top: number } | MouseEvent | BABYLON.IPointerEvent) {
        if (pos) this.config.position = pos;
        let config = this.config;
        if (!config.position) {
            this.popUp.style.top = 200 + "px";
            if (this.popUp.clientHeight > document.body.clientHeight) this.popUp.style.top = 0 + "px";
            this.popUp.style.left = (document.body.clientWidth - this.popUp.offsetWidth) / 2 + "px";
        } else if (typeof config.position != "string" && "clientX" in config.position && "clientY" in config.position) {
            let x = config.position.clientX;
            let y = config.position.clientY;
            let width = this.popUp.offsetWidth;
            let height = this.popUp.offsetHeight;
            if (x + width > document.body.clientWidth) x = document.body.clientWidth - width;
            if (y + height > document.body.clientHeight) y = document.body.clientHeight - height;
            this.popUp.style.top = y + "px";
            this.popUp.style.left = x + "px";
        } else if (config.position == "bottom-right") {
            let layoutAsset = document.getElementById("layout-assets");
            layoutAsset.append(this.popUp);
            this.popUp.style.top = -this.popUp.offsetHeight + "px";
            this.popUp.style.right = 0 + "px";
        } else if (config.position == "bottom-left") {
            let layoutAsset = document.getElementById("layout-assets");
            layoutAsset.append(this.popUp);
            this.popUp.style.top = -this.popUp.offsetHeight + "px";
            this.popUp.style.left = 0 + "px";
        } else if (config.position == "top-left") {
            let layoutAsset = document.getElementById("layout-toolbar");
            layoutAsset.append(this.popUp);
            this.popUp.style.bottom = -this.popUp.offsetHeight + "px";
            this.popUp.style.left = 0 + "px";
        } else if (config.position == "top-right") {
            let layoutAsset = document.getElementById("layout-toolbar");
            layoutAsset.append(this.popUp);
            // this.popUp.style.bottom = -this.popUp.offsetHeight + "px";
            this.popUp.style.top = 47 + "px";
            this.popUp.style.right = -3 + "px";
        } else {
            this.popUp.style.top = config.position.top + "px";
            this.popUp.style.left = config.position.left + "px";
        }
    }
    public GUI?(): void;

    public bindButton(btn:IButton){
        this.buton=btn;
        if(this.mode=="hide"||this.mode=="none"){
            let func=btn.enable;
            btn.enable=()=>{
                if(func)
                    func();
                this.show();
            }
            if(btn.isActive){
                this.show();
            }
        }
        let func2=btn.disable
        btn.disable=()=>{
            if(func2)
            func2();
            if(this.mode=="confirm"||this.mode=="destroy"){
                if(!this._destroy){
                    this.destroy();
                }
            }else{
                if(this._destroy){
                    this.hide();
                }
            }
        }
        this.closeActList.push(()=>{
            if(btn.isActive){
                btn.click();
            }
        })
        this.confirmActList.push(()=>{
            if(btn.isActive){
                btn.click();
            }
        })
    }
    public show() {
        if (this.popUp) {
            this.popUp.style.display = "block";
        }
        if (this.mask) {
            this.mask.style.display = "block";
        }
        this._destroy = false;
    }
    public closeActList = [];
    public confirmActList = [];
    public addEventListener(type: "close" | "confirm", func: () => void) {
        if (type == "close") this.closeActList.push(func);
        else this.confirmActList.push(func);
    }
    public hide() {
        if (this.buton) {
            if (this.buton.isActive) this.buton.click();
        }
        if (this.popUp) {
            this.popUp.style.display = "none";
        }
        if (this.mask) {
            this.mask.style.display = "none";
        }
        this._destroy = true;
    }
    private _destroy = false;
    public get isDestroy() {
        return this._destroy;
    }
    public destroy() {
        if (this.popUp) {
            this.popUp.remove();
        }
        if (this.mask) {
            this.mask.remove();
        }
        this.closeActList = [];
        this.confirmActList = [];
        this._destroy = true;
        this.buton = undefined;
    }
}

export class MessageBox extends Window {
    constructor(title: string, content: string) {
        super(title, { closeMode: "confirm", mask: true, contentWidth: "445px" });
        this.Message(content, "auto", "auto");
    }

    public createPromise() {
        this.closeActList = [];
        this.confirmActList = [];
        return new Promise<void>((resolve, reject) => {
            this.addEventListener("close", () => {
                reject();
            });
            this.addEventListener("confirm", () => {
                resolve();
            });
        });
    }
}

export class SmallMessage extends Window {
    constructor(message: string) {
        super("", { closeMode: "confirm", contentWidth: "170px" });
        this.Message(message, "auto", "auto");
    }

    public createPromise() {
        this.closeActList = [];
        this.confirmActList = [];
        return new Promise<void>((resolve, reject) => {
            this.addEventListener("close", () => {
                reject();
            });
            this.addEventListener("confirm", () => {
                resolve();
            });
        });
    }

    public updatePos(position: { left: number; top: number } | MouseEvent | BABYLON.IPointerEvent) {
        this.dealPos(position);
    }
}
export class PluginManager extends Window {
    private delPlugin: string[] = [];

    constructor() {
        super("插件管理", {
            closeMode: "confirm",
            position: "top-right",
            maxHeight: "450px"
        });
        let item = this.dealPre("添加插件");
        this.Button("获取插件", { width: "77px", height: "28px" }, item).onclick = () => {
            window.open( "https://store.veryengine.cn/#/?classify=功能插件");
        };
        for (let key in PluginPackage.Pool) {
            if (PluginPackage.Pool[key].isDepend == true || key == "system") continue;
            let toggle = this.Toggle(PluginPackage.Pool[key].name, true);
            toggle.onchange = (val) => {
                if (!val) {
                    this.delPlugin.push(key);
                } else {
                    let index = this.delPlugin.indexOf(key);
                    this.delPlugin.splice(index, 1);
                }
            };
        }
        this.addEventListener("confirm", () => {
            if (this.delPlugin.length != 0) {
                for (let key of this.delPlugin) {
                    if (PluginPackage.Pool[key]) {
                        PluginPackage.Pool[key].uninstall();
                    }
                    //todo 先卸载插件，手欠瞬间又点了加载插件的情况
                    if (VeryEngine.shareBox.id2Asset[key]) {
                        let delFunc = async (asset) => {
                            if (asset && !asset.isDestroy) {
                                if (asset.children)
                                    for (let child of [...asset.children]) {
                                        let childAsset = VeryEngine.shareBox.id2Asset[child];
                                        await delFunc(childAsset);
                                    }
                                let file = asset.get("file");
                                if (file && file.get("filename")) {
                                    await OSS.deleteJsonAsset(asset.id, file.get("filename"));
                                }
                                asset.destroy(false);
                            }
                        };
                        delFunc(VeryEngine.shareBox.id2Asset[key]);
                    }
                }
                OSS.InstallPlugin(PluginPackage.toJson());
            }
        });
    }

    public add(name: string, id: string) {
        let toggle = this.Toggle(name, true);
        toggle.onchange = (val) => {
            if (!val) {
                this.delPlugin.push(id);
            } else {
                let index = this.delPlugin.indexOf(id);
                this.delPlugin.splice(index, 1);
            }
        };
    }
}