import { IEDGUI } from "./IEDGUI";
import {addEntityClass,ATTRIB, IEDAttrib} from "../../engine/IEDProxy"
import { DataType} from "../../engine";
import { Tools } from "../../utility/Tools";

@addEntityClass
export class Checkbox extends IEDGUI{
    public get subtype(): string {
        return "checkbox";
    }

    private inboxDiv:HTMLElement;
    protected realLoad(is2D:boolean){
        if(is2D){
            this.sceneObj = document.createElement("div");
            let divStyle = this.sceneObj.style;
            this.sceneObj.style.pointerEvents = "auto";
            divStyle.position = "absolute";
            divStyle.overflow = "hidden";
            divStyle.position = "absolute";
            divStyle.display = "flex";
            divStyle.justifyContent = "center";
            divStyle.alignItems = "center";
            divStyle.borderStyle = "solid";
            divStyle.boxSizing = "border";
            this.inboxDiv = document.createElement("div");
            const inboxDivStyle = this.inboxDiv.style;
            inboxDivStyle.width = "80%";
            inboxDivStyle.height = "80%";
            this.inboxDiv.addEventListener("click", () => {
                let result = !this.get("gui.isChecked");
                this.set("gui.isChecked", result);
            });
            this.sceneObj.append(this.inboxDiv);
        }else{
            let checkbox = new BABYLON.GUI.Checkbox(this.name);
            this.sceneObj = checkbox;
            checkbox.isPointerBlocker = true;
        }
    }

    private title="复选框"
    @ATTRIB("gui.background")
    public background:IEDAttrib<DataType.Color4>={
        name:"背景色",
        type:DataType.Color4,
        onchange(this:Checkbox,val){
            if(this.is2D){
                (this.sceneObj as HTMLElement).style.background = Tools.rgba2hsvString(val);
                if(!this.get("gui.isChecked"))
                    this.inboxDiv.style.background=Tools.rgba2hsvString(val);
            }else{
                (this.sceneObj as BABYLON.GUI.Checkbox).background = Tools.rgba2hsvString(val);
            }
        },
        title:this.title
    }

    @ATTRIB("gui.color")
    public color:IEDAttrib<DataType.Color4>={
        name:"前景色",
        type:DataType.Color4,
        onchange(this:Checkbox,val){
            if(this.is2D){
                (this.sceneObj as HTMLElement).style.borderColor = Tools.rgba2hsvString(val);
                if(this.get("gui.isChecked"))
                    this.inboxDiv.style.background=Tools.rgba2hsvString(val);
            }else{
                (this.sceneObj as BABYLON.GUI.Checkbox).color = Tools.rgba2hsvString(val);
            }
        },
        default:[0.5,0.5,0.5,1],
        title:this.title
    }

    @ATTRIB("gui.isChecked")
    public isChecked:IEDAttrib<DataType.Bool>={
        name:"值",
        type:DataType.Bool,
        onchange(this:Checkbox,val,isFirst){
            if(!isFirst){
                if(this.is2D){
                    this.inboxDiv.style.background=Tools.rgba2hsvString(val?this.get("gui.color"):this.get("gui.background"));
                }else{
                    (this.sceneObj as BABYLON.GUI.Checkbox).isChecked = val;
                }
            }
        },
        default:true,
        title:this.title
    }

    @ATTRIB("gui.thickness")
    public thickness:IEDAttrib<DataType.Number>={
        name:"边框厚度",
        type:DataType.Number,
        onchange(this:Checkbox,val){
            if(this.is2D){
                (this.sceneObj as HTMLElement).style.borderWidth = val + "px";
            }else{
                (this.sceneObj as BABYLON.GUI.Checkbox).thickness= val
            }
        },
        default:1,
        title:this.title
    }
}