import { IEDMaterial } from "./IEDMaterial";
import { DataType, VeryEngine } from "../../engine";
import { Tools } from "../../utility/Tools";
import { DMap } from "../../djs/type";
import { ATTRIB, BUTTON, IEDAttrib, addAssetClass } from "../../engine/IEDProxy";

@addAssetClass
export abstract class IEDNodeMaterial extends IEDMaterial {

    public get subtype() {
        return "BABYLON.NodeMaterial"
    }

    public assetObj: BABYLON.NodeMaterial;

    public init(): void {
        this.dataId = this._data.get("materialId");
        if (this.dataId)
            IEDMaterial.matID2AssetID[this.dataId] = this.id
    }

    protected async Load() {
        try {
            let materialData = JSON.parse(await OSS.getJsonAsset(this.id, this.name, this.fileHash));
            materialData.id = this.id;
            materialData.name = this.name;
            let store = BABYLON.NodeMaterial.IgnoreTexturesAtLoadTime;
            BABYLON.NodeMaterial.IgnoreTexturesAtLoadTime = false;
            let tempMaterial = BABYLON.NodeMaterial.Parse(materialData, VeryEngine.scene);
            tempMaterial.build();
            BABYLON.NodeMaterial.IgnoreTexturesAtLoadTime = store;
            this.assetObj = tempMaterial;
        } catch (e) {
            this.assetObj = new BABYLON.NodeMaterial("");
            console.error(e);
        }
    }


    public async createUploadData(matData: any, folderId?: string) {
        let path = [];
        if (folderId != null) {
            if (!folderId) path = [];
            else path = [folderId];
        } else if (VeryEngine.commonJson.get("pickAssetFolder")) {
            path = [VeryEngine.commonJson.get("pickAssetFolder")]
        } else {
            path = []
        }
        let matID = matData.assetId ? matData.assetId : Tools.assetID();
        let createdAt = Tools.createdTime();
        let data = {
            id: matID,
            type: 'material',
            subtype: 'BABYLON.NodeMaterial',
            createdAt: createdAt,
            name: matData.name,
            file: matData.file,
            materialId: matData.materialId,
            path: path
        };
        VeryEngine.shareBox.assetMap.set(data.id, new DMap(data));
    }

    @ATTRIB("data.backFaceCulling")
    public backFaceCulling: IEDAttrib<DataType.Bool> = {
        name: "背面隐藏",
        type: DataType.Bool,
        onchange(this: IEDNodeMaterial, val: boolean, a) {
            if (!a) {
                this.assetObj.backFaceCulling = val;
                this.preview();
            }
        },
        default: true
    }

    @ATTRIB("data.needDepthPrePass")
    public needDepthPrePass: IEDAttrib<DataType.Bool> = {
        name: "深度值预先计算",
        type: DataType.Bool,
        onchange(this: IEDNodeMaterial, val: boolean, a) {
            if (!a) {
                this.assetObj.needDepthPrePass = val;
                this.preview();
            }
        },
        default: true
    }

    @ATTRIB("data.alpha")
    public alpha: IEDAttrib<DataType.Slide> = {
        name: "透明度",
        type: DataType.Slide,
        onchange(this: IEDNodeMaterial, val: number, a) {
            if (!a) {
                this.assetObj.alpha = val;
                this.preview();
            }
        },
        default: 1
    }

    @ATTRIB("data.transparencyMode")
    public transparencyMode: IEDAttrib<DataType.DropDown> = {
        name: "透明度模式",
        type: DataType.DropDown,
        onchange(this: IEDNodeMaterial, val: number) {
            this.assetObj.transparencyMode = val;
            this.preview();
        },
        default: -1,
        extra: ['NULL', 'OPAQUE', 'ALPHATEST', 'ALPHABLEND', 'ALPHATESTANDBLEND'],
    }

    @ATTRIB("data.alphaMode")
    public alphaMode: IEDAttrib<DataType.DropDown> = {
        name: "Alpha模式",
        type: DataType.DropDown,
        onchange(this: IEDNodeMaterial, val: number, a) {
            if (!a) {
                this.assetObj.alphaMode = val;
                this.preview();
            }
        },
        extra: ['DISABLE', 'ADD', 'COMBINE', 'SUBTRACT', 'MULTIPAY', 'MAXIMIZED', 'ONEONE', 'PREMULTIPAIED',
            'PREMULTIPAIED_PORTERDUFF', 'INTERPPOLATE', 'SCREENMODE'],
        default: 2
    }

    @ATTRIB("data.ignoreAlpha")
    public ignoreAlpha: IEDAttrib<DataType.Bool> = {
        name: "禁用透明效果",
        type: DataType.Bool,
        onchange(this: IEDNodeMaterial, val: boolean, a) {
            if (!a) {
                this.assetObj.ignoreAlpha = val;
                this.preview();
            }
        },
        default: false
    }


    protected other = "其他"
    @ATTRIB("data.sideOrientation")
    public sideOrientation: IEDAttrib<DataType.DropDown> = {
        name: "面朝向",
        type: DataType.DropDown,
        onchange(this: IEDNodeMaterial, val, a) {
            if (!a) {
                this.assetObj.sideOrientation = val
                this.preview();
            }
        },
        extra: ["顺时针", "逆时针"],
        title: this.other,
        default: 1
    }

    @ATTRIB("data.zOffset")
    public zOffset: IEDAttrib<DataType.Number> = {
        name: "zOffset",
        type: DataType.Number,
        onchange(this: IEDNodeMaterial, val, a) {
            if (!a) {
                this.assetObj.zOffset = val
                this.preview();
            }
        },
        title: this.other,
        default: 0
    }

    @ATTRIB("data.zOffsetUnits")
    public zOffsetUnits: IEDAttrib<DataType.Number> = {
        name: "zOffsetUnits",
        type: DataType.Number,
        onchange(this: IEDNodeMaterial, val, a) {
            if (!a) {
                this.assetObj.zOffsetUnits = val
                this.preview();
            }
        },
        title: this.other,
        default: 0
    }

    @ATTRIB("data.wireframe")
    public wireframe: IEDAttrib<DataType.Bool> = {
        name: "wireframe",
        type: DataType.Bool,
        onchange(this: IEDNodeMaterial, val, a) {
            if (!a) {
                this.assetObj.wireframe = val
                this.preview();
            }
        },
        title: this.other,
    }

    @ATTRIB("data.separateCullingPass")
    public separateCullingPass: IEDAttrib<DataType.Bool> = {
        name: "separateCullingPass",
        type: DataType.Bool,
        onchange(this: IEDNodeMaterial, val, a) {
            if (!a) {
                this.assetObj.separateCullingPass = val
                this.preview();
            }
        },
        title: this.other,
    }

    @ATTRIB("data.disableColorWrite")
    public disableColorWrite: IEDAttrib<DataType.Bool> = {
        name: "disableColorWrite",
        type: DataType.Bool,
        onchange(this: IEDNodeMaterial, val, a) {
            if (!a) {
                this.assetObj.disableColorWrite = val
                this.preview();
            }
        },
        title: this.other,
    }

    @ATTRIB("data.disableDepthWrite")
    public disableDepthWrite: IEDAttrib<DataType.Bool> = {
        name: "disableDepthWrite",
        type: DataType.Bool,
        onchange(this: IEDNodeMaterial, val, a) {
            if (!a) {
                this.assetObj.disableDepthWrite = val
                this.preview();
            }
        },
        title: this.other,
    }

    @ATTRIB("data.forceDepthWrite")
    public forceDepthWrite: IEDAttrib<DataType.Bool> = {
        name: "forceDepthWrite",
        type: DataType.Bool,
        onchange(this: IEDNodeMaterial, val, a) {
            if (!a) {
                this.assetObj.forceDepthWrite = val
                this.preview();
            }
        },
        title: this.other,
    }

    private clone:BABYLON.NodeMaterial;
    @BUTTON
    public ={
        name:"NodeMaterial编辑器",
        action(this:IEDNodeMaterial) {
            var config: BABYLON.INodeMaterialEditorOptions = {
                editorURL: './babylon/babylon.nodeEditor.js'
            };
            if(this.assetObj){
                this.clone=this.assetObj.clone(this.id);
                this.clone.edit(config);
            }
        },
        
    }

    public async update(data:any){
        await OSS.uploadJsonAsset(JSON.stringify(data),this.id,this.name,true);
        let store = BABYLON.NodeMaterial.IgnoreTexturesAtLoadTime;
        BABYLON.NodeMaterial.IgnoreTexturesAtLoadTime = false;
        this.assetObj.loadFromSerialization(data);
        this.assetObj.build();
        BABYLON.NodeMaterial.IgnoreTexturesAtLoadTime = store;
        if(this.clone){
            this.clone.dispose();
        }
        this.preview();
    }
}