export class Tools {
    public static eulerAngleToRadian(val: BABYLON.Vector3): BABYLON.Vector3 {
        let para: number = Math.PI / 180;
        return val.multiplyByFloats(para, para, para);
    }

    public static radianToEulerAngle(val: BABYLON.Vector3): BABYLON.Vector3 {
        let para: number = 180 / Math.PI;
        return val.multiplyByFloats(para, para, para);
    }

    public static eulerAngleFloatToRadian(euler_angle: number): number {
        return euler_angle * Math.PI / 180;
    }

    public static radianFloatToEulerAngle(radian: number): number {
        return radian * 180 / Math.PI;
    }

    public static vector3ToArray(val: BABYLON.Vector3): number[] {
        return [val.x, val.y, val.z];
    }

    public static quatTransfromVector3(quat: BABYLON.Quaternion, vec3: BABYLON.Vector3): BABYLON.Vector3 {
        let res = BABYLON.Vector3.Zero();

        var x = vec3.x, y = vec3.y, z = vec3.z;
        var qx = quat.x, qy = quat.y, qz = quat.z, qw = quat.w;

        // calculate quat * vec
        var ix = qw * x + qy * z - qz * y;
        var iy = qw * y + qz * x - qx * z;
        var iz = qw * z + qx * y - qy * x;
        var iw = -qx * x - qy * y - qz * z;

        // calculate result * inverse quat
        res.x = ix * qw + iw * -qx + iy * -qz - iz * -qy;
        res.y = iy * qw + iw * -qy + iz * -qx - ix * -qz;
        res.z = iz * qw + iw * -qz + ix * -qy - iy * -qx;

        return res;
    }

    public static quatMultiplyVector3(rotation: BABYLON.Quaternion, point: BABYLON.Vector3): BABYLON.Vector3 {
        let num = rotation.x * 2;
        let num2 = rotation.y * 2;
        let num3 = rotation.z * 2;
        let num4 = rotation.x * num;
        let num5 = rotation.y * num2;
        let num6 = rotation.z * num3;
        let num7 = rotation.x * num2;
        let num8 = rotation.x * num3;
        let num9 = rotation.y * num3;
        let num10 = rotation.w * num;
        let num11 = rotation.w * num2;
        let num12 = rotation.w * num3;
        let result: BABYLON.Vector3 = BABYLON.Vector3.Zero();
        result.x = (1 - (num5 + num6)) * point.x + (num7 - num12) * point.y + (num8 + num11) * point.z;
        result.y = (num7 + num12) * point.x + (1 - (num4 + num6)) * point.y + (num9 - num10) * point.z;
        result.z = (num8 - num11) * point.x + (num9 + num10) * point.y + (1 - (num4 + num5)) * point.z;
        return result;
    }

    public static clamp(value: number, min: number, max: number): number {
        return Math.max(min, Math.min(max, value));
    }

    public static quaternionToRadian(q: BABYLON.Quaternion, order: string = 'YZX'): BABYLON.Vector3 {
        let vec3 = new BABYLON.Vector3(0, 0, 0);

        var position = new BABYLON.Vector3(0, 0, 0);
        var scale = new BABYLON.Vector3(1, 1, 1);
        let te: Array<number> = new Array<number>(16);
        var x = q.x, y = q.y, z = q.z, w = q.w;
        var x2 = x + x, y2 = y + y, z2 = z + z;
        var xx = x * x2, xy = x * y2, xz = x * z2;
        var yy = y * y2, yz = y * z2, zz = z * z2;
        var wx = w * x2, wy = w * y2, wz = w * z2;
        var sx = scale.x, sy = scale.y, sz = scale.z;
        te[0] = (1 - (yy + zz)) * sx;
        te[1] = (xy + wz) * sx;
        te[2] = (xz - wy) * sx;
        te[3] = 0;

        te[4] = (xy - wz) * sy;
        te[5] = (1 - (xx + zz)) * sy;
        te[6] = (yz + wx) * sy;
        te[7] = 0;

        te[8] = (xz + wy) * sz;
        te[9] = (yz - wx) * sz;
        te[10] = (1 - (xx + yy)) * sz;
        te[11] = 0;

        te[12] = position.x;
        te[13] = position.y;
        te[14] = position.z;
        te[15] = 1;

        var m11 = te[0], m12 = te[4], m13 = te[8];
        var m21 = te[1], m22 = te[5], m23 = te[9];
        var m31 = te[2], m32 = te[6], m33 = te[10];

        if (order === 'XYZ') {
            vec3.y = Math.asin(Tools.clamp(m13, - 1, 1));
            if (Math.abs(m13) < 0.99999) {
                vec3.x = Math.atan2(- m23, m33);
                vec3.z = Math.atan2(- m12, m11);
            } else {
                vec3.x = Math.atan2(m32, m22);
                vec3.z = 0;
            }
        } else if (order === 'YXZ') {
            vec3.x = Math.asin(- Tools.clamp(m23, - 1, 1));
            if (Math.abs(m23) < 0.99999) {
                vec3.y = Math.atan2(m13, m33);
                vec3.z = Math.atan2(m21, m22);
            } else {
                vec3.y = Math.atan2(- m31, m11);
                vec3.z = 0;
            }
        } else if (order === 'ZXY') {
            vec3.x = Math.asin(Tools.clamp(m32, - 1, 1));
            if (Math.abs(m32) < 0.99999) {
                vec3.y = Math.atan2(- m31, m33);
                vec3.z = Math.atan2(- m12, m22);
            } else {
                vec3.y = 0;
                vec3.z = Math.atan2(m21, m11);
            }
        } else if (order === 'ZYX') {
            vec3.y = Math.asin(- Tools.clamp(m31, - 1, 1));
            if (Math.abs(m31) < 0.99999) {
                vec3.x = Math.atan2(m32, m33);
                vec3.z = Math.atan2(m21, m11);
            } else {
                vec3.x = 0;
                vec3.z = Math.atan2(- m12, m22);
            }
        } else if (order === 'YZX') {
            vec3.z = Math.asin(Tools.clamp(m21, - 1, 1));
            if (Math.abs(m21) < 0.99999) {
                vec3.x = Math.atan2(- m23, m22);
                vec3.y = Math.atan2(- m31, m11);
            } else {
                vec3.x = 0;
                vec3.y = Math.atan2(m13, m33);
            }
        } else if (order === 'XZY') {
            vec3.z = Math.asin(- Tools.clamp(m12, - 1, 1));
            if (Math.abs(m12) < 0.99999) {
                vec3.x = Math.atan2(m32, m22);
                vec3.y = Math.atan2(m13, m11);
            } else {
                vec3.x = Math.atan2(- m23, m33);
                vec3.y = 0;
            }
        } else {
            console.warn('QuaternionToRadian类型错误: ' + order);
        }
        return vec3;
    }

    public static quaternionToEulerAngle(q: BABYLON.Quaternion, order: string = 'YZX'): BABYLON.Vector3 {
        return Tools.radianToEulerAngle(Tools.quaternionToRadian(q, order));
    }


    public static clampAngle(angle: number, min: number, max: number): number {
        if (angle < -360)
            angle += 360;
        if (angle > 360)
            angle -= 360;
        if (angle < min) {
            angle = min;
        } else if (angle > max) {
            angle = max;
        }
        return angle;
    }

    private static _specialExtension: string[] = ['tif', 'tiff', 'tga', 'dds', 'hdr', 'exr', 'env', 'targa', 'psd'];
    
    public static textureUrlFormat(url: string): string {
        for (let i = 0, length = Tools._specialExtension.length; i < length; i++) {
            let index = url.indexOf(Tools._specialExtension[i]);
            if (index >= 0) {
                return url.substring(0, index + Tools._specialExtension[i].length);
            }
        }
        return url;
    }

    public static worldToScreenPoint(world_point: BABYLON.Vector3, scene: BABYLON.Scene, camera: BABYLON.TargetCamera, engine: BABYLON.Engine): BABYLON.Vector3 {
        return BABYLON.Vector3.Project(
            world_point,
            BABYLON.Matrix.Identity(),
            scene.getTransformMatrix(),
            camera.viewport.toGlobal(
                engine.getRenderWidth(),
                engine.getRenderHeight(),
            ),
        );
    }

    public static transformLocalToWorldDirection(node: BABYLON.Node, local_direction: BABYLON.Vector3): BABYLON.Vector3 {
        if (node) {
            let matrix: BABYLON.Matrix = node.computeWorldMatrix();
            return BABYLON.Vector3.TransformCoordinates(local_direction, matrix).subtract((node as any).getAbsolutePosition());
        } else {
            return local_direction;
        }
    }

    public static getmd5=async(file:File)=>{
        return new Promise<string>(async (resolve, reject) => {
            var blobSlice = File.prototype.slice ;
            var chunkSize = 2097152, // 每次读取2MB
            chunks = Math.ceil(file.size / chunkSize),
            currentChunk = 0,
            spark = new SparkMD5.ArrayBuffer(),
            frOnload = function(e:any){
                spark.append(e.target.result);
                currentChunk++;
                if (currentChunk < chunks)
                    loadNext();
                else{
                    resolve(spark.end());
                }
            },
            frOnerror = function () {
                reject("error");
            };
            function loadNext() {
                var fileReader = new FileReader();
                fileReader.onload = frOnload;
                fileReader.onerror = frOnerror;
                var start = currentChunk * chunkSize,
                    end = ((start + chunkSize) >= file.size) ? file.size : start + chunkSize;
                fileReader.readAsArrayBuffer(blobSlice.call(file, start, end));
            };
            loadNext();
        })
    }

    public static uuid(): string {
        return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function (c: string) {
          let r = Math.random() * 16 | 0,
            v = (c === 'x') ? r : (r & 0x3 | 0x8);
          return v.toString(16);
        });
    }

    public static assetID = () => {
        return (
            Math.round(new Date().getTime() / 1000).toString() +
            "-" +
            this.uuid().substring(0, 8)
        );
    }

    public static createdTime() {
        var now = new Date();
        var Y = now.getFullYear();
        var m = this.getRealTime(now.getMonth() + 1);
        var d = this.getRealTime(now.getDate());
        var H = this.getRealTime(now.getHours());
        var i = this.getRealTime(now.getMinutes());
        // var s = getRealTime(now.getSeconds());
        return Y + "-" + m + "-" + d + " " + H + ":" + i;
    }

    private static getRealTime(str:number) {
        if (str < 10) {
            return "0" + str;
        }
        return str;
    }

    public static rgba2hsvString(rgba: number[]): string {
        rgba = Tools.to255rgba(rgba);
        let colorStr = '#';
        for (let i = 0, len = rgba.length; i < len; i++) {
            let hex = ('0' + rgba[i].toString(16)).slice(-2);
            colorStr += hex;
        }
        return colorStr;
    }

    public static string2Rgba(color:string):number[]{
        const reg =
            /^#([0-9a-fA-f]{6}|[0-9a-fA-f]{8})$/;
        if (!reg.test(color)) {
            return [1,1,1,1]
        }
        const r =parseInt(color.substr(1, 2), 16) / 255;
        const g =parseInt(color.substr(3, 2), 16) / 255;
        const b =parseInt(color.substr(5, 2), 16) / 255;
        let a=parseInt(color.substr(7, 2), 16) /255;           
        return [r,g,b,a];
    }

    public static to255rgba(rgba: number[]): number[] {
        let rgba255: number[] = [];
        rgba.forEach((element: number) => {
            rgba255.push(Math.floor(element * 255));
        });
        return rgba255;
    }

    public static showTipMessage(nameSpan:HTMLElement,tip:string,des?:string){
        nameSpan.addEventListener("mouseenter", (e) => {
            e.preventDefault();
            const pos = nameSpan.getBoundingClientRect();
            if((!tip||nameSpan.offsetWidth==nameSpan.scrollWidth)&&!des) return;
            let hoverMessage = document.createElement("div");
            hoverMessage.classList.add("setting-item-message");
            if (tip&&nameSpan.offsetWidth<nameSpan.scrollWidth) {
                let titileDiv = document.createElement("div");
                titileDiv.classList.add("setting-item-message-title");
                titileDiv.innerHTML = tip;
                hoverMessage.append(titileDiv);
            }
            if (des) {
                let desDiv = document.createElement("div");
                desDiv.classList.add("setting-item-message-des");
                desDiv.innerHTML = des;
                hoverMessage.append(desDiv);
            }
            // 84为hoverMessage css属性设置的width的一半，用于位置居中，+5则是手动指定的数字，用于气泡三角形与第一个文字正中间对齐

            if (pos.bottom + 100 > window.innerHeight) {
                hoverMessage.style.bottom =
                    window.innerHeight - pos.top + 6 + "px";
                hoverMessage.classList.add(
                    "setting-item-message-top"
                );
            } else {
                hoverMessage.style.top = pos.bottom + 8 + "px";
            }
            document.body.append(hoverMessage);
            hoverMessage.style.left = pos.left + nameSpan.clientWidth/2-hoverMessage.offsetWidth/2 + "px";
            nameSpan.onmouseleave = () => {
                hoverMessage.remove();
            };
        });
    }

    public static customPrototype(){
        BABYLON.Vector3.prototype.asArraytoFixed = function (this: BABYLON.Vector3) {
            return [
                Math.round(this.x * 1000000) / 1000000,
                Math.round(this.y * 1000000) / 1000000,
                Math.round(this.z * 1000000) / 1000000,
            ];
        };
        let hideActList:Function[]=[];
        let allClickHtml:HTMLElement[]=[];
        let hide=()=>{
            for(let i=0;i<hideActList.length;i++){
                let parent=allClickHtml[i].parentElement;
                let pass=false;
                while(parent){
                    if(parent.nodeName==="BODY"){
                        pass=true;
                        break;
                    }
                    parent=parent.parentElement;
                }
                if(!pass){
                    allClickHtml.splice(i,1);
                    hideActList.splice(i,1);
                    i--;
                }else{
                    if(allClickHtml[i].show){
                        allClickHtml[i].show=false;
                        hideActList[i]();
                    }
                }
            }
        }
        HTMLElement.prototype.clickWithHide=function(this: HTMLElement,showAct:Function,hideAct:Function){
            hideActList.push(hideAct);
            allClickHtml.push(this);
            hideAct();
            this.onclick=(ev)=>{
                if(this.show){
                    this.show=false;
                    hideAct();
                }else{
                    hide();
                    this.show=true;
                    showAct();
                }
                ev.stopPropagation();
            }
        }
        setTimeout(() => {
            document.body.addEventListener("click", () => {
                hide();
            });
        },500);
        MouseEvent.prototype.customPropagation=function(){
            this.isStop=true;
        }
        if(window.TouchEvent)
        TouchEvent.prototype.customPropagation=function(){
            this.isStop=true;
        }
        if(window.KeyboardEvent)
        KeyboardEvent.prototype.customPropagation=function(){
            this.isStop=true;
        }
    }

    public static AssetStoreExtend(){
        if(VeryEngine.EditMode){
            (()=>{
                let storeImport=async function(folderId:string,folderName:string,fileStructure:FileStructure,isPlugin:boolean){
                    let data:any = {
                        id: folderId,
                        type: "folder",
                        createdAt: Tools.createdTime(),
                        name: folderName,
                        path:['root']
                    };
                    if(isPlugin) data.hide=true;
                    VeryEngine.shareBox.assetMap.set(data.id, new DMap(data));
                    Tools.UploadFile(fileStructure,folderId);
                };
                let pluginWindow:PluginManager;
                window.addEventListener("load",function(){
                    let tmp=document.getElementById("shezhi");
                    if(tmp){
                        Tools.showTipMessage(tmp,null,"插件管理")
                        tmp.onclick=()=>{
                            if(!pluginWindow||pluginWindow.isDestroy){
                                tmp.classList.add("active");
                                pluginWindow=new PluginManager();
                                pluginWindow.addEventListener("close",()=>{
                                    tmp.classList.remove("active");
                                })
                                pluginWindow.addEventListener("confirm",()=>{
                                    tmp.classList.remove("active");
                                })
                            }else{
                                pluginWindow.destroy();
                                tmp.classList.remove("active");
                            }
                        }
                    }
                });
                let status=false;
                let storePlugin=async function(productName:string,typeId:string,productId:string,file:{fileUrl:string,fileList:string[]},unit:any){
                    let isPlugin=(typeId=="3a4792177f5f4dd7bdf36c8795e28dca"||typeId=="ee987279c52c424092fbfdef7760a395");
                    if(VeryEngine.shareBox.id2Asset[productId]){
                        if(!isPlugin){
                            Message.showAlert({text:"当前资源已导入过工程，请先删除原有工程再进行导入操作",type:"error",closeable:true});
                            return;
                        }else{
                            let delFunc = async (asset) => {
                                if (asset&&!asset.isDestroy) {
                                    if (asset.children)
                                    for (let child of [...asset.children]) {
                                            let childAsset = VeryEngine.shareBox.id2Asset[child];
                                        await delFunc(childAsset);
                                    }
                                    asset.clearData(false)
                                }
                            };
                            delFunc(VeryEngine.shareBox.id2Asset[productId]);
                        }
                    }
                    if(!status){
                        status=true;
                    }else{
                        Message.showAlert({text:"当前正在加载资源库内容，请稍后再试",type:"error",closeable:true});
                        return;
                    }
                    try{
                        let result=false;
                        let fileStructure:FileStructure={files:[]};
                        let pluginList=[];
                        let preStr="https://assetstore.oss-cn-hangzhou.aliyuncs.com/product_file/";
                        if(file.fileList&&file.fileList.length!=0){
                            if(!file.fileUrl.endsWith("/")){
                                file.fileUrl=file.fileUrl+"/"
                            }
                        }else{
                           file.fileList=[""];
                        }
                        for(let tmp of file.fileList){
                            let one=await OSS.getFile(file.fileUrl+tmp);
                            if(one){
                                if(isPlugin&&one.name.endsWith(".js")){
                                    let conent=await new Promise<string>((resolve)=>{
                                        let reader = new FileReader()
                                        reader.readAsText(one)
                                        reader.onload = () => {
                                            resolve(reader.result as string)
                                        }
                                    })
                                    if(conent.includes("VREdit.installPlugin")){
                                        let pluginId=file.fileUrl+tmp;
                                        pluginList.push(pluginId.substring(preStr.length,pluginId.length-3));
                                        continue;
                                    }
                                }
                                result=true;
                                if(unit!=null)
                                one["unit"]=unit
                                let split=tmp.split('/');
                                let current=fileStructure;
                                for(let i=0;i<split.length-1;i++){
                                    if(split[i]){
                                        if(!current[split[i]]){
                                            current[split[i]]={files:[]};
                                        }
                                        current=current[split[i]];
                                    }
                                }
                                current.files.push(one);
                            }
                        }
                        if(pluginList.length!=0){
                            let pack=PluginPackage.createPackage(productId,pluginList,undefined,productName);
                            if(pack){
                                if(pluginWindow&&!pluginWindow.isDestroy)
                                    pluginWindow.add(productName,productId);
                                OSS.InstallPlugin(PluginPackage.toJson());
                                if(result)
                                await storeImport(productId,productName,fileStructure,true);
                            }
                        }else{
                            if(result)
                            await storeImport(productId,productName,fileStructure,false);
                        }
                    }
                    catch(e){
                        console.error(e);
                    }
                    finally{
                        status=false;
                        if(VeryEngine.StoreWindow&&!VeryEngine.StoreWindow.closed)
                        VeryEngine.StoreWindow.postMessage({name:"doneTitle"},"*")
                    }
            
                }
                window.addEventListener("message",function(event) {
                    if (event.origin.includes("veryengine.cn")){
                        let data=event.data;
                        if(data&&data.name=="storePlugin"){
                            storePlugin(data.params[0],data.params[1],data.params[2],data.params[3],data.params[4])
                        }
                    }
                })
            })()
        }
    }

    public static async UploadFile(fileStructure:FileStructure,folderId:string){
        if(fileStructure.files.length!=0){
            let fileList: {file: File;func: Function;priority: number;}[] = [];
            let files=fileStructure.files;
            for (let i = 0; i < files.length; i++) {
                let nameSplit = files[i].name.split(".");
                let suffix = nameSplit[nameSplit.length - 1];
                let uploadInfo=IEDProxyFactory.getUploadFunc(suffix);
                if(uploadInfo){
                    let uploadPriority=uploadInfo[0];
                    let uploadFunc=uploadInfo[1];
                    let last = true;
                    for (let k = 0; k < fileList.length; k++) {
                        if (fileList[k].priority > uploadPriority) {
                            fileList.splice(k, 0, {
                                file: files[i],
                                func:  uploadFunc,
                                priority:  uploadPriority,
                            });
                            last = false;
                            break;
                        }
                    }
                    if (last)
                        fileList.push({
                            file: files[i],
                            func:  uploadFunc,
                            priority:  uploadPriority,
                        });
                }else{
                    fileList.push({file: files[i],func:async(file,folderId?:string)=>{
                        await IEDData.prototype.createUploadData(file,folderId);
                    },priority:10})
                }
            }
            for (let file of fileList) {
                await file.func(file.file, folderId);
            }
        }
        for(let key in fileStructure){
            if(key!=="files"){
                let newId=Tools.assetID();
                let data:any = {
                    id: newId,
                    type: "folder",
                    createdAt: Tools.createdTime(),
                    name: key,
                    path:[folderId]
                };
                if(key=="hidden") data.hide=true;
                VeryEngine.shareBox.assetMap.set(data.id, new DMap(data));
                this.UploadFile(fileStructure[key],newId);
            }
        }
    }
}
export type FileStructure={files:File[]}&{[propName: string]: any};