import { IEDTransform } from "../IEDTransform";
import { ParticleTools } from "./ParticleTools";
import { VeryEngine,DataType} from "../../engine";
import { ATTRIB, IEDAttrib, addEntityClass } from "../../engine/IEDProxy";
import { VeryParticleSystem } from "../../middleware/VeryParticle";


@addEntityClass
export class Snow extends IEDTransform{
    public get type(): string {
        return "particle";
    }
    public get subtype(){
        return "snow_zzl_code"
    }
    protected dispose(): void {
        this.sceneObj.dispose();
    }
    public sceneObj: VeryParticleSystem
    async Load() {
        this.sceneObj = ParticleTools.createParticleSystemWraper_Snow(
            this.subtype,
            this.name,
            VeryEngine.scene
        );
    }
    private title="雪"
    @ATTRIB()
    public updateSpeed:IEDAttrib<DataType.Slide>={
        name:"雪大小",
        type:DataType.Slide,
        async onchange(this:Snow,updateSpeedValue){
            let radiusValue=this.get("radius");
            var instance = this.sceneObj['particle'];
            var subParticle = VeryParticleSystem._subParticle[instance.name];
            instance.updateSpeed = updateSpeedValue;
            instance.minEmitBox = new BABYLON.Vector3(-1 * radiusValue,100,-1 * radiusValue);
            instance.maxEmitBox = new BABYLON.Vector3(radiusValue,110,radiusValue);
            instance.emitRate =
            (1500 + (1500 * (instance.updateSpeed - 0.001)) / 0.003) *
            (Math.abs(instance.minEmitBox.x) / 50) *(Math.abs(instance.minEmitBox.x) / 50);
            if (subParticle) {
                subParticle.updateSpeed = updateSpeedValue;
                subParticle.minEmitBox = new BABYLON.Vector3(-1*radiusValue,0,-1 * radiusValue);
                subParticle.maxEmitBox = new BABYLON.Vector3(radiusValue,0,radiusValue);
                subParticle.emitRate =
                    (1500 +(1500 * (subParticle.updateSpeed - 0.001)) / 0.003) *
                    (Math.abs(subParticle.minEmitBox.x) / 50) *
                    (Math.abs(subParticle.minEmitBox.x) / 50);
            }
        },
        default:0.001,
        extra:{min:0.001,max:0.004},
        title:this.title
    }

    @ATTRIB()
    public radius:IEDAttrib<DataType.Slide>={
        name:"雪范围",
        type:DataType.Slide,
        onchange(this:Snow,radiusValue,isFirst){
            if(!isFirst){
                let updateSpeedValue=this.get("updateSpeed")
                var instance = this.sceneObj['particle'];
                var subParticle = VeryParticleSystem._subParticle[instance.name];
                instance.updateSpeed = updateSpeedValue;
                instance.minEmitBox = new BABYLON.Vector3(-1 * radiusValue,100,-1 * radiusValue);
                instance.maxEmitBox = new BABYLON.Vector3(radiusValue,110,radiusValue);
                instance.emitRate =
                (1500 + (1500 * (instance.updateSpeed - 0.001)) / 0.003) *
                (Math.abs(instance.minEmitBox.x) / 50) *(Math.abs(instance.minEmitBox.x) / 50);
                if (subParticle) {
                    subParticle.updateSpeed = updateSpeedValue;
                    subParticle.minEmitBox = new BABYLON.Vector3(-1*radiusValue,0,-1 * radiusValue);
                    subParticle.maxEmitBox = new BABYLON.Vector3(radiusValue,0,radiusValue);
                    subParticle.emitRate =
                        (1500 +(1500 * (subParticle.updateSpeed - 0.001)) / 0.003) *
                        (Math.abs(subParticle.minEmitBox.x) / 50) *
                        (Math.abs(subParticle.minEmitBox.x) / 50);
                }
            }
        },
        default:50,
        extra:{max:100,min:50},
        title:this.title
    }
}