import { addEntityClass, ATTRIB, IEDAttrib, IEDProxyFactory } from "../../engine/IEDProxy";
import { VeryEngine, DataType, IED } from "../../engine";
import { IEDEntity } from "../IEDEntity";
import { IEDKrpano } from "./IEDKrpano";
import { Tools } from "../../utility/Tools";
import { IEDFolder } from "src/assets";
import KrpanoToolJS from "../../utility/krpanoTool.js";

@addEntityClass
export abstract class KrpanoText extends IEDKrpano {
    public get subtype(): string {
        return "krpanoText";
    }

    protected async realLoad() {
        this.sceneObj = document.createElement("div");
        this.sceneObj.style.pointerEvents = "auto";
       
        let text = this.get("gui.text");
        let ath = this.get("gui.ath");
        let atv = this.get("gui.atv");
        let rx = this.get("gui.rx");
        let ry = this.get("gui.ry");
        let rz = this.get("gui.rz");
        let ox = this.get("gui.ox");
        let oy = this.get("gui.oy");
        let fontSize = this.get("gui.fontSize");
        this.krpano.call(`vreditor_add_text_hotspot(${this.id},${text},${ath},${atv},${rx},${ry},${rz},${ox},${oy},${fontSize})`);
    }

    public filterParentType(parent: IEDKrpano): boolean {
        if (["category"].includes(parent.subtype)) {
            return true;
        } else {
            return false;
        }
    }

    protected async Load(): Promise<void> {
        //@ts-ignore
        window.krpanoTextPositionChange = (ath, atv, id) => {
            if (id === this.id) {
                VeryEngine.pickEntities([id]);
                this.set("gui.atv", atv);
                this.set("gui.ath", ath);
            }
        };
    }
    private title = "按钮";

    @ATTRIB("gui.text")
    public text: IEDAttrib<DataType.String> = {
        name: "文字",
        type: DataType.String,
        async onchange(this: KrpanoText, val, isFirst) {
            if (isFirst) {
                return;
            }
           
            let ath = this.krpano.get("view.hlookat");
            let atv = this. krpano.get("view.vlookat");
            let rx = this.get("gui.rx");
            let ry = this.get("gui.ry");
            let rz = this.get("gui.rz");
            let ox = this.get("gui.ox");
            let oy = this.get("gui.oy");
            let fontSize = this.get("gui.fontSize");
            this.krpano.call(`vreditor_add_text_hotspot(${this.id},${val},${ath},${atv},${rx},${ry},${rz},${ox},${oy},${fontSize})`);
        },
        title: this.title,
    };

    @ATTRIB("gui.ath")
    public ath: IEDAttrib<DataType.Number> = {
        name: "水平方向角度",
        type: DataType.Number,
        async onchange(this: KrpanoText, val, isFirst) {
            if (!isFirst) this.setHotspotProp(this.id, "ath", val);
        },
        default: 0,
        title: this.title,
    };
    @ATTRIB("gui.atv")
    public atv: IEDAttrib<DataType.Number> = {
        name: "垂直方向角度",
        type: DataType.Number,
        async onchange(this: KrpanoText, val, isFirst) {
            if (!isFirst) this.setHotspotProp(this.id, "atv", val);
        },
        default: 0,
        title: this.title,
    };
    @ATTRIB("gui.rx")
    public rx: IEDAttrib<DataType.Number> = {
        name: "自旋X角度",
        type: DataType.Number,
        async onchange(this: KrpanoText, val, isFirst) {
            if (!isFirst) this.setHotspotProp(this.id, "rx", val);
        },
        default: 0,
        title: this.title,
    };
    @ATTRIB("gui.ry")
    public ry: IEDAttrib<DataType.Number> = {
        name: "自旋Y角度",
        type: DataType.Number,
        async onchange(this: KrpanoText, val, isFirst) {
            if (!isFirst) this.setHotspotProp(this.id, "ry", val);
        },
        default: 0,
        title: this.title,
    };
    @ATTRIB("gui.rz")
    public rz: IEDAttrib<DataType.Number> = {
        name: "自旋Z角度",
        type: DataType.Number,
        async onchange(this: KrpanoText, val, isFirst) {
            if (!isFirst) this.setHotspotProp(this.id, "rz", val);
        },
        default: 0,
        title: this.title,
    };
    @ATTRIB("gui.ox")
    public ox: IEDAttrib<DataType.Number> = {
        name: "相对X坐标",
        type: DataType.Number,
        async onchange(this: KrpanoText, val, isFirst) {
            if (!isFirst) this.setHotspotProp(this.id, "ox", val);
        },
        default: 0,
        title: this.title,
    };
    @ATTRIB("gui.oy")
    public oy: IEDAttrib<DataType.Number> = {
        name: "相对Y坐标",
        type: DataType.Number,
        async onchange(this: KrpanoText, val, isFirst) {
            if (!isFirst) this.setHotspotProp(this.id, "oy", val);
        },
        default: 0,
        title: this.title,
    };
    @ATTRIB("gui.fontSize")
    public fontSize: IEDAttrib<DataType.Number> = {
        name: "字体大小",
        type: DataType.Number,
        async onchange(this: KrpanoText, val, isFirst) {
            if (!isFirst) this.setHotspotProp(this.id, "css", `'text-align:left; color:#FFFFFF; font-family:MicrosoftYahei; font-size:${val}px;`);
        },
        default: 0,
        title: this.title,
    };
    
}
