import {  IEDAsset} from ".";
import {IEDMaterial} from "./Material";
import { VeryEngine,DataType } from "../engine";
import { Tools } from "../utility/Tools";
import { DMap } from "../djs/type";
import { IEDJson } from "./IEDJson";
import { VersionTool } from "../utility/VersionTool";
import { IEDProxyFactory, addAssetClass } from "../engine/IEDProxy";

@addAssetClass
export class IEDModel extends IEDAsset{

    public get type(): string {
        return "model"
    }

    public assetObj: any;

    public async doubleClick() {
        this.loadToScene();
    }

    protected async Load(){
        let babylonModel=JSON.parse(await OSS.getJsonAsset(this.id,this.fileName,this.fileHash))
        this.assetObj =this.parseBabylon(babylonModel);
        if(!this.assetObj){
            console.error(this.id+"-"+this.name+ ",该模型下载错误，请删除后重新上传");
        }
    }

    public get suffix(): string[] {
        return ["babylon"]
    }
    

    public async createUploadData(file: any,folderId?:string){
        // let data=await this.upload(file,folderId);
        var hash = await  Tools.getmd5(file);
        var assetID = Tools.assetID();
        var createdAt = Tools.createdTime();
        let path=[];
        if(folderId!=null){
            if(!folderId) path=[];
            else path=[folderId];
        }else if(VeryEngine.commonJson.get("pickAssetFolder")){
            path=[VeryEngine.commonJson.get("pickAssetFolder")]
        }else{
            path=[]
        }
        var babylonFile;
        let data:any={
            id: assetID,
            type: this.type,
            createdAt: createdAt,
            name: file.name,
            file: {
                filename: file.name,
                size: file.size,
                hash: hash,
            },
            path: path
        };
        babylonFile = await new Promise<string>((resolve, reject) => {
            var reader = new FileReader();
            reader.readAsText(file, 'utf-8');
            reader.onload = function (e) {
                resolve(reader.result!.toString());
            };
            reader.onerror = function (err) {
                reject(err);
            }
        });
        babylonFile = JSON.parse(babylonFile);
        if(file.unit){
            let unitNumber={m:1,dm:0.1,cm:0.01,mm:0.001};
            let unit=unitNumber[file.unit];
            if(unit!=null&&unit!=1){
                if(babylonFile.meshes)
                for(let mesh of babylonFile.meshes){
                    if(mesh.positions)
                    for(let i=0;i<mesh.positions.length;i++){
                        mesh.positions[i]=mesh.positions[i]*unit;
                    }
                    if(mesh.position)
                    for(let i=0;i<mesh.position.length;i++){
                        mesh.position[i]=mesh.position[i]*unit;
                    }
                }
                if(babylonFile.transformNodes)
                for(let mesh of babylonFile.transformNodes){
                    if(mesh.positions)
                    for(let i=0;i<mesh.positions.length;i++){
                        mesh.positions[i]=mesh.positions[i]*unit;
                    }
                    if(mesh.position)
                    for(let i=0;i<mesh.position.length;i++){
                        mesh.position[i]=mesh.position[i]*unit;
                    }
                }
                if (babylonFile.geometries && babylonFile.geometries.vertexData){
                    for(let vertexData of babylonFile.geometries.vertexData){
                        if(vertexData.positions){
                            for(let i=0;i<vertexData.positions.length;i++){
                                vertexData.positions[i]=vertexData.positions[i]*unit;
                            }
                        }
                    }
                }
            }
        }
        //后面有异步操作，需要上传完主asset就决定好path
        folderId=path.length>0?path[path.length-1]:"";
        if(!babylonFile.vr)
        babylonFile.vr=[];

        if( babylonFile.vrGUI){
            for(let vr of  babylonFile.vrGUI){
                VersionTool.gui(vr);
            }
            babylonFile.vr.push(...babylonFile.vrGUI);
            delete babylonFile.vrGUI
        }
        if(babylonFile.vrCamera){
            for(let vr of babylonFile.vrCamera){
                VersionTool.camera(vr);
            }
            babylonFile.vr.push(...babylonFile.vrCamera)
            delete babylonFile.vrCamera
        }
        if(babylonFile.vrLight){
            for(let vr of babylonFile.vrLight){
                VersionTool.light(vr);
            }
            babylonFile.vr.push(...babylonFile.vrLight)
            delete babylonFile.vrLight;
        }
        if(babylonFile.vrEffects){
            for(let vr of babylonFile.vrEffects){
                VersionTool.particle(vr);
            }
            babylonFile.vr.push(...babylonFile.vrEffects);
            delete babylonFile.vrEffects;
        }
        if(babylonFile.vrSprite){
            for(let vr of babylonFile.vrSprite){
                VersionTool.sprite(vr);
            }
            babylonFile.vr.push(...babylonFile.vrSprite)
            delete babylonFile.vrSprite;
        }
        if(babylonFile.vr){
            let folder=VeryEngine.shareBox.id2Asset[folderId?folderId:"root"];
            for(let vr of babylonFile.vr){
               IEDProxyFactory.getImportFunc(vr,folder);
            }
        }

        await OSS.uploadFile(new File([JSON.stringify(babylonFile)],file.name), assetID, file.name, hash);
        if (babylonFile.materials) {
            for(let material of babylonFile.materials){
                if(material.customType && material.customType === 'BABYLON.NodeMaterial'){
                    let file=new File([JSON.stringify(material)],material.name+".json");
                    await IEDJson.prototype.createUploadData(file,folderId)
                }else{
                    if(material.customType && material.customType === 'BABYLON.PBRMaterial'){
                        if(material.albedoTexture){
                            material.diffuseTexture=material.albedoTexture;
                            delete material.albedoTexture;
                        }
                    }
                    await IEDMaterial.prototype.createUploadData(material,folderId);
                }
            }
        }
        if(babylonFile.multiMaterials){
            for(let material of babylonFile.multiMaterials){
                material.customType="Babylon.MultiMaterial"
                await IEDMaterial.prototype.createUploadData(material,folderId);
            }
        }
        VeryEngine.shareBox.assetMap.set(data.id,new DMap(data));
    }
    //因为从3dmax导出的babylon都有parent，为了兼容性考虑，引擎导出的资源也需要有parent(包括babylon、gui)
    protected async convertSceneData(children:string[]){
        let entityList=[];
        let vr:{[key:string]:any}={};
        let meshes:any[]=this.assetObj.meshes;
        let skeleton2UUID={};
        for(let id in meshes){
            if(id){
                let mesh=meshes[id];
                let tmp:any=this.createEntityData(this.id,mesh); 
                tmp.checkCollisions = mesh.checkCollisions;
                if(mesh.isPickable!=undefined)
                tmp.pickable = mesh.isPickable;
                if(mesh.skeletonId!=undefined&&mesh.skeletonId!=-1){
                    tmp.skeletonUUID=mesh.skeletonId;
                    if(!skeleton2UUID[mesh.skeletonId]){
                        skeleton2UUID[mesh.skeletonId]=Tools.uuid();
                    }
                }
                if(mesh.skeletonRangeIndex!=undefined)
                    tmp.skeletonRangeIndex=mesh.skeletonRangeIndex
                if(mesh.skeletonActive!=undefined)
                    tmp.skeletonActive=mesh.skeletonActive;
                if(mesh.autoAnimate!=undefined) tmp.autoAnimate=mesh.autoAnimate;
                if(mesh.autoAnimateLoop!=undefined) tmp.autoAnimateLoop=mesh.autoAnimateLoop;
                if(mesh.autoAnimateFrom!=undefined) tmp.autoAnimateFrom=mesh.autoAnimateFrom;
                if(mesh.autoAnimateTo!=undefined) tmp.autoAnimateTo=mesh.autoAnimateTo;
                tmp.isVisible = mesh.isVisible;
                tmp.type = 'mesh';
                entityList.push(tmp);
                vr[id]=tmp;
            }
        }
        let transformNodes:any[]=this.assetObj.transformNodes;
        for(let id in transformNodes){
            if(id){
                let node=transformNodes[id];
                let tmp:any=this.createEntityData(this.id,node); 
                entityList.push(tmp);
                vr[id]=tmp;
            }
        }
        if(this.assetObj.vr)
        for(let node of this.assetObj.vr){
            if(node.type=="mesh"){
                let tmp:any=this.createEntityData(this.id,node);
                entityList.push(tmp);
                vr[node.id]=tmp;
            }
            else if(node.resource_id){
                node=Object.assign({},node);
                if(node.children) node.children=[...node.children];
                entityList.push(node);
                vr[node.resource_id]=node;
            }
        }
        for(let node of entityList){
            let uuid:string;
            let id=node.resource_id
            if(VeryEngine.shareBox.id2Entity[node.resource_id]){
                uuid=Tools.uuid();
                node.resource_id=uuid;
            }
            let parent=vr[node.parent||node.parentId];
            delete node.parentId;
            if(parent){
                if(!parent.children){
                    parent.children=[];
                }
                let index=parent.children.indexOf(id);
                if(index>=0){
                    if(uuid){
                    parent.children.splice(index,1,uuid);
                    }
                }else{
                    parent.children.push(node.resource_id)
                }
                node.parent=parent;

            }else{
                children.push(node.resource_id)
            }
        }
        //处理骨骼动画 子的骨骼动画统一由最顶层对象处理
        //记录最顶层、序号最前的以及同一层的个数
        let skeletonLevel:{[id:string]:{[key:string]:number}}={};
        let skeletonTop:{[id:string]:{resource:any,level:number,order:number,count:number}}={}
        for(let tmp of entityList){
            if(tmp.skeletonUUID!=undefined){
                if(!skeletonLevel[tmp.skeletonUUID]){
                    skeletonLevel[tmp.skeletonUUID]={};
                }
                this.getLevel(tmp,skeletonLevel[tmp.skeletonUUID],skeletonTop,tmp.skeletonUUID);
            }
        }
        //判断骨骼动画有没有parent相同的
        let recordParent=[];
        for(let id in skeletonTop){
            if(skeletonTop[id].resource.parent){
               let result=true;
               for(let tmp of recordParent){
                   if(tmp.resource.parent==skeletonTop[id].resource.parent){
                     skeletonTop[id].count=1;
                     tmp.count=1; result=false;
                     break;
                   }
               }
               if(result){
                 recordParent.push(skeletonTop[id]);
               }
            }
        }
        //若同一层个数为1，则那个1当作总的动画控制对象。否则同一层的父物体为动画控制对象
        for(let id in skeletonTop){
            let parent;
            if(skeletonTop[id].count==1){
                skeletonTop[id].resource.skeleton=skeletonTop[id].resource.skeletonUUID;
                parent=skeletonTop[id].resource;
            }else{
                parent=skeletonTop[id].resource.parent;
                parent.skeleton=skeletonTop[id].resource.skeletonUUID;
                parent.skeletonUUID=parent.skeleton;
            }
            let skeletonsInfo=this.assetObj.skeletons[parent.skeleton];
            if(skeletonsInfo.ranges&&skeletonsInfo.ranges.length!=0){
                let rangs=["无动画"];
                for(let tmp of skeletonsInfo.ranges){
                    rangs.push(tmp.name);
                }
                if(parent.skeletonRangeIndex===undefined)
                    parent.skeletonRangeIndex=0;
                parent.rangeList=rangs;
            }else{
                if(parent.skeletonActive===undefined)
                    parent.skeletonActive=false;
            }
        }
        for(let tmp of entityList){
            if(tmp.skeletonUUID!=undefined){
                tmp.skeletonUUID=skeleton2UUID[tmp.skeletonUUID];
            }
            delete tmp.parent;
        }
        return entityList;
    }

    private getLevel(node:any,info:{[key:string]:number},skeletonTop:{[id:string]:{resource:string,level:number,order:number,count:number}},skeletonId:string){
        if(info[node.resource_id]){
            return info[node.resource_id]
        }
        else if(node.parent){
            let level=this.getLevel(node.parent,info,skeletonTop,skeletonId)+1;
            if(node.skeletonUUID==skeletonId){
                if(!skeletonTop[skeletonId]){
                    skeletonTop[skeletonId]={resource:node,level:level,order:node.parent.children.indexOf(node.resource_id),count:1}
                }else{
                    if(level<skeletonTop[skeletonId].level){
                        skeletonTop[skeletonId]={resource:node,level:level,order:node.parent.children.indexOf(node.resource_id),count:1}
                    }else if(level==skeletonTop[skeletonId].level){
                        if(node.parent.children.indexOf(node.resource_id)<skeletonTop[skeletonId].order){
                            skeletonTop[skeletonId].resource=node;
                            skeletonTop[skeletonId].order=node.parent.children.indexOf(node.resource_id);
                        }
                        skeletonTop[skeletonId].count++;
                    }
                }
                info[node.resource_id]=level;
            }
            return level;
        }else{
            if(node.skeletonUUID==skeletonId){
                if(!skeletonTop[skeletonId]){
                    skeletonTop[skeletonId]={resource:node,level:0,order:0,count:1}
                }
                info[node.resource_id]=0;
            }
            return 0
        }
    }
    private createEntityData(assetId:string,mesh:any){
        let obj:any= {
            name: mesh.name,
            resource_id: mesh.id,
            babylon_id: mesh.id,
            asset_id: assetId,  // 对应babylon资源id
            parent: mesh.parent||mesh.parentId,
            children:[],
            enabled: mesh.isEnabled,
            type: 'mesh',
        }
        if(mesh.alphaIndex!=null){
            obj.alphaIndex=mesh.alphaIndex
        }
        if(mesh.position){
            obj.position=mesh.position;
        }
        if(mesh.materialId){
            obj.material=VeryEngine.shareBox.matID2AssetID[mesh.materialId]
        }
        if(mesh.rotation){
            let tmp=[];
            for(let i=0;i<mesh.rotation.length;i++){
                tmp.push(mesh.rotation[i]/Math.PI*180);
            }
            obj.rotation=tmp;
        }
        if(mesh.scaling){
            obj.scale=mesh.scaling;
        }
        if(mesh.subtype){
            obj.subtype=mesh.subtype;
        }
        if(mesh.children){
            obj.children=[...mesh.children]
        }
        return obj;
    }


    parseBabylon(babylonData: any): any {
        if (babylonData) {
            let parsedData: any = {};
            // 材质
            if (babylonData.materials) {
                parsedData.materials = {};
                babylonData.materials.forEach((material: any) => {
                    parsedData.materials[material.id] = material;
                });
            }
            if (babylonData.multiMaterials) {
                parsedData.multiMaterials = {};
                babylonData.multiMaterials.forEach((material: any) => {
                    parsedData.multiMaterials[material.id] = material;
                });
            }
            // geometries
            if (babylonData.geometries && babylonData.geometries.vertexData) {
                parsedData.geometries = {};
                babylonData.geometries.vertexData.forEach((geometry: any) => {
                    parsedData.geometries[geometry.id] = geometry;
                });
            }
            //DO_20211203:骨骼动画,babylon文件中skeleton信息解析
            if (babylonData.skeletons) {
                //console.warn("babylon文件中skeleton信息解析");
                parsedData.skeletons = {};
                babylonData.skeletons.forEach((skeleton: any) => {
                    parsedData.skeletons[skeleton.id] = skeleton;
                });
            }
            // mesh
            if (babylonData.meshes) {
                parsedData.meshes = {};
                babylonData.meshes.forEach((mesh: any) => {
                    parsedData.meshes[mesh.id] = mesh;
                    if (mesh.rotationQuaternion !== null && mesh.rotationQuaternion !== undefined) {
                        let qua = new BABYLON.Quaternion(mesh.rotationQuaternion[0], mesh.rotationQuaternion[1], mesh.rotationQuaternion[2], mesh.rotationQuaternion[3]);
                        // let vec3 = Tools.quaternionToRadian(qua);
                        let vec3 = qua.toEulerAngles();
                        mesh.rotationQuaternion = null;
                        mesh.rotation = [vec3.x, vec3.y, vec3.z];
                    }
                });
            }
            // transformNodes
            if (babylonData.transformNodes) {
                parsedData.transformNodes = {};
                babylonData.transformNodes.forEach((transformNode: any) => {
                    parsedData.transformNodes[transformNode.id] = transformNode;
                    if (transformNode.rotationQuaternion !== null && transformNode.rotationQuaternion !== undefined) {
                        let qua = new BABYLON.Quaternion(transformNode.rotationQuaternion[0], transformNode.rotationQuaternion[1], transformNode.rotationQuaternion[2], transformNode.rotationQuaternion[3]);
                        // let vec3 = Tools.quaternionToRadian(qua);
                        let vec3 = qua.toEulerAngles();
                        transformNode.rotationQuaternion = null;
                        transformNode.rotation = [vec3.x, vec3.y, vec3.z];
                    }
                });
            }
            if(babylonData.vr)
                parsedData.vr=babylonData.vr;
            if(babylonData.vrGUI)
                parsedData.vrGUI=babylonData.vrGUI;
            if(babylonData.vrCamera)
                parsedData.vrCamera=babylonData.vrCamera;
            if(babylonData.vrLight)
                parsedData.vrLight=babylonData.vrLight;
            if(babylonData.vrEffects)
                parsedData.vrEffects=babylonData.vrEffects;
            if(babylonData.vrSprite)
                parsedData.vrSprite=babylonData.vrSprite;
            if(babylonData.vrTable)
                parsedData.vrTable=babylonData.vrTable;
            return parsedData;
        }
        return null;
    }

    public customAttributes() {
        return [{
            attributes:[{
                name:'ID',attr:'id',type:DataType.String,readonly:true
            },{
                name:'名字',attr:'name',type:DataType.Name
            }]
        }]
    }
}