import { IEDTransform } from "../IEDTransform";
import { ParticleTools } from "./ParticleTools";
import { VeryEngine,DataType} from "../../engine";
import { ATTRIB, IEDAttrib, addEntityClass } from "../../engine/IEDProxy";
import { VeryParticleSystem } from "../../middleware/VeryParticle";


@addEntityClass
export class Fire extends IEDTransform{
    public get type(): string {
        return "particle";
    }
    public get subtype(){
        return "fire_zzl_code"
    }
    protected dispose(): void {
        this.sceneObj.dispose();
    }
    public sceneObj: VeryParticleSystem
    async Load() {
        this.sceneObj = ParticleTools.createParticleSystemWraper_Fire(
            this.subtype,
            this.name,
            VeryEngine.scene
        );
    }
    private title="火焰"
    @ATTRIB()
    public radius:IEDAttrib<DataType.Slide>={
        name:"火焰大小",
        type:DataType.Slide,
        async onchange(this:Fire,radiusValue){
            var updateSpeedValue = this.get("updateSpeed");
            var maxLifeTime = this.get("maxLifeTime");
            var instance:BABYLON.ParticleSystem = this.sceneObj['particle'];
            var subParticle = VeryParticleSystem._subParticle[instance.name];
            instance.minEmitBox = new BABYLON.Vector3(-1 * radiusValue,0,-1 * radiusValue);
            instance.maxEmitBox = new BABYLON.Vector3(radiusValue,0,radiusValue);
            instance.emitRate =
                (1500 + (1500 * (updateSpeedValue - 0.001)) / 0.004) *
                (1 + ((radiusValue - 0.5) / 4.5) * 3);
            instance.maxLifeTime =
                maxLifeTime + ((radiusValue - 0.5) / 4.5) * (0.175 - 0.12);
            instance.maxSize = 0.1 + ((radiusValue - 0.5) / 4.5) * 1.9;
            instance.minSize = 2 + ((radiusValue - 0.5) / 4.5) * 4;
            if(subParticle){
                subParticle.minEmitBox = new BABYLON.Vector3(-1 * radiusValue,3 +(0.5 * (maxLifeTime - 0.05)) / (0.12 - 0.05) +((radiusValue - 0.5) / 4.5) * (10 - 3.5),-1 * radiusValue);
                subParticle.maxEmitBox = new BABYLON.Vector3(radiusValue,2 +(0.5 * (maxLifeTime - 0.05)) / (0.12 - 0.05) +((radiusValue - 0.5) / 4.5) * (9 - 2.5),radiusValue);
                subParticle.maxLifeTime =0.2 +((maxLifeTime - 0.05) / (0.12 - 0.05)) * 0.05 +((radiusValue - 0.5) / 4.5) * (0.5 - 0.25);
                subParticle.maxSize =
                    1.2 + ((radiusValue - 0.5) / 4.5) * (7.2 - 1.2);
                subParticle.minSize =
                    2 + ((radiusValue - 0.5) / 4.5) * (12 - 2);
            }
        },
        default:0.5,
        extra:{min:0.5,max:5},
        title:this.title
    }

    @ATTRIB()
    public maxLifeTime:IEDAttrib<DataType.Slide>={
        name:"火焰高度",
        type:DataType.Slide,
        onchange(this:Fire,maxLifeTime){
            var radiusValue = this.get("radius");
            var instance:BABYLON.ParticleSystem = this.sceneObj['particle'];
            var subParticle = VeryParticleSystem._subParticle[instance.name];
            instance.maxLifeTime =
            maxLifeTime + ((radiusValue - 0.5) / 4.5) * (0.175 - 0.12);
            if(subParticle){
            subParticle.minEmitBox = new BABYLON.Vector3(-1 * radiusValue,3 +(0.5 * (maxLifeTime - 0.05)) / (0.12 - 0.05) +((radiusValue - 0.5) / 4.5) * (10 - 3.5),-1 * radiusValue);
            subParticle.maxEmitBox = new BABYLON.Vector3(radiusValue,2 +(0.5 * (maxLifeTime - 0.05)) / (0.12 - 0.05) +((radiusValue - 0.5) / 4.5) * (9 - 2.5),radiusValue);
            subParticle.maxLifeTime =0.2 +((maxLifeTime - 0.05) / (0.12 - 0.05)) * 0.05 +((radiusValue - 0.5) / 4.5) * (0.5 - 0.25);
            }
        },
        default:0.08,
        extra:{max:0.12,min:0.05},
        title:this.title
    }

    @ATTRIB()
    public updateSpeed:IEDAttrib<DataType.Slide>={
        name:"火焰烈度",
        type:DataType.Slide,
        onchange(this:Fire,updateSpeedValue){
            var emitRate = this.get("emitRate");
            var radiusValue = this.get("radius");
            var instance:BABYLON.ParticleSystem = this.sceneObj['particle'];
            var subParticle = VeryParticleSystem._subParticle[instance.name];
            instance.emitRate =
            (1500 + (1500 * (updateSpeedValue - 0.001)) / 0.004) *
            (1 + ((radiusValue - 0.5) / 4.5) * 3);
            instance.updateSpeed = updateSpeedValue;
            if(subParticle){
            subParticle.updateSpeed =
                0.001 + ((updateSpeedValue - 0.001) / 0.004) * 0.001;
            subParticle.emitRate =
                emitRate + (1000 * (updateSpeedValue - 0.001)) / 0.004;
            }
        },
        default:0.001,
        extra:{max:0.005,min:0.001},
        title:this.title
    }

    @ATTRIB()
    public emitRate:IEDAttrib<DataType.Slide>={
        name:"盐浓度",
        type:DataType.Slide,
        onchange(this:Fire,emitRate){
            var updateSpeedValue = this.get("updateSpeed");
                var instance:BABYLON.ParticleSystem = this.sceneObj['particle'];
                var subParticle = VeryParticleSystem._subParticle[instance.name];
                if(subParticle)
                subParticle.emitRate =
                    emitRate + (1000 * (updateSpeedValue - 0.001)) / 0.004;
        },
        default:1000,
        extra:{max:2000,min:1000},
        title:this.title
    }
}