import { ATTRIB, IEDAttrib, addEntityClass } from "../engine/IEDProxy";
import { Tools } from "../utility/Tools";
import { VeryEngine,DataType, IED } from "../engine";
import { IEDAsset, IEDModel } from "../assets";
import { IEDTransform } from "./IEDTransform";

@addEntityClass
export class IEDMesh extends IEDTransform{
    public sceneObj:BABYLON.AbstractMesh;

    public get type(): string {
        return "mesh"
    }
    private matId;
    private static skeletonControl:{[uuid:string]:BABYLON.Skeleton}={};
    private static skeletonToLoad:{[uuid:string]:IEDMesh[]}={};
    async Load(){
        let singleBabylon;
        let assetID=this._data.get("asset_id");
        let assetOrigin=VeryEngine.shareBox.id2Asset[assetID];
        let multiple=VeryEngine.version=="5.0"?100:1;
        if (this.subtype === 'box') {
            this.sceneObj= BABYLON.MeshBuilder.CreateBox(this.name,{ size: multiple },VeryEngine.scene);
        } else if (this.subtype === 'sphere') {
            this.sceneObj= BABYLON.MeshBuilder.CreateSphere(this.name, { segments: 20, diameter: multiple },VeryEngine.scene);
        } else if (this.subtype === 'plane') {
            this.sceneObj = BABYLON.MeshBuilder.CreateGround(this.name, { width: 50*multiple, height: 50*multiple, subdivisions: 10 }, VeryEngine.scene);
        }else if (this.subtype === 'cylinder') {
            this.sceneObj = BABYLON.MeshBuilder.CreateCylinder(this.name,{ height: 2*multiple, diameter: multiple }, VeryEngine.scene);
        }else if(this.subtype==="lines"){
            this.sceneObj=new BABYLON.LinesMesh(this.name,VeryEngine.scene);
        }
        else if(assetOrigin instanceof IEDModel){
            if(!assetOrigin.assetObj){
                await VeryEngine.shareBox.id2Asset[assetID].onceOnlyLoad();
            }
            singleBabylon=assetOrigin.assetObj;
            let meshID: string =this._data.get('babylon_id');
            if (singleBabylon.meshes[meshID]) {
                let meshData = singleBabylon.meshes[meshID];
                if (meshData.geometryId) {
                    if (VeryEngine.scene.getGeometryById(meshData.geometryId) === null) {
                        if (singleBabylon.geometries && singleBabylon.geometries[meshData.geometryId]) {
                            let vertexData = singleBabylon.geometries[meshData.geometryId];
                            BABYLON.Geometry.Parse(vertexData, VeryEngine.scene, "");
                        }
                    }
                }
                let skeletonId=meshData.skeletonId;
                delete meshData.skeletonId;
                let geometryId=meshData.geometryId;
                this.sceneObj=BABYLON.Mesh.Parse(meshData,VeryEngine.scene, "");
                if(geometryId!=null){
                    VeryEngine.scene.getGeometryById(meshData.geometryId).applyToMesh((this.sceneObj as BABYLON.Mesh));
                    meshData.geometryId=geometryId;
                }
                meshData.skeletonId=skeletonId;
                this.matId=meshData.materialId;
                let skeletonUUID=this._data.get("skeletonUUID");
                if(skeletonUUID!=undefined){
                    if(IEDMesh.skeletonControl[skeletonUUID]){
                        this.sceneObj.skeleton=IEDMesh.skeletonControl[skeletonUUID];
                    }else{
                        //只有一个父物体或者大哥有skeleton属性
                        let skeleton=this._data.get("skeleton");
                        if(skeleton!=undefined&&singleBabylon.skeletons[skeleton]){
                            skeleton=BABYLON.Skeleton.Parse(singleBabylon.skeletons[skeleton], VeryEngine.scene);
                            this.sceneObj.skeleton=skeleton;
                            IEDMesh.skeletonControl[skeletonUUID]=skeleton;
                            if(IEDMesh.skeletonToLoad[skeletonUUID]){
                                for(let tmp of IEDMesh.skeletonToLoad[skeletonUUID]){
                                    tmp.sceneObj.skeleton=skeleton;
                                }
                                delete IEDMesh.skeletonToLoad[skeletonUUID]
                            }
                        }else{
                            if(IEDMesh.skeletonToLoad[skeletonUUID]){
                                IEDMesh.skeletonToLoad[skeletonUUID].push(this);
                            }else{
                                IEDMesh.skeletonToLoad[skeletonUUID]=[this];
                            }
                        }
                    }
                }
            }else{
                this.sceneObj=new BABYLON.Mesh(this.name,VeryEngine.scene);
            }
        }else{
            this.sceneObj=new BABYLON.Mesh(this.name,VeryEngine.scene);
        }
        this.sceneObj.id=this.id
        this.sceneObj.name=this.name;
    }

    private addMatDepend(mat:IEDAsset){
        let id=mat.id;
        VeryEngine.entityReady.addEventListener(id, ()=>{
            let ied =VeryEngine.shareBox.id2Asset[mat.id];
            this.sceneObj.material=ied.assetObj;
        })
    }

    public recordSceneObj(sceneObj: BABYLON.Mesh) {
        let map=super.recordSceneObj(sceneObj);
        var positions = sceneObj.getVerticesData(BABYLON.VertexBuffer.PositionKind);
        var normals = sceneObj.getVerticesData(BABYLON.VertexBuffer.NormalKind);  
        var indices = sceneObj.getIndices();
        var uvs = sceneObj.getVerticesData(BABYLON.VertexBuffer.UVKind);
        var uvs2 = sceneObj.getVerticesData(BABYLON.VertexBuffer.UV2Kind);
        var uvs3 = sceneObj.getVerticesData(BABYLON.VertexBuffer.UV3Kind);
        var uvs4 = sceneObj.getVerticesData(BABYLON.VertexBuffer.UV4Kind);
        var uvs5 = sceneObj.getVerticesData(BABYLON.VertexBuffer.UV5Kind);
        var uvs6 = sceneObj.getVerticesData(BABYLON.VertexBuffer.UV6Kind);
        if(positions)map["positions"]=[...positions];
        if(normals)map["normals"]=[...normals];
        if(indices)map["indices"]=[...indices];
        if(uvs)map["uvs"]=[...uvs];if(uvs2)map["uvs2"]=[...uvs2];
        if(uvs3)map["uvs3"]=[...uvs3];if(uvs4)map["uvs4"]=[...uvs4];
        if(uvs5)map["uvs5"]=[...uvs5];if(uvs6)map["uvs6"]=[...uvs6];
        map["position"]=sceneObj.position.asArraytoFixed();
        map["rotation"]=Tools.radianToEulerAngle(sceneObj.rotation).asArraytoFixed();
        map["scale"]=sceneObj.scaling.asArraytoFixed();
        return map;
    }

    protected dispose(): void {
        this.sceneObj.dispose();
    }

    public export(vrData:any,file:IED[],parent?:string){
        let assetID=this._data.get("asset_id");
        let assetOrigin=VeryEngine.shareBox.id2Asset[assetID];
        let json=this._data.jsonParse();
        if(json.rotation){
            let tmp=[];
            for(let i=0;i<json.rotation.length;i++){
                tmp[i]=json.rotation[i]*Math.PI/180;
            }
            json.rotation=tmp;
        }
        if(json.scale){
            json.scaling=json.scale;
            delete json.scale;
        }
        if(parent)
            json.parentId=parent;
        if(json.material){
            for(let matID in VeryEngine.shareBox.matID2AssetID){
                if(VeryEngine.shareBox.matID2AssetID[matID]==json.material){
                    json.materialId=matID;break;
                }
            }
            if(json.materialId){
                let assetID=VeryEngine.shareBox.matID2AssetID[json.materialId];
                let matAsset=VeryEngine.shareBox.id2Asset[assetID];
                if(matAsset) matAsset.export(vrData,file);
            }
        }
        delete json.babylon_id;
        delete json.material;
        delete json.asset_id;
        json.id=json.resource_id;
        delete json.resource_id;
        json.isEnabled=json.enabled;
        delete json.enabled;

        if(assetOrigin instanceof IEDModel){
            let  singleBabylon=assetOrigin.assetObj;
            let meshID: string =this._data.get('babylon_id');
            let meshData = singleBabylon.meshes[meshID];
            if(meshData){
                if (meshData.geometryId) {
                    vrData.geometries.vertexData.push(singleBabylon.geometries[meshData.geometryId]);
                }
            }
            json=Object.assign({},meshData,json);
            delete json.rotationQuaternion;
            vrData.meshes.push(json);
        }else{
            vrData.vr.push(json);
        }
        for(let child of this.children){
            child.export(vrData,file,this.id);
        }
    }

    @ATTRIB()
    public checkCollisions:IEDAttrib<DataType.Bool>={
        name:"碰撞检测",
        type:DataType.Bool,
        onchange(this:IEDMesh,val){
            this.sceneObj.checkCollisions=val;
        }
    }

    @ATTRIB()
    public isPickable:IEDAttrib<DataType.Bool>={
        name:"可选中",
        type:DataType.Bool,
        onchange(this:IEDMesh,val){
            if(VeryEngine.EditMode){
                this.sceneObj.isPickable=true;
            }else{
                this.sceneObj.isPickable=val;
            }
        },
        default:true
    }

    @ATTRIB()
    public visibility:IEDAttrib<DataType.Slide>={
        name:"透明度",
        type:DataType.Slide,
        onchange(this:IEDMesh,val){
            this.sceneObj.visibility=val;
        },
        default:1,
        title:"渲染属性"
    }

    @ATTRIB()
    public material:IEDAttrib<DataType.MaterialBox>={
        name:"材质",
        type:DataType.MaterialBox,
        async onchange(this:IEDMesh,val,isFirst){
            if(VeryEngine.shareBox.id2Asset[val]){
                await VeryEngine.shareBox.id2Asset[val].onceOnlyLoad();
                this.sceneObj.material=VeryEngine.shareBox.id2Asset[val].assetObj;
                this.addMatDepend(VeryEngine.shareBox.id2Asset[val])
            }else if(this.matId&&this.matId!="default material"){
                let matAssetId=VeryEngine.shareBox.matID2AssetID[this.matId];
                if(VeryEngine.shareBox.id2Asset[matAssetId]){
                    await VeryEngine.shareBox.id2Asset[matAssetId].onceOnlyLoad();
                    let matAsset=VeryEngine.shareBox.id2Asset[matAssetId];
                    this.sceneObj.material=matAsset.assetObj;
                    // this.addMatDepend(matAsset);
                }else {
                    console.error('模型材质加载错误！模型名：' + this.sceneObj.name + '材质ID：' + this.matId + '，无法查找到该模型材质对应的资源：' + matAssetId);
                }
            }else if(!isFirst){
                if(this.sceneObj instanceof BABYLON.LinesMesh)
                    this.sceneObj.material=null;
                else
                    this.sceneObj.material=VeryEngine.scene.defaultMaterial;
            }
        },
        title:"渲染属性"
    }

    @ATTRIB()
    public receiveShadows:IEDAttrib<DataType.Bool>={
        name:"允许接收阴影",
        type:DataType.Bool,
        async onchange(this:IEDMesh,val){
            this.sceneObj.receiveShadows=val;
        },
        title:"渲染属性"
    }

    @ATTRIB()
    public color={
        onchange(this:IEDMesh,val:number[]){
            if(!this._data.get("material")){
                if(!this.sceneObj.material)
                    this.sceneObj.material=VeryEngine.scene.defaultMaterial.clone(this.id);
                (<BABYLON.StandardMaterial>this.sceneObj.material).diffuseColor=BABYLON.Color3.FromArray(val);
            }
        },
        default:null
    }

    @ATTRIB()
    public positions={
        onchange(this:IEDMesh,val){
            this.sceneObj.setVerticesData(BABYLON.VertexBuffer.PositionKind,val);
        },
        default:null
    }

    @ATTRIB()
    public indices={
        onchange(this:IEDMesh,val){
            this.sceneObj.setIndices(val,null);
        },
        default:null
    }

    @ATTRIB()
    public normals={
        onchange(this:IEDMesh,val){
            this.sceneObj.setVerticesData(BABYLON.VertexBuffer.NormalKind,val);
        },
        default:null
    }

    @ATTRIB()
    public uvs={
        onchange(this:IEDMesh,val){
            this.sceneObj.setVerticesData(BABYLON.VertexBuffer.UVKind,val);
        },
        default:null
    }

    @ATTRIB()
    public uvs2={
        onchange(this:IEDMesh,val){
            this.sceneObj.setVerticesData(BABYLON.VertexBuffer.UV2Kind,val);
        }
    }

    @ATTRIB()
    public uvs3={
        onchange(this:IEDMesh,val){
            this.sceneObj.setVerticesData(BABYLON.VertexBuffer.UV3Kind,val);
        },
        default:null
    }

    @ATTRIB()
    public uvs4={
        onchange(this:IEDMesh,val){
            this.sceneObj.setVerticesData(BABYLON.VertexBuffer.UV4Kind,val);
        },
        default:null
    }

    @ATTRIB()
    public uvs5={
        onchange(this:IEDMesh,val){
            this.sceneObj.setVerticesData(BABYLON.VertexBuffer.UV5Kind,val);
        },
        default:null
    }

    @ATTRIB()
    public uvs6={
        onchange(this:IEDMesh,val){
            this.sceneObj.setVerticesData(BABYLON.VertexBuffer.UV6Kind,val);
        },
        default:null
    }

    @ATTRIB()
    public skeletonRangeIndex:IEDAttrib<DataType.DropDown>={
        name:"动画选择",
        type:DataType.DropDown,
        onchange(this:IEDMesh,val){
            let skeleton=IEDMesh.skeletonControl[this._data.get("skeletonUUID")];
            if(skeleton){
                let tmpRanges = skeleton.getAnimationRanges();
                if(tmpRanges.length>0){
                    if(val==0){
                        VeryEngine.scene.stopAnimation(skeleton);
                    }else{
                        VeryEngine.scene.beginAnimation(skeleton,tmpRanges[val-1].from,tmpRanges[val-1].to,this.get("skeletonLoop"))
                    }
                }
            }
        },
        filter(this:IEDMesh){
            return this.get("skeletonRangeIndex")!=undefined
        },
        title:"骨骼动画",
        default:null,
        extra:function(){
            return this._data.get("rangeList")
        }
    }

    @ATTRIB()
    public skeletonActive:IEDAttrib<DataType.Bool>={
        name:"骨骼动画激活",
        type:DataType.Bool,
        onchange(this:IEDMesh,value){
            let skeleton=IEDMesh.skeletonControl[this._data.get("skeletonUUID")];
            if(skeleton&&skeleton.bones.length>0&&skeleton.bones[skeleton.bones.length-1].animations.length>0){
                let to=skeleton.bones[skeleton.bones.length-1].animations[0].getKeys();
                if(value){
                    VeryEngine.scene.beginAnimation(skeleton,0
                    , to[to.length-1].frame, this.get("skeletonLoop"));
                }else{
                    VeryEngine.scene.stopAnimation(skeleton);
                }
            }
        },
        default:null,
        filter(this:IEDMesh){
            return this.get("skeletonActive")!=undefined
        },
        title:"骨骼动画"
    }

    @ATTRIB()
    public skeletonLoop:IEDAttrib<DataType.Bool>={
        name:"动画循环",
        type:DataType.Bool,
        onchange(val, isFirst) {
            if(!isFirst){
                let skeleton=IEDMesh.skeletonControl[this._data.get("skeletonUUID")];
                if(skeleton){
                    if(this._data.get("skeletonRangeIndex")){
                        let index=this._data.get("skeletonRangeIndex");
                        let tmpRanges = skeleton.getAnimationRanges();
                        if(tmpRanges.length>0){
                            VeryEngine.scene.beginAnimation(skeleton,tmpRanges[index-1].from,tmpRanges[index-1].to,val)
                        }
                    }else if(this._data.get("skeletonActive")){
                        if(skeleton.bones.length>0&&skeleton.bones[skeleton.bones.length-1].animations.length>0){
                            let to=skeleton.bones[skeleton.bones.length-1].animations[0].getKeys();
                            VeryEngine.scene.beginAnimation(skeleton,0
                                , to[to.length-1].frame, val);
                        }
                    }
                }
            }
        },
        filter() {
            return this.get("skeletonRangeIndex")||this.get("skeletonActive")
        },
        title:"骨骼动画"
    }

    @ATTRIB()
    public autoAnimate:IEDAttrib<DataType.Bool>={
        name:"自动播放",
        type:DataType.Bool,
        onchange(this:IEDMesh,val){
            if(this.sceneObj.animations&&this.sceneObj.animations.length!=0)
            if(this._data.get("autoAnimateTo")){
                if(val)
                VeryEngine.scene.beginAnimation(this.sceneObj,this._data.get('autoAnimateFrom'),this._data.get('autoAnimateTo'),
                this._data.get('autoAnimateLoop'))
                else
                VeryEngine.scene.stopAnimation(this.sceneObj);
            }
        },
        filter() {
            return this.sceneObj.animations&&this.sceneObj.animations.length!=0
        },
        title:"动画属性"
    }

    @ATTRIB()
    public autoAnimateLoop:IEDAttrib<DataType.Bool>={
        name:"自动循环",
        type:DataType.Bool,
        onchange(this:IEDMesh,val,isFirst){
            if(this.sceneObj.animations&&this.sceneObj.animations.length!=0)
            if(!isFirst&&this._data.get("autoAnimate"))
                VeryEngine.scene.beginAnimation(this.sceneObj,this._data.get('autoAnimateFrom'),this._data.get('autoAnimateTo'),
            val)
        },
        filter(){
            return this.sceneObj.animations&&this.sceneObj.animations.length!=0
        },
        title:"动画属性"
    }
}