    private createAssetData(data: any, asset: IEDAsset) {
        let folderId;
        if (asset && (asset.type == "root" || asset.type == "folder"))
            folderId = asset.id;
        VeryEngine.addAssetData(data,folderId);
    }
    private createEntityData(data: any, entity: IEDEntity) {
        VeryEngine.addEntityData(data,entity,true);
    }
    private createUIData(data: any, entity: IEDEntity) {
        let parent:IEDEntity;
        if (!entity || entity.type == "root") {
            if (IEDGUI.lastCanvas && !IEDGUI.lastCanvas.isDestroy) {
                parent = IEDGUI.lastCanvas;
            } else {
                let id = Tools.uuid();
                VeryEngine.addEntityData({
                    name: "2D画布",
                    type: "gui",
                    subtype: "canvas",
                    gui: {
                        width: 100,
                        widthType: 1,
                        height: 100,
                        heightType: 1,
                    },
                    children: [data.resource_id],
                    resource_id: id,
                })
                VeryEngine.addEntityData(data,id,true);
            }
        } else {
            parent = entity;
        }
        if(parent)
        VeryEngine.addEntityData(data,parent,true);
    }
    private createKrpanoData(data: any, entity: IEDEntity) {
        let parent;
        let category;
        if (!entity || entity.type == "root") {
            if (KrpanoCanvas.lastKrpanoCanvas) {
                parent = KrpanoCanvas.lastKrpanoCanvas;
            } else {
                let id = Tools.uuid();
                VeryEngine.addEntityData({
                    name: "全景画布",
                    type: "krpano",
                    subtype: "canvas",
                    gui: {
                        width: 400,
                        widthType: 0,
                        height: 300,
                        heightType: 0,
                    },
                    children: [data.resource_id],
                    resource_id: id,
                });
                let root = VeryEngine.shareBox.id2Entity[IEDEntity.rootId];
                root.children.push(id);
            }
        } else {
            parent = entity;
        }
        if ((entity.subtype === "canvas" || !entity) && (data.subtype === "sceneImage"|| data.subtype === "sceneVideo")) {
            if (KrpanoCategory.lastKrpanoCategory) {
                category = KrpanoCategory.lastKrpanoCategory;
            } else {
                let id = Tools.uuid();
                VeryEngine.addEntityData({
                    name: "全景分类",
                    type: "krpano",
                    subtype: "category",
                    gui: {
                        width: 100,
                        widthType: 1,
                        height: 100,
                        heightType: 1,
                    },
                    children: [data.resource_id],
                    resource_id: id,
                });
                parent.children.push(id);
                category = KrpanoCategory.lastKrpanoCategory;
            }
        } else {
            category = entity;
        }
        if (parent && data.subtype === "category") {
            parent.children.push(data.resource_id);
        }
        if ((parent && data.subtype === "krpanoImage") || (parent && data.subtype === "krpanoVideo") || (parent && data.subtype === "krpanoText")) {
            parent.children.push(data.resource_id);
        }
        if (category && (data.subtype === "sceneImage"|| data.subtype === "sceneVideo")) {
            console.log(data.resource_id);
            category.children.push(data.resource_id);
        }
        console.log(data);
        console.log(parent);
        VeryEngine.addEntityData(data,parent,true);
    }
