import { VeryEngine } from "./VeryEngine";
import { VeryCamera } from "../middleware/VeryCamera";
import { Tools } from "../utility/Tools";
import { IEDEntity } from "../entities/IEDEntity";

export class ViewportCamera{
    public x:number=0;
    public y:number=0;
    private isCamRot=false;
    private isCamMove=false;
    public veryCamera:VeryCamera;
    private cameraX:BABYLON.Vector3;
    private cameraY:BABYLON.Vector3;
    private initScreenPos:BABYLON.Vector3;
    private targetOnScreenPosition:BABYLON.Vector3;
    private initPosition:BABYLON.Vector3=BABYLON.Vector3.Zero();

    //上帝相机角度
    private storeRotation:BABYLON.Quaternion= BABYLON.Quaternion.Zero();
    //上帝相机距离
    public cameraDistance:number=5;
    //上帝相机对焦点
    private targetPosition:BABYLON.Vector3=BABYLON.Vector3.Zero();

    private beforeViewUpdate:({[key:string]:((entity:IEDEntity,pickEntityIds:IEDEntity[])=>void)[]})={};
    private afterViewUpdate:({[key:string]:((entity:IEDEntity,pickEntityIds:IEDEntity[])=>void)[]})={};

    public addBeforeViewUpdate(id,act){
        if(!this.beforeViewUpdate[id]) this.beforeViewUpdate[id]=[]
        this.beforeViewUpdate[id].push(act);
    } 

    public removeBeforeVeiwUpdate(id){
        delete this.beforeViewUpdate[id];
    }

    public addAfterViewUpdate(id,act){
        if(!this.afterViewUpdate[id]) this.afterViewUpdate[id]=[]
        this.afterViewUpdate[id].push(act);
    } 

    public removeAfterVeiwUpdate(id){
        delete this.afterViewUpdate[id];
    }

    public customView(target:BABYLON.TransformNode,distance?:number,vect3?:BABYLON.Vector3){
        this.beforeView();
        if(vect3){
            let tmp=new BABYLON.Quaternion(0,0,0,1);
            if(target) tmp=target.rotation.toQuaternion();
            this.storeRotation=tmp.multiply(new BABYLON.Vector3(vect3.y*Math.PI/180, vect3.x*Math.PI/180, vect3.z*Math.PI/180).toQuaternion());
            this.veryCamera.rotationQuaternion=this.storeRotation;
            let arr= Tools.radianToEulerAngle(this.veryCamera.rotationQuaternion.toEulerAngles()).asArray();
            this.y=arr[0];this.x=arr[1];
        }
        if(distance==null){
            let pickEntities=VeryEngine.pickedEntities;
            let recordMesh:BABYLON.AbstractMesh[]=[];
            for(let tmp of pickEntities){
                if(tmp.sceneObj instanceof BABYLON.AbstractMesh){
                    recordMesh.push(tmp.sceneObj);
                }
            }
            if(recordMesh.length>1){
                let meshesOrMinMaxVector = BABYLON.Mesh.MinMax(recordMesh);
                distance = BABYLON.Vector3.Distance(meshesOrMinMaxVector.min, meshesOrMinMaxVector.max) * 1.5;
            }else if(recordMesh.length==1){
                let boundingBox = recordMesh[0].getBoundingInfo().boundingBox;
                distance = BABYLON.Vector3.Distance(boundingBox.minimumWorld, boundingBox.maximumWorld) * 1.5;
            }
        }
        if(!distance) distance=3;
        this.cameraDistance=distance;
        if(target) 
        {
            let tmp=target.absolutePosition;
            this.targetPosition=tmp.clone();
        }
        this.targetOnScreenPosition=this.targetPosition.clone();
        this.veryCamera.orthoSize =this.cameraDistance * 0.0007;
        this.veryCamera.position = Tools.quatMultiplyVector3(this.storeRotation, new BABYLON.Vector3(0.0, 0.0, -this.cameraDistance)).add(this.targetPosition);
        this.afterView();
    }
    constructor(){
        var val = localStorage.getItem("view-camera"+VeryEngine.projectId);
        var camera = new BABYLON.UniversalCamera('__viewportCamera__', new BABYLON.Vector3(0, 1, -20), VeryEngine.scene);
        // camera.minZ =1;
        // camera.maxZ = 9000000;
        VeryEngine.scene.cameraToUseForPointers = camera;
        // VeryEngine.scene.activeCamera=camera;
        this.veryCamera=new VeryCamera(camera,VeryEngine.scene,VeryEngine.canvas);
        this.veryCamera.enable(true,VeryEngine.scene)
        this.veryCamera.clearColor=new BABYLON.Color4(0,0,0,0);
        if(val){
            let obj=JSON.parse(val);
            this.storeRotation.x=obj.rot[0];
            this.storeRotation.y=obj.rot[1];
            this.storeRotation.z=obj.rot[2];
            this.storeRotation.w=obj.rot[3];
            this.cameraDistance=obj.dis;
            this.targetPosition.x=obj.pos[0];
            this.targetPosition.y=obj.pos[1];
            this.targetPosition.z=obj.pos[2];
            this.veryCamera.rotationQuaternion=this.storeRotation.clone();
            [this.y,this.x] = Tools.radianToEulerAngle(this.veryCamera.rotationQuaternion.toEulerAngles()).asArray();
            this.veryCamera.position = Tools.quatMultiplyVector3(this.storeRotation, new BABYLON.Vector3(0.0, 0.0, -this.cameraDistance)).add(this.targetPosition);
        }else{
            [this.y,this.x] = Tools.radianToEulerAngle(this.veryCamera.rotation).asArray();
            this.veryCamera.rotationQuaternion=this.veryCamera.rotation.toQuaternion();
            this.storeRotation = BABYLON.Quaternion.FromEulerVector(Tools.eulerAngleToRadian(new BABYLON.Vector3(this.y, this.x, 0)));
            this.veryCamera.position = Tools.quatMultiplyVector3(this.storeRotation, new BABYLON.Vector3(0.0, 0.0, -this.cameraDistance)).add(this.targetPosition);
        }
        this.targetOnScreenPosition=this.targetPosition.clone();
        window.onbeforeunload=()=>{
            let obj ={rot:[this.storeRotation.x,this.storeRotation.y,this.storeRotation.z,this.storeRotation.w],
                dis:this.cameraDistance,
                pos:[this.targetPosition.x,this.targetPosition.y,this.targetPosition.z]};
            localStorage.setItem("view-camera"+VeryEngine.projectId,JSON.stringify(obj));
        }
    }

    public get Camera(){
        return this.veryCamera.camera;
    }

    public set mode(val:number){
        if(this.veryCamera.camera.mode!=val){
            this.beforeView();
            this.veryCamera.camera.mode=val;
            this.afterView();
        }
    }

    public get mode(){
        return this.veryCamera.camera.mode;
    }

    private beforeView(){
        if(this.viewConunt==0){
            for(let id in this.beforeViewUpdate){
                for(let tmp of this.beforeViewUpdate[id])
                tmp(VeryEngine.pickedEntity,VeryEngine.pickedEntities);
            }
        }
        this.viewConunt++;
    }

    private afterView(){
        this.viewConunt--;
        if(this.viewConunt==0){
            for(let id in this.afterViewUpdate){
                for(let tmp of this.afterViewUpdate[id])
                tmp(VeryEngine.pickedEntity,VeryEngine.pickedEntities);
            }
        }
    }
    public onPointerDown(evt:BABYLON.IMouseEvent){
        if(evt.button>0){
            let rect=VeryEngine.canvas.getBoundingClientRect();
            if(evt.button==2){
                this.isCamRot=true;
            }else{
                this.isCamMove=true;
                this.cameraX = this.veryCamera.right;
                this.cameraY = this.veryCamera.up;
                this.initScreenPos = new BABYLON.Vector3(evt.clientX - rect.left, rect.height - evt.clientY, this.targetOnScreenPosition.z);

                // targetOnScreenPosition.z为目标物体到相机xmidbuttonDownPositiony平面的法线距离
                this.targetOnScreenPosition = Tools.worldToScreenPoint(this.targetPosition, VeryEngine.scene, this.veryCamera.camera, VeryEngine.engine);
                this.initPosition.copyFrom(this.targetPosition);
            }
            this.beforeView();
        }
    }
    public onPointerUp(evt:BABYLON.IMouseEvent){
        if(evt.button>0){
            if(evt.button==2)
                this.isCamRot=false;
            else
                this.isCamMove=false;
            this.afterView();
        }
    }

    public onPointerMove(evt:BABYLON.IPointerEvent){
        if(this.isCamRot)
        {
            this.x += evt.movementX * 250 * 0.002;
            this.y -= -evt.movementY * 120 * 0.002;
            this.y = Tools.clampAngle(this.y, -360, 360);
            this.storeRotation = BABYLON.Quaternion.FromEulerVector(Tools.eulerAngleToRadian(new BABYLON.Vector3(this.y, this.x, 0))); 
            this.veryCamera.rotationQuaternion = this.storeRotation;
            this.veryCamera.position=Tools.quatMultiplyVector3(this.storeRotation, new BABYLON.Vector3(0.0, 0.0, -this.cameraDistance)).add(this.targetPosition);
        }
        if(this.isCamMove&&!VeryEngine.showBabylon){
            let rect=VeryEngine.canvas.getBoundingClientRect();
            let curScreenPos = new BABYLON.Vector3(evt.clientX - rect.left, rect.height - evt.clientY, this.targetOnScreenPosition.z);
            let moveSpeed=1;
            //0.01这个系数是控制平移的速度，要根据相机和目标物体的distance来灵活选择
            moveSpeed = this.cameraDistance * 0.005;

            this.targetPosition = this.initPosition.subtract(this.cameraX.scale(curScreenPos.x - this.initScreenPos.x).add(this.cameraY.scale(curScreenPos.y - this.initScreenPos.y)).scale(1 * moveSpeed));
            //重新计算位置
            this.veryCamera.position=Tools.quatMultiplyVector3(this.storeRotation, new BABYLON.Vector3(0.0, 0.0, -this.cameraDistance)).add(this.targetPosition);
        }
    }
    private isWheel=false;
    private latelyWheel:number;
    private viewConunt=0;
    public onMouseWheel(evt: WheelEvent) {
        let rect=VeryEngine.canvas.getBoundingClientRect();
        if(evt.clientX>rect.left&&evt.clientX<rect.left+rect.width&&evt.clientY>rect.top&&evt.clientY<rect.top+rect.height){
            if(!this.isWheel){
                if(this.viewConunt==0)
                for(let id in this.beforeViewUpdate){
                    for(let tmp of this.beforeViewUpdate[id])
                    tmp(VeryEngine.pickedEntity,VeryEngine.pickedEntities);
                }
                this.viewConunt++;
                this.isWheel=true;
                let tmp=setInterval(()=>{
                    if(new Date().getTime()-this.latelyWheel>300){
                        this.isWheel=false;
                        this.viewConunt--;
                        if(this.viewConunt==0){
                            for(let id in this.afterViewUpdate){
                                for(let tmp of this.afterViewUpdate[id])
                                tmp(VeryEngine.pickedEntity,VeryEngine.pickedEntities);
                            }
                        }
                        clearInterval(tmp);
                    }
                },100)
            }
            this.latelyWheel=new Date().getTime();
            if (this.cameraDistance >= 0.1 && this.cameraDistance <= 450000) {
                this.cameraDistance += evt.deltaY * this.cameraDistance * 0.00033;
            }
            if (this.cameraDistance < 0.1) {
                this.cameraDistance=0.1
            }
            if (this.cameraDistance > 450000) {
                this.cameraDistance = 450000;
            }
            this.veryCamera.position=Tools.quatMultiplyVector3(this.storeRotation, new BABYLON.Vector3(0.0, 0.0, -this.cameraDistance)).add(this.targetPosition);
            this.veryCamera.orthoSize=this.cameraDistance*0.0007;
        }
    }

}