import {addEntityClass,ATTRIB, BUTTON, IEDAttrib, IEDProxyFactory} from "../../engine/IEDProxy"
import { VeryEngine,DataType} from "../../engine";
import { IEDGUI } from "./IEDGUI";
import { IEDTransform } from "../IEDTransform";
import { IEDEntity } from "../IEDEntity";


@addEntityClass
export class Canvas extends IEDGUI{

    public get subtype(): string {
        return "canvas";
    }
    public is2D=true;

    protected realLoad(): void {
        
    }
    public filterParentType(parent: IEDEntity): boolean {
        return parent.type == "root";
    }

    async Load(){
        this.sceneObj = document.createElement("div");
        this.sceneObj.classList.add("layout-gui"); // 添加 class
        // 获取父元素
        const parent = document.getElementById("layout-viewport");
        // 添加 div 元素到父元素前面
        parent.append(this.sceneObj);
        IEDGUI.lastCanvas = this;
    }
    @BUTTON
    public to3D={
        name:"2D画布转3D画布",
        action() {
            this.set("subtype","3d-canvas");
        },
        
    }
}

@addEntityClass
export class Canvas3D extends IEDTransform{
    public get type(): string {
        return "gui"
    }
    public get subtype():string{
        return "3d-canvas"
    }

    protected dispose(): void {
        this.guiManager.dispose();
        this.sceneObj.dispose();
    }
    public is2D=false
    private guiManager: BABYLON.GUI.AdvancedDynamicTexture;
    public sceneObj: BABYLON.AbstractMesh;
    protected async Load(): Promise<void> {
        let size=VeryEngine.version=="5.0"?1000:10;
        this.sceneObj = BABYLON.MeshBuilder.CreateGround(this.name,{ width: size, height: size, subdivisions: 10 },VeryEngine.scene);
        this.guiManager =BABYLON.GUI.AdvancedDynamicTexture.CreateForMesh(this.sceneObj);
        this.guiManager.scaleTo(this.get("gui.width"), this.get("gui.height"));
        this.sceneObj.id=this.id;
        if(VeryEngine.EditMode)
        this.sceneObj.showBoundingBox=true;
    }

    protected setChild(child: IEDGUI): void {
        if(child.type!="gui"){
            return
        }
        if(child.is2D==false&&(child.sceneObj as BABYLON.GUI.Control).parent){
            (child.sceneObj as BABYLON.GUI.Control).parent.removeControl((child.sceneObj as BABYLON.GUI.Control));
        }
        if(child.is2D!=this.is2D){
            if(child.sceneObj){
                child["dispose"]();
            }
            //针对gui特殊情况，改成设置父子关系的时候根据父物体的类型进行创建sceneObj和初始化的操作
            //目的是为了可以在3d、2d之间相互拖拽，毕竟它们的数据结构一致
            child.is2D=this.is2D;
            child["realLoad"](this.is2D);
            IEDProxyFactory.loadComplete(child,false);
            child.initDraggable();
            for(let guiEntity of child.children){
                child["setChild"](guiEntity as IEDGUI,null);
            }
        }
        let container=this.guiManager.rootContainer;
        (container as BABYLON.GUI.Container).addControl((child.sceneObj as BABYLON.GUI.Control));
        let last=(container as BABYLON.GUI.Container).children.pop()
        let index=this.children.indexOf(child);
        (container as BABYLON.GUI.Container).children.splice(index,0,last);
    }

    public get rootContainer(){
        return this.guiManager.rootContainer;
    }

    @ATTRIB("gui.width")
    public with:IEDAttrib<DataType.Number>={
        name:"画布宽度",
        type:DataType.Number,
        onchange(this:Canvas3D,_,isFirst){
            if(!isFirst){
                this.setSize()
            }
        },
        default:1024
    }

    @ATTRIB("gui.height")
    public height:IEDAttrib<DataType.Number>={
        name:"画布高度",
        type:DataType.Number,
        onchange(this:Canvas3D,_,isFirst){
            this.setSize();
        },
        default:1024
    }

    @BUTTON
    public to2D={
        name:"3D画布转2D画布",
        action() {
            this.set("subtype","canvas");
        },
        
    }

    private setSize(){
        var tmpControlArray: BABYLON.GUI.Control[] = [];
        for (var i = 0; i < this.guiManager.rootContainer.children.length; i++) {
            tmpControlArray.push(this.guiManager.rootContainer.children[i]);
        }
        this.guiManager.rootContainer.clearControls();
        this.guiManager.scaleTo(this.get('gui.width'), this.get('gui.width'));
        for (var i = 0; i < tmpControlArray.length; i++) {
            this.guiManager.rootContainer.addControl(tmpControlArray[i]);
        }
    }
}