 import { Item } from "./Item";
import {AbstractContent,addContent, contentRefs} from "./AbstractContent"
import {ByteBuffer} from "../util/ByteBuffer"
import { ContentType } from "./ContentType";

@addContent
export class ContentCopy extends AbstractContent {
    //分两种情况，一种是撤销情况，删除一个对象时，实时记录删除前的值，这时候不存在协同的情况，只需要记录删除的值
    //第二种是，将一个对象移动到另外一个地址，这时候需考虑协同情况，不能实时删除对象，
    //只需要记录拷贝对象的id和长度，等到接收item指令时，通过记录的id拷贝出content，然后删除拷贝对象的content
    //todo 还是不对，需考虑 不同人进行 a=>b=>c操作, 当第一个人撤销时如何处理，当c已经被删除时如何处理
    constructor (items:{client:number,clock:number,content:AbstractContent}[]) {
      super();
      this._items=items;
    }
  
    getLength () {
      return 0;
    }
  
    public get refID(): number {
      return 4;
    }

    getContent () {
      return this._items;
    }
  
    isCountable () {
      return false;
    }
  
    splice (offset:number) {
      return null
    }
  
    mergeWith (right:any) {
      return null
    }
    private _items:{client:number,clock:number,content:AbstractContent}[]=[];
    integrate (item:Item) {
      let first=true;
      for(let tmp of this._items){
          let content=tmp.content;
          if(content instanceof ContentType){
            let delParent=item.parent.doc.getParentDelStructByID({client:tmp.client,clock:tmp.clock});
            if(delParent){
              content.reset(delParent);
            }
          }
          if(first){
              first=false;
              item.content=content;
              item.length=content.getLength();
              item.info=content.isCountable()?2:0;
              content.integrate(item);
          }else{
              let target=item.parent.doc.getItem({client:tmp.client,clock:tmp.clock});
              //copy复原对象 必定是被delete的，故无需考虑merge
              if(target.id.clock<tmp.clock){
                target=item.parent.doc.splitItem(target,tmp.clock-target.id.clock);
              }
              if(target.length>tmp.content.getLength()){
                item.parent.doc.splitItem(target,tmp.content.getLength());
              }
              target.content=content;
              target.info=content.isCountable()?2:0;
              content.integrate(target);
          }
      }
    }

    delete () {
      
    }

    write (buff:ByteBuffer) {
     for(let tmp of this._items){
      buff.WriteUshort(tmp.client);
      buff.WriteUint(tmp.clock);
      buff.WriteByte(tmp.content.refID);
      tmp.content.write(buff);
     }
    }

    public reset(value: any){
      
    }
  
    read(buff:ByteBuffer){
     let copy=new ContentCopy(this.buff2Obj(buff));
     return copy;
    }

    buff2Obj(buff:ByteBuffer){
      let obj=[]
      while(buff.ReadableBytes()){
        let client=buff.ReadUshort();
        let clock=buff.ReadUint();
        let refId=buff.ReadByte();
        let content=contentRefs[refId](buff);
        obj.push({client:client,clock:clock,content:content});
      }
      return obj
    }

    value() {
      return null
    }

    public copy() {
      return null;
    }
  }