import { DMap } from "../djs/type";
import { IEDFolder } from "../assets/IEDFolder";
import { VeryEngine } from "../engine/VeryEngine";
import { AssetsPanel } from "../assets-panel";
import { IEDTexture } from "../assets/IEDTexture";


import backgroundImage from "../static/backgroundImage.png";
import valueImage from "../static/valueImage.png";
import thumb from "../static/thumb.png";

export class SystemFolder{
    constructor(assetPanel:AssetsPanel){
        let tmp=[];
        tmp.push(this.create("滑动条背景.png","backgroundImage",backgroundImage))
        tmp.push(this.create("滑动条前景.png","valueImage",valueImage));
        tmp.push(this.create("滑块.png","thumb",thumb));
        //系统资源
        let map=new DMap();
        map.set("name","系统资源");
        map.set("id","system")
        map.set("path",["root"]);
        map.set("type","folder");
        map.set("hide",true);
        let systemFolder=new IEDFolder(map);
        systemFolder.dealWithParent()
        if(VeryEngine.EditMode)
            assetPanel.addAsset(systemFolder);
        for(let unit of tmp){
            let map=new DMap();
            map.set("name",unit.name);
            map.set("id",unit.id)
            map.set("path",["system"]);
            map.set("type","texture");
            let fileMap=new DMap();
            fileMap.set("filename",unit.name)
            map.set("file",fileMap)
            let tmp=new IEDTexture(map);
            tmp.loadType="*"
            tmp.loadComplete=true;
            tmp.assetObj=unit.base64;
            tmp.dealWithParent();
            if(VeryEngine.EditMode)
                assetPanel.addAsset(tmp)
        }
    }

    private create(name:string,id:string,base64:string){
        return {name:name,id:id,base64:base64};
    }
}