import { ContentType } from "../content";
import {Item} from "../content/Item";
import {Doc} from "./Doc";

export class AbstractType {
    public _item:Item;
    public _map:Map<string,Item>=new Map();
    public _start:Item=null;
    public doc:Doc;
    public _length=0;
    public _searchMarker=null;
    public mapSetAct:{[group:string]:{[key:string]:any[]}}={};
    public mapGlobalAct={update:[],delete:[]};

    public insertAct:((index:number,value:any,config:{deleted:boolean})=>void)[]=[]
    public get refID(){
        return 0
    }

    public _integrate (y:Doc, item:Item) {
        this.doc = y
        this._item = item;
    }

    //获取item操作信息
    public mapGet(key:string){
        return this._map.get(key);
    }
    
    //map类数据设置，可能时local激活，也可能时network发送过来
    public mapSet(key:string,item:Item,unable?:boolean){
        this._map.set(key,item);
        //set的delete操作不会触发响应
        if(!unable&&!item.deleted){
            item.parent.doc.addFrameItem(item);
        }
    }

    //local 删除时候调用
    public destroy(undo:boolean){
        if(!this._item.deleted){
            this.doc.createTranscation("local");
            this._item.delete();
            this._item.write();
            this.doc.frameEndAndSend({isNetwork:true,undoStack:undo});
        }
    }

    //清空绑定的响应
    public deepClear(){
        this.clear();
        this._map.forEach(item => {
            item.delete(undefined,undefined,true);
        })
        let start=this._start;
        while(start){
            if(!start.deleted){
                start.delete(undefined,undefined,true);
                if(start.right){
                    start.right.mergeWith(start);
                }
            }
            start=start.left;
        }
    }

    public clear(){
        this.mapSetAct={};
        this.mapGlobalAct={update:[],delete:[]};;
        if(this._item&&this._item.deleted){
            this.doc.addParentDelStruct(this,this._item.id);
        }
    }

    public jsonParse(){
        let obj:any;
        if(this.refID==1){
            obj={};
            this._map.forEach((value,key)=>{
                if(!value.deleted){
                    if(value.content instanceof ContentType){
                        obj[key]=value.content.value().jsonParse();
                    }else{
                        let val=value.content.value();
                        if(val!=null){
                            obj[key]=val;
                        }
                    }
                }
            })
        }else{
            obj=[];
            let start=this._start;
            while(start){
                if(!start.deleted){
                    let val;
                    if(start.content instanceof ContentType){
                        val=start.content.value().jsonParse();
                    }else{
                        val=start.content.value(true);
                    }
                    if(val instanceof Array)
                    obj.push(...val);
                    else
                    obj.push(val);
                }
                start=start.right;
            }
        }
        return obj;
    }
}