import { DataType, VeryEngine } from "../engine";
import {  IEDAsset } from ".";
import { ATTRIB, addAssetClass,IEDAttrib } from "../engine/IEDProxy";

@addAssetClass
export class IEDFolder extends IEDAsset{

    public get type(): string {
        return "folder"
    }
    public assetObj: string;

    public doubleClick(): void {
        VeryEngine.pickAssetFolder(this.id);
    }
    public get Priority(){
        return 0;
    }

    protected async Load(){
    }

    public getEmptyID(name:string){
        for(let child of this.children){
            let childAsset=VeryEngine.shareBox.id2Asset[child];
            if(name==childAsset.name){
                return childAsset.id;
            }
        }
        return "";
    }

    public get suffix(): string[] {
        return [];
    }

    @ATTRIB("name")
    public attrNamestr:IEDAttrib<DataType.String>={
        type:DataType.String,
        name:"名字",
    }
}