import { PreviewMaterial, VeryEngine} from "../../engine";
import { IEDAsset, IEDFolder} from "..";
import { addShare} from "../../engine";
import { Tools } from "../../utility/Tools";
import { DMap } from "../../djs/type";

export abstract class IEDMaterial extends IEDAsset{
    private previewMat:PreviewMaterial;
    public get type(): string {
        return "material"
    }

    public dataId:string;
    public get suffix(): string[] {
        return [];
    }
    public preview(pre?:PreviewMaterial){
        if(VeryEngine.EditMode){
            if(pre){
                this.previewMat=pre;
                this.onceOnlyLoad().then(()=>{
                    this.previewMat.createMatPreview(this);
                })
            }else{
                if(this.loadComplete){
                    this.previewMat.createMatPreview(this);
                }
            }
        }
    }

    public assetObj:any;

    @addShare
    public static matID2AssetID:{[key:string]:string}={};

    public previewImg;
    private tobeloadDiv:HTMLElement;
    public setPreview(base64:string){
        if(this.tobeloadDiv)
        this.tobeloadDiv.style.backgroundImage="url("+base64+")";
        this.previewImg=base64;
    }

    public getPreview(div:HTMLElement){
        this.tobeloadDiv=div;
        if(this.previewImg){
            div.style.backgroundImage="url("+this.previewImg+")";
        }
    }
    public init(): void {
        this.dataId=this.get("data.id");
        IEDMaterial.matID2AssetID[this.dataId]=this.id;
    }

    protected async upload(matData:any,folderId?:string){
        let path=[];
        if(folderId!=null){
            if(!folderId) path=[];
            else path=[folderId];
        }else if(VeryEngine.commonJson.get("pickAssetFolder")){
            path=[VeryEngine.commonJson.get("pickAssetFolder")]
        }else{
            path=[]
        }
        let matID=Tools.assetID();
        let createdAt=Tools.createdTime();
        return {
            id: matID,
            type: 'material',
            subtype: (matData.customType && matData.customType !== '') ? matData.customType : 'BABYLON.StandardMaterial',
            createdAt: createdAt,
            name: matData.name,
            data: matData,
            path: path
        };
    }

    public async createUploadData(file: any,folderId?:string): Promise<void> {
        let data=await this.upload(file,folderId);
        let parent="root";
        if(data.path.length>0)
            parent=data.path[data.path.length-1];
        for(let key in data.data){
            if(data.data[key]){
                if(data.data[key].name){
                    data.data[key].texture_id=VeryEngine.getAsset<IEDFolder>(parent).getEmptyID(data.data[key].name);
                }
            }
        }
        VeryEngine.shareBox.assetMap.set(data.id,new DMap(data));
    }

    public dispose(): void {
        if(this.dataId)
            delete IEDMaterial.matID2AssetID[this.dataId]
        if(this.assetObj)
            this.assetObj.dispose();
    }
}