import { AbstractContent, ContentDeleted, ContentType } from ".";
import { AbstractType, Doc,DMap} from "../type";

export class Item {
    public parent: AbstractType;
    private parentID:ID=null;
    public left: Item = null;
    public right: Item = null;
    public origin: ID = null;
    public rightOrigin: ID = null;
    public parentSub: string = null;
    public id: ID;
    public length: number = 0;
    public content: AbstractContent;
    public info:number;
    public group:string;

    constructor(id: ID, left: Item, origin: ID, right: Item, rightOrigin: ID, parent: AbstractType|ID, parentSub: string, content: AbstractContent) {
        this.id = id;
        this.left = left;
        this.origin = origin;
        this.right = right;
        this.rightOrigin = rightOrigin;
        if(parent instanceof AbstractType)
            this.parent = parent;
        else
            this.parentID=parent;
        this.parentSub = parentSub;
        this.content = content;
        this.length=content.getLength();
        this.info = this.content.isCountable() ? 2 : 0;
        if(content.refID==2)
            this.info|=4;
    }

    public updateMiss(doc:Doc){
        if(this.parentID){
            if(this.parentID.clock >= doc.getState(this.parentID.client)){
                doc.addMiss(this.parentID,this);
                return false;
            }else{
                let item=doc.getItem(this.parentID);
                if(item.deleted){
                    //比如甲立方体已被删除，乙移动了位置
                    this.parent=doc.getParentDelStruct(item);
                }else{
                    this.parent=doc.getItem(this.parentID).content.value();
                }
                this.parentID=null;
            }
        }
        if(this.origin&&!this.left){
            if(this.origin.clock >= doc.getState(this.origin.client)){
                doc.addMiss(this.origin,this);
                return false;
            }else{
                this.left=doc.getItem(this.origin);
            }
        }
        if(this.rightOrigin&&!this.right){
            if(this.rightOrigin.clock >= doc.getState(this.rightOrigin.client)){
                doc.addMiss(this.rightOrigin,this);
                return false;
            }else{
                this.right=doc.getItem(this.rightOrigin);
            }
        }

        return true;
    }

    public integrate() {
        if (this.parent) {
            let doc=this.parent.doc;
            let originItem:Item;
            if(this.origin){
                originItem=doc.getItem(this.origin);
                if(originItem.id.clock+originItem.length>this.origin.clock+1){
                    doc.splitItem(originItem,this.origin.clock-originItem.id.clock+1)
                }
            }
            if ((!this.left && (!this.right || this.right.left !== null)) || (this.left && this.left.right !== this.right)) {
                let left = this.left
                let o: Item;
                if (left !== null) {
                    o = left.right
                } else if (this.parentSub !== null) {
                    o = this.parent.mapGet(this.parentSub) || null
                    while (o !== null&& o.left !== null) {
                        o = o.left
                    }
                } else {
                    o = (this.parent)._start;
                }
                let conflictingItems = new Set();
                let itemsBeforeOrigin = new Set();
                while (o !== null && o !== this.right) {
                    itemsBeforeOrigin.add(o)
                    conflictingItems.add(o)
                    if (this.compareIDs(this.origin, o.origin)) {
                        if (o.id.client < this.id.client) {
                            left = o
                            conflictingItems.clear()
                        } else if (this.compareIDs(this.rightOrigin, o.rightOrigin)) {
                            break
                        }
                    } else if (o.origin !== null && itemsBeforeOrigin.has(doc.getItem(o.origin))) {
                        if (!conflictingItems.has(doc.getItem(o.origin))) {
                            left = o
                            conflictingItems.clear()
                        }
                    } else {
                        break
                    }
                    o = o.right
                }
                this.left = left
            }
            if (this.left !== null) {
                const right = this.left.right
                this.right = right
                this.left.right = this
            } else{
                let r: Item;
                if (this.parentSub !== null) {
                    r = this.parent.mapGet(this.parentSub) || null
                    while (r !== null && r.left !== null) {
                        r = r.left
                    }
                } else {
                    r = (this.parent)._start;
                    (this.parent)._start = this
                }
                this.right = r
            }
            if (this.right !== null) {
                this.right.left = this
            } else if (this.parentSub !== null) {
                let r=this.parent.mapGet(this.parentSub);
                //todo 只是针对引擎数据特点这么设计的，缺乏通用性
                //todo 问题来源于物体连续移动两次，{添加:x1},{删除:x1,添加x2},撤销一次删除x2,添加x3 x3来源等效于x1
                //todo 当再次撤销的时候删x1是无效的
                if(r==null||r.deleted){
                    if((this.parent.doc.mode=="local"||this.parent.doc.mode=="undo")&&this.parent.doc.project)
                        this.parent.doc.addDefaultDel(this.parent as DMap,this.parentSub);
                }
                this.parent.mapSet(this.parentSub, this)
                if (this.left !== null) {
                    this.left.delete()
                }
            }
            if (this.parentSub === null){
                if(this.countable && !this.deleted) {
                    (this.parent)._length += this.length;
                }
                this.parent.doc.addFrameItem(this);
            }
            doc.addStruct(this);
            this.content.integrate(this)
            if ((this.parent)._item !== null && (this.parent)._item.deleted  || (this.parentSub !== null && this.right !== null)) {
                //当父物体已经被删除时，必须将子物体删除
                //撤销重做时，新建的内容必须是新的item，不然子物体会有冲突
                this.delete()
            }else{
                //添加过程不存在需要向右合并的可能
                if(this.left){
                    this.left.mergeWith(this);
                }
            }
            if(originItem&&originItem.right){
                originItem.mergeWith(originItem.right);
            }
            doc.repairMiss(this.id,this.content.getLength());
        }
    }

    public splitItem(diff:number){
        let rightItem=new Item(
            {client:this.id.client,clock:this.id.clock+diff},
            this,
            {client:this.id.client,clock:this.id.clock+diff-1},
            this.right,
            this.rightOrigin,
            this.parent,
            this.parentSub,
            this.content.splice(diff)
        )
        this.length=diff;
        if (this.deleted) {
            rightItem.info |= 4;
        }
        this.right=rightItem;
        if (rightItem.right !== null) {
            rightItem.right.left = rightItem
        }
        if (rightItem.parentSub !== null && rightItem.right === null &&rightItem.parent instanceof DMap) {
            rightItem.parent.mapSet(rightItem.parentSub, rightItem,true)
        }
        return rightItem;
    }

    public delete(clock?:number,len?:number,no_trigger?:boolean) {
        if (!this.deleted) {
            let item:Item=this;
            if(clock&&clock>item.id.clock){
                item=item.parent.doc.splitItem(item,clock-item.id.clock);
            }
            if(len&&item.id.clock+item.length>clock+len){
                item.parent.doc.splitItem(item,clock-item.id.clock+len);
            }
            const parent = item.parent;
            if (item.countable && this.parentSub === null) {
                parent._length -= item.length;
            }
            item.info |= 4;
            if((item.parent.doc.mode=="local"||item.parent.doc.mode=="undo")&&!no_trigger&&item.parent.doc.project){
                //假如当前content类型为ContentType，会记录所有子item的content
                item.parent.doc.addToDeleteSet(item.id.client,item.id.clock,item.length,item.content);
            }
            if(!item.parentSub&&!no_trigger){
                let tmp=new Item(item.id,null,null,null,null,item.parent,null,item.content.copy());
                tmp.info|=4
                item.parent.doc.addFrameItem(tmp);
            }
            item.content.delete();
            item.content=new ContentDeleted(this.length);
            if(item.right){
                item.mergeWith(item.right);
            }
            else{
                //若map类型删除的是最后一个则需要触发监听
                if(item.parentSub&&!no_trigger){
                    item.parent.doc.addFrameItem(item);
                }
            }
            if(item.left){
                item.left.mergeWith(item);
            }
        }
    }

    private compareIDs(a: ID, b: ID) {
        return a === b || (a !== null && b !== null && a.client === b.client && a.clock === b.clock)
    }

    get lastId ():ID {
        if(this.id)
            return this.length === 1 ? this.id : {client:this.id.client,clock:this.id.clock + this.length - 1}
        else
            return null;
    }

    public mergeWith(right:Item) {
        if(this.compareIDs(right.origin,this.lastId)&&this.right===right&&
        this.compareIDs(this.rightOrigin,right.rightOrigin)&&this.id.client===right.id.client&&
        this.id.clock+this.length===right.id.clock&&this.deleted===right.deleted
        &&(this.content as any).constructor===(right.content as any).constructor&&this.content.mergeWith(right.content)){
          const searchMarker = this.parent._searchMarker
          if (searchMarker) {
            searchMarker.forEach(marker => {
              if (marker.p === right) {
                marker.p = this
                if (!this.deleted && this.countable) {
                  marker.index -= this.length
                }
              }
            })
          }
          this.right = right.right
          if (this.right !== null) {
            this.right.left = this
          }
          let doc=this.parent.doc;
          doc.removeItem(right.id);
          this.length += right.length;
          if(this.parentSub)
          if(this.parent.mapGet(this.parentSub)===right){
            this.parent.mapSet(this.parentSub,this,true);
          }
          return true
        }
        return false
    }

    public get deleted () {
        return (this.info & 4) > 0
    }

    public get countable () {
        return (this.info &2) > 0
    }

    write(){
        if(this.parent.doc.socket){
            let buff=this.parent.doc.socket.buff;
            buff.WriteUshort(this.id.client);
            buff.WriteUint(this.id.clock);
            const info =this.content.refID|(this.origin === null ? 0 : 64) |
            (this.rightOrigin === null ? 0 : 32) |
            (this.parentSub === null ? 0 : 16)|
            (this.parent._item===null?0:8)
            buff.WriteByte(info);
            this.content.write(buff);
            if(this.origin){
                buff.WriteUshort(this.origin.client);
                buff.WriteUint(this.origin.clock);
            }
            if(this.rightOrigin){
                buff.WriteUshort(this.rightOrigin.client);
                buff.WriteUint(this.rightOrigin.clock);
            }
            if(this.parentSub){
                buff.WriteString(this.parentSub);
            }
            if(this.parent._item){
                buff.WriteUshort(this.parent._item.id.client);
                buff.WriteUint(this.parent._item.id.clock);
            }else{
                buff.WriteString(this.parent.doc.findRootTypeKey(this.parent));
                buff.WriteByte(this.parent.refID);
            }
        }
    }

    public reset(value){
        this.content.reset(value);
        this.parent.doc.createTranscation("force");
        this.parent.doc.addFrameItem(this);
        this.parent.doc.frameEnd();
    }
}

export interface ID {
    client: number,
    clock: number;
}