import {addEntityClass,ATTRIB, IEDAttrib} from "../../engine/IEDProxy"
import { VeryEngine,DataType} from "../../engine";
import { IEDGUI } from "./IEDGUI";


@addEntityClass
export class Image extends IEDGUI{
    public get subtype(): string {
        return "image";
    }

    protected realLoad(is2D:boolean){
        if(is2D){
            this.sceneObj = document.createElement("img");
            this.sceneObj.draggable = false;
            this.sceneObj.style.position = "absolute";
        }else{
            this.sceneObj = new BABYLON.GUI.Image(this.name, "");
            this.sceneObj.isPointerBlocker = true;
        }
    }

    private title="图片"

    @ATTRIB("gui.through")
    public through:IEDAttrib<DataType.Bool>={
        name:"是否点击穿透",
        type:DataType.Bool,
        onchange(this:Image,val){
            if(this.is2D){
                if (!VeryEngine.EditMode) {
                    if (val) {
                        (this.sceneObj as HTMLImageElement).style.pointerEvents = "none";
                    } else {
                        (this.sceneObj as HTMLImageElement).style.pointerEvents = "auto";
                    }
                } else {
                    (this.sceneObj as HTMLImageElement).style.pointerEvents = "auto";
                }
            }
        },
        title:this.title
    }

    @ATTRIB("gui.source")
    public source:IEDAttrib<DataType.TextureBox>={
        name:"图片",
        type:DataType.TextureBox,
        async onchange(this:Image,val) {
            let picAsset = VeryEngine.shareBox.id2Asset[val];
            if (picAsset) {
                await picAsset.onceOnlyLoad();
                if(this.is2D){
                    (this.sceneObj as HTMLImageElement).src = picAsset.assetObj;
                }else{
                    if(!(this.sceneObj as BABYLON.GUI.Image).domImage)
                        (this.sceneObj as BABYLON.GUI.Image).domImage=document.createElement("img");
                    (this.sceneObj as BABYLON.GUI.Image).domImage.src=picAsset.assetObj
                }
            }else{
                if(this.is2D){
                    (this.sceneObj as HTMLImageElement).src=""
                }else{
                    (this.sceneObj as BABYLON.GUI.Image).domImage=document.createElement("img");
                    (this.sceneObj as BABYLON.GUI.Image)._markAsDirty()
                }
            }
        },
        title:this.title
    }

    @ATTRIB("gui.stretch")
    public stretch:IEDAttrib<DataType.DropDown>={
        name:"填充模式",
        type:DataType.DropDown,
        onchange(this:Image,val){
            if(this.is2D){
                if (val == 1) {
                    (this.sceneObj as HTMLImageElement).style.objectFit = "contain";
                } else {
                    (this.sceneObj as HTMLImageElement).style.objectFit = "initial";
                }
            }else{
                (this.sceneObj as BABYLON.GUI.Image).stretch  = val
            }
        },
        extra:["自由拉伸","原始比例"],
        title:this.title
    }
}