import { IEDEntity } from "../entities";
import { VeryEngine } from "../engine/VeryEngine";
import { installPlugin } from "./IEDPlugin";
import { ClickMode, IButton, IDropDown, Iplugin } from "./Iplugin";
import { Message } from "../utility/Message";
@installPlugin
class FixStartPlugin extends Iplugin {
    public id = "FixStart";
    private publish=false;
    public button:IButton[]=[{
        img:"icon-jujiao",
        tips:"聚焦(ctrl+f)",
        enable:(currentEntity:IEDEntity)=>{
            if (currentEntity&&currentEntity.sceneObj instanceof BABYLON.TransformNode)
            VeryEngine.viewCamera.customView(currentEntity.sceneObj);
        },disable:()=>{

        },
        mode:ClickMode.once
    },{
        img:"icon-yunhang",
        tips:"运行",
        enable:()=>{
            let pub="";
            if(window.location.pathname.includes("index.html"))
                pub=window.location.pathname.replace("index.html","publish.html");
            else
                pub="/publish.html";
           window.open(window.location.protocol + '//' + window.location.host + pub+window.location.search)
        },disable:()=>{

        },
        mode:ClickMode.once
    },{
        img:"icon-moren",
        tips:"发布",
        enable:()=>{
            if(this.publish) {
                Message.showAlert({type:"warn",text:"正在发布中，请稍后再试",closeable:true})
                return;
            }
            this.publish=true;
            let xhr = new XMLHttpRequest();
            xhr.withCredentials=true;
            xhr.open('post', 'https://utp.veryengine.cn/Software/Release')
            xhr.setRequestHeader('Content-Type', 'application/x-www-form-urlencoded');
            xhr.onreadystatechange =()=>{
                if (xhr.readyState == 4) {
                    if (xhr.status == 200) {
                        let obj = JSON.parse(xhr.responseText);
                        if (obj.code == "00000") {
                            Message.showAlert({type:"success",text:"发布成功",closeable:true})
                        } else {
                            Message.showAlert({type:"error",text:"发布失败",closeable:true})
                        }
                        this.publish=false;
                    }
    ​
                }
            }
            xhr.send('softwareId='+VeryEngine.projectId);
        },
        mode:ClickMode.once
    },{
        img:"icon-chexiao",
        tips:"撤销(ctrl+z)",
        enable:()=>{
            VeryEngine.undoManager.undo();
        },
        disable:()=>{

        },
        mode:ClickMode.once
    },{
        img:"icon-huifu",
        tips:"重做(ctrl+x)",
        enable:()=>{
            VeryEngine.undoManager.redo();
        },
        disable:()=>{

        },
        mode:ClickMode.once
    }]

    public init(): void {
        VeryEngine.undoManager.addStackAction("undo",(count:number)=>{
            if(count!=0){
                this.button[3].allow(true);
            }else{
                this.button[3].allow(false);
            }
        })
        VeryEngine.undoManager.addStackAction("redo",(count:number)=>{
            if(count!=0){
                this.button[4].allow(true);
            }else{
                this.button[4].allow(false);
            }
        })
        this.button[3].allow(false);
        this.button[4].allow(false);
    }

    uninstall(): void {
    }
}
@installPlugin
class FixEndPlugin extends Iplugin {
    public id = "FixEnd";
    public button:IButton[]=[{
        img:"icon-genduo1",
        tips:"设置",
        children:[{
            tips:"全屏(空格)",
            enable:()=>{
                VeryEngine.hideDiv();
            },
            disable:()=>{
                VeryEngine.showDiv();
            }
        },{
            tips:"中英切换",
            enable:()=>{}
        },{
            tips:"返回项目管理",
            enable:()=>{
                window.location.href="https://meta.veryengine.cn/admin/#/home";
            },
            mode:ClickMode.once
        },{
            tips:"版本更新",
            enable:()=>{
                window.open("https://showdoc.cool360.com/web/#/12/1165");
            },
            mode:ClickMode.once
        }]
    },{
        img:"icon-wentifankui",
        tips:"问题反馈",
        enable:()=>{
            window.open("https://support.qq.com/products/404593")
        },
        mode:ClickMode.once
    }]

    public init(): void {
        window.addEventListener("keydown", (ev: KeyboardEvent) => {
            if(document.activeElement.nodeName=="INPUT"||document.activeElement.nodeName=="TEXTAREA") return;
            if(ev.keyCode==32){
                this.button[0].children[0].click();
            }
        })
    }

    uninstall(): void {
    }
}