    public static pickEntity(id:string,ctrlKey?:boolean){
        // if(!VeryEngine.EditMode) return;
        if(this._pickMoode=="not-allow"){
            return;
        }
        if(this._pickMoode=="force-multiple"){
            ctrlKey=true;
        }
        VeryEngine.commonJson.set("pickAsset", []);
        // VeryEngine.commonJson.set("pickAssetFolder", null,false,{group:"attr"});
        if(!ctrlKey){
            for(let act of this.pickAction){
                act(!!id);
            }
            VeryEngine.commonJson.set("pickEntity", [id]);
        } else {
            let tmp=VeryEngine.commonJson.get("pickEntity");
            let havePick=[];
            if(tmp){
                for(let i of tmp){
                    if(i){
                        havePick.push(i);
                    }
                }
            }
            if(id){
                let index=havePick.indexOf(id);
                if(index>=0){
                    havePick.splice(index,1);
                }else if(id){
                    havePick.push(id);
                }
            }
            for(let act of this.pickAction){
                act(havePick.length != 0);
            }
            VeryEngine.commonJson.set("pickEntity",havePick);
        }
    }

    public static pickEntities(ids:string[],multiple?:boolean ){
        if(this._pickMoode=="not-allow"){
            return;
        }
        if(this._pickMoode=="force-multiple"){
            multiple=true;
        }
        VeryEngine.commonJson.set("pickAsset", []);
        // VeryEngine.commonJson.set("pickAssetFolder", null,false,{group:"attr"});
        if(!multiple){
            for(let act of this.pickAction){
                act(ids.length != 0);
            }
            VeryEngine.commonJson.set("pickEntity", ids);
        }else{
            let tmp=VeryEngine.commonJson.get("pickEntity");
            let havePick = [];
            if(tmp)
            for(let i of tmp){
                if(i){
                    havePick.push(i);
                }
            }
            havePick.push(...ids);
            for(let act of this.pickAction){
                act(havePick.length != 0);
            }
            VeryEngine.commonJson.set("pickEntity",[...new Set(havePick)]);
        }
    }

