    public static isLoadComplete=false;
    public static async LoadComplete(){
        if(this.isLoadComplete)return;
        if(VeryEngine.EditMode){
            this.gloablEvent.triggerEvent("loadComplete");
            this.isLoadComplete=true;
            window.addEventListener("keydown", (ev: KeyboardEvent) => {
                if(ev.isStop) return;
                if(ev.ctrlKey){
                    if (ev.keyCode == 83) {
                        ev.preventDefault();
                        if (VeryEngine.change & 1) {
                            OSS.upLoadJsonConfig(
                                JSON.stringify({
                                    assets: VeryEngine.shareBox.assetMap.jsonParse(),
                                }),
                                "assets"
                            );
                        } 
                        if (VeryEngine.change & 2) {
                            OSS.upLoadJsonConfig(
                                JSON.stringify({
                                    scenes: [
                                        {
                                            entities: VeryEngine.shareBox.sceneMap.jsonParse(),
                                        },
                                    ],
                                }),
                                "scenes"
                            );
                        }
                        VeryEngine.change = 0;
                    }
                }
                if(document.activeElement.nodeName=="INPUT"||document.activeElement.nodeName=="TEXTAREA") return;
                if (ev.ctrlKey) {
                    if(ev.keyCode==90){
                        VeryEngine.undoManager.undo();
                    }else if(ev.keyCode==88){
                        VeryEngine.undoManager.redo();
                    }
                }
                if (ev.keyCode == 70) {
                    if (this.pickedEntity && this.pickedEntity.sceneObj instanceof BABYLON.TransformNode) VeryEngine.viewCamera.customView(this.pickedEntity.sceneObj);
                }
                if(ev.keyCode==46){
                    if(this.pickedEntity&&!this.pickedEntity.isDestroy&&this.pickedEntity.type!="root"){
                        let delFunc = async (entity: IEDEntity) => {
                            if (entity&&!entity.isDestroy) {
                                for (let child of [...entity.children]) {
                                    await delFunc(child);
                                }
                                entity.clearData();
                            }
                        };
                        delFunc(this.pickedEntity);
                    }
                }
            });
        } else if (!VeryEngine.EditMode && !VeryEngine.showBabylon) {
            VR.BabylonEngine.GUIScene=VeryEngine.scene;
            VR.BabylonEngine.Canvas=VeryEngine.canvas;
            VR.BabylonEngine.Engine=VeryEngine.engine;
            VR.BabylonEngine.Scene=VeryEngine.scene;
            VR.GameGlobal.projectID=VeryEngine.projectId;
            if(VeryEngine.version=="5.0"){
                let entrance: VR.VeryEngine = new VR.VeryEngine();
                for(let key in VeryEngine.shareBox.id2Entity){
                    let table=this.getEntity<IEDLogic>(key);
                    if(table&&table.type=="logic"){
                        if(table.isEnableDeep){
                            let tableAsset=table.source;
                            if(tableAsset){
                                await tableAsset.onceOnlyLoad();
                                let tableName = tableAsset.name.split(".")[0];
                                try {
                                    let data=JSON.parse(tableAsset.assetObj).table;
                                    entrance.init(data,tableName);
                                } catch (e) {
                                    // TODO: 可能会影响效率
                                    console.error(e);
                                }
                                let objects: VR.VE_Objects = VR.VE_Manager.objects(tableName);
                                VeryEngine.scene.onBeforeRenderObservable.add(() => {
                                    for (let i: number = 0; i < objects.count; i++) {
                                        let objectID: string = objects.getObjectID(i);
                                        objects.getVeryObject(objectID).update();
                                    }
                                });
                            }
                        }
                    }
                }
            }
            else if(VeryEngine.version=="5.1"){
                try {
                    for(let key in VeryEngine.shareBox.id2Entity){
                        let table=this.getEntity<IEDLogic>(key);
                        if(table&&table.type=="logic"){
                            if(table.isEnableDeep){
                                let tableAsset=table.source;
                                if(tableAsset){
                                    await tableAsset.onceOnlyLoad();
                                    let data:string[][]=JSON.parse(tableAsset.assetObj).table;
                                    let name=tableAsset.name.split(".");
                                    VR.Compiler.loadTable(table.parent.id, name[0], data);
                                }
                            }
                        }
                    }
                } catch (e) { // TODO: 可能会影响效率
                    console.error(e);
                }
                VR.Compiler.loadEnd();
                VeryEngine.engine.runRenderLoop(() => {
                    VR.Compiler.update();
                })
            }
            this.isLoadComplete=true;

        }else{
            this.isLoadComplete=true;
        }
    }

