    public static systemTags:{[name:string]:string[]}={};
    private static tagUsers: { [name: string]: { id: string; prop: string; func: (isAdd: boolean, id: string) => void }[] } = {};
    public static addTag(id:string,name:string){
        if(this.systemTags[name]){
            this.systemTags[name].push(id);
        }else{
            this.systemTags[name]=[id];
        }
        if(this.tagUsers[name]){
            for(let tmp of this.tagUsers[name]){
                tmp.func(true,id);
            }
        }
    }
    public static removeTag(id:string,name:string[]){
        for(let key in this.systemTags){
            if(this.systemTags[key].includes(id)&&!name.includes(key)){
                let index=this.systemTags[key].indexOf(id);
                this.systemTags[key].splice(index,1);
                if(this.systemTags[key].length==0){
                    delete this.systemTags[key];
                }
                if(this.tagUsers[key]){
                    for(let tmp of this.tagUsers[key]){
                        tmp.func(false,id);
                    }
                }
            }
        }
    }
    public static useTag(name:string,id:string,prop:string,func:(isAdd:boolean,id:string)=>void){
        let b=false;
        for(let key in this.tagUsers){
            for(let i=0;i<this.tagUsers[key].length;i++){
                if(this.tagUsers[key][i].id===id&&this.tagUsers[key][i].prop==prop){
                    this.tagUsers[key].splice(i,1);
                    b = true;
                    break;
                }
            }
            if(b) break;
        }
        if(name!=="empty"){
            let obj={id:id,prop:prop,func:func};
            if(this.tagUsers[name]){
                this.tagUsers[name].push(obj);
            }else{
                this.tagUsers[name] = [obj];
            }
            if(this.systemTags[name]){
                for(let id of this.systemTags[name]){
                    func(true,id);
                }
            }
        }
    }
