    public static hideDiv() {
        const nodes: HTMLElement[] = [document.querySelector("#layout-hierarchy"), document.querySelector("#layout-assets"), document.querySelector("#layout-attributes")];
        nodes.forEach((node) => {
            if(node){
            node.style.opacity = "0";
            switch (node.id) {
                case "layout-hierarchy":
                    node.style.left = "-276px";
                    break;
                case "layout-assets":
                    node.style.bottom = "-251px";
                    break;
                case "layout-attributes":
                    node.style.right = "-276px";
            }
        }
        });
    }

    public static showDiv() {
        const nodes: HTMLElement[] = [document.querySelector("#layout-hierarchy"), document.querySelector("#layout-assets"), document.querySelector("#layout-attributes")];
        nodes.forEach((node) => {
            if(node){
                node.style.opacity = "1";
                switch (node.id) {
                    case "layout-hierarchy":
                        node.style.left = "16px";
                        break;
                    case "layout-assets":
                        node.style.bottom = "16px";
                        break;
                    case "layout-attributes":
                        node.style.right = "16px";
                }
            }
        });
    }

