    public static entityRootId:string;

    public static async addEntityData(json:{resource_id:string,type:string,[pro:string]:any},parent?:string|IEDEntity,autoPick?:boolean){
        parent = parent ? parent: VeryEngine.shareBox.id2Entity[this.entityRootId];
        if(typeof parent =="string"){
            parent=this.getEntity<IEDEntity>(parent);
        }
        if(parent){
            parent.children.push(json.resource_id);
        }
        return await this.addEntityOnlyData(json,autoPick);
    }
    public static addEntityOnlyData(json:{resource_id:string,type:string,[pro:string]:any},autoPick?:boolean){
        return new Promise<IEDEntity>((resolve)=>{
            VeryEngine.shareBox.sceneMap.set(json.resource_id,json);
            this.entityReady.addEventListener(json.resource_id,()=>{
                if(autoPick){
                    VeryEngine.pickEntity(json.resource_id);
                }
                resolve(VeryEngine.shareBox.id2Entity[json.resource_id]);
            });
        });
    }

    public static addAssetData(json:{id:string,type:string,name:string,[pro:string]:any},folderId?:string){
        let path = [];
        if (folderId != null) {
            path = [folderId];
        } else if (VeryEngine.commonJson.get("pickAssetFolder")) {
            path = [VeryEngine.commonJson.get("pickAssetFolder")];
        } else {
            path = [];
        }
        json.path = path;
        VeryEngine.shareBox.assetMap.set(json.id, json);
        return VeryEngine.shareBox.id2Asset[json.id];
    }

