import {addEntityClass,ATTRIB, IEDAttrib} from "../engine/IEDProxy"
import { Tools } from "../utility/Tools";
import { VeryLight } from "../middleware/VeryLight";
import { VeryEngine,DataType, IED } from "../engine";
import { IEDFolder } from "../assets/IEDFolder";
import { IEDTransform } from "./IEDTransform";

export abstract class IEDLight extends IEDTransform{

    protected dispose(): void {
        this.sceneObj.dispose();
    }

    public sceneObj: VeryLight;
    public get type(): string {
        return "light"
    }

    protected lightTitle="灯光属性";

    @ATTRIB()
    public lightType;

    @ATTRIB()
    public diffuse:IEDAttrib<DataType.Color3>={
        name:"颜色",
        type:DataType.Color3,
        onchange(this:IEDLight,val) {
            this.sceneObj.light.diffuse = BABYLON.Color3.FromArray(val);
            this.sceneObj.light.specular = BABYLON.Color3.FromArray(val);
        },
        title:this.lightTitle
    }

    @ATTRIB()
    public intensity:IEDAttrib<DataType.Number>={
        name:"强度",
        type:DataType.Number,
        onchange(this:IEDLight,val) {
            this.sceneObj.light.intensity = val;
        },
        title:this.lightTitle,
        default:1
    }
}


@addEntityClass
export class HemisphericLight extends IEDLight{
    public get subtype(): string {
        return "hemispheric"
    }

    async Load(){
       let  light = new BABYLON.HemisphericLight(this.name, BABYLON.Vector3.Up(),VeryEngine.scene);
       this.sceneObj= new VeryLight(light, VeryEngine.scene);
       this.sceneObj.id=this.id
       light.excludeWithLayerMask=0x90000000
    }

    public rotation:IEDAttrib<DataType.Vector3>={
        name:"角度",
        type:DataType.Vector3,
        onchange(this:HemisphericLight,val){
            this.sceneObj.rotation = Tools.eulerAngleToRadian(BABYLON.Vector3.FromArray(val));
            // 环境光不跟着父物体发生位置变化
            (<BABYLON.HemisphericLight>this.sceneObj.light).direction.copyFrom(this.sceneObj.up);
        }
    }

    @ATTRIB()
    public groundColor:IEDAttrib<DataType.Color3>={
        name:"底色",
        type:DataType.Color3,
        onchange(this:IEDLight,val) {
            this.sceneObj.light['groundColor']=BABYLON.Color3.FromArray(val)
        },
        title:this.lightTitle,
        default:[0,0,0]
    }

    public lightType:IEDAttrib<DataType.String>={
        name:"灯光类型",
        type:DataType.String,
        default:"环境光",
        readonly:true,
        title:this.lightTitle,
    }
}

