@addEntityClass
export class SpotLight extends IEDLight{
    public get subtype(): string {
        return "spot"
    }

    async Load(){
       let  light = new BABYLON.SpotLight(this.name, BABYLON.Vector3.Zero(), new BABYLON.Vector3(0, -1, 0), Math.PI * 0.75, 8, VeryEngine.scene);
       this.sceneObj= new VeryLight(light, VeryEngine.scene);
       this.sceneObj.id=this.id
       light.excludeWithLayerMask=0x90000000
    }

    public lightType:IEDAttrib<DataType.String>={
        name:"灯光类型",
        type:DataType.String,
        default:"聚光灯",
        readonly:true,
        title:this.lightTitle,
    }

    @ATTRIB()
    public range:IEDAttrib<DataType.Number>={
        name:"光照范围",
        type:DataType.Number,
        onchange(this:IEDLight,val) {
            this.sceneObj.light.range = val;
        },
        title:this.lightTitle,
        default:10
    }

    @ATTRIB()
    public spotAngle:IEDAttrib<DataType.Slide>={
        name:"照射锥角",
        type:DataType.Slide,
        onchange(this:IEDLight,val) {
            this.sceneObj.light['angle'] = Tools.eulerAngleFloatToRadian(val);
        },
        extra:{max:360},
        title:this.lightTitle,
        default:135
    }

    @ATTRIB()
    public spotExponent:IEDAttrib<DataType.Number>={
        name:"衰减速率",
        type:DataType.Number,
        onchange(this:IEDLight,val) {
            this.sceneObj.light['exponent'] = val;
        },
        title:this.lightTitle,
        default:8
    }

    @ATTRIB()
    public projectionTexture:IEDAttrib<DataType.TextureBox>={
        name:"投影贴图",
        type:DataType.TextureBox,
        async onchange(this:IEDLight,val) {
            let textureAsset=VeryEngine.shareBox.id2Asset[val];
            if(textureAsset){
                await textureAsset.onceOnlyLoad();
                this.sceneObj.light['projectionTexture'] = new BABYLON.Texture(textureAsset.assetObj, VeryEngine.scene);
            }else if(this.sceneObj.light['projectionTexture']){
                this.sceneObj.light['projectionTexture'].dispose();

            }
        },
        title:this.lightTitle,
    }

    public export(vrData:any,file:IED[],parent?:string){
        let json=super.export(vrData,file,parent);
        if(json['projectionTexture']){
            let linkAsset=VeryEngine.shareBox.id2Asset[json['projectionTexture']];
            if(linkAsset){
                linkAsset.export(vrData,file);
                json['projectionTexture']=linkAsset.autoRename;
            }
        }
    }

    public import(folder:IEDFolder,json:any): void {
        if(json.projectionTexture){
            let split=json.projectionTexture.split('.');
            //若不是assetID,有.后缀
            if(split.length!=1){
                json.projectionTexture=folder.getEmptyID(json.projectionTexture)
            }
        }
    }
}