import { addEntityClass, ATTRIB, IEDAttrib } from "../../engine/IEDProxy";
import { VeryEngine, DataType } from "../../engine";
import { IEDGUI } from "./IEDGUI";

@addEntityClass
export class Video extends IEDGUI {
    public get subtype(): string {
        return "video";
    }
    public taskList: {
        startTime: number;

        callback:Function
        started?:boolean
    }[] = [];
    private _videoPlayer:HTMLVideoElement
    protected realLoad(is2D: boolean) {
        if (is2D) {
            this.sceneObj = document.createElement("div");
            let divStyle = this.sceneObj.style;
            this.sceneObj.style.pointerEvents = "auto";
            divStyle.position = "absolute";
            divStyle.cursor = "pointer";

            divStyle.background = "#fff";
            divStyle.border = "1px solid black";
            divStyle.boxSizing = "border-box";
            // 创建 video 元素
            const videoPlayer = document.createElement("video");
            
            videoPlayer.setAttribute("id", "video-player");
            // videoPlayer.setAttribute(
            //     "src",
            //     "https://verymedia.oss-cn-hangzhou.aliyuncs.com/temp/%E5%BC%80%E6%9E%AA.mp4"
            // );
            videoPlayer.style.width = "100%";
            videoPlayer.style.height = "100%";
            videoPlayer.style.objectFit = "cover";
            // 创建控制面板元素
            const controls = document.createElement("div");
            controls.setAttribute("class", "controls");
            controls.style.position = "absolute";
            controls.style.bottom = "19px";
            controls.style.left = "50%";
            controls.style.transform = "translateX(-50%)";
            controls.style.width = "91.6667%";
            controls.style.height = "51px";
            controls.style.display = "flex";
            controls.style.color = "#fff";
            controls.style.justifyContent = "center";
            controls.style.alignItems = "center";
            // 创建播放/暂停按钮
            const playPauseBtn = document.createElement("div");
            playPauseBtn.setAttribute("id", "play-pause-btn");
            playPauseBtn.style.position = "absolute";
            playPauseBtn.style.bottom = "0";
            playPauseBtn.style.left = "50%";
            playPauseBtn.style.transform = "translateX(-50%)";
            playPauseBtn.style.bottom = "0";
            playPauseBtn.style.width = "40px";
            playPauseBtn.style.height = "40px";

            let playicon = document.createElementNS(
                "http://www.w3.org/2000/svg",
                "svg"
            );
            playicon.style.width = "40px";
            playicon.style.height = "40px";
            playicon.ariaHidden = "true";
            playicon.classList.add("icon", "icon-bofang");
            playicon.innerHTML = `<use xlink:href="#icon-bofang"></use>`;
            let pauseicon = document.createElementNS(
                "http://www.w3.org/2000/svg",
                "svg"
            );
            pauseicon.style.width = "40px";
            pauseicon.style.height = "40px";
            pauseicon.ariaHidden = "true";
            pauseicon.classList.add("icon", "icon-zanting");
            pauseicon.innerHTML = `<use xlink:href="#icon-zanting"></use>`;
            pauseicon.style.display = "none";
            playPauseBtn.append(playicon);
            playPauseBtn.append(pauseicon);
            controls.append(playPauseBtn);
            // 创建显示当前播放时间的元素
            const currentTime = document.createElement("span");
            currentTime.setAttribute("id", "current-time");
            currentTime.textContent = "0:00";

            // 创建显示视频总时长的元素
            const duration = document.createElement("span");
            duration.setAttribute("id", "duration");
            duration.textContent = "0:00";
            const durationBox = document.createElement("div");
            const durationBoxStyle = durationBox.style;
            durationBoxStyle.width = "80px";
            durationBoxStyle.height = "17px";
            durationBoxStyle.display = "flex";
            durationBoxStyle.justifyContent = "center";
            durationBoxStyle.alignItems = "center";
            durationBoxStyle.position = "absolute";
            durationBoxStyle.right = "0";
            durationBoxStyle.bottom = "11px";
            durationBoxStyle.fontSize = "12px";
            durationBox.append(currentTime);
            durationBox.append(document.createTextNode("/"));
            durationBox.append(duration);
            controls.append(durationBox);

            // 创建进度条容器元素
            const progressBarContainer = document.createElement("div");
            progressBarContainer.setAttribute("id", "progress-bar-container");
            progressBarContainer.style.width = "100%";
            progressBarContainer.style.height = "4px";
            progressBarContainer.style.background = "rgba(0, 0, 0, 0.6)";
            progressBarContainer.style.cursor = "pointer";
            progressBarContainer.style.position = "absolute";
            progressBarContainer.style.top = "0";
            controls.append(progressBarContainer);
            // 创建进度条填充元素
            const progressBarFill = document.createElement("div");
            progressBarFill.setAttribute("id", "progress-bar-fill");
            progressBarFill.style.width = "0";
            progressBarFill.style.height = "100%";
            progressBarFill.style.backgroundColor = "#0052D9";
            progressBarContainer.append(progressBarFill);
            // 创建进度条拇指元素
            const progressBarThumb = document.createElement("div");
            progressBarThumb.setAttribute("id", "progress-bar-thumb");
            progressBarThumb.style.width = "10px";
            progressBarThumb.style.height = "10px";
            progressBarThumb.style.backgroundColor = "#0052D9";
            progressBarThumb.style.border = "2px solid #FFFFFF;";
            progressBarThumb.style.borderRadius = "50%";
            progressBarThumb.style.cursor = "pointer";
            progressBarThumb.style.position = "absolute";
            progressBarThumb.style.top = "-3px";
            progressBarThumb.style.left = "0";
            progressBarThumb.style.marginLeft = "-5px";
            progressBarThumb.style.zIndex = "1";
            // 将进度条填充元素和进度条拇指元素添加到进度条容器元素中
            progressBarContainer.append(progressBarThumb);

            // 将控制面板元素中的元素添加到控制面板中
            function handlePlayPause() {
                if (videoPlayer.paused || videoPlayer.ended) {
                    // 如果视频暂停或已结束，则播放
                    videoPlayer.play();
                    (
                        playPauseBtn.querySelector(
                            ".icon-zanting"
                        ) as HTMLElement
                    ).style.display = "block";
                    (
                        playPauseBtn.querySelector(
                            ".icon-bofang"
                        ) as HTMLElement
                    ).style.display = "none";
                } else {
                    // 否则暂停
                    videoPlayer.pause();
                    (
                        playPauseBtn.querySelector(
                            ".icon-zanting"
                        ) as HTMLElement
                    ).style.display = "none";
                    (
                        playPauseBtn.querySelector(
                            ".icon-bofang"
                        ) as HTMLElement
                    ).style.display = "block";
                }
            }

            // 更新已播放时长和进度条
            function updateCurrentTime() {
                const currentTimeValue = formatTime(videoPlayer.currentTime);
                currentTime.textContent = currentTimeValue;
                updateProgressBarFill();
            }

            // 更新总时长和进度条最大值
            function updateDuration() {
                const durationValue = formatTime(videoPlayer.duration);
                duration.textContent = durationValue;
            }

            // 时间格式化函数
            function formatTime(time) {
                const minutes = Math.floor(time / 60);
                const seconds = Math.floor(time % 60);
                return `${minutes}:${padZero(seconds)}`;
            }

            // 数字补零函数
            function padZero(num) {
                return num.toString().padStart(2, "0");
            }

            // 播放结束事件处理函数
            function handleVideoEnd() {
                (
                    playPauseBtn.querySelector(".icon-zanting") as HTMLElement
                ).style.display = "none";
                (
                    playPauseBtn.querySelector(".icon-bofang") as HTMLElement
                ).style.display = "block";
                currentTime.textContent = "0:00";
                progressBarFill.style.width = "0";
                progressBarThumb.style.left = "0";
            }
            // 更新进度条填充和拇指位置
            function updateProgressBarFill() {
                const percent = Math.floor(
                    (videoPlayer.currentTime / videoPlayer.duration) * 100
                );
                progressBarFill.style.width = percent + "%";
                progressBarThumb.style.left = percent + "%";
            }

            // 处理进度条点击事件
            function handleProgressBarClick(event) {
                const data = progressBarContainer.getBoundingClientRect();
                const posX = event.clientX - data.left;
                const percent = posX / data.width;
                const seekTime = percent * videoPlayer.duration;

                videoPlayer.currentTime = seekTime;
                const e = new Event("timeupdate");
                videoPlayer.dispatchEvent(e);
                updateProgressBarFill();
            }

            // 处理拖动进度条拇指事件
            let isDraggingProgressBarThumb = false;
            function handleProgressBarThumbDrag(event) {
                const data = progressBarContainer.getBoundingClientRect();

                if (isDraggingProgressBarThumb) {
                    const posX = event.clientX - data.left;
                    const percent = posX / data.width;
                    const seekTime = percent * videoPlayer.duration;
                    videoPlayer.currentTime = seekTime;
                    const e = new Event("timeupdate");
                    videoPlayer.dispatchEvent(e);
                    updateProgressBarFill();
                }
            }
            // 添加事件监听器
            progressBarContainer.addEventListener(
                "click",
                handleProgressBarClick
            );

            progressBarThumb.addEventListener("mousedown", (e) => {
                e.stopPropagation();
                e.preventDefault;
                isDraggingProgressBarThumb = true;

                document.addEventListener(
                    "mousemove",
                    handleProgressBarThumbDrag
                );
                document.addEventListener("mouseup", () => {
                    isDraggingProgressBarThumb = false;
                    document.removeEventListener(
                        "mousemove",
                        handleProgressBarThumbDrag
                    );
                });
            });
            // 添加事件监听器
            playPauseBtn.addEventListener("click", handlePlayPause);
            videoPlayer.addEventListener("timeupdate", updateCurrentTime);
            videoPlayer.addEventListener("loadedmetadata", updateDuration);
            videoPlayer.addEventListener("ended", handleVideoEnd);
            this.sceneObj.append(videoPlayer);
            this._videoPlayer = videoPlayer
            this.sceneObj.append(controls);
            // 使用示例:
            this.monitorVideoPlay();
            this.addTask ({
                startTime:5,
                callback:()=>{
                    
                }
            })
        }
    }
    public monitorVideoPlay() {
        const that = this
        function checkTime() {
            const currentTime = that._videoPlayer.currentTime;
            that.taskList.forEach((item) => {
                if (currentTime >= item.startTime && !item.started) {
                    item.callback();
                    item.started = true;
                }
            });
        }

        this._videoPlayer.ontimeupdate= checkTime;
        this._videoPlayer.addEventListener("ended", () => {
            if (this.taskList) {
                this.taskList.forEach((item) => {
                    item.started = false;
                });
            }
        });
    }
    public addTask(taskData){
        this.taskList.push(taskData)
    }
    private title = "视频";

    @ATTRIB("gui.through")
    public through: IEDAttrib<DataType.Bool> = {
        name: "是否点击穿透",
        type: DataType.Bool,
        onchange(this: Video, val) {
            if (this.is2D) {
                if (!VeryEngine.EditMode) {
                    if (val) {
                        (this.sceneObj as HTMLElement).style.pointerEvents =
                            "none";
                    } else {
                        (this.sceneObj as HTMLElement).style.pointerEvents =
                            "auto";
                    }
                } else {
                    (this.sceneObj as HTMLElement).style.pointerEvents = "auto";
                }
            }
        },
        title: this.title,
    };

    @ATTRIB("gui.source")
    public source: IEDAttrib<DataType.Video> = {
        name: "视频",
        type: DataType.Video,
        async onchange(this: Video, val) {
            let picAsset = VeryEngine.shareBox.id2Asset[val];
            if (picAsset) {
                await picAsset.onceOnlyLoad();
                if (this.is2D) {
                    (this.sceneObj as HTMLElement).querySelector("video").src =
                        picAsset.assetObj;
                }
            } else {
                if (this.is2D) {
                    (this.sceneObj as HTMLElement).querySelector("video").src =
                        "";
                }
            }
        },
        title: this.title,
    };

    @ATTRIB("gui.stretch")
    public stretch: IEDAttrib<DataType.DropDown> = {
        name: "填充模式",
        type: DataType.DropDown,
        onchange(this: Video, val) {
            if (this.is2D) {
                if (val == 1) {
                    (this.sceneObj as HTMLElement).querySelector(
                        "video"
                    ).style.objectFit = "contain";
                } else {
                    (this.sceneObj as HTMLElement).querySelector(
                        "video"
                    ).style.objectFit = "initial";
                }
            }
        },
        extra: ["自由拉伸", "原始比例"],
        title: this.title,
    };
}
