import { addEntityClass, ATTRIB, IEDAttrib, IEDProxyFactory } from "../../engine/IEDProxy";
import { VeryEngine, DataType, IED } from "../../engine";
import { IEDEntity } from "../IEDEntity";
import { Tools } from "../../utility/Tools";
import { IEDFolder } from "src/assets";
import { KrpanoCanvas } from "./IEDKrpanoCanvas";
import { KrpanoCategory } from "./IEDKrpanoCategory";
import { KrpanoSceneImage } from "./IEDKrpanoSceneImage";
import { KrpanoSceneVideo } from "./IEDKrpanoSceneVideo";

export abstract class IEDKrpano extends IEDEntity {
    public get type(): string {
        return "krpano";
    }
    public get canvas(): KrpanoCanvas {
        return this.getTargetParentIED("canvas", this);
    }
    public get category(): KrpanoCategory {
        return this.getTargetParentIED("category", this);
    }
    // public get scene(): KrpanoSceneImage| KrpanoSceneVideo{
    //     return this.getTargetParentIED("scene", this);
    // }
    public get krpano() {
        return this.getTargetParentIED("canvas", this).krpanoInstance;
    }
    //上一次操作的canvas，创建的ui默认创建在这个canvas下
    public sceneObj: HTMLElement;
    private static hasMethodRun = false;

    protected abstract realLoad(parent: IEDKrpano): void;

    protected setChild(child: IEDKrpano, index: any): void {
        this.loadPromise().then(() => {
            if (["krpanoImage", "krpanoVideo", "krpanoText"].includes(child.subtype)) {
                const currentSceneId = child.krpano.get("xml.scene");
                const currentEntitySceneId = child.parent.get("krpanoData").get("sceneName");
        
                if (currentSceneId === currentEntitySceneId) {
                    child.realLoad(this);
                }
            } else {
                child.realLoad(this);
            }
        
            IEDProxyFactory.loadComplete(child);
        
            if (child.loadEvent) {
                for (const act of child.loadEvent) {
                    act();
                }
                child.loadEvent = null;
            }
        });
    }
    public loadEvent = [];

    public loadPromise() {
        return new Promise<void>((resolve) => {
            if (this.loadEvent == null) {
                resolve();
            } else {
                this.loadEvent.push(resolve);
            }
        });
    }

    public filterParentType(parent: IEDKrpano): boolean {
        if (!["krpano"].includes(this.subtype)) {
            if (["krpano"].includes(parent.subtype)) {
                return true;
            } else {
                return false;
            }
        } else {
            if (parent.type == "root") {
                return true;
            } else {
                return false;
            }
        }
    }

    protected async Load(): Promise<void> {
        this.sceneObj = null;
        if (!IEDKrpano.hasMethodRun) {
            this.watchEntity();
            IEDKrpano.hasMethodRun = true;
        }
    }
    public watchEntity() {
        VeryEngine.commonJson.watch("pickEntity", (e) => {
            const entity = VeryEngine.shareBox.id2Entity[e];
            if (!entity) {
                return;
            }
            if (entity instanceof IEDKrpano) {
                if (entity.subtype === "canvas") {
                    return;
                }
                if (entity.subtype === "category") {
                    return;
                }

                let secne
                if (entity.subtype === "sceneVideo"||entity.subtype === "sceneImage") {
                    secne = entity
                }else{
                    
                    secne = entity.parent
                }
               
                const currentSceneId = this.krpano.get("xml.scene");
                const currentEntitySceneId = secne.get("krpanoData").get("sceneName");
                if (currentSceneId === currentEntitySceneId) {
                    return;
                }

                for (let child of  secne.children) {
                    (child as any).realLoad();
                }
                this.krpano.call("loadscene('" + currentEntitySceneId + "',null,null,OPENBLEND(1.0, -0.5, 0.3, 0.8, linear))");
            }
        });
    }

    public getTargetParentIED<T extends keyof IEDTypeMap>(targetSubtype: T, IED: IEDKrpano): IEDTypeMap[T] {
     
        let targetParentIED: IEDKrpano | KrpanoCanvas | KrpanoCategory | KrpanoSceneImage |KrpanoSceneVideo = IED;
        

        while (targetParentIED.get("subtype") !== targetSubtype) {
            targetParentIED = targetParentIED.parent as IEDKrpano | KrpanoCanvas | KrpanoCategory | KrpanoSceneImage|KrpanoSceneVideo;
        }

        return targetParentIED as IEDTypeMap[T];
    }

    public export(vrData: any, file: IED[], parent?: string) {
        let links = ["source", "thumbImage", "valueBarImage", "backgroundImage"];
        let json = super.export(vrData, file, parent);
        if (json.gui)
            for (let link of links) {
                if (json.gui[link]) {
                    let linkAsset = VeryEngine.shareBox.id2Asset[json.gui[link]];
                    if (linkAsset) {
                        linkAsset.export(vrData, file);
                        json.gui[link] = linkAsset.autoRename;
                    }
                }
            }
    }
    public getHotspot(name: string) {
       
        const hotspot = this.krpano.get(`hotspot[${name}]`);
        return hotspot;
    }
    public setHotspotProp(hotspotName: string, property: string, value: string | number): void {
        const hotspot = this.getHotspot(hotspotName);
        hotspot[property] = value;
        
    }
    public import(folder: IEDFolder, json: any): void {
        let links = ["source", "thumbImage", "valueBarImage", "backgroundImage"];
        if (json.gui)
            for (let link of links) {
                if (json.gui[link]) {
                    let split = json.gui[link].split(".");
                    //若不是assetID,有.后缀
                    if (split.length != 1) {
                        json.gui[link] = folder.getEmptyID(json.gui[link]);
                    }
                }
            }
    }
}
type IEDTypeMap = {
    canvas: KrpanoCanvas;
    category: KrpanoCategory;
    scene: KrpanoSceneImage|KrpanoSceneVideo;
};
