export class VersionTool{
    public static gui(json){
        if(json.type=="2d-gui"){
            json.type="gui";
        }
        if(json.subtype=="root"){
            json.subtype="canvas"
        }
        if(json.subtype=="3dgui"){
            json.type="gui-3d";
            json.subtype="canvas";
        }
        if(json.backgroundImage&&json.backgroundImage.startsWith("url:")){
            delete json.backgroundImage;
        }
        if(json.valueBarImage&&json.valueBarImage.startsWith("url:")){
            delete json.valueBarImage
        }
        if(json.thumbImage&&json.thumbImage.startsWith("url:")){
            delete json.thumbImage;
        }
    }

    public static mesh(json){
        if(json.type=="empty")
            json.subtype="empty";
        if(json.subtype=="3dgui"){
            json.type="gui";
            json.subtype="3dcanvas";
        }else{
            json.type="mesh";
        }
    }

    public static camera(json){
        if(json.fov){
            json.fov=json.fov*180/Math.PI;
        }
    }

    public static light(json){
        if(json.spotAngl){
            json.spotAngl=json.spotAngl*180/Math.PI;
        }
    }

    public static particle(json){
        if(json.emitterType){
            let tmp=['BoxParticleEmitter','ConeParticleEmitter','CylinderParticleEmitter',
        'HemisphericParticleEmitter','PointParticleEmitter','SphereParticleEmitter'];
            json.emitterType=tmp.indexOf(json.emitterType);
        }
        if(json.particleTexture&&json.particleTexture.startsWith("data:image/png;")){
            delete json.particleTexture;
        }
    }

    public static sprite(json){
        if(json.imageUrl=="url:sprite/player.png"||
        json.imageUrl=="url:sprite/palmtree.png"){
            delete json.imageUrl
        }
    }

    public static lensflare(json){
        if(json.lensFlareImageUrl&&json.lensFlareImageUrl.startsWith("url:")){
            delete json.lensFlareImageUrl
        }
    }
} 