import { IEDEntity } from "../entities";
import { IED,IEDAttribute, VeryEngine} from "../engine";
import { IEDAsset, IEDTable } from "../assets";
import { Tools } from "../utility/Tools";
import { DMap } from "../djs/type";

export abstract class Iplugin{
    id?:string;
    productId?:string;
    button?:PluginMenu|PluginMenu[];
    assetContextmenu?:IContextmenu|IContextmenu[];
    entityContextmenu?:IContextmenu|IContextmenu[];
    dependence?:string[];
    init?(currentEntity?:IEDEntity,pickEntityIds?:IEDEntity[]):void;
    onEntityPick?(currentEntity?:IEDEntity,pickEntityIds?:IEDEntity[]):void;
    onAssetPick?(currentAsset?:IEDAsset,pickAssets?:IEDAsset[]):void;
    onBeforeViewUpdate?(currentEntity?:IEDEntity,pickEntityIds?:IEDEntity[]):void;
    onAfterViewUpdate?(currentEntity?:IEDEntity,pickEntityIds?:IEDEntity[]):void;
    onBeforePoseMatrixUpdate?(currentEntity?:BABYLON.TransformNode):void;
    onAfterPoseMatrixUpdate?(currentEntity?:BABYLON.TransformNode):void;
    abstract uninstall():void;
    protected isActive(index?:number){
        if(this.button){
            if(index==undefined) index=0;
            let button:PluginMenu[];
            if(!(this.button instanceof Array)){
                button=[this.button];
            }else{
                button=this.button;
            }
            if(index>=button.length||!this.isButton(button[index])||(button[index] as IButton).mode==ClickMode.once){
                return null;
            }
            return (button[index]as IButton).isActive;
        }else{
            return null;
        }
    }

    protected click(index?:number){
        if(this.button){
            if(index==undefined) index=0;
            let button:PluginMenu[];
            if(!(this.button instanceof Array)){
                button=[this.button];
            }else{
                button=this.button;
            }
            if(index<button.length){
                if(this.isButton(button[index])){
                    (button[index] as IButton).click();
                }
            }
        }
    }

    public isButton(menu:PluginMenu){
        return !menu.hasOwnProperty("onchange")
    }

    protected getInnerAsset(path:string){
        let pluginFolder=VeryEngine.shareBox.id2Asset[this.productId];
        if(pluginFolder){
            if(pluginFolder.type=="folder"){
                let split=path.split('/');
                for(let tmp of split){
                    if(!tmp) continue;
                    let result=false;
                    for(let child of pluginFolder.children){
                        let tmpFolder=VeryEngine.shareBox.id2Asset[child];
                        if(tmpFolder&&tmpFolder.name==tmp){
                            pluginFolder=tmpFolder;
                            result=true;
                            break;
                        }
                    }
                    if(!result)
                    return null;
                }
            }else{
                pluginFolder=pluginFolder.getAssetByPath(path);
            }
        }
        return pluginFolder;
    }

    public createTable(name?:string,id?:string):IEDTable{
        if(!id)
        id=Tools.assetID();
        if(!name)
            name="新表格"
        if(VeryEngine.shareBox.id2Asset[id]){
            return VeryEngine.shareBox.id2Asset[id] as IEDTable;
        }
        let data = {
            id: id,
            type: "table",
            createdAt: Tools.createdTime(),
            name: name+".table",
            file: {
                filename:name+".table",
                size: 0
            },
            pluginId:this.productId+"~"+this.id,
            path:["root"]
        };
        VeryEngine.shareBox.assetMap.set(data.id, new DMap(data));
        let table=VeryEngine.shareBox.id2Asset[id] as IEDTable;
        table.empty();
        return table;
    }

    public createWindowFromTable?(table:IEDTable):void
}
export type PluginMenu = IButton|IDropDown
export interface IButton{
    img?:string,
    tips:string,
    enable?:(entity?:IEDEntity,pickEntityIds?:IEDEntity[])=>void,
    disable?:(entity?:IEDEntity,pickEntityIds?:IEDEntity[])=>void,
    active?:boolean,
    mutex?:MutexMode.global|MutexMode.self,
    mode?:ClickMode,
    isActive?:boolean,
    allow?:(tag:boolean)=>void,
    click?:()=>void,
    children?:SubButton[];
    element?:HTMLElement
}
export interface SubButton{
    img?:string,
    tips:string,
    enable:(entity?:IEDEntity,pickEntityIds?:IEDEntity[])=>void,
    disable?:(entity?:IEDEntity,pickEntityIds?:IEDEntity[])=>void,
    active?:boolean,
    mode?:ClickMode.once|ClickMode.normal,
    mutex?:MutexMode,
    isActive?:boolean,
    click?:()=>void,
    allow?:(tag:boolean)=>void,
    element?:HTMLElement,
    parent?:IButton
}
export interface IDropDown{
    img:string,
    tips:string,
    onchange:(val:number,entity?:IEDEntity,pickEntityIds?:IEDEntity[])=>void,
    default?:number,
    children:{img?:string,tips:string}[],
    element?:HTMLElement
}
export interface IContextmenu{
    text:string,
    onclick:(ied?:IED|IED[])=>void,
    include?:string[],
    exclude?:string[],
    includeMulti?:string[],
    excludeMulti?:string[],
    path?:string[]
}

export enum ClickMode{
    once,
    normal,
    always
}
export enum MutexMode{
    self,
    global,
    dropdown
}
export enum AttrMode{
    cover,
    append
}
export interface IAttrPanel{
    mode?:AttrMode
    type:string,
    subtype?:string,
    attrPanel:{title?:string,filter?:()=>boolean,attributes:IEDAttribute[]}[]
}

export type IExtends={
    init:(self?:IED)=>void,
    destroy?:(self?:IED)=>void,
    subtype?:string,
}&{
    [props:string]:{onchange:(self:IED,val:any)=>void,default?:(self?:IED)=>any}
}

