import { addEntityClass, ATTRIB, IEDAttrib, IEDProxyFactory } from "../../engine/IEDProxy";
import { VeryEngine, DataType, IED } from "../../engine";
import { IEDEntity } from "../IEDEntity";
import { IEDKrpano } from "./IEDKrpano";
import { Tools } from "../../utility/Tools";
import { IEDFolder } from "src/assets";
import KrpanoToolJS from "../../utility/krpanoTool.js";

@addEntityClass
export abstract class KrpanoImage extends IEDKrpano {
    public get subtype(): string {
        return "krpanoImage";
    }
    protected async realLoad(parent) {

        this.sceneObj = null;
        let source = this.get("gui.source");

        setTimeout(async () => {
            let krpano = this.canvas.krpanoInstance;
            let ath = this.get("gui.ath");
            let atv = this.get("gui.atv");
            let rx = this.get("gui.rx");
            let ry = this.get("gui.ry");
            let rz = this.get("gui.rz");
            let ox = this.get("gui.ox");
            let oy = this.get("gui.oy");
            let width = this.get("gui.width");
            let height = this.get("gui.height");
            if (source != undefined) {
                let picAsset = VeryEngine.shareBox.id2Asset[source];
                if (picAsset) {
                    await picAsset.onceOnlyLoad();
                    krpano.call(`vreditor_add_edit_image_hotspot(${this.id},${picAsset.assetObj},${ath},${atv},${width},${height},${rx},${ry},${rz},${ox},${oy})`);
                }
            }
        }, 0);
    }

    public filterParentType(parent: IEDKrpano): boolean {
        if (["sceneVideo","sceneImage"].includes(parent.subtype)) {
            return true;
        } else {
            return false;
        }
    }

    protected async Load(): Promise<void> {}
    private title = "图片热点";

    @ATTRIB("gui.source")
    public source: IEDAttrib<DataType.TextureBox> = {
        name: "图片",
        type: DataType.TextureBox,
        async onchange(this: KrpanoImage, val, isFirst) {
            if (isFirst) {
                return;
            }
            let picAsset = VeryEngine.shareBox.id2Asset[val];
            setTimeout(async () => {
                if (picAsset) {
                    let krpano = this.canvas.krpanoInstance;
                    await picAsset.onceOnlyLoad();
                    let ath: number;
                    let atv: number;
                    let rx: number;
                    let ry: number;
                    let rz: number;
                    let ox: number;
                    let oy: number;
                    let width: number;
                    let height: number | string;

                    ath = krpano.get("view.hlookat");
                    atv = krpano.get("view.vlookat");
                    rx = this.get("gui.rx");
                    ry = this.get("gui.ry");
                    rz = this.get("gui.rz");
                    ox = this.get("gui.ox");
                    oy = this.get("gui.oy");
                    width = this.get("gui.width");
                    if (this.get("gui.height")) {
                        height = this.get("gui.height");
                    } else {
                        height = "prop";
                        this.set("gui.height", "prop");
                    }

                    krpano.call(`vreditor_add_edit_image_hotspot(${this.id},${picAsset.assetObj},${ath},${atv},${width},${height},${rx},${ry},${rz},${ox},${oy})`);
                }
            }, 100);
        },
        title: this.title,
    };
    @ATTRIB("gui.width")
    public width: IEDAttrib<DataType.Number> = {
        name: "宽度",
        type: DataType.Number,
        async onchange(this: KrpanoImage, val, isFirst) {
            if (!isFirst) {
                this.setHotspotProp(this.id, "width", val);
            }
        },
        default: 640,
        title: this.title,
    };
    @ATTRIB("gui.height")
    public height: IEDAttrib<DataType.Number> = {
        name: "高度",
        type: DataType.Number,
        async onchange(this: KrpanoImage, val, isFirst) {
            if (!isFirst) {
                this.setHotspotProp(this.id, "height", val);
            }
        },
        title: this.title,
    };
    @ATTRIB("gui.ath")
    public ath: IEDAttrib<DataType.Number> = {
        name: "水平方向角度",
        type: DataType.Number,
        async onchange(this: KrpanoImage, val, isFirst) {
            if (!isFirst) {
                this.setHotspotProp(this.id, "ath", val);
            }
        },
        title: this.title,
    };
    @ATTRIB("gui.atv")
    public atv: IEDAttrib<DataType.Number> = {
        name: "垂直方向角度",
        type: DataType.Number,
        async onchange(this: KrpanoImage, val, isFirst) {
            if (!isFirst) {
                this.setHotspotProp(this.id, "atv", val);
            }
        },
        title: this.title,
    };
    @ATTRIB("gui.rx")
    public rx: IEDAttrib<DataType.Number> = {
        name: "自旋X角度",
        type: DataType.Number,
        async onchange(this: KrpanoImage, val, isFirst) {
            if (!isFirst) {
                this.setHotspotProp(this.id, "rx", val);
            }
        },
        title: this.title,
    };
    @ATTRIB("gui.ry")
    public ry: IEDAttrib<DataType.Number> = {
        name: "自旋Y角度",
        type: DataType.Number,
        async onchange(this: KrpanoImage, val, isFirst) {
            if (!isFirst) {
                this.setHotspotProp(this.id, "ry", val);
            }
        },
        title: this.title,
    };
    @ATTRIB("gui.rz")
    public rz: IEDAttrib<DataType.Number> = {
        name: "自旋Z角度",
        type: DataType.Number,
        async onchange(this: KrpanoImage, val, isFirst) {
            if (!isFirst) {
                this.setHotspotProp(this.id, "rz", val);
            }
        },
        title: this.title,
    };
    @ATTRIB("gui.ox")
    public ox: IEDAttrib<DataType.Number> = {
        name: "相对X坐标",
        type: DataType.Number,
        async onchange(this: KrpanoImage, val, isFirst) {
            if (!isFirst) {
                this.setHotspotProp(this.id, "ox", val);
            }
        },
        title: this.title,
    };
    @ATTRIB("gui.oy")
    public oy: IEDAttrib<DataType.Number> = {
        name: "相对Y坐标",
        type: DataType.Number,
        async onchange(this: KrpanoImage, val, isFirst) {
            if (!isFirst) {
                this.setHotspotProp(this.id, "oy", val);
            }
        },
        title: this.title,
    };

}
