import { addEntityClass, ATTRIB, IEDAttrib } from "../../engine/IEDProxy";
import { VeryEngine, DataType, IED } from "../../engine";
import { IEDKrpano } from "./IEDKrpano";
import { Tools } from "../../utility/Tools";
import KrpanoToolJS from "../../utility/krpanoTool.js";

@addEntityClass
export abstract class KrpanoSceneVideo extends IEDKrpano {
    public get subtype(): string {
        return "sceneVideo";
    }
    protected sceneName: string;
    protected realLoad() {
        this.sceneObj = null;
        this.sceneName = this._data.get("krpanoData").get("sceneName");
    }

    public filterParentType(parent: IEDKrpano): boolean {
        if (["category"].includes(parent.subtype)) {
            return true;
        } else {
            return false;
        }
    }
    private title = "按钮";
    protected async dispose() {
        const krpanoTool = new KrpanoToolJS();

        const xml = krpanoTool.removeScene(
            this.canvas.lastTourXml,
            this.sceneName
        );
        console.log(xml);
        await OSS.clientOrigin
            .put(
                `project/${VeryEngine.projectId}/ALL/vtour/tour.xml`,
                new Blob([xml], {
                    type: "application/xml",
                })
            )

            .catch(function (err) {
                console.log(err);
            });
        await this.krpano.call(
            "loadpano(https://project.veryengine.cn/project/" +
                VeryEngine.projectId +
                "/ALL/vtour/tour.xml?" +
                Date.now() +
                ",null,MERGE,null)"
        );

        VeryEngine.pickEntity(this.category.childIds[0]);
    }
    @ATTRIB("gui.source")
    public source: IEDAttrib<DataType.Video> = {
        name: "视频",
        type: DataType.Video,
        async onchange(this: KrpanoSceneVideo, val, isFirst) {
            if (isFirst) {
                return;
            }

            let picAsset = VeryEngine.shareBox.id2Asset[val];
            if (picAsset) {
                await picAsset.onceOnlyLoad();
                const krpanoTool = new KrpanoToolJS();

                try {
                    // let result = await krpanoTool.makeTiles(file);
                    function getUniqueId(length: number = 8) {
                        const str = "0123456789abcdefghijklmnopqrstuvwxyz";
                        let result = "";
                        for (let i = 0; i < length; i++) {
                            const id = Math.floor(Math.random() * str.length);
                            result += str[id];
                        }
                        return (
                            result || Math.random().toString(36).substr(2, 8)
                        );
                    }
                    const pinyinName = "pano_" + getUniqueId(8);

                    // 场景名称不能以数字开头
                    const sceneName = "scene_" + pinyinName;
                    // const dirName = pinyinName + ".tiles";
                    let string = `
                           <scene name="${sceneName}" isvideopano="true"  title="${picAsset.name}">
                                <plugin name="video"
                                        url.html5="%SWFPATH%/plugins/videoplayer.js"
                                        url.flash="%SWFPATH%/plugins/videoplayer.swf"
                                        pausedonstart="true"
                                        loop="true"
                                        volume="1.0"
                                       
                                        videourl.ios="${picAsset.assetObj}"
                                        
                                        videourl.no-ios="${picAsset.assetObj}"
                                        onvideoready="skin_showloading(false);"
                                        />
                                <image>
                                    <sphere url="plugin:video" />
                                </image>
                                <view hlookat="0" vlookat="0" fovtype="DFOV" fov="130" fovmin="75" fovmax="150" distortion="0.0" />
                            </scene>
                           `;

                    let xml = krpanoTool.addScene(
                        this.canvas.lastTourXml,
                        string
                    );
                    this.canvas.lastTourXml = xml;
                    this._data.get("krpanoData").set("sceneName", sceneName);

                    await OSS.clientOrigin
                        .put(
                            `project/${VeryEngine.projectId}/ALL/vtour/tour.xml`,
                            new Blob([xml], {
                                type: "application/xml",
                            })
                        )
                        .catch(function (err) {
                            console.log(err);
                        });
                } catch (error) {
                    console.log(error);
                }
            }

            if (picAsset) {
                await picAsset.onceOnlyLoad();
                const krpanoTool = new KrpanoToolJS();
                this.blobUrlToFile(
                    picAsset.assetObj,
                    picAsset.name,
                    async (file) => {
                        try {
                            function getUniqueId(length: number = 8) {
                                const str =
                                    "0123456789abcdefghijklmnopqrstuvwxyz";
                                let result = "";
                                for (let i = 0; i < length; i++) {
                                    const id = Math.floor(
                                        Math.random() * str.length
                                    );
                                    result += str[id];
                                }
                                return (
                                    result ||
                                    Math.random().toString(36).substr(2, 8)
                                );
                            }
                            const pinyinName = "pano_" + getUniqueId(8);
                            const sceneName = "scene_" + pinyinName;
                            const dirName = pinyinName + ".tiles";
                            await OSS.clientOrigin
                                .put(
                                    `project/${
                                        VeryEngine.projectId
                                    }/ALL/vtour/panos/${
                                        dirName + "/" + file.name
                                    }`,
                                    file
                                )
                                .then(function (result) {
                                    console.log(result);
                                })
                                .catch(function (err) {
                                    console.log(err);
                                });
                            function getVideoFirstFrame(videoUrl) {
                                // 创建video元素
                                const video = document.createElement("video");
                                video.src = videoUrl;
                                video.setAttribute("crossOrigin", "Anonymous"); // 处理跨域
                                video.setAttribute("preload", "auto"); // auto|metadata|none
                                // 等待视频加载完成
                                return new Promise((resolve, reject) => {
                                    video.addEventListener(
                                        "loadedmetadata",
                                        () => {
                                            debugger;
                                            // 创建canvas元素
                                            const canvas =
                                                document.createElement(
                                                    "canvas"
                                                );
                                            canvas.width = video.videoWidth;
                                            canvas.height = video.videoHeight;

                                            // 将视频第一帧绘制到canvas上
                                            const ctx = canvas.getContext("2d");

                                            ctx.drawImage(
                                                video,
                                                0,
                                                0,
                                                canvas.width,
                                                canvas.height
                                            );

                                            debugger;
                                            // 将canvas图像转换为base64格式的数据URI
                                            const dataUrl = canvas.toDataURL();

                                            // 返回base64格式的数据URI
                                            resolve(dataUrl);
                                        }
                                    );

                                    // 如果视频加载出错，则返回错误信息
                                    video.addEventListener("error", () => {
                                        reject(
                                            `Failed to load video: ${videoUrl}`
                                        );
                                    });
                                });
                            }
                            getVideoFirstFrame(picAsset.assetObj).then(
                                async (dataurl) => {
                                    function base64ToFile(
                                        dataUrl: any,
                                        name: any
                                    ) {
                                        var arr = dataUrl.split(","),
                                            mime = arr[0].match(/:(.*?);/)[1],
                                            bstr = atob(arr[1]),
                                            n = bstr.length,
                                            u8arr = new Uint8Array(n);
                                        while (n--) {
                                            u8arr[n] = bstr.charCodeAt(n);
                                        }
                                        return new File(
                                            [u8arr],
                                            name + ".jpg",
                                            { type: "image/jpg" }
                                        );
                                    }
                                    const file = base64ToFile(
                                        dataurl,
                                        "thumb.jpg"
                                    );
                                    await OSS.clientOrigin
                                        .put(
                                            `project/${VeryEngine.projectId}/ALL/vtour/panos/${dirName}/thumb.jpg`,
                                            file
                                        )
                                        .then(function (result) {
                                            console.log(result);
                                        })
                                        .catch(function (err) {
                                            console.log(err);
                                        });
                                }
                            );

                            let string = `
                            <scene name="${sceneName}" isvideopano="true" thumburl="%SWFPATH%/panos/${dirName}/thumb.jpg" title="${picAsset.name}">
                                 <plugin name="video"
                                         url.html5="%SWFPATH%/plugins/videoplayer.js"
                                         url.flash="%SWFPATH%/plugins/videoplayer.swf"
                                         pausedonstart="true"
                                         loop="true"
                                         volume="1.0"
                                        
                                         videourl.ios="%SWFPATH%/panos/${dirName}/${file.name}"
                                         
                                         videourl.no-ios="%SWFPATH%/panos/${dirName}/${file.name}"
                                         onvideoready="skin_showloading(false);"
                                         />
                                 <image>
                                     <sphere url="plugin:video" />
                                 </image>
                                 <view hlookat="0" vlookat="0" fovtype="DFOV" fov="130" fovmin="75" fovmax="150" distortion="0.0" />
                             </scene>
                            `;
                            let xml = krpanoTool.addScene(
                                this.canvas.lastTourXml,
                                string
                            );
                            this.canvas.lastTourXml = xml;

                            this._data
                                .get("krpanoData")
                                .set("sceneName", sceneName);

                            await OSS.clientOrigin
                                .put(
                                    `project/${VeryEngine.projectId}/ALL/vtour/tour.xml`,
                                    new Blob([xml], {
                                        type: "application/xml",
                                    })
                                )

                                .catch(function (err) {
                                    console.log(err);
                                });
                            await this.krpano.call(
                                "loadpano(https://project.veryengine.cn/project/" +
                                    VeryEngine.projectId +
                                    "/ALL/vtour/tour.xml?" +
                                    Date.now() +
                                    ",null,MERGE,null)"
                            );

                            this.krpano.call(
                                "loadscene('" +
                                    sceneName +
                                    "',null,null,OPENBLEND(1.0, -0.5, 0.3, 0.8, linear))"
                            );

                            VeryEngine.pickEntity(this.id);
                        } catch (error) {
                            console.log(error);
                        }
                    }
                );
            }
        },
        title: this.title,
    };
    private blobUrlToFile(blobUrl, fileName, callback) {
        var xhr = new XMLHttpRequest();
        xhr.open("GET", blobUrl);
        xhr.responseType = "blob";
        xhr.onload = function () {
            var blob = xhr.response;
            var file = new File([blob], fileName, { type: "image/jpeg" });

            callback(file);
        };
        xhr.send();
    }
}
