import { Viewport } from "../viewport";
import { Iplugin, IButton, ClickMode, MutexMode, PluginMenu, IDropDown, SubButton} from "./Iplugin";
import {PoseMatrixTool} from "../entities/PoseMatrixTool";
import { VeryEngine } from "../engine";
import {AssetsPanel} from "../assets-panel";
import {AttributesPanel} from "../attributes-panel";
import { Hierarchy } from "../hierarchy";
import { Tools } from "../utility/Tools";
import { IEDProxyFactory } from "../engine/IEDProxy";

export interface IpluginExtends extends Iplugin{
    isLoad:0|2;
    script:HTMLScriptElement;
}


export const pluginDontLoad=function(protetype:any){
    let script=document.currentScript as HTMLScriptElement;
    let notLoadPlugin:IpluginExtends=new protetype.constructor();
    if(script.textContent){
        let obj=JSON.parse(script.textContent);
        notLoadPlugin.productId=obj.id;
    }
    return  PluginPackage.install(notLoadPlugin,script,true);
};

const plugin2Script:{[key:string]:HTMLScriptElement[]}={};
const recentlyInstall:{[key:string]:number}={};
const readyTimeOut:{[key:string]:any}={};

const oneScriptReady=function(id:string,script:HTMLScriptElement){
    if(plugin2Script[id]){
        let index=plugin2Script[id].indexOf(script);
        if(index>=0){
            plugin2Script[id].splice(index,1);
        }
    }
    if(!plugin2Script[id]||plugin2Script[id].length==0){
        let now= new Date().getTime();
        if(readyTimeOut[id]){
            clearTimeout(readyTimeOut[id]);
        }
        if(now-recentlyInstall[id]>200){
            VeryEngine.pluginReady.readyEvent(id);
            delete plugin2Script[id];
            delete recentlyInstall[id];
            delete readyTimeOut[id];
        }else{
            readyTimeOut[id]=setTimeout(() => {
                VeryEngine.pluginReady.readyEvent(id);
                delete plugin2Script[id];
                delete recentlyInstall[id];
                delete readyTimeOut[id];
            }, 200);
        }
    }
}

export const installPlugin=function(veryPlugin:Function){
    let script=document.currentScript as HTMLScriptElement;
    let plugin:IpluginExtends=new veryPlugin.prototype.constructor();
    if(script.textContent){
        let obj=JSON.parse(script.textContent);
        if(obj.id!=null){
            if(plugin2Script[obj.id]){
                plugin2Script[obj.id].push(script);
            }else{
                plugin2Script[obj.id]=[script];
            }
            recentlyInstall[obj.id]=new Date().getTime();
        }
        plugin.productId=obj.id;
    }
    PluginPackage.install(plugin,script);
};


export const uninstallPlugin=function(id:string){
    if(PluginPackage.Pool[id]){
        PluginPackage.Pool[id].uninstall();
    }
};

export class IEDPlugin{
    public static get instance(){
        return IEDPlugin._instance;
    }
    private static _instance:IEDPlugin;
    public static createInstance(viewport: Viewport,assetPanel: AssetsPanel,attrPanel: AttributesPanel,hierarchy: Hierarchy) {
        IEDPlugin._instance = new IEDPlugin(viewport,assetPanel,attrPanel,hierarchy);
        for(let veryPlugin of IEDPlugin.tobeLoaded){
            IEDPlugin._instance.installPlugin(veryPlugin);
        }
        IEDPlugin.tobeLoaded=[];
    }

    public static tobeLoaded:IpluginExtends[]=[];
    private viewport:Viewport;
    private assetPanel:AssetsPanel;
    private attrPanel:AttributesPanel;
    private hierarchy:Hierarchy;
    public static dependence:{[key:string]:string[]}={};

    private installPluginHandle: {[type: string]: (veryPlugin: Iplugin) => void;} = {};
    private uninstallPluginHandle: {[type: string]: (veryPlugin: Iplugin) => void} = {};

    private toolbar:HTMLElement;
    private constructor(viewport:Viewport,assetPanel:AssetsPanel,attrPanel:AttributesPanel,hierarchy:Hierarchy){
        this.viewport=viewport;
        this.assetPanel=assetPanel;
        this.attrPanel=attrPanel;
        this.hierarchy=hierarchy;
        this.toolbar=document.getElementById("layout-toolbar");
        let pluginbar=document.getElementById("plugin-bar");
        let left=document.getElementById("plugin-left");
        let right=document.getElementById("plugin-right");
        let isScroll=false;
        if(!VeryEngine.EditMode) this.toolbar.style.display="none";
        let self=this;
        window.addEventListener("keydown", (ev: KeyboardEvent) => {
            if(ev.ctrlKey&&ev.altKey){
                if(ev.keyCode==81){
                    if(!VeryEngine.scene.debugLayer.isVisible())
                        VeryEngine.scene.debugLayer.show();
                    else
                        VeryEngine.scene.debugLayer.hide();
                }
            }
        })
        if(VeryEngine.EditMode){
            left.onclick=()=>{
                if(pluginbar.scrollLeft!=0){
                    pluginbar.scrollBy({left:-pluginbar.clientWidth,top:0,behavior: 'smooth'});
                    if(pluginbar.scrollLeft<=pluginbar.clientWidth){
                        left.classList.add("not-allow");
                    }
                }
                right.classList.remove("not-allow");
            }
            right.onclick=()=>{
                if(pluginbar.scrollLeft+pluginbar.clientWidth<pluginbar.scrollWidth){
                    pluginbar.scrollBy({left:pluginbar.clientWidth,top:0,behavior: 'smooth'});
                    if(pluginbar.scrollLeft+2*pluginbar.clientWidth>pluginbar.scrollWidth){
                        right.classList.add("not-allow");
                    }
                }
                left.classList.remove("not-allow");
            }
        }
        else{
            return;
        }
        //针对插件类型做对应的系统处理
        this.installPluginHandle["button"] = (veryPlugin: IpluginExtends)=> {
            let iconList=self.createButton(veryPlugin);
            if(iconList.length>0){
                let divList=this.getElementList(iconList);
                if(veryPlugin.id=="FixStart"){
                    this.toolbar.prepend(...divList);
                }else if(veryPlugin.id=="FixEnd"){
                    this.toolbar.querySelector(".last").append(...divList)
                }else{
                    pluginbar.append(...divList);
                    if(!isScroll){
                        if(pluginbar.scrollWidth>pluginbar.clientWidth){
                            isScroll=true;
                            left.style.display="flex";
                            right.style.display="flex";
                        }
                    }
                }
            }
        };
        this.installPluginHandle["assetContextmenu"] = (veryPlugin: IpluginExtends) => {
            let id =veryPlugin.productId+veryPlugin.id;
            if(veryPlugin.assetContextmenu instanceof Array){
                for(let i=0;i<veryPlugin.assetContextmenu.length;i++){
                    this.assetPanel.addMenuItem(id,veryPlugin.assetContextmenu[i]);
                }
            }else{
                this.assetPanel.addMenuItem(id,veryPlugin.assetContextmenu);
            }
        };
        this.installPluginHandle["entityContextmenu"] = (veryPlugin: IpluginExtends) => {
            let id = veryPlugin.productId+veryPlugin.id;
            if(veryPlugin.entityContextmenu instanceof Array){
                for(let i=0;i<veryPlugin.entityContextmenu.length;i++){
                    this.hierarchy.addMenuItem(id,veryPlugin.entityContextmenu[i]);
                }
            }else{
                this.hierarchy.addMenuItem(id,veryPlugin.entityContextmenu);
            }
        };
        this.uninstallPluginHandle["button"] = function (veryPlugin: IpluginExtends) {
            if(!(veryPlugin.button instanceof Array)){
                veryPlugin.button=[veryPlugin.button];
            }
            for(let icon of veryPlugin.button){
                pluginbar.removeChild(icon.element);
            }
            if(isScroll&&pluginbar.scrollWidth<=pluginbar.clientWidth){
                isScroll=false;
                left.style.display="none";
                right.style.display="none";
            }
        }

        this.uninstallPluginHandle["assetContextmenu"] = (veryPlugin: IpluginExtends) => {
            let id = veryPlugin.productId+veryPlugin.id;
            this.assetPanel.removeMenuItem(id);
        }
        this.uninstallPluginHandle["entityContextmenu"] = (veryPlugin: IpluginExtends) => {
            let id = veryPlugin.productId+veryPlugin.id;
            this.hierarchy.removeMenuItem(id);
        }
    }


    private getElementList(iconList:PluginMenu[]){
        let divList:HTMLElement[]=[];
        for(let icon of iconList){
            divList.push(icon.element);
        }
        return divList
    }

    private createButton(veryPlugin:IpluginExtends){
        let iconList:PluginMenu[]=[].concat(veryPlugin.button);
        let actList:HTMLDivElement[]=[];
        for(let icon of iconList){
            let div=document.createElement("div");div.classList.add("ui-button");
            if(icon.img.startsWith("icon-")){
                let svg=`<svg class="icon ${icon.img}" aria-hidden="true"><use xlink:href="#${icon.img}"></use></svg>`;
                div.innerHTML=svg;
            }else{
                let img=document.createElement("img");img.src=icon.img;div.append(img);
            }
            icon.element=div;
            Tools.showTipMessage(div.firstElementChild as HTMLElement,null,icon.tips);
            if(veryPlugin.isButton(icon)){
                icon=icon as IButton
                if(icon.children&&icon.children.length!=0){
                    icon.mode=ClickMode.normal;
                    icon.mutex=null;
                    let dropTip=document.createElement("div");
                    dropTip.classList.add("drop-tip");
                    div.append(dropTip);
                    let drop=document.createElement("div");
                    drop.classList.add("drop-menu");
                    
                    div.clickWithHide(()=>{this.toolbar.append(drop); drop.style.left=div.offsetLeft-12+"px"},()=>{drop.remove()});
                    for(let child of icon.children){
                        let div=document.createElement("div");
                        div.classList.add("drop-menu-item");
                        div.onclick=(ev)=>{ev.stopPropagation()};
                        child.element=div;
                        child.parent=icon;
                        let start=document.createElement("div");
                        start.classList.add("drop-start");
                        if(child.img){
                            if(child.img.startsWith("icon-")){
                                let svg=`<svg class="icon drop-menu-item-icon" aria-hidden="true"><use xlink:href="#${child.img}"></use></svg>`;
                                start.innerHTML=svg;
                            }else{
                                let img=document.createElement("img");img.src=child.img;start.append(img);
                            }
                        }
                        let span=document.createElement("span");
                        span.classList.add("drop-menu-item-text");
                        span.innerText=child.tips;
                        start.append(span);
                        div.append(start);
                        if(child.mode!=ClickMode.once){
                            let label=document.createElement("label");
                            label.classList.add("switch");
                            let span=document.createElement("span");
                            span.classList.add("slider","round");
                            label.append(span);
                            span.innerHTML="<div></div>"
                            div.append(label);
                            div.addEventListener("click",(e)=>{e.stopPropagation()});
                            this.addClick(child,veryPlugin,actList);
                            Object.defineProperty(child,"isActive",{
                                get(){
                                    return child.element.classList.contains("active")
                                },
                                set(val){
                                    if(val)
                                        child.element.classList.add("active");
                                    else
                                        child.element.classList.remove("active")
                                }
                            })
                        }else{
                            this.addClick(child,veryPlugin,actList)
                        }
                        drop.append(div);
                    }
                }else if(icon.enable){
                    this.addClick(icon,veryPlugin,actList);
                    if(icon.mode!=ClickMode.once){
                        Object.defineProperty(icon,"isActive",{
                            get(){
                                return icon.element.classList.contains("active")
                            },
                            set(val){
                                if(val)
                                    icon.element.classList.add("active");
                                else
                                    icon.element.classList.remove("active")
                            }
                        })
                    }
                }
            }else{
                icon=icon as IDropDown;
                if(icon.children&&icon.children.length!=0){
                    let dropTip=document.createElement("div");
                    dropTip.classList.add("drop-tip");
                    div.append(dropTip);
                    let drop;
                    div.clickWithHide(()=>{
                        drop=document.createElement("div");
                        drop.classList.add("drop-menu");
                        let def=0;
                        if((icon as IDropDown).default) def=(icon as IDropDown).default;
                        for(let i=0;i<icon.children.length;i++){
                            let child=icon.children[i];
                            let div=document.createElement("div");
                            div.classList.add("drop-menu-item");
                            div.onclick=(ev)=>{ev.stopPropagation()};
                            let start=document.createElement("div");
                            start.classList.add("drop-start");
                            let svg="";
                            if(def==i){
                                svg=`<svg class="icon drop-menu-item-icon" style="width:12px" aria-hidden="true"><use xlink:href="#icon-dui"></use></svg>`;
                            }else{
                                svg=`<span style="width:12px" class="drop-menu-item-icon"></span>`
                            }
                            if(child.img){
                                if(child.img.startsWith("icon-")){
                                    svg+=`<svg class="icon drop-menu-item-icon" aria-hidden="true"><use xlink:href="#${child.img}"></use></svg>`;
                                }else{
                                    svg+=`<img src=${child.img}>`
                                }
                            }
                            div.onclick=()=>{(icon as IDropDown).default=i;
                                (icon as IDropDown).onchange.call(icon,i,VeryEngine.pickedEntity,VeryEngine.pickedEntities)
                            };
                            start.innerHTML=svg;
                            let span=document.createElement("span");
                            span.classList.add("drop-menu-item-text");
                            span.innerText=child.tips;
                            start.append(span);
                            div.append(start);
                            drop.append(div);
                        }
                        this.toolbar.append(drop); 
                        drop.style.left=div.offsetLeft-12+"px"
                    },
                    ()=>{if(drop)drop.remove();drop=null;});
                }
            }
        }
        for(let icon of actList){
            icon.click();
        }
        return iconList
    }
    private addClick(icon:IButton|SubButton,veryPlugin:IpluginExtends,actList:HTMLElement[]){
        let div=icon.element;
        div.onclick=()=>{
            let e=VeryEngine.pickedEntity;
            let pickEntities=VeryEngine.pickedEntities;
            if(!div.classList.contains("active")){
                let buttons=[];
                if(icon.mutex==MutexMode.self){
                    buttons=veryPlugin.button instanceof Array?veryPlugin.button:[veryPlugin.button];
                }else if(icon.mutex==MutexMode.dropdown){
                    buttons=[(icon as SubButton).parent]
                }else if(icon.mutex==MutexMode.global){
                    for(let key in PluginPackage.Pool){
                        for(let file of PluginPackage.Pool[key].pluginList){
                            if(file.button){
                                if(file.button instanceof Array){
                                    buttons.push(...file.button)
                                }else{
                                    buttons.push(file.button);
                                }
                            }
                        }
                    }
                }
                for(let button of buttons){
                    if(veryPlugin.isButton(button)){
                        let tmp=button as IButton;
                        if(tmp.children){
                            for(let child of tmp.children){
                                if(child==icon) continue;
                                if(child.mutex==icon.mutex&&child.isActive==true){
                                    child.isActive=false;
                                    if(child.disable)
                                        child.disable.call(veryPlugin,e,pickEntities)
                                    child.element.classList.remove("active")
                                }
                            }
                        }else{
                            if(tmp.mutex==icon.mutex&&tmp.isActive==true){
                                if(tmp==icon) continue;
                                tmp.isActive=false;
                                if(tmp.disable)
                                    tmp.disable.call(veryPlugin,e,pickEntities);
                                tmp.element.classList.remove("active");
                            }
                        }
                    }
                }
                icon.isActive = true;
                if(icon.enable)
                icon.enable.call(veryPlugin,e,pickEntities);
                if(icon.mode!=ClickMode.once)
                    div.classList.add("active");
            }else if(icon.mode!=ClickMode.always){
                icon.isActive=false;
                if(icon.disable){
                    icon.disable.call(veryPlugin,e,pickEntities);
                }
                div.classList.remove("active");
            }
        };
        icon.click = () => {
            div.click();
        };
        icon.allow=(tag:boolean)=>{
            if(tag)
            div.style.color="#fff";
            else
            div.style.color="#585858";
        }
        if(icon.active){
            actList.push(div);
        }
    }
    public async installPlugin(veryPlugin:IpluginExtends){
        veryPlugin.uninstall=((uninstall:Function)=>{
            return ()=>{
                //删除共享变量
                VeryEngine.shareBox.delOrigin(veryPlugin);
                // for(let id in VeryEngine.shareBox.id2Entity){
                //     VeryEngine.shareBox.id2Entity[id].unwatch(veryPlugin.id);
                // }
                let id=veryPlugin.productId+veryPlugin.id
                if(VeryEngine.EditMode){
                    if(veryPlugin.onEntityPick){
                        this.viewport.removeCheckAct(id);
                    }
                    if(veryPlugin.onAssetPick){
                        this.assetPanel.removeCheckAct(id);
                    }
                    if(veryPlugin.onBeforeViewUpdate){
                        this.viewport.removeBeforeViewUpdate(id);
                    }
                    if(veryPlugin.onAfterViewUpdate){
                        this.viewport.removeAfterViewUpdate(id);
                    }
                    if(veryPlugin.onBeforePoseMatrixUpdate){
                        PoseMatrixTool.removeBeforePoseMatrix(id);
                    }
                    if(veryPlugin.onAfterPoseMatrixUpdate){
                        PoseMatrixTool.removeAfterPoseMatrix(id);
                    }
                    for(let key in this.uninstallPluginHandle){
                        if(veryPlugin[key]){
                            this.uninstallPluginHandle[key](veryPlugin);
                        }
                    }
                }
                try{
                    uninstall.call(veryPlugin);
                }catch(e){
                    console.error(e);
                }
            };
        })(veryPlugin.uninstall);
        if(!VeryEngine.EditMode) return;
        for(let key in this.installPluginHandle){
            if(veryPlugin[key]){
                this.installPluginHandle[key](veryPlugin);
            }
        }
        if(veryPlugin.init){
            if(VeryEngine.isLoadComplete){
                veryPlugin.init(VeryEngine.pickedEntity,VeryEngine.pickedEntities);
            }else{
                VeryEngine.gloablEvent.addEventListener("loadComplete",()=>{
                    veryPlugin.init(VeryEngine.pickedEntity,VeryEngine.pickedEntities);
                })
            }
        }
        let id=veryPlugin.productId+veryPlugin.id;
        if(veryPlugin.onEntityPick){
            this.viewport.addCheckAct(id,veryPlugin.onEntityPick.bind(veryPlugin));
        }
        if(veryPlugin.onAssetPick){
            this.assetPanel.addCheckAct(id,veryPlugin.onAssetPick.bind(veryPlugin));
        }
        if(veryPlugin.onBeforeViewUpdate){
            this.viewport.addBeforeViewUpdate(id,veryPlugin.onBeforeViewUpdate.bind(veryPlugin));
        }
        if(veryPlugin.onAfterViewUpdate){
            this.viewport.addAfterViewUpdate(id,veryPlugin.onAfterViewUpdate.bind(veryPlugin));
        }
        if(veryPlugin.onBeforePoseMatrixUpdate){
            PoseMatrixTool.addBeforePoseMatrix(id,veryPlugin.onBeforePoseMatrixUpdate.bind(veryPlugin));
        }
        if(veryPlugin.onAfterPoseMatrixUpdate){
            PoseMatrixTool.addAfterPoseMatrix(id,veryPlugin.onAfterPoseMatrixUpdate.bind(veryPlugin));
        }
        oneScriptReady(veryPlugin.productId,veryPlugin.script);
    }
}

//主要用于处理依赖关系
export class PluginPackage{
    public pluginList:IpluginExtends[]=[];
    //被依赖的对象的id
    private depended:string[]=[];
    //依赖对象的id
    private dependence:string[]=[]
    private id:string;
    private ids:string[];
    public isDepend:boolean;
    public name:string;
    //对应资源库 一个包的id
    public static Pool:{[id:string]:PluginPackage}={system:new PluginPackage("system",[])};
    constructor(id:string,pluginIds:string[],depend?:string,name?:string){
        this.id=id;
        this.ids=pluginIds;
        this.name=name;
        if(depend){
            this.depended.push(depend);
            this.isDepend=true;
        }
    }
    public static createPackage(id:string,pluginIds:string[],depend?:string,name?:string){
        return new Promise<PluginPackage>(resiolve=>{
            if(this.Pool[id]&&this.Pool[id].id){
                if(!depend&&this.Pool[id].isDepend){
                    this.Pool[id].isDepend=false;
                    this.Pool[id].name=name;
                }
                console.warn("插件:"+id+",该插件已经加载请勿重新加载");
                resiolve(null);
            }else{
                let pack:PluginPackage;
                if(this.Pool[id]){
                    pack=this.Pool[id];
                    pack.id=id;
                    pack.ids=pluginIds;
                    pack.name=name;
                    if(depend){
                        pack.isDepend=true;
                        if(!pack.depended.includes(depend))
                        pack.depended.push(depend);
                    }
                }else{
                    pack=new PluginPackage(id,pluginIds,depend,name);
                    this.Pool[id]=pack;
                }
                for(let file of pluginIds){
                    let body = document.body;
                    var myscript = document.createElement('script');
                    myscript.src = window.location.protocol+"//assetstore.oss-cn-hangzhou.aliyuncs.com/product_file/"+file+".js";
                    myscript.type = 'text/javascript';
                    myscript.async=false;
                    let obj={id:id};
                    myscript.textContent=JSON.stringify(obj);
                    body.appendChild(myscript);
                }
                if(IEDPlugin.instance)
                    oneScriptReady(id,null);
                VeryEngine.pluginReady.addEventListener(id,()=>{
                    resiolve(pack);
                })
            }
        })
    }

    public static install(plugin:IpluginExtends,script:HTMLScriptElement,notInstall?:boolean){
        if(!plugin.productId)
            plugin.productId="system";
        if(PluginPackage.Pool[plugin.productId]){
            let exit=false;
            for(let exitPlugin of PluginPackage.Pool[plugin.productId].pluginList){
                if((plugin as any).__proto__==(exitPlugin as any).__proto__){
                    exit=true;
                    exitPlugin.productId=plugin.productId;
                    plugin = exitPlugin;
                    break;
                }
            }
            plugin.script=script;
            if(!exit)
                PluginPackage.Pool[plugin.productId].pluginList.push(plugin);
            if(!plugin.isLoad&&!notInstall){
                PluginPackage.Pool[plugin.productId].dealDepend(plugin);
            }
        }
        return plugin;
    }

    public static getPlugin(id:string){
        let split=id.split("~");
        if(split.length>1){
            let productId=split[0];
            id=id.substring(productId.length+1);
            let product=this.Pool[productId];
            for(let plugin of product.pluginList){
                if(plugin.id===id){
                    return plugin;
                }
            }
        }
        return null;
    }

    public static toJson(){
        let obj={};
        for(let key in PluginPackage.Pool){
            if(PluginPackage.Pool[key].isDepend==true||key=="system") continue;
            obj[key]={name:PluginPackage.Pool[key].name,pluginList:PluginPackage.Pool[key].ids};
        }
        return JSON.stringify(obj);
    }

    public get isLoad(){
        if(!this.id||this.ids.length!=this.pluginList.length){
            return false;
        }
        for(let file of this.pluginList){
            if(file.isLoad!=2){
                return false;
            }
        }
        return true;
    }

    private async dealDepend(plugin:IpluginExtends){
        if(plugin.productId=="system") plugin.dependence=null;
        if(plugin.dependence){
            for(let i=0;i<plugin.dependence.length;i++){
                if(!this.dependence.includes(plugin.dependence[i]))
                    this.dependence.push(plugin.dependence[i]);
                let one=plugin.dependence[i];
                if(!PluginPackage.Pool[one]){
                    PluginPackage.Pool[one]=new PluginPackage(undefined,[]);
                    let pluginList=await OSS.listAssetFile(one);
                    if(pluginList.length!=0){
                        PluginPackage.createPackage(one,pluginList,plugin.productId);
                    }else{
                        plugin.dependence.splice(i,1);
                        i--;
                    }
                }else{
                    if(PluginPackage.Pool[one].isLoad){
                        plugin.dependence.splice(i,1);
                        i--;
                    }else{
                        if(!PluginPackage.Pool[one].depended.includes(plugin.productId))
                            PluginPackage.Pool[one].depended.push(plugin.productId);
                    }
                }
            }
        }
        if(plugin.isLoad!=2&&(plugin.dependence==null||plugin.dependence.length==0)){
            if(IEDPlugin.instance){
                setTimeout(()=>{
                    IEDPlugin.instance.installPlugin(plugin);
                })
            }else{
                IEDPlugin.tobeLoaded.push(plugin);
            }
            plugin.isLoad=2;
            if(this.isLoad){
                this.recursion();
            }
        }
    }

    private recursion(){
        for(let tmp of this.depended){
            for(let file of PluginPackage.Pool[tmp].pluginList){
                if(file.dependence){
                    let index=file.dependence.indexOf(this.id);
                    if(index>=0){
                        file.dependence.splice(index,1);
                        if(file.isLoad!=2&&file.dependence.length==0){
                            file.isLoad=2;
                            if(IEDPlugin.instance){
                                setTimeout(()=>{
                                    IEDPlugin.instance.installPlugin(file);
                                })
                            }else{
                                IEDPlugin.tobeLoaded.push(file);
                            }
                        }
                    }
                }
            }
            if(PluginPackage.Pool[tmp].isLoad){
                PluginPackage.Pool[tmp].recursion()
            }
        }
    }

    public uninstall(){
        let scriptList=[]
        for(let file of this.pluginList){
            if(file.script&&!scriptList.includes(file.script)){
                scriptList.push(file.script);
            }
            file.uninstall();
        }
        for(let script of scriptList){
            //删除插件创建的IED
            IEDProxyFactory.uninstall(script);
            VeryEngine.shareBox.delIEDOrigin(script);
        }
        let folderIED=VeryEngine.shareBox.id2Asset[this.id];
        if(folderIED){
            let delFunc = async (asset) => {
                if (asset&&!asset.isDestroy) {
                    if (asset.children)
                    for (let child of [...asset.children]) {
                            let childAsset = VeryEngine.shareBox.id2Asset[child];
                        await delFunc(childAsset);
                    }
                    asset.clearData(false)
                }
            };
            delFunc(folderIED);
        }
        delete PluginPackage.Pool[this.id];
        for(let one in PluginPackage.Pool){
            let index=PluginPackage.Pool[one].depended.indexOf(this.id);
            if(index>=0){
                PluginPackage.Pool[one].depended.splice(index,1);
                if(PluginPackage.Pool[one].isDepend&&PluginPackage.Pool[one].depended.length==0){
                    PluginPackage.Pool[one].uninstall();
                }
            }
        }
    }
}
