import { AbstractType } from "./AbstractType";
import { Item } from "../content/Item";
import { AbstractContent, ContentAny, ContentType } from "../content";
import { DMap } from "./DMap";
import { Doc } from "./Doc";

//todo _searchMarker记录上一次操作的下标功能还未添加，本次操作以上一次操作的index为起始点寻找
export class DArray extends AbstractType {
    private _prelimContent:Array<any>;
    constructor (entries?:any[]) {
        super()
        if (entries === undefined) {
            this._prelimContent = new Array();
        } else {
          this._prelimContent = new Array();
          for(let key of entries){
            if(typeof (key) == 'object'){
                if(Object.prototype.toString.call(key).toLowerCase() == "[object object]"){
                    this._prelimContent.push(new DMap(key))
                }else if(Object.prototype.toString.call(key).toLowerCase() == "[object array]"){
                    this._prelimContent.push(new DArray(key));
                }
            }else{
              this._prelimContent.push(key);
            }
          }
        }
    }
    private static _special=["positions","indices","normals","uvs"];
    public static isArray(key:string){
        if(this._special.includes(key)){
            return false;
        }
        if(key.endsWith("s")||key.endsWith("ren")){
            return true;
        }
        return false;
    }

    public _integrate (y:Doc, item:Item) {
        super._integrate(y, item);
        if(this._prelimContent){
          let common=[];
          let right:Item=null;
          let ownClientId = this.doc.clientID
          this._prelimContent.forEach((value) => {
            if(value instanceof AbstractType){
                if(common.length!=0){
                    let content = new ContentAny(common);
                    right=new Item({ client: ownClientId, clock: this.doc.getState(ownClientId) }, right, right && right.lastId, null, null, this, null, content);
                    common=[];
                    right.write();
                    right.integrate();
                }
                let content = new ContentType(value);
                right=new Item({ client: ownClientId, clock: this.doc.getState(ownClientId) }, right, right && right.lastId, null, null, this, null, content);
                right.write();
                right.integrate();
            }
            else{
                common.push(value);
            }
          })
          if(common.length!=0){
            let content = new ContentAny(common);
            right=new Item({ client: ownClientId, clock: this.doc.getState(ownClientId) }, right, right && right.lastId, null, null, this, null, content);
            common=[];
            right.write();
            right.integrate();
          }
        }
        this._prelimContent = null
    }

    public push(...value: any) {
        this.doc.createTranscation("local");
        let right = this._start;
        while (right && right.right) {
            right = right.right;
        }
        let ownClientId = this.doc.clientID;
        let content: AbstractContent
        for(let val of value){
            let last=content;
            if (value instanceof AbstractType) {
                content = new ContentType(val)
            } else if (Object.prototype.toString.call(val) == '[object Object]') {
                content=new ContentType(new DMap(val));
            }else if(Object.prototype.toString.call(val) == '[object Array]'){
                content=new ContentType(new DArray(val))
            }
            else {
                content = new ContentAny([val])
            }
            if(last){
                if(!last.mergeWith(content)){
                    let item=new Item({ client: ownClientId, clock: this.doc.getState(ownClientId) }, right, right && right.lastId, null, null, this, null, last);
                    item.write();
                    item.integrate();
                    right=item;
                }else{
                    content=last;
                }
            }
        }
        if(content){
            let item=new Item({ client: ownClientId, clock: this.doc.getState(ownClientId) }, right, right && right.lastId, null, null, this, null, content);
            item.write();
            item.integrate();
        }
        this.doc.frameEndAndSend(null);
    }

    public insert(index:number,...value:any){
        this.doc.createTranscation("local");
        let right=this._start;
        let left:Item=null;
        let current=0;
        while(right){
            if(!right.deleted) 
            {
                if(current==index){
                    left=right.left;
                    break;
                }
                current+=right.length;
                if(current>index){
                    let tmp=this.doc.splitItem(right,right.length-current+index);
                    left=right;
                    right=tmp;
                    break;
                }
            }
            right=right.right;
        }
        let ownClientId = this.doc.clientID;
        let content: AbstractContent
        for(let val of value){
            let last=content;
            if (value instanceof AbstractType) {
                content = new ContentType(val)
            } else if (Object.prototype.toString.call(val) == '[object Object]') {
                content=new ContentType(new DMap(val));
            }else if(Object.prototype.toString.call(val) == '[object Array]'){
                content=new ContentType(new DArray(val))
            }
            else {
                content = new ContentAny([val])
            }
            if(last){
                if(!last.mergeWith(content)){
                    let item=new Item({ client: ownClientId, clock: this.doc.getState(ownClientId) }, left, left && left.lastId, right,right&&right.lastId, this, null, last);
                    item.write();
                    item.integrate();
                    left=item;
                }else{
                    content=last;
                }
            }
        }
        if(content){
            let item=new Item({ client: ownClientId, clock: this.doc.getState(ownClientId) }, left, left && left.lastId, right,right&&right.lastId, this, null, content);
            item.write();
            item.integrate();
        }
        this.doc.frameEndAndSend(null);
    }

    public remove(index?:number){
        this.doc.createTranscation("local");
        let item=this._start;
        let current=0;
        while(item){
            if(!item.deleted){
                if(current===index){
                    if(item.length>1){
                        this.doc.splitItem(item,1);
                    }
                    break;
                }
                current+=item.length;
                if(current>index){
                    item=this.doc.splitItem(item,item.length-current+index);
                    if(item.length!=1){
                        this.doc.splitItem(item,1);
                    }
                    break;
                }
            }
            item=item.right;
        }
        if(item){
            item.delete();
            item.write();
            this.doc.frameEndAndSend(null);
        }
    }
    
    public get refID(){
        return 2
    }

    public get value():any[]{
        return this.jsonParse();
    }
}