import { IEDTransform } from "../IEDTransform";
import { ParticleTools } from "./ParticleTools";
import { VeryEngine,DataType} from "../../engine";
import { ATTRIB, IEDAttrib, addEntityClass } from "../../engine/IEDProxy";
import { VeryParticleSystem } from "../../middleware/VeryParticle";


@addEntityClass
export class Rain extends IEDTransform{
    public get type(): string {
        return "particle";
    }
    public get subtype(){
        return "rain_zzl_code"
    }
    protected dispose(): void {
        this.sceneObj.dispose();
    }
    public sceneObj: VeryParticleSystem
    async Load() {
        this.sceneObj = ParticleTools.createParticleSystemWraper_Rain(
            this.subtype,
            this.name,
            VeryEngine.scene
        );
    }
    private title="雨"
    @ATTRIB()
    public updateSpeed:IEDAttrib<DataType.Slide>={
        name:"雨大小",
        type:DataType.Slide,
        async onchange(this:Rain,updateSpeedValue){
            var instance = this.sceneObj['particle'];
            var subParticle = VeryParticleSystem._subParticle[instance.name];
            var radiusValue = this.get("radius");
            instance.updateSpeed = updateSpeedValue;
            instance.minEmitBox = new BABYLON.Vector3(-1 * radiusValue,100,-1 * radiusValue);
            instance.maxEmitBox = new BABYLON.Vector3(radiusValue,90,radiusValue);
            instance.emitRate =
                (200 + (1300 * (instance.updateSpeed - 0.001)) / 0.006) *
                (Math.abs(instance.minEmitBox.x) / 50) *
                (Math.abs(instance.minEmitBox.x) / 50);
            if (subParticle) {
                if (updateSpeedValue < 0.003) {
                    subParticle.stop();
                } else {
                    subParticle.start();
                    subParticle.updateSpeed =0.001 + (updateSpeedValue - 0.003);
                }
                subParticle.minEmitBox = new BABYLON.Vector3(-1 * radiusValue,100,-1 * radiusValue);
                subParticle.maxEmitBox = new BABYLON.Vector3(radiusValue,100,radiusValue);
                subParticle.emitRate =
                    (4000 +(4000 * (subParticle.updateSpeed - 0.003)) / 0.004) *
                    (Math.abs(subParticle.minEmitBox.x) / 50) *(Math.abs(subParticle.minEmitBox.x) / 50);
            }
        },
        default:0.001,
        extra:{min:0.001,max:0.004},
        title:this.title
    }

    @ATTRIB()
    public radius:IEDAttrib<DataType.Slide>={
        name:"雨范围",
        type:DataType.Slide,
        onchange(this:Rain,radiusValue,isFirst){
            if(!isFirst){
                var instance = this.sceneObj['particle'];
                var subParticle = VeryParticleSystem._subParticle[instance.name];
                var updateSpeedValue = this.get("updateSpeed");
                instance.updateSpeed = updateSpeedValue;
                instance.minEmitBox = new BABYLON.Vector3(-1 * radiusValue,100,-1 * radiusValue);
                instance.maxEmitBox = new BABYLON.Vector3(radiusValue,90,radiusValue);
                instance.emitRate =
                    (200 + (1300 * (instance.updateSpeed - 0.001)) / 0.006) *
                    (Math.abs(instance.minEmitBox.x) / 50) *
                    (Math.abs(instance.minEmitBox.x) / 50);
                if (subParticle) {
                    if (updateSpeedValue < 0.003) {
                        subParticle.stop();
                    } else {
                        subParticle.start();
                        subParticle.updateSpeed =0.001 + (updateSpeedValue - 0.003);
                    }
                    subParticle.minEmitBox = new BABYLON.Vector3(-1 * radiusValue,100,-1 * radiusValue);
                    subParticle.maxEmitBox = new BABYLON.Vector3(radiusValue,100,radiusValue);
                    subParticle.emitRate =
                        (4000 +(4000 * (subParticle.updateSpeed - 0.003)) / 0.004) *
                        (Math.abs(subParticle.minEmitBox.x) / 50) *(Math.abs(subParticle.minEmitBox.x) / 50);
                }
            }
        },
        default:50,
        extra:{max:100,min:50},
        title:this.title
    }
}