import {DataType, IED, VeryEngine} from "../engine";
import { IEDEntity} from "./IEDEntity";
import {addEntityClass,IEDAttrib,ATTRIB, IEDProxyFactory} from "../engine/IEDProxy"
import { IEDFolder, IEDTable } from "../assets";


@addEntityClass
export class IEDLogic extends IEDEntity{
    protected setChild(child: IEDEntity) {
    }

    public filterParentType(parent: IEDEntity){
        if(parent.type==this.type||parent.type=="root"){
            return false;
        }
        if(VeryEngine.version=="5.1")
        for(let child of parent.children){
            if(child.type==this.type){
                return false;
            }
        }
        return true;
    }


    public sceneObj:string;
    public get type(): string {
        return "logic"
    }
    public static table2Logic:{[key:string]:string[]}={};
    public source:IEDTable;

    async Load(){
        let tableId=this.get("source");
        if(!IEDLogic.table2Logic[tableId])
            IEDLogic.table2Logic[tableId]=[this.id];
        else
            IEDLogic.table2Logic[tableId].push(this.id);
        this.source=VeryEngine.getAsset<IEDTable>(tableId);
        if(this.source)
        this.sceneObj=null;
        else
        this.sceneObj=undefined;
    }

    protected dispose(): void {
        
    }

    public export(vrData:any,file:any[],parent?:string){
        let json= super.export(vrData,file,parent);
        if(this.source){
            this.source.export(vrData,file);
            json.source=this.source.autoRename;
        }
    }

    public import(folder:IEDFolder,json:any): void {
        let split=json.source.split('.');
        if(split.length!=1){
            json.source=folder.getEmptyID(json.source)
        }
    }

    public get name(): string {
        if(this.source){
            let name=this.source.name;
            return name.substr(0,name.length-6);
        }
        return "";
    }

    public isEnabled:IEDAttrib<DataType.Bool>={
        name:"激活",
        type:DataType.Bool,
        default:true,
        title:"表格控制"
    }

    public nameStr=null;

    public watch(attr:string,func:(value:any,old:any,config?:{origin?:string,deleted?:boolean})=>void,group?:string){
        let self:IED=this;
        if(attr=="name")
            self=this.source;
        let func2=(value,old,config)=>{
            if(value==null){
                value=IEDProxyFactory.getDefault(self,attr);
            }
            else if(attr=="name"){
                value=value.substr(0,value.length-6)
            }
            func.call(self,value,old,config)
        }
        if(self)
        self.getEventGroup(group).addEventListener(attr,func2);
    }
}
