    public assetObj: BABYLON.PBRMaterial | BABYLON.StandardMaterial;

    protected async Load() {
        let newMat = this.data;
        let matJson = newMat.jsonParse();
        matJson.customType = this.subtype;
        let customType = matJson.customType;
        if (newMat !== undefined && newMat !== null && customType !== 'BABYLON.ShaderMaterial') {
            if (!customType || customType === 'BABYLON.StandardMaterial' || customType === 'BABYLON.PBRMaterial') {
                let textureTypeList: string[] = ["diffuseTexture", "specularTexture", "reflectionTexture", "refractionTexture", "emissiveTexture",
                    "bumpTexture", "opacityTexture", "ambientTexture", "lightmapTexture",
                    "metallicReflectanceTexture", "metallicTexture", "microSurfaceTexture", "reflectanceTexture", "reflectivityTexture"];
                for (let type of textureTypeList) {
                    delete matJson[type];
                }
                let mat = BABYLON.Material.Parse(matJson, VeryEngine.scene, "");
                if(VeryEngine.maxLights>0)
                (mat as BABYLON.StandardMaterial).maxSimultaneousLights = VeryEngine.maxLights;
                this.assetObj = mat as any;
            }
        }
    }

    public export(vrData: any, file: IED[]): void {
        let textureTypeList: string[] = ["diffuseTexture", "specularTexture", "reflectionTexture", "refractionTexture", "emissiveTexture",
            "bumpTexture", "opacityTexture", "ambientTexture", "lightmapTexture",
            "albedoTexture", "metallicReflectanceTexture", "metallicTexture", "microSurfaceTexture", "reflectanceTexture", "reflectivityTexture"];
        let json = this.data.jsonParse();
        json.name = this.name;
        if (this.subtype != json.customType) {
            json.customType = this.subtype;
        }
        if (this.subtype == "BABYLON.PBRMaterial" && json["diffuseTexture"]) {
            json["albedoTexture"] = json["diffuseTexture"];
            delete json["diffuseTexture"]
        }
        for (let texture of textureTypeList) {
            if (json[texture]) {
                if (json[texture].texture_id) {
                    let picAsset = VeryEngine.shareBox.id2Asset[json[texture].texture_id];
                    if (picAsset) {
                        picAsset.export(vrData, file);
                        json[texture].name = picAsset.name;
                    }
                    delete json[texture].texture_id;
                }
            }
        }
        vrData.materials.push(json);
    }

