    protected async dealWithTexture(textureId: string, assetType: string, type: string, isFirst: boolean) {
        if (textureId) {
            let picAsset = VeryEngine.getAsset<IEDTexture>(textureId);
            if (picAsset) {
                await picAsset.onceOnlyLoad();
                let baseTexture=this.initTextureParams(picAsset,type);
                if(baseTexture){
                    if(this.assetObj[assetType]){
                        this.assetObj[assetType].dispose()
                    }
                    this.assetObj[assetType] = baseTexture;
                    this.preview();
                }

            } else {
                if (isFirst) {
                    VeryEngine.entityReady.addEventListener(textureId,()=>{
                        let texture=VeryEngine.shareBox.id2Asset[textureId] as IEDTexture;
                        let baseTexture=this.initTextureParams(texture,type);
                        if(baseTexture){
                            this.assetObj[assetType] = baseTexture;
                            this.preview();
                        }
                    })
                }
            }
        } else if (this.assetObj[assetType]) {
            this.assetObj[assetType].dispose();
            this.assetObj[assetType] = (<BABYLON.StandardMaterial>VeryEngine.scene.defaultMaterial).diffuseTexture;
            if (!isFirst)
                this.preview();
        }
    }

    private initTextureParams(texture: IEDTexture, type: string) {
        let data=this.get("data."+type);
        if(data&&texture.assetObj){
            data=data.jsonParse();
            data.name=texture.assetObj;
            return BABYLON.Texture.Parse(data,VeryEngine.scene,"");
        }
        return null;
    }

    protected textureTemplate(name: string, assetType: string, type?: string): IEDAttrib<DataType.TextureBox> {
        if (!type) type = assetType;
        return {
            name: name,
            type: DataType.TextureBox,
            async onchange(this: IEDPSMaterial, val: string, isFirst: boolean) {
                await this.dealWithTexture(val, assetType, type, isFirst);
            },
            title: this.textureTitle
        }
    }

    protected templateLevel(assetType: string, type?: string): IEDAttrib<DataType.Number> {
        if (!type) type = assetType;
        return {
            name: "level",
            type: DataType.Number,
            onchange: function (this: IEDPSMaterial, val: number, a) {
                if (this.assetObj[assetType] && !a) {
                    this.assetObj[assetType].level = val;
                    this.preview();
                }
            },
            filter() {
                return this.get("data." + type + ".texture_id")
            },
            default: 1,
            title: this.textureTitle
        }
    }

