import { addEntityClass, ATTRIB, IEDAttrib, IEDProxyFactory } from "../../engine/IEDProxy";
import { VeryEngine, DataType, IED } from "../../engine";
import { IEDEntity } from "../IEDEntity";
import { IEDKrpano } from "./IEDKrpano";
import { Tools } from "../../utility/Tools";
import { IEDFolder } from "src/assets";
import { KrpanoCanvas } from "./IEDKrpanoCanvas";
@addEntityClass
export abstract class KrpanoCategory extends IEDKrpano {
    public static lastKrpanoCategory:KrpanoCategory
    public get subtype(): string {
        return "category";
    }

    protected async  realLoad(parent){
        KrpanoCategory.lastKrpanoCategory = this
        let canvas=this.parent as KrpanoCanvas;
        console.log(canvas);
        if(canvas){
            await canvas.loadPromise();
            this.sceneObj =null
        }
    };

    public filterParentType(parent: IEDKrpano): boolean {
        if (["canvas"].includes(parent.subtype)) {
            return true;
        } else {
            return false;
        }
    }
}
