import { Item } from ".";
import { ByteBuffer } from "../util/ByteBuffer";
import {AbstractContent,addContent} from "./AbstractContent"
@addContent
export class ContentDeleted extends AbstractContent{
    private len:number;

    constructor (len:number) {
      super();
      this.len = len
    }
  
    getLength () {
      return this.len
    }
  
    getContent () {
      return []
    }
  
    isCountable () {
      return false
    }

    copy () {
      return new ContentDeleted(this.len)
    }
  
  
  
    splice (offset:number) {
      let content = new ContentDeleted(this.len - offset)
      this.len = offset
      return content
    }
  

    mergeWith (right:ContentDeleted) {
      this.len += right.len
      return true
    }
  
    integrate (item:Item) {
      item.info |= 4;
    }
  

    delete () {}

    write (buff:ByteBuffer,offset?:number) {
      buff.WriteUshort(this.len);
    }

    value() {
      return null
    }

    public reset(value: any) {
      
    }

    public get refID(): number {
      return 2;
    }

    read(buff:ByteBuffer){
      let len=buff.ReadUshort();
      return new ContentDeleted(len);
    }
  }