import {IEDEntity} from "./entities"
import { DArray, DMap } from "./djs/type";
import { Progress } from "./utility/Progress";
import { VeryEngine,ViewportCamera} from "./engine";
import { Hierarchy } from "./hierarchy";
import { IEDTransform } from "./entities/IEDTransform";
import { IEDProxyFactory } from "./engine/IEDProxy";

export class Viewport {

    constructor(hierarchy:Hierarchy){
        if(hierarchy)
        hierarchy.viewport=this;
        VeryEngine.shareBox.sceneMap.watchObject("update",async (_,value:DMap)=>{
            if(VeryEngine.isLoadComplete)
                VeryEngine.change|=2;
            let entity=IEDProxyFactory.createNode(value) as IEDEntity;
            if(entity){
                VeryEngine.entityReady.addEventListener(entity.id,()=>{             
                    if(VeryEngine.EditMode)
                        hierarchy.addEntity(entity);
                    Progress.entityLoad();
                })
                await entity.mount();
            }else{
                setTimeout(() => {
                    let count=this.emptyChildrenCount(value.get("resource_id"));
                    for(let i=0;i<count;i++){
                        Progress.entityLoad();
                    }
                }, 0);
            }
         })
        this.loadBabylon();
    }

    private emptyIds:string[]=[];

    private emptyChildrenCount(id:string){
        let count=1;
        if(!this.emptyIds.includes(id)){
            this.emptyIds.push(id);
        }else{
            return 0
        }
        let emptyNode=VeryEngine.shareBox.sceneMap.get(id);
        let children=emptyNode.get("children") as DArray;
        if(children)
        for(let child of children.value){
            count+=this.emptyChildrenCount(child);
        }
        return count;
    }

    //物体选中事件
    private checkAct:({[key:string]:((entity:IEDEntity,pickEntityIds:IEDEntity[])=>void)[]})={};
    public addCheckAct(id:string,act:(entity:IEDEntity,pickEntityIds:IEDEntity[])=>void){
        if(!this.checkAct[id]) this.checkAct[id]=[]
        this.checkAct[id].push(act);
    }
    public removeCheckAct(id:string){
        delete this.checkAct[id]
    }

    //上帝相机视角变换事件
    public addBeforeViewUpdate(id:string,act:(entity:IEDEntity)=>void){
        VeryEngine.viewCamera.addBeforeViewUpdate(id,act);
    }
    public removeBeforeViewUpdate(id:string){
        VeryEngine.viewCamera.removeBeforeVeiwUpdate(id);
    }
    public addAfterViewUpdate(id:string,act:(entity:IEDEntity)=>void){
        VeryEngine.viewCamera.addAfterViewUpdate(id,act);
    }
    public removeAfterViewUpdate(id:string){
        VeryEngine.viewCamera.removeAfterVeiwUpdate(id);
    }

    private prePointerDown=[];
    public addPrePointerDown(func){
        if(!this.prePointerDown.includes(func))
        this.prePointerDown.push(func);
    }

    public hasPrePointerDown(func){
        return this.prePointerDown.includes(func)
    }
    public romvePrePointerDown(func){
        let index= this.prePointerDown.indexOf(func);
        if(index>=0)
            this.prePointerDown.splice(index,1);
    }
    private loadBabylon(){
        VeryEngine.engine.runRenderLoop(() => {
            if(VeryEngine.scene.activeCameras.length!=0||VeryEngine.scene.activeCamera)
                VeryEngine.scene.render();
        })
        window.addEventListener('resize', function () {
            VeryEngine.engine.resize();
        })
        if(VeryEngine.EditMode||VeryEngine.showBabylon){
            VeryEngine.commonJson.watch("pickEntity",()=>{
                for(let id in this.checkAct){
                    for(let tmp of this.checkAct[id]){
                        tmp(VeryEngine.pickedEntity,VeryEngine.pickedEntities);
                    }
                }
            })
            //创建上帝相机
            VeryEngine.viewCamera=new ViewportCamera();
            BABYLON.UtilityLayerRenderer.DefaultUtilityLayer.setRenderCamera(VeryEngine.viewCamera.Camera);
            BABYLON.PointerInfoBase.prototype.stopPropagation=function(){
                this.event.isStop=true;
            }
            VeryEngine.scene.onPointerObservable.add((data)=>{
                VeryEngine.viewCamera.onPointerDown(data.event);
            },BABYLON.PointerEventTypes.POINTERDOWN);
            VeryEngine.scene.onPointerMove=(evt)=>{
                VeryEngine.viewCamera.onPointerMove(evt);
            }
            VeryEngine.scene.onPointerObservable.add((data)=>{
                if(data.event.button==0){
                    if(this.prePointerDown.length!=0){
                        for(let act of this.prePointerDown){
                            act();
                        }
                        this.prePointerDown=[];
                    }
                    else{
                        if(data.pickInfo&&data.pickInfo.pickedMesh&&VeryEngine.shareBox.id2Entity[data.pickInfo.pickedMesh.id]){
                            let transform=VeryEngine.shareBox.id2Entity[data.pickInfo.pickedMesh.id];
                            if(transform&&transform instanceof IEDTransform&&transform.type!="gui")
                            setTimeout(()=>{
                                if(!data.event.isStop){
                                    VeryEngine.pickEntity(data.pickInfo.pickedMesh.id,data.event.ctrlKey);
                                }
                            },0)
                        }
                        else{
                            setTimeout(()=>{
                                if(!data.event.isStop)
                                VeryEngine.pickEntity("");
                            },0)
                        }
                    }
                }
                VeryEngine.viewCamera.onPointerUp(data.event);
            },BABYLON.PointerEventTypes.POINTERUP)
            document.getElementById("layout-viewport").addEventListener("mousedown",(ev:MouseEvent)=>{
                VeryEngine.viewCamera.onPointerDown(ev);
            })
            //todo 鼠标在窗口外抬起
            document.getElementById("layout-viewport").addEventListener("mouseup",(ev:MouseEvent)=>{
                VeryEngine.viewCamera.onPointerUp(ev);
            })
            document.getElementById("layout-viewport").addEventListener("mousemove",(ev:MouseEvent)=>{
                VeryEngine.viewCamera.onPointerMove(ev as any);
            })
            document.getElementById("layout-viewport").addEventListener('wheel', (evt)=>{VeryEngine.viewCamera.onMouseWheel(evt)}, false);
        }
    }
}