import {  IEDAsset } from ".";
import { VeryEngine, DataType } from "../engine";
import { DMap } from "../djs/type";
import { ATTRIB, IEDAttrib, addAssetClass } from "../engine/IEDProxy";
import { PluginPackage } from "../plugin/IEDPlugin";
@addAssetClass
export class IEDScript extends IEDAsset {
    public get type(): string {
        return "script";
    }

    public assetObj: string;
    public init(): void {
        if(!VeryEngine.EditMode){
            if(this._data.get("run"))
            this.onceOnlyLoad().then(()=>{
                var oHead = document.getElementsByTagName('head')[0];
                var oScript = document.createElement('script');
                oScript.type = 'text/javascript';
                oScript.innerHTML = this.id
                oScript.src = this.assetObj;
                // console.warn(oScript.src);
                oHead.appendChild(oScript);
            })
        }else{
            if(this._data.get("editRun"))
            this.onceOnlyLoad().then(()=>{
                var oHead = document.getElementsByTagName('head')[0];
                var oScript = document.createElement('script');
                oScript.type = 'text/javascript';
                oScript.innerHTML = "{\"id\":\""+this.id+"\"}"
                oScript.src = this.assetObj;
                PluginPackage.Pool[this.id]=new PluginPackage(this.id,[]);
                PluginPackage.Pool[this.id].isDepend=true;
                // console.warn(oScript.src);
                oHead.appendChild(oScript);
            })
        }
    }

    protected async Load() {
        try {
            this.assetObj = await OSS.getUrl(this.id, this.name, this.fileHash);
        } catch (e) {
            console.error(e);
            this.assetObj = null;
        }
    }

    public get suffix(): string[] {
        return ["js"];
    }

    protected async  upload(file: File, folderId?: string): Promise<any> {
        let data=await super.upload(file,folderId);
        let str = await new Promise<string>((resolve, reject) => {
            var reader = new FileReader();
            reader.readAsText(file, 'utf-8');
            reader.onload = function (e) {
                resolve(reader.result!.toString());
            };
            reader.onerror = function (err) {
                reject(err);
            }
        });
        if(str.includes("VR.VE_")){
            data.run=true;
        }else if(str.includes("VREdit.installPlugin")){
            data.editRun=true;
        }
        return data;
    }

    @ATTRIB()
    public run:IEDAttrib<DataType.Bool>={
        name:"加载自动运行",
        type:DataType.Bool
    }
}
