import { Tools } from "../utility/Tools";
import { IEDEntity} from "./IEDEntity";
import { ATTRIB, IEDAttrib, addEntityClass } from "../engine/IEDProxy";
import { IEDTransform } from "./IEDTransform";
import { IEDSprite } from "./IEDSprite";
import { DataType,VeryEngine } from "../engine";

@addEntityClass
export class IEDRoot extends IEDEntity{
    public filterParentType() {
        return false;
    }

    
    protected setChild( child: IEDEntity,config?:{origin:string}) {            
        if(config){
            if(child instanceof IEDTransform&&(!child.parent||child.parent.type!="root")){

                let isFirst=child.parent===undefined;
                if(!isFirst&&config.origin=="local"){
                    let position=child.sceneObj.getAbsolutePosition().asArray()
                    let rotation=child.sceneObj.absoluteRotationQuaternion.toEulerAngles();
                    let scal=child.sceneObj.absoluteScaling;
                    child.sceneObj.parent=null;      
                    child.set("position",position);
                    child.set("rotation",Tools.radianToEulerAngle(rotation).asArray());
                    child.set("scale",scal.asArray())
                }else{
                    child.sceneObj.parent=null;
                }
            }else if(child instanceof IEDSprite){
                child.realPos(null)
            }
        }
    }

    public sceneObj:BABYLON.Scene;
    public get type(): string {
        return "root"
    }
    
    async Load(){
        IEDEntity.rootId=this.id;
        VeryEngine.entityRootId=this.id;
        this.sceneObj=VeryEngine.scene;
    }

    @ATTRIB("scene.clearColor")
    public checkCollisions:IEDAttrib<DataType.Color4>={
        name:"相机背景色",
        type:DataType.Color4,
        onchange(this:IEDRoot,val){
            if(VeryEngine.EditMode)
            VeryEngine.viewCamera.veryCamera.clearColor = BABYLON.Color4.FromArray(val);
        },
        default:[0,0,0,0]
    }

    @ATTRIB("viewportMinZ")
    public viewportMinZ:IEDAttrib<DataType.Number>={
        name:"近平面(编辑相机)",
        type:DataType.Number,
        onchange(this:IEDRoot,val){
            if(VeryEngine.EditMode)
            VeryEngine.scene.cameraToUseForPointers.minZ = val;
        },
        default:0.1,
    }

    @ATTRIB("viewportMaxZ")
    public viewportMaxZ:IEDAttrib<DataType.Number>={
        name:"远平面(编辑相机)",
        type:DataType.Number,
        onchange(this:IEDRoot,val){
            if(VeryEngine.EditMode)
            VeryEngine.scene.cameraToUseForPointers.maxZ = val;
        },
        default:9000000,
    }

    private environment="环境参数"

    @ATTRIB("environment.ambientColor")
    public ambientColor:IEDAttrib<DataType.Color3>={
        name:"环境光",
        type:DataType.Color3,
        onchange(this:IEDRoot,val){
            VeryEngine.scene.ambientColor = BABYLON.Color3.FromArray(val);
        },
        default:[0,0,0],
        title:this.environment
    }

    public isEnabled: IEDAttrib<DataType.Bool>=null;

    @ATTRIB("environment.maxLights")
    public maxLights:IEDAttrib<DataType.Number>={
        name:"最大灯光格个数",
        des:"超过该个数的灯光会被屏蔽,灯光越多，消耗的性能越大",
        type:DataType.Number,
        onchange(this:IEDRoot,val){
            for(let material of VeryEngine.scene.materials){
                (material as BABYLON.StandardMaterial).maxSimultaneousLights=val;
            }
            VeryEngine.maxLights=val;
        },
        default:4,
        title:this.environment
    }

    @ATTRIB("environment.environmentIntensity")
    public environmentIntensity:IEDAttrib<DataType.Number>={
        name:"IBL",
        type:DataType.Number,
        onchange(this:IEDRoot,val){
            VeryEngine.scene.environmentIntensity = val;
        },
        default:1,
        title:this.environment
    }

    @ATTRIB("environment.fogMode")
    public fogMode:IEDAttrib<DataType.DropDown>={
        name:"雾效模式",
        type:DataType.DropDown,
        onchange(this:IEDRoot,val){
            VeryEngine.scene.fogMode = val;
        },
        extra: ['无', '指数模式', '指数平方模式', '线性模式'],
        title:this.environment
    }

    @ATTRIB("environment.fogColor")
    public fogColor:IEDAttrib<DataType.Color3>={
        name:"雾效颜色",
        type:DataType.Color3,
        onchange(this:IEDRoot,val){
            VeryEngine.scene.fogColor = BABYLON.Color3.FromArray(val);
        },
        filter(){
            if (this.get('environment.fogMode') !== BABYLON.Scene.FOGMODE_NONE) {
                return true;
            } else {
                return false;
            }
        },
        default:[0,0,0],
        title:this.environment
    }

    @ATTRIB("environment.fogDensity")
    public fogDensity:IEDAttrib<DataType.Number>={
        name:"雾效密度",
        type:DataType.Number,
        onchange(this:IEDRoot,val){
            VeryEngine.scene.fogDensity=val;
        },
        filter(){
            if (this.get('environment.fogMode') === BABYLON.Scene.FOGMODE_EXP || this.get('environment.fogMode') === BABYLON.Scene.FOGMODE_EXP2) {
                return true;
            } else {
                return false;
            }
        },
        default:0.1,
        title:this.environment
    }

    @ATTRIB("environment.fogStart")
    public fogStart:IEDAttrib<DataType.Number>={
        name:"雾效起始距离",
        type:DataType.Number,
        onchange(this:IEDRoot,val){
            VeryEngine.scene.fogStart=val;
        },
        filter(){
            if (this.get('environment.fogMode') === BABYLON.Scene.FOGMODE_LINEAR) {
                return true;
            } else {
                return false;
            }
        },
        title:this.environment
    }

    @ATTRIB("environment.fogEnd")
    public fogEnd:IEDAttrib<DataType.Number>={
        name:"雾效终止距离",
        type:DataType.Number,
        onchange(this:IEDRoot,val){
            VeryEngine.scene.fogEnd=val;
        },
        filter(){
            if (this.get('environment.fogMode') === BABYLON.Scene.FOGMODE_LINEAR) {
                return true;
            } else {
                return false;
            }
        },
        default:1000,
        title:this.environment
    }

    private skyBoxTitle="天空盒"

    // @ATTRIB("skybox.enabled")
    public skyboxEnabled:IEDAttrib<DataType.Bool>={
        name:"启用",
        type:DataType.Bool,
        onchange(this:IEDRoot,val){
            if (val === true) {
                if (this.skyBox === null) {
                    this.createSkyBox();
                } else {
                    this.skyBox.setEnabled(true);
                }
            } else {
                if (this.skyBox) {
                    this.skyBox.setEnabled(false);
                }
            }
        },
        title:this.skyBoxTitle
    }

    // @ATTRIB("skybox.texture_id")
    public skyboxTexture:IEDAttrib<DataType.TextureBox>={
        name:"环境贴图",
        type:DataType.TextureBox,
        async onchange(this:IEDRoot,val){
            if (val) {
                let picAsset = VeryEngine.shareBox.id2Asset[val];
                if (picAsset) {

                    if (picAsset.assetObj && picAsset['skybox']) {
                        this.skyBoxMaterial!.reflectionTexture = picAsset['skybox'];
                    } else {
                        await picAsset.onceOnlyLoad();
                        if (picAsset.assetObj) {
                            if (picAsset.fileName.toLowerCase().endsWith('.env') || picAsset.fileName.toLowerCase().endsWith('.dds')) {
                                picAsset['skybox'] = new BABYLON.CubeTexture(this.textureUrlFormat(picAsset.assetObj), VeryEngine.scene);
                            }
                            else if (picAsset.fileName.toLowerCase().endsWith('.hdr')) {
                                picAsset['skybox'] = new BABYLON.HDRCubeTexture(this.textureUrlFormat(picAsset.assetObj), VeryEngine.scene, 1024);
                            } else {
                                picAsset['skybox'] = new BABYLON.Texture(this.textureUrlFormat(picAsset.assetObj), VeryEngine.scene);
                            }

                            this.skyBoxMaterial!.reflectionTexture = picAsset['skybox'];
                            if (this.skyBoxMaterial!.reflectionTexture) {
                                this.skyBoxMaterial!.reflectionTexture.coordinatesMode = BABYLON.Texture.SKYBOX_MODE;
                            }
                        }
                    }
                    return;
                }
            }
            this.skyBoxMaterial!.reflectionTexture = this.skyEnviromentCopy;
            if (this.skyBoxMaterial!.reflectionTexture) {
                this.skyBoxMaterial!.reflectionTexture.coordinatesMode = BABYLON.Texture.SKYBOX_MODE;
            }
        },
        filter(){
            return this.get("skybox.enabled")
        },
        title:this.skyBoxTitle
    }

    @ATTRIB("scene.backgroundTexture")
    public backgroundTexture:IEDAttrib<DataType.TextureBox>={
        name:"场景背景图片",
        type:DataType.TextureBox,
        async onchange(this:IEDRoot,val){
            if (this.sceneBackgroundLayer === null) {
                this.sceneBackgroundLayer = new BABYLON.Layer('__background_texture__', '', VeryEngine.scene, true);
            }
            if (val) {
                let picAsset = VeryEngine.shareBox.id2Asset[val];
                if (picAsset) {
                    if (picAsset.assetObj && picAsset['backgroundTexture']) {
                        this.sceneBackgroundLayer.texture = picAsset['backgroundTexture'];
                    } else {
                        await picAsset.onceOnlyLoad();
                        if (picAsset.assetObj) {
                            picAsset['backgroundTexture'] = new BABYLON.Texture(this.textureUrlFormat(picAsset.assetObj), VeryEngine.scene);

                            this.sceneBackgroundLayer.texture = picAsset['backgroundTexture'];
                        }
                    }
                }
            } else {
                if (this.sceneBackgroundLayer !== null) {
                    this.sceneBackgroundLayer.texture = null;
                }
            }
        },
        title:"场景背景图片"
    }

    private postprocessTitle="滤镜";

    // @ATTRIB("postprocess.sample")
    // public postprocessSample(){

    // }

    public enableSkybox: boolean = false;
    public skyBox: Nullable<BABYLON.Mesh> = null;
    public skyBoxMaterial: Nullable<BABYLON.PBRMaterial> = null;
    public skyEnviromentCopy: Nullable<BABYLON.BaseTexture> = null;

    public viewScenePipeline: BABYLON.DefaultRenderingPipeline;
    public ssrPostProcess: Nullable<BABYLON.ScreenSpaceReflectionPostProcess> = null;
    public ssaoPostProcess: Nullable<BABYLON.SSAO2RenderingPipeline> = null;

    public  mapSizeShadow: number = 1024;

    public  sceneBackgroundLayer: Nullable<BABYLON.Layer> = null;

    public  createSkyBox(): void {
        this.skyBox = BABYLON.MeshBuilder.CreateBox('__skybox_veryengine__', { size: 200000000 }, VeryEngine.scene);
        this.skyBox.isPickable = false;
        this.skyBox.infiniteDistance = true;
        // TODO: 4.2.0版本无此参数
        // console.warn(Config.skyBox.ignoreCameraMaxZ);
        this.skyBox.ignoreCameraMaxZ = true;
        this.skyBoxMaterial = new BABYLON.PBRMaterial('__skybox_veryengine__', VeryEngine.scene);
        this.skyBoxMaterial.backFaceCulling = false;
        this.skyBoxMaterial.disableLighting = true;
        this.skyBox.material = this.skyBoxMaterial;

        if (this.skyEnviromentCopy) {
            this.skyBoxMaterial!.reflectionTexture = this.skyEnviromentCopy;
        } else {
            if (VeryEngine.scene.environmentTexture) {
                this.skyBoxMaterial!.reflectionTexture = VeryEngine.scene.environmentTexture.clone();
                this.skyEnviromentCopy = this.skyBoxMaterial!.reflectionTexture;
            }
        }
        if (this.skyBoxMaterial!.reflectionTexture) {
            this.skyBoxMaterial!.reflectionTexture.coordinatesMode = BABYLON.Texture.SKYBOX_MODE;
        }

    }

    public _specialExtension: string[] = ['tif', 'tiff', 'tga', 'dds', 'hdr', 'exr', 'env', 'targa', 'psd'];
    public textureUrlFormat(url: string): string {
        for (let i = 0, length = this._specialExtension.length; i < length; i++) {
            const index = url.indexOf(this._specialExtension[i]);
            if (index >= 0) {
                return url.substring(0, index + this._specialExtension[i].length);
            }
        }
        return url;
    }
}
