import { IEDGUI } from "./IEDGUI";
import {addEntityClass,ATTRIB, IEDAttrib} from "../../engine/IEDProxy"
import { VeryEngine,DataType} from "../../engine";
import { Tools } from "../../utility/Tools";

@addEntityClass
export class Input extends IEDGUI{
    public get subtype(): string {
        return "input";
    }
    private inputDiv:HTMLInputElement;

    protected realLoad(is2D:boolean){
        if(is2D){
            this.sceneObj = document.createElement("div");
            let divStyle = this.sceneObj.style;
            this.sceneObj.style.pointerEvents = "auto";
            divStyle.position = "absolute";
            divStyle.overflow = "hidden";
            divStyle.position = "absolute";
            divStyle.display = "flex";
            divStyle.borderStyle = "solid";
            divStyle.borderColor="black";
            this.inputDiv = document.createElement("input");
            let inputDivStyle = this.inputDiv.style;
            this.inputDiv.type = "text";
            inputDivStyle.width = "100%";
            inputDivStyle.height = "100%";
            inputDivStyle.fontSize = "inherit";
            inputDivStyle.background = "transparent";
            inputDivStyle.color="inherit";
            this.sceneObj.append(this.inputDiv);
            !VeryEngine.EditMode &&
            (this.inputDiv.onchange = () => {
                this.set("gui.text", this.inputDiv.value);
            });
        }else{
            let input = new BABYLON.GUI.InputText(this.name, "");
            this.sceneObj = input;
            input.isPointerBlocker = true;
            !VeryEngine.EditMode &&
            (input.onTextChangedObservable.add( () => {
                this.set("gui.text", input.text);
            }));
        }
    }

    private title="输入框"

    @ATTRIB("gui.background")
    public background:IEDAttrib<DataType.Color4>={
        name:"背景色",
        type:DataType.Color4,
        onchange(this:Input,val){
            if(this.is2D){
                (this.sceneObj as HTMLElement).style.background = Tools.rgba2hsvString(val);
            }else{
                (this.sceneObj as BABYLON.GUI.InputText).background = Tools.rgba2hsvString(val);
            }
        },
        title:this.title
    }

    @ATTRIB("gui.textColor")
    public textColor:IEDAttrib<DataType.Color4>={
        name:"字体颜色",
        type:DataType.Color4,
        onchange(this:Input,val){
            if(this.is2D){
                (this.sceneObj as HTMLElement).style.color = Tools.rgba2hsvString(val);
            }else{
                (this.sceneObj as BABYLON.GUI.InputText).color = Tools.rgba2hsvString(val);
            }
        },
        default:[0,0,0,1],
        title:this.title
    }

    @ATTRIB("gui.text")
    public text:IEDAttrib<DataType.Textarea>={
        name:"文字",
        type:DataType.Textarea,
        onchange(this:Input,val,isFirst) {
            if(this.is2D){
                val=val+"";
                this.inputDiv.value = val.replace(/ /g, "&nbsp;").replace(/\n/g, "<br>");
            }else
                (this.sceneObj as BABYLON.GUI.InputText).text=val;
            if(isFirst){
                let split = val.split(".");
                if (split[split.length - 1].startsWith("*"))
                    this.addVeryVal({ attr: "gui.text", valName: val });
            }
        },
        title:this.title
    }

    @ATTRIB("gui.fontSize")
    public fontSize:IEDAttrib<DataType.Number>={
        name:"字体大小",
        type:DataType.Number,
        onchange(this:Input,val){
            if(this.is2D){
                (this.sceneObj as HTMLElement).style.fontSize = val+"px"
            }else{
                (this.sceneObj as BABYLON.GUI.InputText).fontSize = val
            }
        },
        default:18,
        title:this.title
    }

    @ATTRIB("gui.placeholderText")
    public placeholderText:IEDAttrib<DataType.String>={
        name:"预留文字",
        type:DataType.String,
        onchange(this:Input,val){
            if(this.is2D){
                this.inputDiv.placeholder = val;
            }else{
                (this.sceneObj as BABYLON.GUI.InputText).placeholderText = val
            }
        },
        default:"输入...",
        title:this.title
    }

    @ATTRIB("gui.placeholderColor")
    public placeholderColor:IEDAttrib<DataType.Color4>={
        name:"预留文字颜色",
        type:DataType.Color4,
        onchange(this:Input,val){
            if(this.is2D){
                let inputDivStyle = this.inputDiv.style;
                this.inputDiv.setAttribute("data-placeholder", "color");
                inputDivStyle.setProperty("--c", Tools.rgba2hsvString(val));
            }else{
                (this.sceneObj as BABYLON.GUI.InputText).placeholderColor = Tools.rgba2hsvString(val)
            }
        },
        default:[0,0,0,0.4],
        title:this.title
    }

    @ATTRIB("gui.focusedBackground")
    public focusedBackground:IEDAttrib<DataType.Color4>={
        name:"聚焦背景色",
        type:DataType.Color4,
        onchange(this:Input,val){
            if(this.is2D){
                this.inputDiv.onfocus = () => {
                    (this.sceneObj as HTMLElement).style.backgroundColor =Tools.rgba2hsvString(val);
                    (this.sceneObj as HTMLElement).style.borderColor="white"
                };
                this.inputDiv.onblur = () => {
                    (this.sceneObj as HTMLElement).style.backgroundColor = Tools.rgba2hsvString(
                        this.get("gui.background")
                    );
                    (this.sceneObj as HTMLElement).style.borderColor="black"
                };
            }else{
                (this.sceneObj as BABYLON.GUI.InputText).focusedBackground = Tools.rgba2hsvString(val)
            }
        },
        default:[0.502, 0.502, 0.502, 1],
        title:this.title
    }

    @ATTRIB("gui.thickness")
    public thickness:IEDAttrib<DataType.Number>={
        name:"边框厚度",
        type:DataType.Number,
        onchange(this:Input,val){
            if(this.is2D){
                (this.sceneObj as HTMLElement).style.borderWidth = val + "px";
            }else{
                (this.sceneObj as BABYLON.GUI.InputText).thickness= val
            }
        },
        default:1,
        title:this.title
    }
}