 import { Item } from "./Item";
import {AbstractContent,addContent} from "./AbstractContent"
import {ByteBuffer} from "../util/ByteBuffer"
@addContent
export class ContentAny extends AbstractContent {
    private arr:any[];
    constructor (arr:any[]) {
      super();
      this.arr = arr
    }
  
    getLength () {
      return this.arr.length
    }
  
    public get refID(): number {
      return 1;
    }
    getContent () {
      return this.arr
    }
  
    isCountable () {
      return true
    }
  
    copy () {
      return new ContentAny([...this.arr])
    }
    
    splice (offset:number) {
      let content = new ContentAny(this.arr.slice(offset))
      this.arr = this.arr.slice(0, offset)
      return content
    }
  
    mergeWith (right:ContentAny) {
      this.arr = this.arr.concat(right.arr)
      return true
    }
  
    integrate (item:Item) {}

    delete () {}
    reset(value: any): void {
      this.arr[this.arr.length-1]=value;
    }
    write (buff:ByteBuffer,offset?:number) {
      const len = this.arr.length;
      if(!offset)
        offset=0;
      buff.WriteUshort(len-offset);
      for (let i = offset; i < len; i++) {
        const c = this.arr[i];
        buff.WriteAny(c);
      }
    }
  
    read(buff:ByteBuffer){
      let len=buff.ReadUshort();
      let arry=[];
      for(let i=0;i<len;i++){
        arry.push(buff.ReadAny());
      }
      return new ContentAny(arry);
    }

    value(is_array?:boolean) {
      if(this.arr.length==0)
        return null;
      else{
        if(!is_array)
        return this.arr[this.arr.length-1];
        else
          return [...this.arr];
      }
    }
  }