import { IEDGUI } from "./IEDGUI";
import {addEntityClass,ATTRIB, IEDAttrib} from "../../engine/IEDProxy"
import { DataType, VeryEngine} from "../../engine";
import { Tools } from "../../utility/Tools";

abstract class SliderMoveTool extends IEDGUI{

    protected sliderTrack:HTMLElement;
    protected sliderProgress:HTMLElement;
    protected sliderThumb:HTMLElement;

    protected startPos={x:0,y:0};
    protected startVal=0;
    protected cos:number;
    protected sin:number;
    protected abstract load3D():void;
    protected title="滑动条";
    protected realLoad(is2D: boolean): void {
        if(is2D){
            this.sceneObj = document.createElement("div");
            let divStyle = this.sceneObj.style;
            divStyle.pointerEvents = "auto";
            divStyle.position = "absolute";
            divStyle.display = "flex";
            divStyle.alignItems = "center";
            //背景
            this.sliderTrack = document.createElement("div");
            let sliderTrackStyle = this.sliderTrack.style;
            this.sliderTrack.className = "sliderTrack";
            sliderTrackStyle.width = "100%";
            sliderTrackStyle.borderStyle="solid";
            sliderTrackStyle.backgroundSize = "100% 100%";
            sliderTrackStyle.backgroundRepeat = "no-repeat";
            sliderTrackStyle.position = "relative";
            this.sceneObj.append(this.sliderTrack);
            this.sliderTrack.addEventListener("mousedown",(ev)=>{
                let val=ev.offsetX/this.sliderTrack.offsetWidth;
                let min=this.get("gui.min");
                let max=this.get("gui.max");
                val=min+(max-min)*val;
                this.set("gui.value",val);
            })
            //滑动后显示的区域
            this.sliderProgress = document.createElement("div");
            let sliderProgressStyle = this.sliderProgress.style;
            this.sliderProgress.className = "sliderProgress";
            sliderProgressStyle.height = "100%";
            sliderProgressStyle.borderRadius="inherit";
            sliderProgressStyle.backgroundSize = "100% 100%";
            sliderProgressStyle.backgroundRepeat = "no-repeat";
            sliderProgressStyle.position = "relative";
            this.sliderTrack.append(this.sliderProgress);
            //滑块
            this.sliderThumb = document.createElement("div");
            let sliderThumbStyle = this.sliderThumb.style;
            this.sliderThumb.className = "sliderThumb";
            sliderThumbStyle.position = "absolute";
            sliderThumbStyle.boxSizing="content-box";
            sliderThumbStyle.transform = "translateX(-50%)";
            sliderThumbStyle.backgroundSize = "100% 100%";
            sliderThumbStyle.backgroundRepeat = "no-repeat";
            if(this.subtype=="slider")
            sliderThumbStyle.border="1px solid"

            let minImage=document.createElement("img");
            minImage.src="data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABAQAAAAA3bvkkAAAAAnRSTlMAAQGU/a4AAAABb3JOVAHPoneaAAAACklEQVQIHWNoAAAAggCB8KrjIgAAAABJRU5ErkJggg==";
            minImage.style.height="100%";
            this.sliderThumb.append(minImage);
            this.sceneObj.append(this.sliderThumb);
        }else{
            this.load3D();
            (this.sceneObj as BABYLON.GUI.Slider).onValueChangedObservable.add((val)=>{
                this.set("gui.value",val/100)
            })
        }
        if(is2D){
            //移动端没有offsetX/Y，只能通过手动计算偏移量
            this.sliderThumb.addEventListener("mousedown",(ev)=>{
                ev.customPropagation();
                this.thumbStartInfo(ev);
                window.addEventListener("mousemove",this.thumMove);
                window.addEventListener("mouseup",this.thumEnd);
            })
            this.sliderThumb.addEventListener("touchstart",(ev)=>{
                ev.customPropagation();
                this.thumbStartInfo(ev.targetTouches[0]);
                window.addEventListener("touchmove",this.thumMove);
                window.addEventListener("touchend",this.thumEnd);
            })
        }
        if(VeryEngine.EditMode)
        VeryEngine.resetPanel();
    }

    protected thumbStartInfo(ev:Touch|MouseEvent){
        this.startPos={x:ev.clientX,y:ev.clientY};
        let min=this.get("gui.min");
        let max=this.get("gui.max");
        this.startVal=(this.get("gui.value")-min)/(max-min);
        let roataion=0;
        let parent:IEDGUI=this;
        while(!parent.subtype.includes("canvas")){
            roataion+=parent.get("gui.rotation");
            parent=parent.parent as IEDGUI;
        }
        roataion=roataion/180*Math.PI;
        this.cos=Math.cos(roataion);
        this.sin=Math.sin(roataion);
    }

    protected thumMove=(ev:MouseEvent|TouchEvent)=>{
        let diff;
        if("targetTouches" in ev){
            diff={x:ev.targetTouches[0].clientX-this.startPos.x,y:ev.targetTouches[0].clientY-this.startPos.y}
        }else{
            diff={x:ev.clientX-this.startPos.x,y:ev.clientY-this.startPos.y};
        }
        let length=diff.x*this.cos+diff.y*this.sin;
        let val=length/this.sliderTrack.offsetWidth;
        val=this.startVal+val;
        if(val<0) val=0;if(val>1) val=1;
        let min=this.get("gui.min");
        let max=this.get("gui.max");
        val=min+(max-min)*val;
        this.set("gui.value",val);
    }

    protected thumEnd=()=>{   
        window.removeEventListener("mousemove",this.thumMove);
        window.removeEventListener("mouseup",this.thumEnd);
    }

    @ATTRIB("gui.barOffset")
    public barOffset:IEDAttrib<DataType.Number>={
        name:"边界偏移",
        type:DataType.Number,
        onchange(this:SliderMoveTool,val){
            if(this.is2D){
                this.sliderTrack.style.height="calc(100% - "+(val*2)+"px)";
            }else{
                (this.sceneObj as BABYLON.GUI.Slider).barOffset=val;
            }
        },
        title:this.title,
        default:4
    }

    @ATTRIB("gui.thumbWidth")
    public thumbWidth:IEDAttrib<DataType.Number>={
        name:"滑块高度百分比",
        type:DataType.Number,
        onchange(this:SliderMoveTool,val){
            if(this.is2D){
                this.sliderThumb.style.height=val+"%";
            }else{
            }
        },
        filter() {
            return this.is2D
        },
        title:this.title,
        default:100
    }

    @ATTRIB("gui.value")
    public value:IEDAttrib<DataType.Slide>={
        name:"值",
        type:DataType.Slide,
        onchange(this:SliderMoveTool,val,isFirst){
            this.controlValue(isFirst);
        },
        extra:{min:function(){return this.get("gui.min")},max:function(){
            return this.get("gui.max")
        }},
        title:this.title,
    }

    @ATTRIB("gui.min")
    public min:IEDAttrib<DataType.Number>={
        name:"最小值",
        type:DataType.Number,
        onchange(this:SliderMoveTool,val,isFirst){
            if(!isFirst){
                VeryEngine.resetPanel();
                this.controlValue(isFirst);
            }
        },
        title:this.title
    }

    @ATTRIB("gui.max")
    public max:IEDAttrib<DataType.Number>={
        name:"最大值",
        type:DataType.Number,
        onchange(this:SliderMoveTool,val,isFirst){
            if(!isFirst){
                VeryEngine.resetPanel();
                this.controlValue(isFirst);
            }
        },
        title:this.title,
        default:1
    }

    @ATTRIB("gui.thickness")
    public thickness:IEDAttrib<DataType.Number>={
        name:"边框厚度",
        type:DataType.Number,
        onchange(this:SliderMoveTool,val){
            if(this.is2D){
                this.sliderTrack.style.borderWidth = val + "px";
            }
        },
        filter(this:SliderMoveTool){
            return this.is2D==true;
        },
        title:this.title
    }

    @ATTRIB("gui.borderColor")
    public borderColor:IEDAttrib<DataType.Color4>={
        name:"边框色",
        type:DataType.Color4,
        onchange(this:SliderMoveTool,val){
            if(this.is2D){
                this.sliderTrack.style.borderColor = Tools.rgba2hsvString(val);
            }
        },
        filter(this:SliderMoveTool){
            return this.is2D==true;
        },
        title:this.title
    }

    @ATTRIB("gui.cornerRadius")
    public cornerRadius:IEDAttrib<DataType.Number>={
        name:"圆角半径",
        type:DataType.Number,
        onchange(this:SliderMoveTool,val){
            if(this.is2D){
                this.sliderTrack.style.borderRadius = val + "px";
            }
        },
        filter(this:SliderMoveTool){
            return this.is2D==true;
        },
        default:2,
        title:this.title
    }

    private controlValue(isFirst:boolean){
        let val=this.get("gui.value");
        let min=this.get("gui.min");
        let max=this.get("gui.max");
        val=(val-min)/(max-min);
        if(val<0) val=0;
        if(val>1) val=1;
        if(this.is2D){
            this.sliderThumb.style.left=(val*100)+"%";
            this.sliderProgress.style.width=(val*100)+"%"
        }else{
            if(!isFirst||val!=0)
            (this.sceneObj as BABYLON.GUI.Slider).value=val*100;
        }
    }
}

@addEntityClass
export class Slider extends SliderMoveTool{
    public get subtype(): string {
        return "slider";
    }

    protected load3D(): void {
        let slider = new BABYLON.GUI.Slider(this.name);
        this.sceneObj = slider;
        slider.isPointerBlocker = true;
    }

    @ATTRIB("gui.thumbBorderColor")
    public thumbBorderColor:IEDAttrib<DataType.Color4>={
        name:"滑块边框颜色",
        type:DataType.Color4,
        onchange(this:Slider,val){
            if(this.is2D){
                 this.sliderThumb.style.borderColor = Tools.rgba2hsvString(val);
            }else{
                (this.sceneObj as BABYLON.GUI.Slider).borderColor = Tools.rgba2hsvString(val);
            }
        },
        title:this.title
    }

    @ATTRIB("gui.color")
    public color:IEDAttrib<DataType.Color4>={
        name:"前景色",
        type:DataType.Color4,
        onchange(this:Slider,val){
            if(this.is2D){
                 this.sliderThumb.style.backgroundColor = Tools.rgba2hsvString(val);
                 this.sliderProgress.style.backgroundColor=Tools.rgba2hsvString(val);
            }else{
                (this.sceneObj as BABYLON.GUI.Slider).color = Tools.rgba2hsvString(val);
            }
        },
        title:this.title
    }

    @ATTRIB("gui.background")
    public background:IEDAttrib<DataType.Color4>={
        name:"背景色",
        type:DataType.Color4,
        onchange(this:Slider,val){
            if(this.is2D){
                this.sliderTrack.style.background = Tools.rgba2hsvString(val);
            }else{
                (this.sceneObj as BABYLON.GUI.Slider).background = Tools.rgba2hsvString(val);
            }
        },
        title:this.title
    }
}

@addEntityClass
export class SliderImage extends SliderMoveTool{
    public get subtype(): string {
        return "imageslider";
    }

    protected load3D(): void {
        let slider = new BABYLON.GUI.ImageBasedSlider(this.name);
        this.sceneObj = slider;
        slider.backgroundImage = new BABYLON.GUI.Image("back", "");
        slider.isPointerBlocker = true;
    }

    @ATTRIB("gui.backgroundImage")
    public backgroundImage:IEDAttrib<DataType.TextureBox>={
        name:"背景图片",
        type:DataType.TextureBox,
        async onchange(this:SliderImage,val){
            let picAsset = VeryEngine.shareBox.id2Asset[val];
            if (picAsset) {
                await picAsset.onceOnlyLoad();
                if(this.is2D)
                    this.sliderTrack.style.backgroundImage = `url(${picAsset.assetObj})`;
                else{
                    (this.sceneObj as BABYLON.GUI.ImageBasedSlider).backgroundImage.domImage=document.createElement("img");
                    (this.sceneObj as BABYLON.GUI.ImageBasedSlider).backgroundImage.domImage.src=picAsset.assetObj;
                }
            }else{
                if(this.is2D)
                    this.sliderTrack.style.backgroundImage = "";
                else{
                    (this.sceneObj as BABYLON.GUI.ImageBasedSlider).backgroundImage.domImage=document.createElement("img");
                    (this.sceneObj as BABYLON.GUI.ImageBasedSlider).backgroundImage._markAsDirty();
                }
            }
        },
        default:"backgroundImage",
        title:this.title
    }

    @ATTRIB("gui.valueBarImage")
    public valueBarImage:IEDAttrib<DataType.TextureBox>={
        name:"前景图片",
        type:DataType.TextureBox,
        async onchange(this:SliderImage,val){
            let picAsset = VeryEngine.shareBox.id2Asset[val];
            if (picAsset) {
                await picAsset.onceOnlyLoad();
                if(this.is2D)
                    this.sliderProgress.style.backgroundImage = `url(${picAsset.assetObj})`;
                else{
                    (this.sceneObj as BABYLON.GUI.ImageBasedSlider).valueBarImage.domImage=document.createElement("img");
                    (this.sceneObj as BABYLON.GUI.ImageBasedSlider).valueBarImage.domImage.src=picAsset.assetObj;
                }
            }else{
                if(this.is2D)
                    this.sliderProgress.style.backgroundImage = "";
                else{
                    (this.sceneObj as BABYLON.GUI.ImageBasedSlider).valueBarImage.domImage=document.createElement("img");
                    (this.sceneObj as BABYLON.GUI.ImageBasedSlider).valueBarImage._markAsDirty();
                }
            }
        },
        default:"valueImage",
        title:this.title
    }

    @ATTRIB("gui.thumbImage")
    public thumbImage:IEDAttrib<DataType.TextureBox>={
        name:"滑块图片",
        type:DataType.TextureBox,
        async onchange(this:SliderImage,val){
            let picAsset = VeryEngine.shareBox.id2Asset[val];
            if (picAsset) {
                await picAsset.onceOnlyLoad();
                if(this.is2D)
                    (this.sliderThumb as HTMLImageElement).style.backgroundImage = `url(${picAsset.assetObj})`;
                else{
                    (this.sceneObj as BABYLON.GUI.ImageBasedSlider).thumbImage.domImage=document.createElement("img");
                    (this.sceneObj as BABYLON.GUI.ImageBasedSlider).thumbImage.domImage.src=picAsset.assetObj;
                }
            }else{
                if(this.is2D)
                    (this.sliderThumb as HTMLImageElement).style.backgroundImage="";
                else{
                    (this.sceneObj as BABYLON.GUI.ImageBasedSlider).thumbImage.domImage=document.createElement("img");
                    (this.sceneObj as BABYLON.GUI.ImageBasedSlider).thumbImage._markAsDirty();
                }
            }
        },
        default:"thumb",
        title:this.title
    }
}