export abstract class IED extends VREvent<string> {
    public abstract get type(): string;
    public get subtype():string{
        return "*"
    }
    public set subtype(val:string){
    }
    public abstract get id(): string;

    public get name(): string{
        return this._data.get("name");
    }

    public init?():void;

    protected _data:DMap;

    public get(key:string){
        if(this.isDestroy)
            return null;
        let split=key.split('.');
        let value:any=this._data;
        for(let i=0;i<split.length;i++){
            if(value instanceof DMap){
                value=value.get(split[i]);
            }else{
                value=null;break;
            }
        }
        if (value == null) {
            value = IEDProxyFactory.getDefault(this,key);
        }
        return value;
    }

    public loadType:string;
    public copyData(){
        return this._data.jsonParse();
    }

    public unwatch(group:string){
        this.deleteEventGroup(group);
    }

    public set(key: string,value: any,config?: { isNetwork?: boolean; undoStack?: boolean; origin?: string }) {
        let split = key.split(".");
        let data = this._data;
        for (let i = 0; i < split.length; i++) {
            if (i == split.length - 1) {
                data.set(split[i], value, false, config);
            } else {
                if (data instanceof DMap) {
                    let tmpData = data.get(split[i]);
                    if(tmpData==null){
                        tmpData=new DMap();
                        data.set(split[i],tmpData);
                    }
                    data=tmpData;
                } else {
                    break;
                }
            }
        }
    }

    constructor(data:DMap){
        super();
        this._data=data;
    }

    public watch(attr:string,func:(value:any,old:any,config?:{origin?:string,deleted?:boolean})=>void,group?:string){
        let func2=(value,old,config)=>{
            if(value==null){
                value=IEDProxyFactory.getDefault(this,attr);
            }
            func.call(this,value,old,config)
        }
        this.getEventGroup(group).addEventListener(attr,func2);
    }

    public get tagNames():string[]{
        let tags=this.get("tags");
        if(tags instanceof DArray){
            return tags.jsonParse();
        }
        return null;
    }
    protected dispose?():void;
    public destroy(){
        if(this._data){
            if(this.dispose)
                this.dispose();
            VeryEngine.removeTag(this.id,[]);
            IEDProxyFactory.destroyExtend(this);
            this.clearEvent();
            this._data=null;
        }
    }

    public clearData(undo?:boolean){
        if(undo==undefined)
            undo=true;
        this._data.destroy(undo);
    }

    
    //IED被摧毁了，但是保留其原始数据，方便下一次通过数据复原
    public clearDataButRecord(list?:DMap[]){
        if(list!=null)
            list.push(this._data);
        this._data.forceDeleteTrigger();
        this._data = null;
    }

    public get isDestroy() {
        return this._data == null;
    }
}
