export class ShareBox{
    public assetMap:DMap;
    public sceneMap:DMap;
    public init(doc:Doc){
        if(doc.network){
            Progress.init();
            Progress.setTotal(3);
        }else{
            Progress.init()
            OSS.getJsonConfig("assets").then(async(assetStr)=>{
                if(assetStr){
                    let assetJson=JSON.parse(assetStr).assets;
                    if(assetJson){
                        this.pareseMap(assetJson,this.assetMap);
                    }
                }
                if(VeryEngine.showBabylon&&this.id2Asset[VeryEngine.showBabylon]){
                    Progress.setTotal(3);
                    let test=await this.id2Asset[VeryEngine.showBabylon].loadToScene();
                    Progress.entityLoad();
                    Progress.entityLoad();
                    VeryEngine.viewCamera.customView(test[0].sceneObj,500);
                    Progress.entityLoad();
                }else{
                    OSS.getJsonConfig("scenes").then(async(scenesStr)=>{
                        if(scenesStr){
                            let sceneJson=JSON.parse(scenesStr).scenes[0].entities;
                            sceneJson=this.filterNoParentNode(sceneJson);
                            Progress.setTotal(Object.keys(sceneJson).length)
                            if(sceneJson){
                                for(let key in sceneJson){
                                    if(sceneJson[key].type=="table"){
                                        if(!sceneJson[VeryEngine.logicControl]){
                                            sceneJson[VeryEngine.logicControl]={name: "表格控制器",type:"mesh",subtype:"empty",children:[],
                                            resource_id: VeryEngine.logicControl}
                                            sceneJson["799f7762-3ef2-4564-a59b-c0ae959a90ce"].children.push(VeryEngine.logicControl);
                                        }
                                        for(let tableObj of sceneJson[key].controller){
                                            let id=Tools.uuid();
                                            sceneJson[id]={resource_id:id,enabled:tableObj.enabled,type:"logic",source:tableObj.id};
                                            sceneJson[VeryEngine.logicControl].children.push(id)
                                        }
                                        delete sceneJson[key];
                                    }
                                }
                                this.pareseMap(sceneJson,this.sceneMap);
                            }
                        }else{
                            Progress.setTotal(3);
                            this.pareseMap(JSON.parse(`{"799f7762-3ef2-4564-a59b-c0ae959a90ce":{"name":"新建场景","type":"root","resource_id":"799f7762-3ef2-4564-a59b-c0ae959a90ce","children":["5e7ecc24-75b7-445a-b381-a66bd7699163","3109cca1-b962-4fd5-a83a-0b28719d2616"]},"5e7ecc24-75b7-445a-b381-a66bd7699163":{"name":"主相机","type":"camera","resource_id":"5e7ecc24-75b7-445a-b381-a66bd7699163","position":[0,0,-200],"children":[]},"3109cca1-b962-4fd5-a83a-0b28719d2616":{"name":"环境光","type":"light","resource_id":"3109cca1-b962-4fd5-a83a-0b28719d2616","subtype":"hemispheric","position":[500,500,500],"children":[]}}`)
                            ,this.sceneMap);
                        }
                    });
                }
            });
        }
    }

    private filterNoParentNode(sceneJson:any){
        let json={};
        for(let node in sceneJson){
            if(sceneJson[node].type=="root"){
                json[node]=sceneJson[node];
                this.allChildren(json[node],json,sceneJson);
                break;
            }
        }
        return json;
    }

    private allChildren(node:any,target:any,origin:any){
        if(node.children){
            for(let child of node.children){
                if(origin[child]){
                    target[child]=origin[child];
                    this.allChildren(target[child],target,origin);
                }
            }
        }
    }

    private pareseMap(obj: any, map: DMap) {
        for (let key in obj) {
            if (Object.prototype.toString.call(obj[key]) == "[object Object]") {
                let tmp = new DMap();
                this.pareseMap(obj[key], tmp);
                map.set(key, tmp);
            } else if (Object.prototype.toString.call(obj[key]) == "[object Array]") {
                let tmp = [];
                this.pareseArray(key,obj[key], tmp);
                map.set(key, tmp);
            } else if (obj[key] != null) {
                map.set(key, obj[key]);
            }
        }
    }

    private pareseArray(key:string,arr: any[], list: any[]) {
        for (let unit of arr) {
            if (Object.prototype.toString.call(unit) == "[object Object]") {
                list.push(unit);
            } else if (Object.prototype.toString.call(unit) == "[object Array]") {
                let tmp = [];
                this.pareseArray("",unit, tmp);
                list.push(tmp);
            } else if(unit!=null&&(!DArray.isArray(key)||!list.includes(unit))){
                list.push(unit);
            }
        }
    }

    //记录共享属性,key为属性名
    //插件中的共享属性
    private _shareOrigin: { [key: string]: IpluginExtends } = {};
    //IED中的共享属性
    private _shareIEDOrigin: { [key: string]: HTMLOrSVGScriptElement } = {};

    public recordOrigin(key: string, Iplugin: IpluginExtends) {
        this._shareOrigin[key] = Iplugin;
    }

    public recordIEDOrigin(key: string, id: HTMLOrSVGScriptElement) {
        this._shareIEDOrigin[key] = id;
    }

    public delOrigin(plugin: IpluginExtends) {
        for (let key in this._shareOrigin) {
            if (this._shareOrigin[key] === plugin) {
                delete this._shareOrigin[key];
                delete this[key];
            }
        }
    }

    public delIEDOrigin(script: HTMLScriptElement) {
        for (let key in this._shareIEDOrigin) {
            if (this._shareIEDOrigin[key] === script) {
                delete this._shareIEDOrigin[key];
                delete this[key];
            }
        }
    }
    public filterAssetType:(type: string|string[],oldAssetId?:string)=>Promise<IEDAsset>;
    public filterEntityType:(type:string|string[])=>Promise<IEDEntity>;
    public id2Asset: { [key: string]: IEDAsset } = {};
    public id2Entity: { [key: string]: IEDEntity } = {};
    public import = {};
    [propName: string]: any;
}
VeryEngine.shareBox = new ShareBox();

export function addShare(target: any, key: string) {
    let prototype = target;
    let isStatic = false;
    //静态
    if (target.prototype) {
        prototype = target.prototype;
        isStatic = true;
    }
    let isFunc = typeof target[key] === "function";
    //IED 里面普通变量必须要用static修饰
    if (prototype.__proto__.__proto__ == IED.prototype) {
        if (!isFunc && !isStatic) {
            console.error(key + ",该变量必须用static修饰");
        } else {
            if (isFunc) VeryEngine.shareBox[key] = target[key];
            else {
                Object.defineProperty(VeryEngine.shareBox, key, {
                    get() {
                        return target[key];
                    },
                    set(val) {
                        target[key] = val;
                    },
                });
            }
            VeryEngine.shareBox.recordIEDOrigin(key, document.currentScript);
        }
    }
    //IPulgin
    else if (prototype.hasOwnProperty("uninstall")) {
        let instance = pluginDontLoad(prototype);
        if (!isStatic) {
            if (isFunc) {
                VeryEngine.shareBox[key] = instance[key].bind(instance);
            } else {
                Object.defineProperty(VeryEngine.shareBox, key, {
                    get() {
                        return instance[key];
                    },
                    set(val) {
                        instance[key] = val;
                    },
                    configurable: true
                });
            }
            VeryEngine.shareBox.recordOrigin(key, instance);
        } else {
            if (isFunc) VeryEngine.shareBox[key] = target[key];
            else
                Object.defineProperty(VeryEngine.shareBox, key, {
                    get() {
                        return target[key];
                    },
                    set(val) {
                        target[key] = val;
                    },
                    configurable: true
                });
            VeryEngine.shareBox.recordOrigin(key, instance);
        }
    } else {
        console.error("addShare 装饰器只能在IED类或者IPlugin插件中才有效");
    }
}

